                        </div>
                        <button type="submit" class="w-full bg-blue-500 hover:bg-blue-700 text-white font-bold py-3 rounded-md transition-colors">Send Message</button>
                    </form>
                </div>
            </div>
        </section>
    </main>

    <footer class="bg-gray-800 text-gray-300 py-12">
        <div class="container mx-auto px-6 text-center">
            <p>&copy; 2024 Photographer Name. All rights reserved.</p>
            <div class="mt-4 flex justify-center space-x-6">
                <a href="#" class="hover:text-white"><i class="fab fa-instagram fa-lg"></i></a>
                <a href="#" class="hover:text-white"><i class="fab fa-facebook fa-lg"></i></a>
                <a href="#" class="hover:text-white"><i class="fab fa-twitter fa-lg"></i></a>
            </div>
        </div>
    </footer>

    <div id="full-screen-preview" class="hidden fixed top-0 left-0 w-full h-full full-screen-overlay flex items-center justify-center cursor-pointer" onclick="closeFullScreen()">
        <img src="" alt="Full Screen Image" class="full-screen-image" id="full-screen-img">
    </div>

    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');
        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        let page = 1;
        const perPage = 12;
        const gallery = document.getElementById('image-gallery');
        const loading = document.getElementById('loading');
        const scrollTrigger = document.getElementById('infinite-scroll-trigger');
        let loadingData = false;

        const loadImages = async () => {
            if (loadingData) return;
            loadingData = true;
            loading.classList.remove('hidden');

            const start = (page - 1) * perPage;
            const end = start + perPage;

            for (let i = start; i < end; i++) {
                const imageUrl = `https://picsum.photos/id/${i}/400/300`;
                const item = document.createElement('div');
                item.className = 'gallery-item cursor-pointer overflow-hidden rounded-lg shadow-md';
                item.innerHTML = `
                    <img src="${imageUrl}" alt="Gallery Image ${i}" class="w-full h-full block object-cover">
                `;
                item.addEventListener('click', () => openFullScreen(imageUrl));
                gallery.appendChild(item);
                await new Promise(resolve => setTimeout(resolve, 50));
            }

            loading.classList.add('hidden');
            loadingData = false;
        };

        loadImages();

        const observer = new IntersectionObserver(entries => {
            if (entries[0].isIntersecting) {
                page++;
                loadImages();
            }
        }, { threshold: 1 });

        observer.observe(scrollTrigger);

        let fullScreenOverlay = document.getElementById('full-screen-preview');
        let fullScreenImg = document.getElementById('full-screen-img');

        function openFullScreen(imageUrl) {
            fullScreenImg.src = imageUrl;
            fullScreenOverlay.classList.remove('hidden');
            setTimeout(() => {
                fullScreenOverlay.classList.add('opacity-100');
            }, 10);
        }

        function closeFullScreen() {
            fullScreenOverlay.classList.add('hidden');
            fullScreenOverlay.classList.remove('opacity-100');
        }
    </script>

</body>
</html>
