</div>

<script>
    document.querySelectorAll('.category-header').forEach(header => {
        header.addEventListener('click', () => {
            const category = header.dataset.category;
            const content = document.getElementById(category);
            const icon = header.querySelector('.fa-chevron-down');
            content.classList.toggle('expanded');
            icon.classList.toggle('rotate-180');
        });
    });

    document.addEventListener('DOMContentLoaded', () => {
        document.querySelectorAll('.category-header').forEach(header => {
            const content = document.getElementById(header.dataset.category);
            content.style.maxHeight = '0px';
        });
    });

    document.querySelectorAll('.category-header').forEach(header => {
        header.addEventListener('click', function() {
            const categoryContent = this.nextElementSibling;
            const isExpanded = categoryContent.classList.contains('expanded');

            document.querySelectorAll('.category-content.expanded').forEach(content => {
                content.classList.remove('expanded');
                content.style.maxHeight = '0px';
                const headerIcon = content.previousElementSibling.querySelector('.fa-chevron-down');
                headerIcon.classList.remove('rotate-180');
            });

            if (!isExpanded) {
                categoryContent.classList.add('expanded');
                categoryContent.style.maxHeight = categoryContent.scrollHeight + 'px';
                this.querySelector('.fa-chevron-down').classList.add('rotate-180');
            }
        });
    });

    gsap.registerPlugin(ScrollTrigger);

    gsap.utils.toArray('section').forEach(section => {
        gsap.from(section.querySelectorAll('.rounded-2xl, .rounded-3xl, .grid > div'), {
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.2,
            ease: "power3.out",
            scrollTrigger: {
                trigger: section,
                start: "top 80%",
                toggleActions: "play none none reverse"
            }
        });
    });

    const mainContent = document.querySelector('main');

    function navigateTo(url) {
        mainContent.classList.remove('fade-in');
        mainContent.classList.add('fade-out');
        setTimeout(() => {
            window.location.href = url;
        }, 500);
    }

    document.querySelectorAll('aside a').forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            const href = this.getAttribute('href');
            navigateTo(href);
        });
    });
</script>

</body>
</html>
