        <nav class="hidden md:flex space-x-6">
            <a href="#" class="hover:text-teal-200 transition-colors">Sessions</a>
            <a href="#" class="hover:text-teal-200 transition-colors">Speakers</a>
            <a href="#" class="hover:text-teal-200 transition-colors">Sponsors</a>
            <a href="#" class="hover:text-teal-200 transition-colors">Help</a>
        </nav>
        <button class="md:hidden text-white focus:outline-none">
            <i class="fa fa-bars fa-lg"></i>
        </button>
