    </div>
</footer>

<script>
    function toggleSessionDetails(sessionId) {
        const sessionDetails = document.getElementById(sessionId);
        sessionDetails.classList.toggle('expanded');
    }

    let currentRoom = null;
    const breakoutRoomView = document.getElementById('breakout-room-view');
    const breakoutRoomTitle = document.getElementById('breakout-room-title');
    const breakoutRoomImage = document.getElementById('breakout-room-image');

    function goToBreakoutRoom(roomId) {
        if (currentRoom) {
            animateRoomTransitionOut(currentRoom, roomId);
        } else {
            animateRoomTransitionIn(roomId);
        }
        currentRoom = roomId;
    }

    function closeBreakoutRoom() {
        animateRoomTransitionOut(currentRoom, null);
        currentRoom = null;
    }

    function animateRoomTransitionIn(roomId) {
        breakoutRoomView.classList.remove('hidden');
        breakoutRoomView.style.opacity = 0;
        breakoutRoomView.style.transform = 'translateX(100%)';

        if (roomId === 'room1') {
            breakoutRoomTitle.textContent = 'Breakout Room: Marketing';
            breakoutRoomImage.src = 'https://picsum.photos/600/300';
        } else if (roomId === 'room2') {
            breakoutRoomTitle.textContent = 'Breakout Room: Design';
            breakoutRoomImage.src = 'https://picsum.photos/601/300';
        } else if (roomId === 'room3') {
            breakoutRoomTitle.textContent = 'Breakout Room: Sales';
            breakoutRoomImage.src = 'https://picsum.photos/602/300';
        }

        setTimeout(() => {
            breakoutRoomView.style.opacity = 1;
            breakoutRoomView.style.transform = 'translateX(0)';
        }, 10);
    }


    function animateRoomTransitionOut(fromRoomId, toRoomId) {
        breakoutRoomView.style.opacity = 1;
        breakoutRoomView.style.transform = 'translateX(0)';

        setTimeout(() => {
            breakoutRoomView.style.opacity = 0;
            breakoutRoomView.style.transform = 'translateX(-100%)';
        }, 10);

        setTimeout(() => {
            breakoutRoomView.classList.add('hidden');
            if (toRoomId) {
                animateRoomTransitionIn(toRoomId);
            }
        }, 500);
    }


</script>

</body>
</html>
