        @keyframes pulse-bg {
            0%, 100% { opacity: 0.75 }
            50% { opacity: 1; }
        }
        .shadow-music { box-shadow: 0 15px 35px rgba(0, 0, 0, 0.8); }
    </style>
</head>
<body class="bg-gray-900 text-white">

    <div class="flex h-screen">

        <!-- Sidebar (Playlist & Navigation) -->
        <aside class="sidebar fixed top-0 left-0 h-full bg-gray-800 shadow-xl z-40 md:relative">
            <div class="p-6">
                <h2 class="text-2xl font-bold mb-4 text-purple-500">Muse Stream</h2>
                <nav>
                    <ul class="space-y-2">
                        <li><a href="#" class="block py-2 px-4 rounded-md hover:bg-gray-700 transition-colors flex items-center"><i class="fa fa-home fa-fw mr-3"></i> Home</a></li>
                        <li><a href="#" class="block py-2 px-4 rounded-md hover:bg-gray-700 transition-colors flex items-center"><i class="fa fa-compass fa-fw mr-3"></i> Explore</a></li>
                        <li><a href="#" class="block py-2 px-4 rounded-md hover:bg-gray-700 transition-colors flex items-center"><i class="fa fa-headphones-alt fa-fw mr-3"></i> Library</a></li>
                    </ul>
                </nav>
            </div>
            <div class="p-6 mt-4">
                <h3 class="text-lg font-semibold mb-3 text-gray-400">Playlists</h3>
                <ul class="space-y-2" id="playlist-sidebar">
                    </ul>
                <button onclick="addPlaylist()" class="block py-2 px-4 rounded-md hover:bg-gray-700 transition-colors w-full text-left flex items-center"><i class="fa fa-plus fa-fw mr-3"></i> Add Playlist</button>
            </div>
        </aside>

        <!-- Main Content -->
        <main class="main-content flex-1 p-8">

            <!-- Hero Section -->
            <section class="mb-12">
                <div class="gradient-bg rounded-3xl shadow-music overflow-hidden relative">
                    <img src="https://picsum.photos/1920/400" alt="Hero Image" class="w-full h-64 object-cover opacity-70">
                    <div class="absolute inset-0 p-8 flex items-center">
                        <div>
                            <h1 class="text-4xl font-extrabold mb-4">Discover New Music</h1>
                            <p class="text-lg text-gray-300 mb-8">Explore curated playlists and find your next favorite song.</p>
                            <button class="bg-purple-500 hover:bg-purple-600 text-white font-semibold py-3 px-6 rounded-full transition-colors">Explore Now</button>
                        </div>
                    </div>
                </div>
            </section>

            <!-- Audio Visualizer -->
            <section class="mb-12">
                <div class="bg-gray-800 rounded-2xl shadow-music p-6">
                    <h2 class="text-xl font-semibold mb-4">Now Playing</h2>
                    <div class="flex items-center justify-between">
                        <div class="flex items-center">
                            <img id="album-art" src="https://picsum.photos/100/100" alt="Album Art" class="w-20 h-20 rounded-md mr-4">
                            <div>
                                <h3 id="track-title" class="font-semibold">Track Title</h3>
                                <p id="artist-name" class="text-gray-300">Artist Name</p>
                            </div>
                        </div>
                        <div class="flex items-center space-x-4">
                            <button onclick="previousTrack()" class="hover:text-white"><i class="fa fa-backward"></i></button>
                            <button onclick="playPauseTrack()" class="text-purple-500 hover:text-purple-400 text-xl"><i id="play-pause-icon" class="fa fa-play"></i></button>
                            <button onclick="nextTrack()" class="hover:text-white"><i class="fa fa-forward"></i></button>
                        </div>
                    </div>
                    <div class="mt-6">
                        <canvas id="audio-visualizer" width="100%" height="80"></canvas>
                    </div>
                </div>
            </section>

            <!-- Artist Profiles (Collapsible) -->
            <section>
                <h2 class="text-2xl font-bold mb-6">Featured Artists</h2>
                <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    <div class="bg-gray-800 rounded-2xl shadow-music overflow-hidden artist-profile">
                        <img src="https://picsum.photos/400/300" alt="Artist Image" class="w-full h-48 object-cover">
                        <div class="p-6">
                            <h3 class="text-xl font-semibold mb-2 artist-name">Artist Name 1</h3>
                            <p class="text-gray-300 mb-4 artist-genre">Genre: Pop</p>
                            <button onclick="toggleArtistProfile(this)" class="bg-purple-500 hover:bg-purple-600 text-white font-semibold py-2 px-4 rounded-full transition-colors block w-full text-center">View Profile</button>
                            <div class="artist-bio hidden mt-4 text-sm text-gray-400">
                                <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nulla eget metus auctor, laoreet ipsum eget, tempor justo. Integer nec erat vel justo tincidunt tincidunt.</p>
                            </div>
                        </div>
                    </div>
                    <div class="bg-gray-800 rounded-2xl shadow-music overflow-hidden artist-profile">
                        <img src="https://picsum.photos/400/301" alt="Artist Image" class="w-full h-48 object-cover">
                        <div class="p-6">
                            <h3 class="text-xl font-semibold mb-2 artist-name">Artist Name 2</h3>
                            <p class="text-gray-300 mb-4 artist-genre">Genre: Rock</p>
                            <button onclick="toggleArtistProfile(this)" class="bg-purple-500 hover:bg-purple-600 text-white font-semibold py-2 px-4 rounded-full transition-colors block w-full text-center">View Profile</button>
                            <div class="artist-bio hidden mt-4 text-sm text-gray-400">
                                <p>Praesent commodo cursus magna, vel scelerisque nisl consectetur et. Vivamus sagittis lacus vel augue laoreet rutrum faucibus dolor auctor.</p>
                            </div>
                        </div>
                    </div>
                    <div class="bg-gray-800 rounded-2xl shadow-music overflow-hidden artist-profile">
                        <img src="https://picsum.photos/400/302" alt="Artist Image" class="w-full h-48 object-cover">
                        <div class="p-6">
                            <h3 class="text-xl font-semibold mb-2 artist-name">Artist Name 3</h3>
                            <p class="text-gray-300 mb-4 artist-genre">Genre: Electronic</p>
                            <button onclick="toggleArtistProfile(this)" class="bg-purple-500 hover:bg-purple-600 text-white font-semibold py-2 px-4 rounded-full transition-colors block w-full text-center">View Profile</button>
                            <div class="artist-bio hidden mt-4 text-sm text-gray-400">
                                <p>Donec ullamcorper nulla non metus auctor fringilla. Donec id elit non mi porta gravida at eget metus. Aenean lacinia bibendum nulla sed consectetur.</p>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

        </main>

    </div>

    <script>
        const playlistSidebar = document.getElementById('playlist-sidebar');
        let playlists = ['Chill Vibes', 'Workout Beats', 'Focus Flow'];

        function renderPlaylists() {
            playlistSidebar.innerHTML = '';
            playlists.forEach(playlist => {
                const li = document.createElement('li');
                li.innerHTML = `<a href="#" class="block py-2 px-4 rounded-md hover:bg-gray-700 transition-colors flex items-center"><i class="fa fa-list fa-fw mr-3"></i> ${playlist}</a>`;
                playlistSidebar.appendChild(li);
            });
        }

        renderPlaylists();

        function addPlaylist() {
            const newPlaylistName = prompt("Enter new playlist name:");
            if (newPlaylistName) {
                playlists.push(newPlaylistName);
                renderPlaylists();
            }
        }

        const albumArt = document.getElementById('album-art');
        const trackTitle = document.getElementById('track-title');
        const artistName = document.getElementById('artist-name');
        const playPauseIcon = document.getElementById('play-pause-icon');
        const visualizerCanvas = document.getElementById('audio-visualizer');
        const visualizerContext = visualizerCanvas.getContext('2d');
        let isPlaying = false;
        let currentTrackIndex = 0;
        const trackList = [
            { title: 'Track 1', artist: 'Artist A', albumArt: 'https://picsum.photos/100/100?image=10' },
            { title: 'Track 2', artist: 'Artist B', albumArt: 'https://picsum.photos/100/100?image=20' },
            { title: 'Track 3', artist: 'Artist C', albumArt: 'https://picsum.photos/100/100?image=30' }
        ];

        function loadTrack(trackIndex) {
            const track = trackList[trackIndex];
            albumArt.src = track.albumArt;
            trackTitle.textContent = track.title;
            artistName.textContent = track.artist;
        }

        loadTrack(currentTrackIndex);

        function playPauseTrack() {
            isPlaying = !isPlaying;
            playPauseIcon.classList.toggle('fa-play', !isPlaying);
            playPauseIcon.classList.toggle('fa-pause', isPlaying);
            if (isPlaying) {
                animateVisualizer();
            } else {
                cancelAnimationFrame(animationFrameId);
            }
        }

        function nextTrack() {
            currentTrackIndex = (currentTrackIndex + 1) % trackList.length;
            loadTrack(currentTrackIndex);
            if (isPlaying) animateVisualizer();
        }

        function previousTrack() {
            currentTrackIndex = (currentTrackIndex - 1 + trackList.length) % trackList.length;
            loadTrack(currentTrackIndex);
            if (isPlaying) animateVisualizer();
        }

        let animationFrameId;
        function animateVisualizer() {
            visualizerContext.clearRect(0, 0, visualizerCanvas.width, visualizerCanvas.height);
            visualizerContext.fillStyle = '#purple-500';
            const barWidth = visualizerCanvas.width / 25;
            let x = 0;
            for (let i = 0; i < 25; i++) {
                const barHeight = Math.random() * visualizerCanvas.height;
                visualizerContext.fillStyle = `rgba(168, 85, 247, ${Math.random() * 0.8 + 0.2})`;
                visualizerContext.fillRect(x, visualizerCanvas.height - barHeight, barWidth, barHeight);
                x += barWidth;
            }
            if (isPlaying) {
                animationFrameId = requestAnimationFrame(animateVisualizer);
            }
        }

        function toggleArtistProfile(buttonElement) {
            const artistProfile = buttonElement.closest('.artist-profile');
            const bioElement = artistProfile.querySelector('.artist-bio');
            bioElement.classList.toggle('hidden');
            artistProfile.classList.toggle('collapsed');
            buttonElement.textContent = bioElement.classList.contains('hidden') ? 'View Profile' : 'Collapse Profile';
        }
    </script>

</body>
</html>
