<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Recipe Hub - Discover Culinary Delights</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap" rel="stylesheet">
    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Poppins', sans-serif;
        }
        .grid-recipe {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 2rem;
        }
        .recipe-card {
            overflow: hidden;
            border-radius: 1.25rem;
            box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.05);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .recipe-card:hover {
            transform: scale(1.03);
            box-shadow: 0 0.75rem 1.5rem rgba(0, 0, 0, 0.1);
        }
        .recipe-image {
            height: 200px;
            object-fit: cover;
            width: 100%;
        }
        .recipe-content {
            padding: 1.5rem;
        }
        .ingredient-list {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.4s ease-in-out;
        }
        .ingredient-list.expanded {
            max-height: 600px;
        }
        .dark-mode .recipe-card {
            background-color: #1e293b;
            box-shadow: 0 0.5rem 1rem rgba(255, 255, 255, 0.05);
        }
        .dark-mode .recipe-card:hover {
            box-shadow: 0 0.75rem 1.5rem rgba(255, 255, 255, 0.1);
        }
        .dark-mode body {
            background-color: #0f172a;
