    <script>
        const ingredientToggles = document.querySelectorAll('.ingredient-toggle');
        ingredientToggles.forEach(toggle => {
            toggle.addEventListener('click', () => {
                const ingredientList = toggle.nextElementSibling;
                ingredientList.classList.toggle('expanded');
            });
        });

        const darkModeToggle = document.getElementById('darkModeToggle');
        const html = document.documentElement;

        darkModeToggle.addEventListener('click', () => {
            html.classList.toggle('dark-mode');
            const circle = darkModeToggle.querySelector('.toggle-circle');
            circle.classList.toggle('translate-x-1');
            circle.classList.toggle('translate-x-6');
        });

        const mobileMenuButton = document.getElementById('mobileMenuButton');
        const mobileMenu = document.getElementById('mobileMenu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });
    </script>
</body>
</html>
