        }
        .gallery-item:hover {
            transform: scale(1.05);
        }
        .parallax {
            perspective: 1px;
            overflow-x: hidden;
            overflow-y: auto;
            position: relative;
            height: 100vh;
        }
        .parallax-group {
            position: relative;
            height: 100vh;
            transform-style: preserve-3d;
        }
        .parallax-layer {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
        }
        .parallax-base {
            transform: translateZ(0);
            z-index: 1;
        }
        .parallax-back {
            transform: translateZ(-1px) scale(2);
            z-index: -1;
        }
        .full-screen-modal {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.9);
            z-index: 1000;
