        <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div class="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div>
                    <h4 class="text-lg font-semibold text-white mb-4">Masterpiece Gallery</h4>
                    <p>Showcasing art from around the globe.</p>
                </div>
                <div>
                    <h4 class="text-lg font-semibold text-white mb-4">Explore</h4>
                    <ul class="space-y-2">
                        <li><a href="#" class="hover:text-white">Collections</a></li>
                        <li><a href="#" class="hover:text-white">Artists</a></li>
                        <li><a href="#" class="hover:text-white">Exhibitions</a></li>
                    </ul>
                </div>
                <div>
                    <h4 class="text-lg font-semibold text-white mb-4">Connect</h4>
                    <p>Stay updated on new arrivals and events.</p>
                    <div class="mt-4 flex space-x-4">
                        <a href="#" class="hover:text-white"><i class="fab fa-instagram text-xl"></i></a>
                        <a href="#" class="hover:text-white"><i class="fab fa-twitter text-xl"></i></a>
                        <a href="#" class="hover:text-white"><i class="fab fa-facebook text-xl"></i></a>
                    </div>
                </div>
            </div>
            <div class="mt-8 border-t border-gray-700 pt-8 text-center">
                <p>&copy; 2024 Masterpiece Gallery. All rights reserved.</p>
            </div>
        </div>
    </footer>

    <script>
        const filterButtons = document.querySelectorAll('.filter-button');
        const galleryItems = document.querySelectorAll('.gallery-item');
        const mobileMenuButton = document.querySelector('.mobile-menu-button');
        const mobileMenu = document.querySelector('.mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        filterButtons.forEach(button => {
            button.addEventListener('click', () => {
                const filterValue = button.dataset.filter;

                filterButtons.forEach(btn => btn.classList.remove('active'));
                button.classList.add('active');

                galleryItems.forEach(item => {
                    if (filterValue === 'all' || item.classList.contains(filterValue)) {
                        item.style.display = 'block';
                    } else {
                        item.style.display = 'none';
                    }
                });
                if (!mobileMenu.classList.contains('hidden')) {
                    mobileMenu.classList.add('hidden');
                }
            });
        });

        let modal = document.getElementById('fullScreenSlideshow');
        let modalImg = document.querySelector('.modal-image');

        function openModal(imgSrc) {
            modal.classList.add('active');
            modalImg.src = imgSrc;
        }

        function closeModal() {
            modal.classList.remove('active');
            modalImg.src = '';
        }
    </script>

</body>
</html>
