    <script>
        lucide.createIcons();

        let postCount = 3;
        const postContainer = document.getElementById('post-container');
        const loadingIndicator = document.getElementById('loading-indicator');
        let isLoading = false;

        function loadMorePosts() {
            if (isLoading) return;
            isLoading = true;
            loadingIndicator.style.display = 'block';

            setTimeout(() => {
                loadingIndicator.style.display = 'none';
                for (let i = 0; i < 3; i++) {
                    postCount++;
                    const article = document.createElement('article');
                    article.className = 'post-card bg-white rounded-xl shadow-md overflow-hidden';
                    article.innerHTML = `
                        <img src="https://picsum.photos/200/300?random=${postCount}" alt="Blog Post Image" class="w-full h-48 object-cover">
                        <div class="p-6">
                            <h2 class="text-xl font-bold text-gray-900 mb-2 hover:text-teal-600 transition-colors"><a href="#">New Blog Post Title ${postCount}</a></h2>
                            <p class="text-gray-700 mb-4">This is a dynamically loaded blog post with more amazing content. Infinite scroll example.</p>
                            <div class="flex justify-between items-center">
                                <span class="text-sm text-gray-500"><i data-lucide="calendar" class="inline-block w-3 h-3 mr-1 align-text-top"></i> Just Now</span>
                                <a href="#" class="button-primary button-sm">Read More</a>
                            </div>
                        </div>
                    `;
                    postContainer.appendChild(article);
                }
                isLoading = false;
            }, 1000);
        }

        window.addEventListener('scroll', () => {
            if (!isLoading && window.innerHeight + window.scrollY >= document.body.offsetHeight - 500) {
                loadMorePosts();
            }
        });

        document.querySelectorAll('.reply-button').forEach(button => {
            button.addEventListener('click', function() {
                this.closest('.flex').nextElementSibling.classList.toggle('hidden');
            });
        });

        document.getElementById('comment-form').addEventListener('submit', function(event) {
            event.preventDefault();
            const commentText = document.getElementById('comment-text').value;
            if (!commentText.trim()) return;

            const newComment = document.createElement('div');
            newComment.className = 'comment';
            newComment.innerHTML = `
                <div class="flex items-start mb-2">
                    <img src="https://picsum.photos/50/50?random=${postCount + 10}" alt="User Avatar" class="w-10 h-10 rounded-full mr-4">
                    <div>
                        <p class="font-semibold text-gray-900">You</p>
                        <p class="text-gray-700">${commentText}</p>
                        <div class="mt-2 flex space-x-4">
                            <button class="button-secondary button-xs reply-button"><i data-lucide="reply" class="inline-block w-3 h-3 mr-1 align-text-top"></i> Reply</button>
                            <button class="text-gray-600 hover:text-teal-500 transition-colors like-button"><i data-lucide="thumbs-up" class="inline-block w-3 h-3 mr-1 align-text-top"></i> Like</button>
                        </div>
                        <div class="reply-form hidden mt-4">
                            <textarea placeholder="Your reply..." class="input-field reply-textarea" rows="2"></textarea>
                            <button class="button-primary button-sm post-reply-button">Post Reply</button>
                        </div>
                    </div>
                </div>
            `;
            document.getElementById('comments-container').prepend(newComment);
            document.getElementById('comment-text').value = '';

             newComment.querySelector('.reply-button').addEventListener('click', function() {
                this.closest('.flex').nextElementSibling.classList.toggle('hidden');
            });
        });

        gsap.utils.toArray('.post-card').forEach(card => {
            gsap.from(card, {
                y: 50,
                opacity: 0,
                duration: 0.8,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: card,
                    start: "top 80%",
                    toggleActions: "play none none reverse"
                }
            });
        });
    </script>
</body>
</html>
