                            <button data-trailer-id="trailer3" class="trailer-button text-gray-300 hover:text-white"><i class="fa-solid fa-play"></i> Trailer</button>
                        </div>
                    </div>
                </div>
                <div class="card bg-gray-800 rounded-lg overflow-hidden shadow-md">
                    <img class="w-full h-56 object-cover" src="https://picsum.photos/200/300?random=4" alt="Movie 4">
                    <div class="p-4">
                        <h3 class="font-bold text-xl mb-2">Movie Title 4</h3>
                        <p class="text-gray-300 text-sm mb-3">This is the last movie description example.</p>
                        <div class="flex items-center justify-between">
                            <div class="star-rating">
                                <input type="radio" id="star5-4" name="rating-4" value="5" /><label for="star5-4" title="5 stars"></label>
                                <input type="radio" id="star4-4" name="rating-4" value="4" /><label for="star4-4" title="4 stars"></label>
                                <input type="radio" id="star3-4" name="rating-4" value="3" /><label for="star3-4" title="3 stars"></label>
                                <input type="radio" id="star2-4" name="rating-4" value="2" checked /><label for="star2-4" title="2 stars"></label>
                                <input type="radio" id="star1-4" name="rating-4" value="1" /><label for="star1-4" title="1 star"></label>
                            </div>
                            <button data-trailer-id="trailer4" class="trailer-button text-gray-300 hover:text-white"><i class="fa-solid fa-play"></i> Trailer</button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <div id="trailerModal" class="modal">
        <div class="modal-content">
            <span class="close-button">&times;</span>
            <div class="trailer-container">
                <iframe id="trailerVideo" src="" frameborder="0" allowfullscreen></iframe>
            </div>
        </div>
    </div>

    <footer class="bg-gray-800 py-12">
        <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
            <p class="text-gray-400">© 2024 CineSphere. All rights reserved.</p>
            <div class="mt-4 flex justify-center space-x-6">
                <a href="#" class="text-gray-400 hover:text-white"><i class="fa-brands fa-facebook"></i></a>
                <a href="#" class="text-gray-400 hover:text-white"><i class="fa-brands fa-twitter"></i></a>
                <a href="#" class="text-gray-400 hover:text-white"><i class="fa-brands fa-instagram"></i></a>
            </div>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const trailerButtons = document.querySelectorAll('.trailer-button');
            const modal = document.getElementById('trailerModal');
            const modalVideo = document.getElementById('trailerVideo');
            const closeButton = document.querySelector('.close-button');

            trailerButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const trailerId = this.dataset.trailerId;
                    let videoSrc = '';
                    if (trailerId === 'trailer1') {
                        videoSrc = 'https://www.youtube.com/embed/dQw4w9WgXcQ';
                    } else if (trailerId === 'trailer2') {
                        videoSrc = 'https://www.youtube.com/embed/SccSCuHhFhc';
                    } else if (trailerId === 'trailer3') {
                        videoSrc = 'https://www.youtube.com/embed/jfKfPfyJRdk';
                    } else if (trailerId === 'trailer4') {
                        videoSrc = 'https://www.youtube.com/embed/AiGCOuQx2R8';
                    }
                    modalVideo.src = videoSrc;
                    modal.style.display = "block";
                });
            });

            closeButton.addEventListener('click', function() {
                modal.style.display = "none";
                modalVideo.src = '';
            });

            window.addEventListener('click', function(event) {
                if (event.target == modal) {
                    modal.style.display = "none";
                    modalVideo.src = '';
                }
            });
        });
    </script>
</body>
</html>
