    <title>Zenith Time - Your Day, Elevated</title>
    <link href="https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Roboto', sans-serif; }
        .task-list { min-height: 200px; }
        .task-item {
            @apply bg-white shadow-md rounded-md p-4 mb-2 cursor-grab hover:shadow-lg transition-shadow duration-200;
        }
        .task-item.dragging {
            @apply shadow-xl opacity-70;
        }
        .checklist-item {
            @apply flex items-center mb-2;
        }
        .checklist-input {
            @apply appearance-none h-5 w-5 border border-gray-300 rounded-md checked:bg-indigo-600 checked:border-transparent focus:outline-none;
            transition: background-color 0.2s ease-in-out, border-color 0.2s ease-in-out;
        }
        .checklist-input:checked {
            background-image: url("data:image/svg+xml,%3csvg viewBox='0 0 16 16' fill='white' xmlns='http://www.w3.org/2000/svg'%3e%3cpath d='M12.207 4.793a1 1 0 010 1.414l-5 5a1 1 0 01-1.414 0l-2-2a1 1 0 011.414-1.414L6.5 9.586l4.293-4.293a1 1 0 011.414 0z'/%3e%3c/svg%3e");
        }
        .checklist-label {
            @apply ml-2 text-gray-700;
        }
        .checklist-input:checked + .checklist-label {
            @apply line-through opacity-50;
        }
        .dynamic-bg-gradient {
            background: linear-gradient(to right, #6366f1, #3b82f6, #0ea5e9, #14b8a6, #34d399);
            background-size: 300% 100%;
            animation: gradientAnimation 15s linear infinite;
        }

        @keyframes gradientAnimation {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .task-category-personal { @apply bg-lime-100 border-lime-200; }
        .task-category-work { @apply bg-sky-100 border-sky-200; }
        .task-category-home { @apply bg-rose-100 border-rose-200; }
        .task-category-urgent { @apply bg-orange-100 border-orange-200; }

    </style>
</head>
<body class="bg-gray-50">

<div class="dynamic-bg-gradient fixed inset-0 -z-10 blur-3xl opacity-50"></div>

<div class="container mx-auto px-4 py-10">

    <header class="mb-10">
        <h1 class="text-4xl font-bold text-gray-900 mb-2">Zenith Time</h1>
        <p class="text-gray-600 text-lg">Elevate your day, one task at a time.</p>
    </header>

    <main class="grid grid-cols-1 md:grid-cols-3 gap-8">

        <section class="md:col-span-1">
            <div class="bg-white rounded-lg shadow-md p-6">
                <h2 class="text-xl font-semibold text-gray-800 mb-4">Categories</h2>
                <div class="space-y-3">
                    <button class="flex items-center w-full justify-start px-4 py-2 rounded-md hover:bg-gray-100 transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500">
                        <i class="fa-solid fa-inbox mr-2 text-gray-500"></i>
                        Inbox
                    </button>
                    <button class="flex items-center w-full justify-start px-4 py-2 rounded-md hover:bg-gray-100 transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500">
                        <i class="fa-solid fa-calendar-day mr-2 text-gray-500"></i>
                        Today
                    </button>
                    <button class="flex items-center w-full justify-start px-4 py-2 rounded-md hover:bg-gray-100 transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500">
                        <i class="fa-solid fa-calendar-week mr-2 text-gray-500"></i>
                        This Week
                    </button>
                    <button class="flex items-center w-full justify-start px-4 py-2 rounded-md hover:bg-gray-100 transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500">
                        <i class="fa-solid fa-check-double mr-2 text-gray-500"></i>
                        Completed
                    </button>
