            <div class="bg-white rounded-lg shadow-md p-6">
                <div class="flex justify-between items-center mb-6">
                    <h2 class="text-xl font-semibold text-gray-800">Today's Tasks</h2>
                    <button class="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-2 px-4 rounded-md transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500">
                        <i class="fa-solid fa-plus mr-2"></i> Add Task
                    </button>
                </div>

                <div id="task-list-container" class="space-y-4">

                    <div id="task-list-todo" class="task-list p-4 rounded-md border-2 border-dashed border-gray-300">
                        <h3 class="font-semibold text-gray-700 mb-3"><i class="fa-regular fa-circle mr-2"></i> To Do</h3>
                        <div draggable="true" class="task-item task-category-work" data-task-id="1">
                            <h4 class="font-semibold text-gray-800 mb-2">Project Proposal Draft</h4>
                            <p class="text-gray-600 text-sm">Prepare the initial draft for the client project proposal.</p>
                            <div class="mt-2">
                                <div class="checklist-item">
                                    <input type="checkbox" id="checklist-1-1" class="checklist-input">
                                    <label for="checklist-1-1" class="checklist-label">Outline key sections</label>
                                </div>
                                <div class="checklist-item">
                                    <input type="checkbox" id="checklist-1-2" class="checklist-input">
                                    <label for="checklist-1-2" class="checklist-label">Gather project data</label>
                                </div>
                            </div>
                        </div>

                        <div draggable="true" class="task-item task-category-personal" data-task-id="2">
                            <h4 class="font-semibold text-gray-800 mb-2">Grocery Shopping</h4>
                            <p class="text-gray-600 text-sm">Buy groceries for the week.</p>
