                        </div>
                    </div>

                    <div id="task-list-completed" class="task-list p-4 rounded-md border-2 border-dashed border-gray-300">
                        <h3 class="font-semibold text-gray-700 mb-3"><i class="fa-regular fa-check-circle mr-2"></i> Completed</h3>
                        <div draggable="true" class="task-item task-category-urgent" data-task-id="4">
                            <h4 class="font-semibold text-gray-800 mb-2">Pay Bills</h4>
                            <p class="text-gray-600 text-sm">Pay monthly utility bills.</p>
                            <div class="mt-2">
                                <div class="checklist-item">
                                    <input type="checkbox" id="checklist-4-1" class="checklist-input" checked>
                                    <label for="checklist-4-1" class="checklist-label">Electricity bill</label>
                                </div>
                                <div class="checklist-item">
                                    <input type="checkbox" id="checklist-4-2" class="checklist-input" checked>
                                    <label for="checklist-4-2" class="checklist-label">Internet bill</label>
                                </div>
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </section>

    </main>

    <footer class="mt-20 text-center text-gray-500">
        <p>&copy; 2024 Zenith Time. Crafted for peak productivity.</p>
    </footer>

</div>

<script>
    const taskItems = document.querySelectorAll('.task-item');
    const taskLists = document.querySelectorAll('.task-list');
    let draggedTask = null;

    taskItems.forEach(task => {
        task.addEventListener('dragstart', (e) => {
            draggedTask = task;
            task.classList.add('dragging');
        });

        task.addEventListener('dragend', () => {
            draggedTask.classList.remove('dragging');
            draggedTask = null;
        });
    });

    taskLists.forEach(list => {
        list.addEventListener('dragover', (e) => {
            e.preventDefault();
        });

        list.addEventListener('drop', (e) => {
            e.preventDefault();
            if (draggedTask) {
                list.appendChild(draggedTask);
            }
        });
    });

    const checklistInputs = document.querySelectorAll('.checklist-input');
    checklistInputs.forEach(input => {
        input.addEventListener('change', (e) => {
            if (e.target.checked) {
                // Example animation - you can enhance this
                e.target.nextElementSibling.classList.add('line-through', 'opacity-50');
                setTimeout(() => {
                    e.target.nextElementSibling.classList.remove('line-through', 'opacity-50');
                }, 1000); // Simple fade out effect, replace with more sophisticated animation
            }
        });
    });
</script>

</body>
</html>
