            <p>&copy; 2024 The Grand Azure Hotel. All rights reserved.</p>
        </div>
    </footer>

    <script>
        lucide.createIcons();

        gsap.registerPlugin(ScrollTrigger);

        gsap.utils.toArray('.animate-fade-in').forEach(element => {
            gsap.from(element, {
                opacity: 0,
                y: 30,
                duration: 1,
                ease: "power2.out",
                delay: parseFloat(element.style.animationDelay) || 0
            });
        });

        document.querySelectorAll('.amenity-toggle').forEach(toggle => {
            toggle.addEventListener('click', function() {
                const targetId = this.dataset.target;
                const amenityList = document.getElementById(targetId);
                amenityList.classList.toggle('expanded');
                const icon = this.querySelector('i');
                icon.classList.toggle('-rotate-180');
                gsap.to(icon, {rotation: amenityList.classList.contains('expanded') ? -180 : 0, duration: 0.3, ease: "power2.out"});
            });
        });

        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                const target = document.querySelector(this.getAttribute('href'));
                if(target) {
                    window.scrollTo({
                        top: target.offsetTop - (document.querySelector('nav').offsetHeight),
                        behavior: 'smooth'
                    });
                }
            });
        });

        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenuClose = document.getElementById('mobile-menu-close');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.remove('hidden');
        });

        mobileMenuClose.addEventListener('click', () => {
            mobileMenu.classList.add('hidden');
        });
    </script>

</body>
</html>
