<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Virtual Event Platform</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Poppins', sans-serif;
        }
        .hero-section {
            background: #0d0d0d;
        }
        .electric-blue {
            color: #4ad4ff;
        }
        .electric-bg {
            background-color: #4ad4ff;
        }
        .schedule-item:nth-child(odd) {
            background-color: rgba(255, 255, 255, 0.05);
        }
        .schedule-item:nth-child(even) {
            background-color: rgba(255, 255, 255, 0.1);
        }
        .form-input {
            background-color: rgba(255, 255, 255, 0.1);
            border: 1px solid rgba(255, 255, 255, 0.2);
        }
        .form-input:focus {
            background-color: rgba(255, 255, 255, 0.2);
            border-color: #4ad4ff;
            outline: none;
            box-shadow: 0 0 0 2px rgba(74, 212, 255, 0.3);
        }
        .btn-primary {
            background-color: #4ad4ff;
            transition: background-color 0.3s ease;
        }
        .btn-primary:hover {
            background-color: #3bb5e0;
        }
        .shadow-electric {
            --tw-shadow-color: #4ad4ff;
            --tw-shadow-opacity: 0.25;
            box-shadow: var(--tw-shadow);
        }
        .animate-slide-up {
            animation: slideUp 0.7s ease-out forwards;
            opacity: 0;
        }
        @keyframes slideUp {
            from {
                transform: translateY(50px);
                opacity: 0;
            }
            to {
                transform: translateY(0);
                opacity: 1;
            }
        }
        .animate-fade-in {
            animation: fadeIn 1s ease-out forwards;
            opacity: 0;
        }
        @keyframes fadeIn {
            from {
                opacity: 0;
            }
            to {
                opacity: 1;
            }
        }
        .hero-bg-gradient {
            background: linear-gradient(135deg, #0d0d0d 0%, #1a1a1a 50%, #0d0d0d 100%);
        }

    </style>
</head>
<body class="bg-gray-900 text-white">

    <header class="sticky top-0 z-50 bg-black bg-opacity-70 backdrop-blur-md shadow-lg">
        <nav class="container mx-auto px-6 py-4">
            <div class="flex items-center justify-between">
                <div class="text-xl font-bold electric-blue animate-fade-in">
                    <i class="fa-solid fa-video"></i> Virtual Events
                </div>
                <div class="hidden md:flex space-x-6 animate-fade-in delay-100">
                    <a href="#schedule" class="hover:electric-blue transition-colors">Schedule</a>
                    <a href="#speakers" class="hover:electric-blue transition-colors">Speakers</a>
                    <a href="#register" class="hover:electric-blue transition-colors">Register</a>
                </div>
                <div class="md:hidden">
                    <button id="mobile-menu-button" class="text-white hover:electric-blue focus:outline-none">
                        <i class="fa-solid fa-bars text-xl animate-fade-in delay-200"></i>
                    </button>
                </div>
            </div>
        </nav>

        <div class="md:hidden hidden" id="mobile-menu">
            <div class="bg-black bg-opacity-90 backdrop-blur-md py-4 px-6 animate-slide-up">
                <a href="#schedule" class="block py-2 hover:electric-blue transition-colors">Schedule</a>
                <a href="#speakers" class="block py-2 hover:electric-blue transition-colors">Speakers</a>
                <a href="#register" class="block py-2 hover:electric-blue transition-colors">Register</a>
            </div>
        </div>
    </header>

    <section class="hero-section hero-bg-gradient py-32 md:py-48 relative overflow-hidden">
        <div class="absolute inset-0 bg-black opacity-70"></div>
        <div class="container mx-auto px-6 relative z-10">
            <div class="grid md:grid-cols-2 gap-8 items-center">
