<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Futuristic Productivity App</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600;700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <script src="https://unpkg.com/lucide@latest"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>
    <style>
        body {
            font-family: 'Inter', sans-serif;
        }
        h1, h2, h3, h4, h5, h6 {
            font-family: 'Poppins', sans-serif;
        }
        .hero-section {
            background: linear-gradient(145deg, #1e293b, #334155);
        }
        .feature-icon {
            filter: drop-shadow(0 0 10px rgba(0, 207, 191, 0.7));
        }
        .task-list-item {
            background: rgba(255, 255, 255, 0.05);
            backdrop-filter: blur(10px);
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
        }
        .demo-video-overlay {
            background: rgba(0, 0, 0, 0.7);
        }
        .btn-accent {
            background-color: #00cfbf;
            color: #1e293b;
            box-shadow: 0 4px 6px rgba(0, 207, 191, 0.3);
        }
        .btn-accent:hover {
            background-color: #00e8d7;
            box-shadow: 0 6px 8px rgba(0, 207, 191, 0.5);
            transform: translateY(-2px);
        }
        .shadow-cool {
            box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.2), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
        }
        .vibrant-border {
            border-color: #00cfbf;
        }
        .pulse-vibrant {
            animation: pulse-vibrant-animation 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulse-vibrant-animation {
            0%, 100% {
                opacity: 1;
            }
            50% {
                opacity: 0.7;
            }
        }
        .slide-in-left {
            animation: slide-in-left-animation 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
        }
        @keyframes slide-in-left-animation {
            0% {
                transform: translateX(-50px);
                opacity: 0;
            }
            100% {
                transform: translateX(0);
                opacity: 1;
            }
        }
        .slide-in-right {
            animation: slide-in-right-animation 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
        }
        @keyframes slide-in-right-animation {
            0% {
                transform: translateX(50px);
                opacity: 0;
            }
            100% {
                transform: translateX(0);
                opacity: 1;
            }
        }
        .fade-in {
            animation: fade-in-animation 1s ease-out both;
        }
        @keyframes fade-in-animation {
            0% {
                opacity: 0;
            }
            100% {
                opacity: 1;
            }
        }
    </style>
</head>
<body class="bg-gray-900 text-gray-300">

    <div class="hero-section relative overflow-hidden">
        <div class="absolute inset-0 bg-gradient-to-br from-gray-900 to-gray-800 opacity-70"></div>
        <div class="container mx-auto px-6 py-24 relative z-10">
            <div class="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
                <div class="text-center md:text-left">
                    <h1 class="text-5xl md:text-6xl font-bold text-white mb-6 slide-in-left">
                        Reimagine Productivity.
                        <span class="text-cyan-500">Effortlessly.</span>
                    </h1>
                    <p class="text-lg mb-8 slide-in-left" style="animation-delay: 0.2s;">
                        The future of personal task management is here. Streamline your day, conquer your goals, and achieve peak efficiency with our intuitive app.
                    </p>
                    <div class="space-x-4 mb-12 md:mb-0 slide-in-left" style="animation-delay: 0.4s;">
                        <button class="btn-accent font-bold py-3 px-6 rounded-full hover:shadow-lg transition-all duration-200">
                            Get Started Free
                        </button>
                        <button class="bg-transparent border border-gray-400 text-gray-300 py-3 px-6 rounded-full hover:border-cyan-500 hover:text-cyan-500 transition-colors duration-200">
