```html
<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Aether Watches - Exquisite Timepieces</title>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700&family=Roboto:wght@400;500&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="YOUR-SRI-HASH-HERE" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>
    <style>
        body {
            font-family: 'Roboto', sans-serif;
        }
        h1, h2, h3, h4, h5, h6, .font-serif {
            font-family: 'Playfair Display', serif;
        }
        .zoom-container {
            overflow: hidden;
        }
        .zoom-container img {
            transition: transform 0.3s ease;
        }
        .zoom-container:hover img {
            transform: scale(1.1);
        }
        .product-card {
            overflow: hidden;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .product-card:hover {
            transform: scale(1.05);
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
        }
        .hero-gradient {
            background: linear-gradient(160deg, #f0f0f0 30%, #e0e0e0 70%);
        }
        .pulse-icon {
            animation: pulse 2s infinite;
        }
        @keyframes pulse {
            0% { transform: scale(1); opacity: 1; }
            50% { transform: scale(1.2); opacity: 0.7; }
            100% { transform: scale(1); opacity: 1; }
        }
        .fade-in-section {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 1s ease-out, transform 1s ease-out;
        }
        .fade-in-section.active {
            opacity: 1;
            transform: translateY(0);
        }
        .slide-up {
            transform: translateY(50px);
            opacity: 0;
            transition: transform 0.8s ease-out, opacity 0.8s ease-out;
        }

        .slide-up.active {
            transform: translateY(0);
            opacity: 1;
        }
        .hero-text-shadow {
            text-shadow: 2px 2px 4px rgba(0,0,0,0.2);
        }
        .luxury-button {
            background-color: #2d3748;
            color: #fff;
            padding: 1rem 2rem;
            border-radius: 0.5rem;
            transition: background-color 0.3s ease, transform 0.3s ease;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
            font-weight: 500;
            box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
        }

        .luxury-button:hover {
            background-color: #1a202c;
            transform: scale(1.05);
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
        }
        .underline-animation {
            position: relative;
            overflow: hidden;
            display: inline-block;
        }

        .underline-animation::after {
            content: '';
            position: absolute;
            left: 0;
            bottom: -2px;
            width: 100%;
            height: 2px;
            background-color: #4b5563;
            transform: scaleX(0);
            transform-origin: left;
            transition: transform 0.3s ease;
        }

        .underline-animation:hover::after {
            transform: scaleX(1);
        }

        .product-image-gallery {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 0.5rem;
        }

        .product-image-gallery img {
            border-radius: 0.25rem;
            cursor: pointer;
            transition: border-color 0.3s ease;
            border: 2px solid transparent;
        }

        .product-image-gallery img.active,
        .product-image-gallery img:hover {
            border-color: #718096;
        }
        .interactive-zoom-container {
            position: relative;
            overflow: hidden;
            cursor: zoom-in;
        }

        .interactive-zoom-container img {
            transition: transform 0.5s ease;
            display: block;
            width: 100%;
            height: auto;
        }

        .interactive-zoom-container.zoomed {
            cursor: zoom-out;
        }

        .interactive-zoom-container.zoomed img {
            transform: scale(2); /* Adjust zoom level as needed */
            transform-origin: top left; /* Zoom from top left */
        }

        .interactive-zoom-container.zoomed::before {
            content: '';
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.8); /* Darken background when zoomed */
            z-index: 10; /* Ensure overlay is above other content */
        }

        .interactive-zoom-container.zoomed img {
            position: relative;
            z-index: 11; /* Ensure image is above overlay */
        }
        .product-option {
            padding: 0.75rem 1.25rem;
            border-radius: 0.375rem;
            border: 1px solid #d2d6dc;
            cursor: pointer;
            transition: border-color 0.3s ease, background-color 0.3s ease;
        }

        .product-option.active,
        .product-option:hover {
            border-color: #718096;
            background-color: #f0f0f0;
        }

        .product-option.active {
            font-weight: 500;
        }
        .animated-underline {
            position: relative;
            display: inline-block;
        }

        .animated-underline::after {
            content: '';
            position: absolute;
            left: 0;
            bottom: -4px;
            width: 100%;
            height: 4px;
            background-color: #718096;
            border-radius: 2px;
            transform: scaleX(0);
            transform-origin: left;
            transition: transform 0.5s cubic-bezier(0.77, 0, 0.175, 1); /* More sophisticated ease */
        }

        .animated-underline:hover::after {
            transform: scaleX(1);
        }
        .swatch {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            border: 2px solid transparent;
            cursor: pointer;
            transition: border-color 0.3s ease, transform 0.2s ease;
        }

        .swatch.active,
        .swatch:hover {
            border-color: #718096;
            transform: scale(1.1);
        }

        .swatch.active {
            border-width: 3px;
        }
        .product-details-enter-active, .product-details-leave-active {
            transition: opacity 0.5s, transform 0.5s;
        }

        .product-details-enter-from, .product-details-leave-to {
            opacity: 0;
            transform: translateY(-20px);
        }
    </style>
</head>
