    <script>
        const carouselTrack = document.getElementById('collectionCarouselTrack');
        const carouselItems = document.querySelectorAll('.carousel-item');
        let currentIndex = 0;
        const itemWidth = carouselItems[0].offsetWidth;
        const itemsToShow = 3;

        function updateCarousel() {
            carouselTrack.style.transform = `translateX(-${currentIndex * itemWidth}px)`;
        }

        function nextCarousel() {
            currentIndex = Math.min(currentIndex + 1, carouselItems.length - itemsToShow);
            updateCarousel();
        }

        function prevCarousel() {
            currentIndex = Math.max(currentIndex - 1, 0);
            updateCarousel();
        }

        gsap.from('.hero-content h1', {opacity: 0, y: 50, duration: 1, ease: 'power3.out'});
        gsap.from('.hero-content p', {opacity: 0, y: 30, duration: 1, delay: 0.2, ease: 'power3.out'});
        gsap.from('.hero-content button', {opacity: 0, y: 30, duration: 1, delay: 0.4, ease: 'power3.out'});

        gsap.utils.toArray('.carousel-item').forEach(item => {
            gsap.from(item, {
                opacity: 0,
                x: 50,
                duration: 1,
                scrollTrigger: {
                    trigger: item,
                    start: "top 80%",
                    end: "bottom 20%",
                    toggleActions: "play none none reverse"
                }
            });
        });
    </script>

</body>
