            0% { transform: translate(0, 0); }
            100% { transform: translate(-100%, 0); }
        }
        .animate-fade-in {
            animation: fadein 0.5s ease-in-out forwards;
            opacity: 0;
        }
        @keyframes fadein {
            to { opacity: 1; }
        }
        .news-card {
            transition: transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out;
