            font-weight: 500;
        }
        .headline-animated {
            position: relative;
            overflow: hidden;
            line-height: 1.2;
        }
        .headline-animated::after {
            content: '';
            position: absolute;
            left: 0;
            bottom: 0;
            width: 100%;
            height: 4px;
            background-color: #3b82f6;
            transform: scaleX(0);
            transform-origin: left;
            transition: transform 0.4s ease-out;
        }
        .headline-animated:hover::after {
            transform: scaleX(1);
        }

    </style>
