            <div class="news-card bg-white rounded-lg shadow-md overflow-hidden">
                <div class="relative">
                    <img src="https://picsum.photos/200/300?random=5" alt="News Image" class="w-full h-48 object-cover">
                    <span class="category-badge bg-red-500 text-white">World</span>
                </div>
                <div class="p-4">
                    <h3 class="text-xl font-semibold mb-2 headline-animated"><a href="#">International Climate Summit Opens Amidst Urgent Calls for Action</a></h3>
                    <p class="text-gray-700 text-sm">World leaders gather to discuss strategies for combating climate change and its impacts.</p>
                    <div class="mt-4 flex justify-between items-center">
