                    <div class="mt-4 flex justify-between items-center">
                        <span class="text-gray-600 text-xs">2 days ago</span>
                        <a href="#" class="text-blue-600 hover:underline text-sm">Read More</a>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <section id="infinite-scroll-container">
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6" id="news-feed">
            </div>
        <div class="text-center py-4" id="loading-indicator">
            <p class="text-gray-500">Loading more news...</p>
        </div>
    </section>
</main>

<footer class="bg-gray-900 text-gray-300 py-8">
    <div class="container mx-auto px-4 flex justify-between items-center">
        <p>&copy; 2024 Apex News. All rights reserved.</p>
        <div class="space-x-4">
            <a href="#" class="hover:text-white">About</a>
            <a href="#" class="hover:text-white">Contact</a>
            <a href="#" class="hover:text-white">Privacy Policy</a>
        </div>
    </div>
</footer>

<script>
    const mobileMenuButton = document.getElementById('mobile-menu-button');
    const mobileMenu = document.getElementById('mobile-menu');

    mobileMenuButton.addEventListener('click', () => {
        mobileMenu.classList.toggle('hidden');
    });

    let page = 1;
    const newsFeed = document.getElementById('news-feed');
    const loadingIndicator = document.getElementById('loading-indicator');
    const imageWidth = 200;
    const imageHeight = 300;

    const categories = ['World', 'Technology', 'Business', 'Sports'];
    const categoryColors = ['red', 'green', 'purple', 'orange'];

    function createNewsCard(index) {
        const categoryIndex = index % categories.length;
        const category = categories[categoryIndex];
        const color = categoryColors[categoryIndex];
        const randomNum = Math.floor(Math.random() * 1000);

        const card = document.createElement('div');
        card.className = 'news-card bg-white rounded-lg shadow-md overflow-hidden animate-fade-in';
        card.innerHTML = `
            <div class="relative">
                <img src="https://picsum.photos/${imageWidth}/${imageHeight}?random=${randomNum + index}" alt="News Image" class="w-full h-48 object-cover">
                <span class="category-badge bg-${color}-500 text-white">${category}</span>
            </div>
            <div class="p-4">
                <h3 class="text-xl font-semibold mb-2 headline-animated"><a href="#">Placeholder News Headline ${index + 1}</a></h3>
                <p class="text-gray-700 text-sm">This is a sample news description for card number ${index + 1}. More details to come as you read further.</p>
                <div class="mt-4 flex justify-between items-center">
                    <span class="text-gray-600 text-xs">${Math.floor(Math.random() * 24) + 1} hours ago</span>
                    <a href="#" class="text-blue-600 hover:underline text-sm">Read More</a>
                </div>
            </div>
        `;
        return card;
    }

    function loadMoreNews() {
        loadingIndicator.classList.remove('hidden');
        setTimeout(() => {
            loadingIndicator.classList.add('hidden');
            for (let i = 0; i < 6; i++) {
                newsFeed.appendChild(createNewsCard(page * 6 + i));
            }
            page++;
        }, 1000);
    }

    loadMoreNews();

    const infiniteScrollContainer = document.getElementById('infinite-scroll-container');

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                loadMoreNews();
            }
        });
    }, {
        root: null,
        rootMargin: '0px',
        threshold: 0.1
    });

    observer.observe(loadingIndicator);

</script>

</body>
</html>
