            duration: 1,
            ease: 'power2.out',
            scrollTrigger: {
                trigger: '#about',
                start: 'top 70%',
                once: true
            }
        });

        gsap.from('#about > div > div:last-child', {
            x: 50,
            opacity: 0,
            duration: 1,
            ease: 'power2.out',
            scrollTrigger: {
                trigger: '#about',
                start: 'top 70%',
                once: true
            }
        });

        gsap.from('#contact .container > *', {
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.15,
            ease: 'power2.out',
            scrollTrigger: {
                trigger: '#contact',
                start: 'top 80%',
                once: true
            }
        });


    </script>

</body>
</html>
