    <script>
        const businessCards = document.querySelectorAll('.business-card');
        businessCards.forEach(card => {
            const expandButton = card.querySelector('.expand-button');
            const profileSection = card.querySelector('.business-profile');
            const icon = expandButton.querySelector('i');

            expandButton.addEventListener('click', () => {
                profileSection.classList.toggle('expanded');
                icon.classList.toggle('rotate-180');
            });
        });

        const categoryFilter = document.getElementById('category-filter');
        const locationFilter = document.getElementById('location-filter');
        const filterButton = document.getElementById('filter-button');
        const resetButton = document.getElementById('reset-button');
        const listingsSection = document.getElementById('business-listings');

        let allListingsData = Array.from(listingsSection.children).map(listing => {
            return {
                element: listing,
                category: listing.querySelector('.business-category').textContent.toLowerCase(),
                name: listing.querySelector('.business-name').textContent.toLowerCase(),
                location: listing.querySelector('.business-location').textContent.toLowerCase(),
                description: listing.querySelector('.business-description').textContent.toLowerCase()
            };
        });

        function applyFilters() {
            const selectedCategory = categoryFilter.value;
            const selectedLocation = locationFilter.value.toLowerCase();

            listingsSection.innerHTML = '';

            const filteredListings = allListingsData.filter(business => {
                const categoryMatch = selectedCategory === '' || business.category === selectedCategory;
                const locationMatch = selectedLocation === '' || business.location.includes(selectedLocation) || business.name.includes(selectedLocation) || business.description.includes(selectedLocation);
                return categoryMatch && locationMatch;
            });

            if (filteredListings.length === 0) {
                listingsSection.innerHTML = '<p class="text-gray-600">No businesses found matching your criteria.</p>';
            } else {
                filteredListings.forEach(business => {
                    listingsSection.appendChild(business.element.cloneNode(true));
                });
                // Re-initialize expand buttons for cloned elements
                const newBusinessCards = listingsSection.querySelectorAll('.business-card');
                newBusinessCards.forEach(card => {
                    const expandButton = card.querySelector('.expand-button');
                    const profileSection = card.querySelector('.business-profile');
                    const icon = expandButton.querySelector('i');

                    expandButton.addEventListener('click', () => {
                        profileSection.classList.toggle('expanded');
                        icon.classList.toggle('rotate-180');
                    });
                });
            }
        }


        filterButton.addEventListener('click', applyFilters);
        resetButton.addEventListener('click', () => {
            categoryFilter.value = '';
            locationFilter.value = '';
            applyFilters();
        });

        categoryFilter.addEventListener('change', () => {
            listingsSection.classList.add('opacity-50');
            setTimeout(() => {
                applyFilters();
                listingsSection.classList.remove('opacity-50');
                listingsSection.classList.add('transition-opacity', 'duration-300');
                setTimeout(() => {
                    listingsSection.classList.remove('transition-opacity', 'duration-300');
                }, 300);
            }, 300);
        });

        locationFilter.addEventListener('input', () => {
            listingsSection.classList.add('opacity-50');
            setTimeout(() => {
                applyFilters();
                listingsSection.classList.remove('opacity-50');
                listingsSection.classList.add('transition-opacity', 'duration-300');
                setTimeout(() => {
                    listingsSection.classList.remove('transition-opacity', 'duration-300');
                }, 300);
            }, 300);
        });


    </script>

</body>
</html>
