            inset: 0;
            background: linear-gradient(180deg, rgba(249, 250, 247, 0.8) 0%, rgba(249, 250, 247, 1) 100%);
            pointer-events: none;
        }
        .solar-panel {
            position: absolute;
            width: 50px;
            height: 70px;
            background-color: #34D399;
            clip-path: polygon(0% 0%, 100% 0%, 100% 80%, 50% 100%, 0% 80%);
            animation: float 5s infinite alternate, glow 3s infinite alternate;
        }
        .solar-panel::before {
            content: '';
            position: absolute;
            inset: 5px;
            background-color: #059669;
            clip-path: polygon(0% 0%, 100% 0%, 100% 80%, 50% 100%, 0% 80%);
        }
        @keyframes float {
            0% { transform: translateY(0); }
            100% { transform: translateY(-15px); }
        }
        @keyframes glow {
            0% { box-shadow: 0 0 5px rgba(52, 211, 153, 0.8); }
            100% { box-shadow: 0 0 20px rgba(52, 211, 153, 0.8); }
        }
        .investment-calculator {
            background-color: rgba(255, 255, 255, 0.9);
            backdrop-filter: blur(10px);
            border-radius: 1rem;
            padding: 2rem;
            box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1);
        }
        .input-field {
            background-color: rgba(243, 244, 246, 0.5);
            border-radius: 0.5rem;
            padding: 0.75rem;
            border: 1px solid transparent;
            transition: border-color 0.3s ease;
        }
        .input-field:focus {
            outline: none;
            border-color: #6EE7B7;
            box-shadow: 0 0 0 2px rgba(110, 231, 183, 0.3);
        }
        .calculate-button {
            background-color: #059669;
            color: white;
            padding: 0.75rem 1.5rem;
            border-radius: 0.5rem;
            transition: background-color 0.3s ease, transform 0.2s ease;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
        }
        .calculate-button:hover {
            background-color: #047857;
            transform: scale(1.05);
        }
        .calculate-button:active {
            transform: scale(0.95);
        }
        .animated-underline {
            position: relative;
            display: inline-block;
        }
        .animated-underline::after {
            content: '';
            position: absolute;
            left: 0;
            bottom: -2px;
            width: 100%;
            height: 2px;
            background-color: #34D399;
            transform: scaleX(0);
            transform-origin: left;
            transition: transform 0.3s ease-in-out;
        }
        .animated-underline:hover::after {
            transform: scaleX(1);
        }
        .feature-card {
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .feature-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 30px -10px rgba(0, 0, 0, 0.2);
