            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
        }
        .cta-button:hover {
            background-color: #059669;
            transform: scale(1.03);
            box-shadow: 0 8px 15px rgba(0, 0, 0, 0.2);
        }
        .cta-button:active {
            transform: scale(0.98);
        }
        .secondary-button {
            border: 2px solid #34D399;
