                    <button type="submit" class="calculate-button w-full">Send Message</button>
                </form>
            </div>
        </div>
    </section>

    <footer class="bg-gray-800 text-white py-12">
        <div class="container mx-auto px-6 flex justify-between items-center">
            <div>
                &copy; 2024 RenewTech. All rights reserved.
            </div>
            <div class="flex space-x-4">
                <a href="#" class="hover:text-green-300"><i class="fab fa-facebook-f"></i></a>
                <a href="#" class="hover:text-green-300"><i class="fab fa-twitter"></i></a>
                <a href="#" class="hover:text-green-300"><i class="fab fa-instagram"></i></a>
            </div>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            gsap.from('.hero-section > div > div > *', {
                y: 30,
                opacity: 0,
                stagger: 0.2,
                duration: 1,
                ease: 'power2.out'
            });

            const panels = document.querySelectorAll('.solar-panel');
            panels.forEach(panel => {
                gsap.to(panel, {
                    y: -10,
                    repeat: -1,
                    yoyo: true,
                    duration: 3,
                    ease: 'sine.inOut',
                    delay: parseFloat(panel.style.animationDelay || 0)
                });
            });
        });

        function calculateInvestment() {
            const energyConsumption = parseFloat(document.getElementById('energyConsumption').value);
            const investmentAmount = parseFloat(document.getElementById('investmentAmount').value);

            if (isNaN(energyConsumption) || isNaN(investmentAmount)) {
                alert('Please enter valid numbers for energy consumption and investment amount.');
                return;
            }

            const savings = energyConsumption * 0.15 * 12;
            const roi = (savings / investmentAmount) * 100;

            document.getElementById('savingsEstimate').textContent = `Estimated annual savings: $${savings.toFixed(2)}`;
            document.getElementById('roiEstimate').textContent = `Return on investment (ROI): ${roi.toFixed(2)}%`;
            document.getElementById('calculationResults').classList.remove('hidden');
        }

        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });
    </script>

</body>
</html>
