            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });

        function showStep(stepId) {
            document.querySelectorAll('.ticket-step').forEach(step => {
                step.classList.add('hidden');
            });
            document.getElementById(stepId).classList.remove('hidden');
            document.querySelectorAll('.ticket-flow-step').forEach(stepDot => {
                stepDot.classList.remove('active');
            });
            document.querySelector(`.ticket-flow-step.${stepId}`).classList.add('active');
             gsap.fromTo(`#${stepId}`, {opacity: 0, y: 20}, {opacity: 1, y: 0, duration: 0.5, ease: "power2.out"});
        }

        function nextStep(stepId) {
            const currentStep = document.querySelector('.ticket-flow-step.active');
            currentStep.classList.remove('active');
            const nextStepElement = document.querySelector(`.ticket-flow-step.${stepId}`);
            nextStepElement.classList.add('active');


            document.querySelectorAll('.ticket-step').forEach(step => {
                step.classList.add('hidden');
            });
            document.getElementById(stepId).classList.remove('hidden');
            gsap.fromTo(`#${stepId}`, {opacity: 0, y: 20}, {opacity: 1, y: 0, duration: 0.5, ease: "power2.out"});
        }


        gsap.registerPlugin(ScrollTrigger);

        gsap.utils.toArray('section').forEach(section => {
            gsap.from(section.querySelector('h2'), {
                y: 50,
                opacity: 0,
                duration: 1,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: section,
                    start: "top 80%",
                    end: "top 20%",
                    toggleActions: "play none none reverse"
                }
            });
             gsap.from(section.querySelectorAll('.shadow-lg'), {
                y: 50,
                opacity: 0,
                duration: 1,
                stagger: 0.2,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: section,
                    start: "top 80%",
                    end: "top 20%",
                    toggleActions: "play none none reverse"
                }
            });
        });
    </script>

</body>
</html>
