</div>

<script>
    const darkModeToggle = document.getElementById('dark-mode-toggle');
    const darkModeIcon = document.getElementById('dark-mode-icon');
    const html = document.documentElement;
    let darkMode = localStorage.getItem('darkMode') === 'true' || (!('darkMode' in localStorage) && window.matchMedia('(prefers-color-scheme: dark)').matches);

    const setDarkMode = (isDark) => {
        if (isDark) {
            html.classList.add('dark');
            darkModeIcon.classList.remove('fa-moon');
            darkModeIcon.classList.add('fa-sun');
        } else {
            html.classList.remove('dark');
            darkModeIcon.classList.remove('fa-sun');
            darkModeIcon.classList.add('fa-moon');
        }
        localStorage.setItem('darkMode', isDark);
    };

    setDarkMode(darkMode);

    darkModeToggle.addEventListener('click', () => {
        darkMode = !darkMode;
        setDarkMode(darkMode);
        darkModeToggle.classList.add('dark-mode-toggle-active');
        setTimeout(() => {
            darkModeToggle.classList.remove('dark-mode-toggle-active');
        }, 300);
    });

    const sidebar = document.getElementById('sidebar');
    const sidebarToggleDesktop = document.getElementById('sidebar-toggle-desktop');
    const sidebarToggleMobile = document.getElementById('sidebar-toggle-mobile');

    const toggleSidebar = () => {
        sidebar.classList.toggle('sidebar-expanded');
        sidebar.classList.toggle('sidebar-collapsed');
    };

    sidebarToggleDesktop.addEventListener('click', toggleSidebar);
    sidebarToggleMobile.addEventListener('click', toggleSidebar);

    if (window.innerWidth < 768) {
        sidebar.classList.remove('sidebar-expanded');
        sidebar.classList.add('sidebar-collapsed');
    } else {
        sidebar.classList.remove('sidebar-collapsed');
        sidebar.classList.add('sidebar-expanded');
    }

    window.addEventListener('resize', () => {
        if (window.innerWidth < 768) {
            sidebar.classList.remove('sidebar-expanded');
            sidebar.classList.add('sidebar-collapsed');
        } else {
            sidebar.classList.remove('sidebar-collapsed');
            sidebar.classList.add('sidebar-expanded');
        }
    });


</script>

</body>
</html>
