            <div>
                <h4 class="font-bold text-lg mb-4 font-['Playfair_Display']">Quick Links</h4>
                <ul class="space-y-2">
                    <li><a href="#hero" class="footer-link hover:underline">Hero</a></li>
                    <li><a href="#timeline" class="footer-link hover:underline">Timeline</a></li>
                    <li><a href="#artifacts" class="footer-link hover:underline">Artifacts</a></li>
