<script>
    document.addEventListener('DOMContentLoaded', () => {
        const counters = document.querySelectorAll('.metric-counter');
        const speed = 200;

        counters.forEach(counter => {
            const target = parseInt(counter.getAttribute('data-target'));
            const increment = target / speed;

            function updateCount() {
                const currentCount = parseInt(counter.innerText);
                if (currentCount < target) {
                    counter.innerText = Math.ceil(currentCount + increment);
                    setTimeout(updateCount, 1);
                } else {
                    counter.innerText = target;
                }
            }
            updateCount();
        });

        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenuClose = document.getElementById('mobile-menu-close');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.remove('hidden');
        });

        mobileMenuClose.addEventListener('click', () => {
            mobileMenu.classList.add('hidden');
        });

        const transactionHistorySection = document.getElementById('transaction-history');
        const toggleHistoryButton = document.getElementById('toggle-transaction-history');
        let isCollapsed = false;

        toggleHistoryButton.addEventListener('click', () => {
            isCollapsed = !isCollapsed;
            if (isCollapsed) {
                transactionHistorySection.style.maxHeight = '0';
                transactionHistorySection.style.overflow = 'hidden';
                toggleHistoryButton.innerHTML = '<i class="fa-solid fa-chevron-down mr-2"></i>Expand';
            } else {
                transactionHistorySection.style.maxHeight = '500px';
                transactionHistorySection.style.overflow = 'auto';
                toggleHistoryButton.innerHTML = '<i class="fa-solid fa-chevron-down mr-2"></i>Collapse';
            }
        });
    });
</script>

</body>
</html>
