        }

        .hero-section {
            background: linear-gradient(135deg, #1e293b, #334155);
        }

        .agenda-timeline li::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 2px;
            height: 100%;
            background-color: #6b7280;
            transform: translateX(calc(-50% + 1px));
        }

        .agenda-timeline li:last-child::before {
            height: 50%;
        }

        .agenda-timeline li .timeline-event {
            transform: translateY(-50%);
        }

        .agenda-timeline li:nth-child(odd) .timeline-event {
            left: 0;
            text-align: right;
            padding-right: 20px;
        }

        .agenda-timeline li:nth-child(even) .timeline-event {
            right: 0;
            text-align: left;
            padding-left: 20px;
        }

        .agenda-timeline li .timeline-event::before {
            content: '';
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
            width: 12px;
            height: 12px;
            border-radius: 50%;
            background-color: #f9fafb;
            border: 2px solid #6366f1;
        }

        .agenda-timeline li:nth-child(odd) .timeline-event::before {
            right: -6px;
        }

        .agenda-timeline li:nth-child(even) .timeline-event::before {
            left: -6px;
        }

        .speaker-card:hover .speaker-image {
            transform: scale(1.05);
        }

        .registration-form input:focus,
        .registration-form textarea:focus {
            outline: 2px solid transparent;
            outline-offset: 2px;
            border-color: #6366f1;
