            @apply bg-transparent hover:bg-indigo-500 text-indigo-500 hover:text-white font-bold py-3 px-8 rounded-full transition-colors duration-300 border-2 border-indigo-500 shadow-md;
        }

        .section-title {
            @apply text-4xl font-bold text-gray-900 text-center mb-12;
