    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            let currentSlide = 1;
            const slides = document.querySelectorAll('#recipeCarousel .carousel-slide');
            const recipeTitles = ["Exquisite Tomato Bruschetta", "Creamy Mushroom Risotto", "Decadent Chocolate Tart"];
            const recipeDescriptions = [
                "A classic Italian appetizer with fresh tomatoes and basil on toasted bread.",
                "Rich and flavorful risotto with a blend of wild mushrooms and parmesan cheese.",
                "An intensely chocolatey tart with a buttery crust and ganache filling."
            ];

            function showSlide(n) {
                slides.forEach(slide => slide.classList.add('opacity-0'));
                slides[n - 1].classList.remove('opacity-0');
                document.getElementById('carouselRecipeTitle').textContent = recipeTitles[n-1];
                document.getElementById('carouselRecipeDescription').textContent = recipeDescriptions[n-1];
            }

            function nextSlide() {
                currentSlide = (currentSlide === slides.length) ? 1 : currentSlide + 1;
                showSlide(currentSlide);
            }

            function prevSlide() {
                currentSlide = (currentSlide === 1) ? slides.length : currentSlide - 1;
                showSlide(currentSlide);
            }

            showSlide(currentSlide);
            let carouselInterval = setInterval(nextSlide, 5000);

            document.getElementById('carouselNext').addEventListener('click', () => {
                clearInterval(carouselInterval);
                nextSlide();
                carouselInterval = setInterval(nextSlide, 5000);
            });

            document.getElementById('carouselPrev').addEventListener('click', () => {
                clearInterval(carouselInterval);
                prevSlide();
                carouselInterval = setInterval(nextSlide, 5000);
            });

            gsap.registerPlugin(ScrollTrigger);

            gsap.utils.toArray('section').forEach(section => {
                gsap.from(section.querySelectorAll('.category-card, .recipe-card, .restaurant-card'), {
                    y: 50,
                    opacity: 0,
                    duration: 1,
                    stagger: 0.2,
                    scrollTrigger: {
                        trigger: section,
                        start: "top 80%",
                        end: "top 20%",
                        toggleActions: "play none none reverse"
                    }
                });
            });
        });
    </script>

</body>
</html>
