    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            const filterButton = document.getElementById('filter-button');
            const filtersContainer = document.getElementById('filters-container');
            const filterItems = document.querySelectorAll('.filter-item');
            const productGrid = document.getElementById('product-grid');
            const productCards = Array.from(productGrid.children);

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            filterButton.addEventListener('click', () => {
                filtersContainer.classList.toggle('hidden');
            });

            filterItems.forEach(item => {
                item.addEventListener('click', (e) => {
                    e.preventDefault();
                    const filter = item.dataset.filter;

                    productCards.forEach(card => {
                        const productName = card.querySelector('h3').textContent.toLowerCase();
                        let display = 'none';

                        if (filter === 'all') {
                            display = 'block';
                        } else if (filter === 'fruits' && (productName.includes('apple') || productName.includes('banana'))) {
                            display = 'block';
                        } else if (filter === 'vegetables' && (productName.includes('carrot') || productName.includes('broccoli'))) {
                            display = 'block';
                        } else if (filter === 'dairy' && productName.includes('milk')) {
                            display = 'block';
                        } else if (filter === 'grains' && productName.includes('oats')) {
                            display = 'block';
                        }

                        card.style.display = display;
                    });
                });
            });

            gsap.utils.toArray('.hero-gradient').forEach(section => {
                gsap.from(section.querySelector('h1'), {
                    y: 50,
                    opacity: 0,
                    duration: 1,
                    ease: "power3.out",
                });
                 gsap.from(section.querySelector('p'), {
                    y: 60,
                    opacity: 0,
                    duration: 1.2,
                    ease: "power3.out",
                    delay: 0.2,
                });
                 gsap.from(section.querySelector('button'), {
                    y: 70,
                    opacity: 0,
                    duration: 1.4,
                    ease: "power3.out",
                    delay: 0.4,
                });
            });
        });
    </script>

</body>
</html>
