        }
        h1, h2, h3, h4, h5, h6 {
            font-family: 'Poppins', sans-serif;
            font-weight: 700;
        }
        .lightbox {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.9);
            z-index: 1000;
            display: none;
            justify-content: center;
            align-items: center;
            overflow: auto;
        }
        .lightbox-content {
            max-width: 90%;
            max-height: 90%;
            position: relative;
        }
        .lightbox-content img {
            display: block;
            max-width: 100%;
            max-height: 100%;
        }
        .lightbox-close {
            position: absolute;
            top: 20px;
            right: 20px;
            color: #F9FAFB;
            font-size: 2rem;
            cursor: pointer;
        }
        .project-details {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.5s ease-in-out;
        }
        .project-details.expanded {
            max-height: 500px;
        }
        .grid-image {
            transition: transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out;
        }
        .grid-image:hover {
            transform: scale(1.05);
            box-shadow: 0 10px 20px rgba(0,0,0,0.3);
        }
        .accent-text {
            color: #2DD4CF;
        }
        .accent-bg {
            background-color: #2DD4CF;
        }
        .hover-accent-text:hover .accent-text {
            color: #F9FAFB;
        }
        .hover-accent-bg:hover {
            background-color: #2DD4CF;
        }
        .transition-opacity {
            transition-property: opacity;
            transition-timing-function: ease-in-out;
            transition-duration: 0.3s;
        }
        .shadow-depth-1 {
            box-shadow: 0 4px 6px rgba(0,0,0,0.1), 0 2px 4px rgba(0,0,0,0.06);
        }
        .shadow-depth-2 {
            box-shadow: 0 10px 15px rgba(0,0,0,0.1), 0 4px 6px rgba(0,0,0,0.05);
        }
        .shadow-depth-3 {
            box-shadow: 0 20px 25px rgba(0,0,0,0.1), 0 10px 10px rgba(0,0,0,0.04);
        }
        .animate-fade-in {
            opacity: 0;
            animation: fade-in 1s ease-out forwards;
        }
        @keyframes fade-in {
            from { opacity: 0; }
            to { opacity: 1; }
