    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenuClose = document.getElementById('mobile-menu-close');
        const mobileMenu = document.getElementById('mobile-menu');
        const searchInput = document.getElementById('search-input');
        const searchSuggestions = document.getElementById('search-suggestions');
        const booksGrid = document.getElementById('books-grid');
        const filterButtons = document.querySelectorAll('.filter-button');
        const bookCards = Array.from(booksGrid.children);

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.remove('hidden');
        });

        mobileMenuClose.addEventListener('click', () => {
            mobileMenu.classList.add('hidden');
        });

        searchInput.addEventListener('input', () => {
            const searchTerm = searchInput.value.toLowerCase();
            searchSuggestions.innerHTML = '';
            if (!searchTerm) {
                searchSuggestions.classList.add('hidden');
                return;
            }

            const suggestions = getSearchSuggestions(searchTerm);
            if (suggestions.length > 0) {
                suggestions.forEach(suggestion => {
                    const suggestionItem = document.createElement('div');
                    suggestionItem.textContent = suggestion;
                    suggestionItem.classList.add('search-suggestion', 'px-4', 'py-2', 'cursor-pointer');
                    suggestionItem.addEventListener('click', () => {
                        searchInput.value = suggestion;
                        searchSuggestions.classList.add('hidden');
                        // Implement search functionality here if needed
                    });
                    searchSuggestions.appendChild(suggestionItem);
                });
                searchSuggestions.classList.remove('hidden');
            } else {
                searchSuggestions.classList.add('hidden');
            }
        });

        function getSearchSuggestions(searchTerm) {
            const allBookTitles = Array.from(booksGrid.querySelectorAll('.book-card h3')).map(h3 => h3.textContent.toLowerCase());
            return allBookTitles.filter(title => title.includes(searchTerm)).slice(0, 5);
        }

        filterButtons.forEach(button => {
            button.addEventListener('click', () => {
                filterButtons.forEach(btn => btn.classList.remove('filter-active', 'button-primary'));
                filterButtons.forEach(btn => btn.classList.add('button-secondary'));
                button.classList.remove('button-secondary');
                button.classList.add('filter-active', 'button-primary');

                const filterValue = button.dataset.filter;
                bookCards.forEach(card => {
                    if (filterValue === 'all' || card.dataset.category === filterValue) {
                        card.classList.remove('hidden');
                    } else {
                        card.classList.add('hidden');
                    }
                });
            });
        });
    </script>

</body>
</html>
