            <img src="" alt="Floor Plan" class="floor-plan-image" id="floorPlanImage">
        </div>
    </div>

    <script>
        document.querySelectorAll('.project-floor-plan-button').forEach(button => {
            button.addEventListener('click', function() {
                const floorPlanName = this.getAttribute('data-floorplan');
                const floorPlanOverlay = document.getElementById('floorPlanOverlay');
                const floorPlanImage = document.getElementById('floorPlanImage');
                floorPlanImage.src = `https://picsum.photos/600/400?floorplan=${floorPlanName}`;
                floorPlanOverlay.style.display = 'flex';
            });
        });

        function closeFloorPlan() {
            document.getElementById('floorPlanOverlay').style.display = 'none';
        }

        document.addEventListener('DOMContentLoaded', () => {
            const navLinks = document.querySelectorAll('.nav-link');

            navLinks.forEach(link => {
                link.addEventListener('click', function(e) {
                    navLinks.forEach(nl => nl.classList.remove('active-nav-link'));
                    this.classList.add('active-nav-link');
                });
            });
        });
    </script>
</body>
</html>
