    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        const bookCarouselSlider = document.getElementById('bookCarouselSlider');
        const carouselPrev = document.getElementById('carouselPrev');
        const carouselNext = document.getElementById('carouselNext');
        let bookIndex = 0;
        const bookWidth = 200 + 16; // image width + mx-2 * 2
        const totalBooks = bookCarouselSlider.children.length;

        carouselNext.addEventListener('click', () => {
            bookIndex = (bookIndex + 1) % totalBooks;
            updateCarousel();
        });

        carouselPrev.addEventListener('click', () => {
            bookIndex = (bookIndex - 1 + totalBooks) % totalBooks;
            updateCarousel();
        });

        function updateCarousel() {
            bookCarouselSlider.style.transform = `translateX(${-bookIndex * bookWidth}px)`;
        }

        setInterval(() => {
            bookIndex = (bookIndex + 1) % totalBooks;
            updateCarousel();
        }, 5000);

        const planOptions = document.querySelectorAll('.plan-option');
        planOptions.forEach(plan => {
            plan.addEventListener('click', () => {
                planOptions.forEach(p => p.classList.remove('active'));
                plan.classList.add('active');
            });
        });
    </script>

</body>
</html>
