    <script>
        const darkModeToggle = document.getElementById('darkModeToggle');
        const darkModeToggleMobile = document.getElementById('darkModeToggleMobile');
        const body = document.body;
        const mobileMenuButton = document.getElementById('mobileMenuButton');
        const mobileMenu = document.getElementById('mobileMenu');

        darkModeToggle.addEventListener('click', () => {
            body.classList.toggle('dark-mode');
            body.classList.toggle('light-mode');
            updateToggleThumbPosition(darkModeToggle);
        });
        darkModeToggleMobile.addEventListener('click', () => {
            body.classList.toggle('dark-mode');
            body.classList.toggle('light-mode');
            updateToggleThumbPosition(darkModeToggleMobile);
        });

        function updateToggleThumbPosition(toggleButton) {
            const thumb = toggleButton.querySelector('.toggle-thumb');
            if (body.classList.contains('dark-mode')) {
                thumb.style.transform = 'translateX(100%)';
            } else {
                thumb.style.transform = 'translateX(0)';
            }
        }
        updateToggleThumbPosition(darkModeToggle);
        updateToggleThumbPosition(darkModeToggleMobile);


        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        let timerInterval;
        let timeLeft;
        const minutesInput = document.getElementById('minutesInput');
        const secondsInput = document.getElementById('secondsInput');
        const startButton = document.getElementById('startTimer');
        const pauseButton = document.getElementById('pauseTimer');
        const resetButton = document.getElementById('resetTimer');
        const countdownDisplay = document.getElementById('countdownDisplay');

        function updateDisplay() {
            const minutes = Math.floor(timeLeft / 60);
            const seconds = timeLeft % 60;
            countdownDisplay.textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
        }

        function startTimer() {
            let minutes = parseInt(minutesInput.value, 10) || 0;
            let seconds = parseInt(secondsInput.value, 10) || 0;
            timeLeft = minutes * 60 + seconds;

            if (timeLeft <= 0) {
                alert("Please enter a valid time.");
                return;
            }

            minutesInput.disabled = true;
            secondsInput.disabled = true;
            startButton.disabled = true;
            pauseButton.disabled = false;
            resetButton.disabled = false;

            updateDisplay();
            timerInterval = setInterval(() => {
                timeLeft--;
                updateDisplay();
                if (timeLeft <= 0) {
                    clearInterval(timerInterval);
                    pauseButton.disabled = true;
                    resetButton.disabled = false;
                    countdownDisplay.textContent = "00:00";
                    alert("Meditation session complete!");
                }
            }, 1000);
        }

        function pauseTimer() {
            clearInterval(timerInterval);
            startButton.disabled = false;
            pauseButton.disabled = true;
            resetButton.disabled = false;
        }

        function resetTimer() {
            clearInterval(timerInterval);
            minutesInput.disabled = false;
            secondsInput.disabled = false;
            startButton.disabled = false;
            pauseButton.disabled = true;
            resetButton.disabled = true;
            minutesInput.value = '10';
            secondsInput.value = '0';
            updateDisplay();
        }

        startButton.addEventListener('click', startTimer);
        pauseButton.addEventListener('click', pauseTimer);
        resetButton.addEventListener('click', resetTimer);
        updateDisplay();

        gsap.registerPlugin(ScrollTrigger);

        gsap.from('.hero-section h1', {
            y: 50,
            opacity: 0,
            duration: 1,
            ease: "power3.out"
        });
        gsap.from('.hero-section p', {
            y: 30,
            opacity: 0,
            duration: 1,
            delay: 0.3,
            ease: "power3.out"
        });
        gsap.from('.hero-section button', {
            y: 30,
            opacity: 0,
            duration: 1,
            delay: 0.6,
            ease: "power3.out"
        });

        gsap.utils.toArray('.session-card').forEach(card => {
            gsap.from(card, {
                y: 50,
                opacity: 0,
                duration: 1,
                scrollTrigger: {
                    trigger: card,
                    start: "top 80%",
                    end: "top 20%",
                    toggleActions: "play none none reverse"
                }
            });
        });
        gsap.from('#timer h2', {
            y: 50,
            opacity: 0,
            duration: 1,
            scrollTrigger: {
                trigger: '#timer',
                start: "top 80%",
                end: "top 20%",
                toggleActions: "play none none reverse"
            }
        });
        gsap.from('#timer .flex', {
            y: 30,
            opacity: 0,
            duration: 1,
            delay: 0.3,
            scrollTrigger: {
                trigger: '#timer',
                start: "top 80%",
                end: "top 20%",
                toggleActions: "play none none reverse"
            }
        });
        gsap.from('#timer #countdownDisplay', {
            y: 30,
            opacity: 0,
            duration: 1,
            delay: 0.6,
            scrollTrigger: {
                trigger: '#timer',
                start: "top 80%",
                end: "top 20%",
                toggleActions: "play none none reverse"
            }
        });


    </script>
</body>
</html>
