            box-shadow: 0 0 1em rgba(0, 255, 255, 0.5);
        }
        .gallery-item {
            transition: transform 0.3s ease, opacity 0.3s ease;
        }
        .gallery-item:hover {
            transform: scale(1.1);
            opacity: 0.9;
        }
        .hero-background {
            background: radial-gradient(circle at center, #1E1E1E 0%, #121212 70%);
        }
        .transition-fade {
            transition: opacity 0.5s ease-in-out;
        }
        .gradient-bg {
            background: linear-gradient(45deg, #1e40af, #3b82f6, #60a5fa, #a78bfa, #e879f9, #f472b6, #fb7185, #f97316, #f59e0b, #eab308);
            background-size: 600% 600%;
            animation: gradientAnimation 30s ease infinite;
        }
        @keyframes gradientAnimation {
            0%{background-position:0% 50%}
            50%{background-position:100% 50%}
            100%{background-position:0% 50%}
        }

    </style>
</head>
