    <link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;700&family=DM+Sans:wght@400;500&display=swap" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin=""/>
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCkoUJxwCygnJfCPUZYSaa10ZTjbEOo-RfPxk+u5=" crossorigin=""></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
    <style>
        body { font-family: 'DM Sans', sans-serif; }
        h1, h2, h3 { font-family: 'Montserrat', sans-serif; }
        .hero-section {
            background: linear-gradient(135deg, #60a5fa, #3b82f6, #1e40af);
            background-size: 200% 200%;
            animation: gradient 15s ease infinite;
        }
        @keyframes gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .shadow-depth-1 { box-shadow: 0px 5px 15px rgba(0, 0, 0, 0.05); }
        .shadow-depth-2 { box-shadow: 0px 10px 30px rgba(0, 0, 0, 0.1); }
        .shadow-depth-3 { box-shadow: 0px 15px 45px rgba(0, 0, 0, 0.15); }
        .marker-pin {
            width: 30px;
            height: 30px;
            border-radius: 50% 50% 50% 0%;
            background: #eab308;
            position: relative;
            transform: rotate(-45deg);
            cursor: pointer;
        }
        .marker-pin::after {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 8px;
            height: 8px;
            background: white;
            border-radius: 50%;
            transform: translate(-50%, -50%);
        }
        .marker-pin::before {
            content: '';
            position: absolute;
            top: 20px;
            left: 50%;
            width: 1px;
            height: 20px;
            background: black;
            transform: translateX(-50%) rotate(45deg);
        }
        .leaflet-popup-content-wrapper {
            background-color: #fff;
            color: #1e293b;
            border-radius: 0.5rem;
            padding: 0.5rem;
            box-shadow: 0 3px 10px rgba(0,0,0,0.2);
        }
        .leaflet-popup-content {
            margin: 0.3rem;
        }
        .leaflet-popup-tip-container {
            width: 20px;
            height: 10px;
        }
        .leaflet-popup-tip {
            background: #fff;
            border: none;
            box-shadow: 2px 2px 5px rgba(0,0,0,0.1);
        }
    </style>
</head>
<body class="bg-gray-50">

