<script>
    document.addEventListener('DOMContentLoaded', () => {
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });
    });

    function toggleDay(dayNumber) {
        const content = document.getElementById(`day-${dayNumber}-content`);
        const icon = document.querySelector(`.day-card:nth-child(${dayNumber}) .day-header i`);
        content.classList.toggle('hidden');
        icon.classList.toggle('fa-chevron-down');
        icon.classList.toggle('fa-chevron-up');
        gsap.fromTo(content, { opacity: 0, y: -10 }, { opacity: 1, y: 0, duration: 0.3 });
    }

    var map = L.map('map').setView([48.8566, 2.3522], 12);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
    }).addTo(map);

    var parisMarker = L.marker([48.8566, 2.3522]).addTo(map);
    parisMarker.bindPopup("<b>Paris</b><br>Day 1 & 2 Destinations").openPopup();

    var parisPinIcon = L.divIcon({
        className: 'custom-marker-icon',
        html: '<div class="marker-pin"></div>',
        iconSize: [30, 30],
        iconAnchor: [15, 30],
        popupAnchor: [0, -30]
    });
    var parisCustomMarker = L.marker([48.8566, 2.3522], {icon: parisPinIcon}).addTo(map);
    parisCustomMarker.bindPopup("<b>Paris</b><br>Custom Pin Marker").openPopup();


    document.getElementById('destination-form').addEventListener('submit', function(e) {
        e.preventDefault();
        const destinationName = document.getElementById('destination-name').value;
        const destinationDate = document.getElementById('destination-date').value;
        const destinationActivities = document.getElementById('destination-activities').value;

        const newDayNumber = document.querySelectorAll('.day-card').length + 1;
        const dayCardHTML = `
            <div class="day-card bg-white shadow-depth-1 rounded-lg overflow-hidden">
                <div class="day-header px-6 py-4 bg-gray-100 cursor-pointer flex justify-between items-center" onclick="toggleDay(${newDayNumber})">
                    <h3 class="text-xl font-semibold text-gray-800">Day ${newDayNumber}: ${destinationName} <span class="text-gray-500">(${destinationDate})</span></h3>
                    <i class="fa fa-chevron-down text-gray-500"></i>
                </div>
                <div id="day-${newDayNumber}-content" class="day-content px-6 py-4 hidden">
                    <div class="activity-item py-3 flex items-start space-x-4">
                        <i class="fa fa-map-marker text-red-500 mt-1"></i>
                        <div>
                            <h4 class="font-semibold text-gray-700">${destinationName} Activities</h4>
                            <p class="text-gray-600 text-sm">${destinationActivities || 'No activities specified.'}</p>
                        </div>
                    </div>
                </div>
            </div>
        `;

        document.getElementById('itinerary-days').innerHTML += dayCardHTML;
        document.getElementById('destination-form').reset();
        alert('Destination added to itinerary!');
    });

    gsap.from('.hero-section .container > *', {
        y: 30,
        opacity: 0,
        duration: 1,
        stagger: 0.2,
        ease: 'power3.out'
    });
    gsap.from('#itinerary-days > *', {
        y: 20,
        opacity: 0,
        duration: 0.8,
        stagger: 0.15,
        scrollTrigger: {
            trigger: '#itinerary',
            start: 'top 80%',
            end: 'bottom 20%',
            toggleActions: 'play none none reverse'
        }
    });
    gsap.from('#map-section h2, #map', {
        y: 20,
        opacity: 0,
        duration: 0.8,
        scrollTrigger: {
            trigger: '#map-section',
            start: 'top 80%',
            end: 'bottom 20%',
            toggleActions: 'play none none reverse'
        }
    });
    gsap.from('#add-destination h2, #destination-form', {
        y: 20,
        opacity: 0,
        duration: 0.8,
        scrollTrigger: {
            trigger: '#add-destination',
            start: 'top 80%',
            end: 'bottom 20%',
            toggleActions: 'play none none reverse'
        }
    });

</script>

</body>
</html>
