        const sidebar = document.getElementById('sidebar');
        const sidebarToggleOpen = document.getElementById('sidebar-toggle-open');
        const sidebarToggleClose = document.getElementById('sidebar-toggle-close');

        sidebarToggleOpen.addEventListener('click', () => {
            sidebar.classList.remove('-translate-x-full');
            sidebar.classList.add('animate-slide-in-left');
        });

        sidebarToggleClose.addEventListener('click', () => {
            sidebar.classList.remove('animate-slide-in-left');
            sidebar.classList.add('animate-slide-out-left', '-translate-x-full');
        });

        if (window.innerWidth >= 1024) {
            sidebar.classList.remove('-translate-x-full');
        } else {
            sidebar.classList.add('-translate-x-full');
        }

        window.addEventListener('resize', () => {
            if (window.innerWidth >= 1024) {
                sidebar.classList.remove('-translate-x-full', 'animate-slide-out-left', 'animate-slide-in-left');
            } else if (!sidebar.classList.contains('animate-slide-in-left')) {
                sidebar.classList.add('-translate-x-full');
            }
        });

        function updateScoresAndOdds() {
            // Example of updating score for the first card
            const scoreTeamA_1 = Math.floor(Math.random() * 5);
            const scoreTeamB_1 = Math.floor(Math.random() * 5);
            document.querySelectorAll('.live-score')[0].querySelectorAll('.font-bold')[0].textContent = scoreTeamA_1;
            document.querySelectorAll('.live-score')[0].querySelectorAll('.font-bold')[1].textContent = scoreTeamB_1;

            // Example of updating odds for the first card
            const oddTeamA_1 = (Math.random() * 2 + 1).toFixed(2);
            const oddTeamB_1 = (Math.random() * 2 + 1).toFixed(2);
            const oddDraw_1 = (Math.random() * 3 + 2).toFixed(2);
            document.querySelectorAll('.live-score')[0].querySelectorAll('.positive-odd')[0].textContent = "+" + Math.round(oddTeamA_1 * 100);
            document.querySelectorAll('.live-score')[0].querySelectorAll('.negative-odd')[0].textContent = "-" + Math.round(oddTeamB_1 * 100);
            document.querySelectorAll('.live-score')[0].querySelectorAll('.positive-odd')[1].textContent = "+" + Math.round(oddDraw_1 * 100);

            // ... similarly update for other cards ...
        }

        setInterval(updateScoresAndOdds, 5000); // Update every 5 seconds
        updateScoresAndOdds(); // Initial update on page load
    </script>
