            min-height: 200px;
        }
        .task-card {
            @apply bg-white rounded-md p-4 mb-4 shadow-sm cursor-grab hover:shadow-md transition-shadow duration-200;
        }
        .task-card:active {
            @apply cursor-grabbing;
        }
        .filter-option {
