            @apply inline-block bg-blue-100 text-blue-800 px-2 py-1 rounded-full text-xs font-semibold mr-2;
        }
        .card-badge-green {
            @apply inline-block bg-green-100 text-green-800 px-2 py-1 rounded-full text-xs font-semibold mr-2;
        }
        .card-badge-orange {
            @apply inline-block bg-orange-100 text-orange-800 px-2 py-1 rounded-full text-xs font-semibold mr-2;
        }
        .card-badge-red {
            @apply inline-block bg-red-100 text-red-800 px-2 py-1 rounded-full text-xs font-semibold mr-2;
        }
        .card-badge-purple {
            @apply inline-block bg-purple-100 text-purple-800 px-2 py-1 rounded-full text-xs font-semibold mr-2;
        }
        .card-badge-gray {
            @apply inline-block bg-gray-200 text-gray-800 px-2 py-1 rounded-full text-xs font-semibold mr-2;
        }
        .card-priority-high {
