                        </div>
                    </div>

                    <div class="task-card card-status-todo card-priority-high animate-fade-in" draggable="true">
                        <h4 class="font-semibold text-gray-800 mb-2">Mobile App Development</h4>
                        <p class="text-gray-600 text-sm mb-3">Develop iOS and Android mobile applications.</p>
                        <div>
                            <span class="card-badge-purple">Mobile</span>
                            <span class="card-badge-red">High Priority</span>
                        </div>
                        <div class="mt-2 flex justify-between items-center">
                            <img src="https://picsum.photos/200/201" class="w-8 h-8 rounded-full" alt="Assignee Avatar">
                            <span class="text-gray-500 text-xs">Due: 2024-04-01</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- In Progress Column -->
            <div class="kanban-column">
                <h3 class="text-xl font-semibold text-gray-700 mb-4"><i class="fa-solid fa-spinner fa-spin mr-2 text-yellow-500"></i> In Progress</h3>
                <div id="inprogress-column" class="space-y-2">
                    <div class="task-card card-status-inprogress card-priority-low animate-fade-in" draggable="true">
                        <h4 class="font-semibold text-gray-800 mb-2">Marketing Campaign</h4>
                        <p class="text-gray-600 text-sm mb-3">Launch Q2 marketing campaign across social media.</p>
                        <div>
                            <span class="card-badge-green">Marketing</span>
                            <span class="card-badge-gray">Low Priority</span>
                        </div>
                        <div class="mt-2 flex justify-between items-center">
                            <img src="https://picsum.photos/200/202" class="w-8 h-8 rounded-full" alt="Assignee Avatar">
                            <span class="text-gray-500 text-xs">Due: 2024-03-22</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Review Column -->
            <div class="kanban-column">
                <h3 class="text-xl font-semibold text-gray-700 mb-4"><i class="fa-solid fa-magnifying-glass mr-2 text-purple-500"></i> In Review</h3>
                <div id="review-column" class="space-y-2">
                    <div class="task-card card-status-review card-priority-medium animate-fade-in" draggable="true">
                        <h4 class="font-semibold text-gray-800 mb-2">Backend API Development</h4>
                        <p class="text-gray-600 text-sm mb-3">Develop and test RESTful APIs for backend services.</p>
                        <div>
                            <span class="card-badge-blue">Backend</span>
                            <span class="card-badge-orange">Medium Priority</span>
                        </div>
                        <div class="mt-2 flex justify-between items-center">
                            <img src="https://picsum.photos/200/203" class="w-8 h-8 rounded-full" alt="Assignee Avatar">
                            <span class="text-gray-500 text-xs">Due: 2024-03-18</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Done Column -->
            <div class="kanban-column">
                <h3 class="text-xl font-semibold text-gray-700 mb-4"><i class="fa-solid fa-check-circle mr-2 text-green-500"></i> Done</h3>
                <div id="done-column" class="space-y-2">
                    <div class="task-card card-status-done card-priority-low animate-fade-in" draggable="true">
                        <h4 class="font-semibold text-gray-800 mb-2">User Testing</h4>
                        <p class="text-gray-600 text-sm mb-3">Conduct user testing sessions for website prototype.</p>
                        <div>
                            <span class="card-badge-green">Testing</span>
                            <span class="card-badge-gray">Low Priority</span>
                        </div>
                        <div class="mt-2 flex justify-between items-center">
                            <img src="https://picsum.photos/200/204" class="w-8 h-8 rounded-full" alt="Assignee Avatar">
                            <span class="text-gray-500 text-xs">Completed: 2024-03-08</span>
                        </div>
                    </div>
                </div>
            </div>

        </div>

    </main>

</div>

<script>
    const taskCards = document.querySelectorAll('.task-card');
    const kanbanColumns = document.querySelectorAll('.kanban-column > div');
    let draggedCard = null;

    taskCards.forEach(card => {
        card.addEventListener('dragstart', (event) => {
            draggedCard = card;
            card.classList.add('opacity-50');
        });

        card.addEventListener('dragend', () => {
            draggedCard.classList.remove('opacity-50');
            draggedCard = null;
        });
    });

    kanbanColumns.forEach(column => {
        column.addEventListener('dragover', (event) => {
            event.preventDefault();
        });

        column.addEventListener('drop', (event) => {
            event.preventDefault();
            if (draggedCard) {
                column.appendChild(draggedCard);
            }
        });
    });
</script>

</body>
</html>
