                        <li><a href="#journal" class="hover:text-white transition-colors">Journal</a></li>
                    </ul>
                </div>
                <div>
                    <h4 class="text-lg font-bold text-white mb-4">Follow Us</h4>
                    <div class="flex space-x-4">
                        <a href="#" class="hover:text-white transition-colors"><i class="fa fa-facebook-square fa-lg"></i></a>
                        <a href="#" class="hover:text-white transition-colors"><i class="fa fa-instagram fa-lg"></i></a>
                        <a href="#" class="hover:text-white transition-colors"><i class="fa fa-twitter-square fa-lg"></i></a>
                    </div>
