    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const categoryFilters = [
                { id: 'world', color: 'blue' },
                { id: 'tech', color: 'purple' },
                { id: 'business', color: 'green' },
                { id: 'sports', color: 'orange' },
                { id: 'entertainment', color: 'pink' }
            ];

            categoryFilters.forEach(filter => {
                const filterButton = document.getElementById(`filter-${filter.id}`);
                const filterButtonMobile = document.getElementById(`filter-${filter.id}-mobile`);

                const applyFilter = () => {
                    const newsItems = document.querySelectorAll('.news-item');
                    newsItems.forEach(item => {
                        const categorySpan = item.querySelector(`span.bg-${filter.color}-100`);
                        if (categorySpan) {
                            item.style.display = 'block';
                        } else {
                            item.style.display = 'none';
                        }
                    });
                };

                if (filterButton) {
                    filterButton.addEventListener('click', applyFilter);
                }
                if (filterButtonMobile) {
                    filterButtonMobile.addEventListener('click', () => {
                        applyFilter();
                        mobileMenu.classList.add('hidden');
                    });
                }
            });

            const showAllFilters = () => {
                const newsItems = document.querySelectorAll('.news-item');
                newsItems.forEach(item => {
                    item.style.display = 'block';
                });
            };

            const allFiltersButton = document.querySelector('.text-xl.font-bold.text-indigo-600');
            if (allFiltersButton) {
                allFiltersButton.addEventListener('click', showAllFilters);
            }
        });
    </script>

</body>
</html>
