                <button id="prevPage" class="pagination-button bg-white hover:bg-gray-100 text-gray-800 font-semibold py-2 px-4 rounded-l">
                    <i class="fa fa-chevron-left" aria-hidden="true"></i>
                </button>
                <button id="page1" class="pagination-button page-number active-page-button text-white font-semibold py-2 px-4">1</button>
                <button id="page2" class="pagination-button page-number bg-white hover:bg-gray-100 text-gray-800 font-semibold py-2 px-4">2</button>
                <button id="page3" class="pagination-button page-number bg-white hover:bg-gray-100 text-gray-800 font-semibold py-2 px-4">3</button>
                <button id="nextPage" class="pagination-button bg-white hover:bg-gray-100 text-gray-800 font-semibold py-2 px-4 rounded-r">
                    <i class="fa fa-chevron-right" aria-hidden="true"></i>
