    <footer id="contact" class="bg-black text-gray-300 py-12">
        <div class="container mx-auto px-6 flex justify-between items-center">
            <p>&copy; 2024 Monochrome Gallery. All rights reserved.</p>
            <div class="flex space-x-4">
                <a href="#" class="hover:text-white transition-colors"><i class="fab fa-instagram nav-icon"></i></a>
                <a href="#" class="hover:text-white transition-colors"><i class="fab fa-twitter nav-icon"></i></a>
                <a href="#" class="hover:text-white transition-colors"><i class="fab fa-facebook nav-icon"></i></a>
            </div>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const pageNumberButtons = document.querySelectorAll('.page-number');
            const galleryGrid = document.querySelector('.gallery-grid');
            const imagesPerPage = 9;
            let currentPage = 1;

            function loadPage(page) {
                currentPage = page;
                const startRange = (page - 1) * imagesPerPage + 1;
                const endRange = page * imagesPerPage;
                let imageElements = '';
                for (let i = startRange; i <= endRange; i++) {
                    imageElements += `
                        <div class="gallery-item">
                            <img src="https://picsum.photos/id/${i * 10}/200/300" alt="Image ${i}">
                            <div class="gallery-overlay">
                                <i class="fa fa-search-plus gallery-icon" aria-hidden="true"></i>
                            </div>
                        </div>
                    `;
                }
                galleryGrid.innerHTML = imageElements;
                updatePaginationButtons();
            }

            function updatePaginationButtons() {
                pageNumberButtons.forEach(button => {
                    if (parseInt(button.textContent) === currentPage) {
                        button.classList.add('active-page-button', 'text-white');
                        button.classList.remove('bg-white', 'hover:bg-gray-100', 'text-gray-800');
                    } else {
                        button.classList.remove('active-page-button', 'text-white');
                        button.classList.add('bg-white', 'hover:bg-gray-100', 'text-gray-800');
                    }
                });
            }

            pageNumberButtons.forEach(button => {
                button.addEventListener('click', function() {
                    loadPage(parseInt(this.textContent));
                });
            });

            document.getElementById('prevPage').addEventListener('click', function() {
                if (currentPage > 1) {
                    loadPage(currentPage - 1);
                }
            });

            document.getElementById('nextPage').addEventListener('click', function() {
                loadPage(currentPage + 1);
            });

            loadPage(currentPage);
        });
    </script>

</body>
</html>
