        .match-animation-hearts {
            font-size: 4rem;
            color: #FF69B4;
        }
        @keyframes fadeInOut {
            0%, 100% { opacity: 0; }
            10%, 90% { opacity: 1; }
        }
        .animate-fade-match {
            animation: fadeInOut 2s ease-in-out forwards;
        }
        .overlay-gradient {
            background: linear-gradient(to bottom, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.5));
