        <nav class="container mx-auto px-6 py-4 flex justify-between items-center">
            <a href="/" class="text-xl font-bold text-white hover:accent-teal transition-colors">
                My Awesome Blog
            </a>
            <div class="hidden md:flex space-x-8">
                <a href="#home" class="hover:accent-teal transition-colors">Home</a>
                <a href="#posts" class="hover:accent-teal transition-colors">Posts</a>
                <a href="#about" class="hover:accent-teal transition-colors">About</a>
                <a href="#contact" class="hover:accent-teal transition-colors">Contact</a>
            </div>
             <div class="md:hidden">
                <button id="mobile-menu-button" class="text-white focus:outline-none focus:text-accent-teal">
                    <i class="fa fa-bars fa-lg"></i>
                </button>
            </div>
        </nav>
         <!-- Mobile Menu (Hidden by default) -->
        <div class="hidden md:hidden fixed top-0 left-0 w-full h-full bg-gray-900 z-40" id="mobile-menu">
            <div class="px-6 py-6">
                <div class="flex justify-end">
                    <button id="mobile-menu-close" class="text-white focus:outline-none focus:text-accent-teal">
                        <i class="fa fa-times fa-lg"></i>
                    </button>
                </div>
                <div class="flex flex-col items-center mt-16 space-y-8">
                    <a href="#home" class="text-xl hover:accent-teal transition-colors">Home</a>
                    <a href="#posts" class="text-xl hover:accent-teal transition-colors">Posts</a>
                    <a href="#about" class="text-xl hover:accent-teal transition-colors">About</a>
                    <a href="#contact" class="text-xl hover:accent-teal transition-colors">Contact</a>
                </div>
            </div>
        </div>
    </header>

    <!-- Hero Section (Optional - can be the first blog post or a landing section) -->
    <section id="home" class="pt-24 pb-16 bg-gray-900">
        <div class="container mx-auto px-6 text-center">
            <h1 class="text-4xl md:text-5xl font-bold mb-4">Welcome to My Digital Space</h1>
            <p class="text-lg text-gray-400 mb-8">Exploring thoughts, ideas, and creations.</p>
            <button class="bg-accent-teal hover-accent-teal text-gray-900 font-bold py-3 px-8 rounded-full transition-colors">
                Discover More
            </button>
        </div>
    </section>


    <!-- Blog Post Feed (Infinite Scroll) -->
    <main id="posts" class="container mx-auto px-6 pb-20 mt-12 infinite-scroll-container overflow-y-auto max-h-screen" >
        <h2 class="text-3xl font-bold mb-8 text-center">Latest Posts</h2>
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8" id="post-feed">
            <!-- Post cards will be loaded here by JavaScript -->
        </div>
        <div class="text-center mt-8" id="loading-indicator">
            <i class="fa fa-spinner fa-spin fa-2x accent-teal"></i> <span class="ml-2">Loading more posts...</span>
        </div>
    </main>

    <!-- Footer -->
    <footer class="bg-gray-800 py-12 mt-20">
        <div class="container mx-auto px-6 text-center">
            <p class="text-gray-400">© 2024 My Awesome Blog. All rights reserved.</p>
        </div>
    </footer>

    <script>
        const postFeed = document.getElementById('post-feed');
        const loadingIndicator = document.getElementById('loading-indicator');
        let postCount = 0;
        const postsPerPage = 6;
        let loading = false;

        function createPostCard(post) {
            const postCard = document.createElement('div');
            postCard.className = 'post-card p-6 transition-post hover:shadow-lg';

            const image = document.createElement('img');
            image.src = `https://picsum.photos/200/300?random=${post.id}`;
            image.alt = `Post ${post.id} Image`;
            image.className = 'rounded-md mb-4 w-full h-48 object-cover';

            const title = document.createElement('h3');
            title.textContent = post.title;
            title.className = 'text-xl font-bold mb-2 hover:accent-teal transition-colors';

            const excerpt = document.createElement('p');
            excerpt.textContent = post.excerpt;
            excerpt.className = 'text-gray-300 mb-4';
             excerpt.style.overflow = 'hidden';
             excerpt.style.textOverflow = 'ellipsis';
             excerpt.style.display = '-webkit-box';
             excerpt.style.webkitLineClamp = '3'; /* number of lines to show */
             excerpt.style.lineClamp = '3';


            const readMoreLink = document.createElement('a');
            readMoreLink.href = '#post-' + post.id; // Example link - adjust as needed
            readMoreLink.textContent = 'Read More';
            readMoreLink.className = 'text-accent-teal hover:text-light-teal font-semibold transition-colors';

            postCard.appendChild(image);
            postCard.appendChild(title);
            postCard.appendChild(excerpt);
            postCard.appendChild(readMoreLink);

            return postCard;
        }

        function loadPosts() {
            if (loading) return;
            loading = true;
            loadingIndicator.classList.remove('hidden');

            setTimeout(() => { // Simulate API delay
                const fragment = document.createDocumentFragment(); // For performance

                for (let i = 0; i < postsPerPage; i++) {
                    postCount++;
                    const postData = {
                        id: postCount,
                        title: `Post Title ${postCount}`,
                        excerpt: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam...'
                    };
                    fragment.appendChild(createPostCard(postData));
                }
                postFeed.appendChild(fragment);
                loadingIndicator.classList.add('hidden');
                loading = false;
            }, 1000); // Simulate 1 second loading
        }

        // Initial post load
        loadPosts();

        const infiniteScrollContainer = document.querySelector('.infinite-scroll-container');
        infiniteScrollContainer.addEventListener('scroll', () => {
            if (!loading && infiniteScrollContainer.scrollTop + infiniteScrollContainer.clientHeight >= infiniteScrollContainer.scrollHeight - 150) {
                loadPosts();
            }
        });


        // Mobile Menu
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenuClose = document.getElementById('mobile-menu-close');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.remove('hidden');
            setTimeout(() => { // slight delay for animation if needed, not strictly necessary for simple show/hide
                mobileMenu.classList.remove('opacity-0');
            }, 10);
        });

        mobileMenuClose.addEventListener('click', () => {
            mobileMenu.classList.add('opacity-0');
            setTimeout(() => {
                mobileMenu.classList.add('hidden');
            }, 300); // Match transition duration if you add opacity transition to mobile menu
        });


        // Post Transition Animation (Example - GSAP ScrollTrigger for post reveal on scroll)
        gsap.utils.toArray('.post-card').forEach(card => {
            gsap.from(card, {
                opacity: 0,
                y: 50,
                duration: 0.8,
                ease: "power2.out",
                scrollTrigger: {
                    trigger: card,
                    start: "top 90%",
                    once: true // Animation only plays once
                }
            });
        });


    </script>

</body>
</html>
```

