        document.addEventListener('DOMContentLoaded', () => {
            document.querySelectorAll('.circular-progress').forEach(progress => {
                const percent = progress.dataset.percent;
                const color = progress.dataset.color;
                const progressBar = progress.querySelector('.progress-color');
                progressBar.style.strokeDashoffset = 251.2 - (251.2 * percent) / 100;
                progressBar.style.stroke = color;
            });

            document.querySelectorAll('.chart-bar').forEach(bar => {
                bar.style.backgroundColor = bar.style.backgroundColor;
