    <style>
        body { font-family: 'Lato', sans-serif; }
        .calendar-animate-in { animation: calendar-in 0.3s ease-out forwards; }
        .calendar-animate-out { animation: calendar-out 0.3s ease-in forwards; }
        @keyframes calendar-in { from { transform: translateY(-20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        @keyframes calendar-out { from { transform: translateY(0); opacity: 1; } to { transform: translateY(-20px); opacity: 0; } }
        .amenities-animate-in { animation: amenities-in 0.3s ease-out forwards; }
        .amenities-animate-out { animation: amenities-out 0.2s ease-in forwards; }
        @keyframes amenities-in { from { max-height: 0; opacity: 0; } to { max-height: 500px; opacity: 1; } }
        @keyframes amenities-out { from { max-height: 500px; opacity: 1; } to { max-height: 0; opacity: 0; } }
        .pulse-blue { animation: pulse-blue 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
        @keyframes pulse-blue { 0%, 100% { opacity: 1; } 50% { opacity: .5; } }
        .slide-up-fade-in { animation: slide-up-fade-in 0.5s ease-out forwards; }
        @keyframes slide-up-fade-in { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .hero-gradient { background: linear-gradient(135deg, #60a5fa, #3b82f6, #2563eb); background-size: 200% 200%; animation: gradient 15s ease infinite; }
        @keyframes gradient { 0% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } 100% { background-position: 0% 50%; } }
    </style>
</head>
