    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => { mobileMenu.classList.toggle('hidden'); });

            const datePickerInput = document.getElementById('datePicker');
            const calendarElement = document.getElementById('calendar');
            const monthYearElement = document.getElementById('monthYear');
            const daysGridElement = document.getElementById('daysGrid');
            const prevMonthButton = document.getElementById('prevMonth');
            const nextMonthButton = document.getElementById('nextMonth');

            let currentDate = new Date();
            let selectedDate = null;
            let calendarVisible = false;

            function generateCalendar(date) {
                const year = date.getFullYear();
                const month = date.getMonth();
                const firstDayOfMonth = new Date(year, month, 1);
                const lastDayOfMonth = new Date(year, month + 1, 0);
                const daysInMonth = lastDayOfMonth.getDate();
                const startDayOfWeek = firstDayOfMonth.getDay();

                monthYearElement.textContent = date.toLocaleString('default', { month: 'long', year: 'numeric' });
                daysGridElement.innerHTML = '';

                for (let i = 0; i < startDayOfWeek; i++) {
                    const emptyDay = document.createElement('div');
                    daysGridElement.appendChild(emptyDay);
                }

                for (let day = 1; day <= daysInMonth; day++) {
                    const dayElement = document.createElement('div');
                    dayElement.textContent = day;
                    dayElement.classList.add('py-2', 'text-center', 'cursor-pointer', 'hover:bg-blue-100', 'rounded-md');
                    if (year === currentDate.getFullYear() && month === currentDate.getMonth() && day === currentDate.getDate()) {
                        dayElement.classList.add('bg-blue-200');
                    }
                    dayElement.addEventListener('click', () => {
                        selectedDate = new Date(year, month, day);
                        datePickerInput.value = selectedDate.toLocaleDateString();
                        calendarElement.classList.remove('calendar-animate-in');
                        calendarElement.classList.add('calendar-animate-out');
                        setTimeout(() => { calendarElement.classList.add('hidden'); }, 200);
                        calendarVisible = false;
                    });
                    daysGridElement.appendChild(dayElement);
                }
            }

            function showCalendar() {
                if (!calendarVisible) {
                    generateCalendar(currentDate);
                    calendarElement.classList.remove('hidden', 'calendar-animate-out');
                    calendarElement.classList.add('calendar-animate-in');
                    calendarVisible = true;
                } else {
                    calendarElement.classList.remove('calendar-animate-in');
                    calendarElement.classList.add('calendar-animate-out');
                    setTimeout(() => { calendarElement.classList.add('hidden'); }, 200);
                    calendarVisible = false;
                }
            }

            datePickerInput.addEventListener('click', showCalendar);
            prevMonthButton.addEventListener('click', () => {
                currentDate.setMonth(currentDate.getMonth() - 1);
                generateCalendar(currentDate);
            });
            nextMonthButton.addEventListener('click', () => {
                currentDate.setMonth(currentDate.getMonth() + 1);
                generateCalendar(currentDate);
            });

            generateCalendar(currentDate);

            const amenitiesToggle = document.getElementById('amenitiesToggle');
            const amenitiesDetails = document.getElementById('amenitiesDetails');
            const amenitiesToggleText = document.getElementById('amenitiesToggleText');
            const amenitiesToggleIcon = document.getElementById('amenitiesToggleIcon');
            let amenitiesVisible = false;

            amenitiesToggle.addEventListener('click', () => {
                amenitiesVisible = !amenitiesVisible;
                if (amenitiesVisible) {
                    amenitiesDetails.classList.remove('amenities-animate-out', 'hidden');
                    amenitiesDetails.classList.add('amenities-animate-in');
                    amenitiesDetails.style.maxHeight = amenitiesDetails.scrollHeight + 'px';
                    amenitiesDetails.style.opacity = 1;
                    amenitiesToggleText.textContent = 'Hide';
                    amenitiesToggleIcon.classList.remove('fa-chevron-down');
                    amenitiesToggleIcon.classList.add('fa-chevron-up');
                } else {
                    amenitiesDetails.classList.remove('amenities-animate-in');
                    amenitiesDetails.classList.add('amenities-animate-out');
                    amenitiesDetails.style.maxHeight = 0;
                    amenitiesDetails.style.opacity = 0;
                    amenitiesToggleText.textContent = 'Show';
                    amenitiesToggleIcon.classList.remove('fa-chevron-up');
                    amenitiesToggleIcon.classList.add('fa-chevron-down');
                    setTimeout(() => { amenitiesDetails.classList.add('hidden'); }, 200);
                }
            });
        });
    </script>
</body>
</html>
