    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const filterButtons = document.querySelectorAll('.filter-button');
            const recipeCards = document.querySelectorAll('#recipe-grid > div');

            filterButtons.forEach(button => {
                button.addEventListener('click', () => {
                    filterButtons.forEach(btn => btn.classList.remove('active', 'bg-red-600', 'text-white'));
                    button.classList.add('active', 'bg-red-600', 'text-white');
                    const filterTag = button.dataset.tag;

                    recipeCards.forEach(card => {
                        const cardTags = card.querySelectorAll('.tag-item');
                        let showCard = false;
                        if (filterTag === 'all') {
                            showCard = true;
                        } else {
                            cardTags.forEach(tag => {
                                if (tag.dataset.tag === filterTag) {
                                    showCard = true;
                                }
                            });
                        }

                        if (showCard) {
                            card.classList.remove('hidden');
                        } else {
                            card.classList.add('hidden');
                        }
                    });
                });
            });

            gsap.registerPlugin(ScrollTrigger);

            gsap.utils.toArray('.recipe-card').forEach(card => {
                gsap.from(card, {
                    y: 50,
                    opacity: 0,
                    duration: 0.8,
                    ease: "power3.out",
                    scrollTrigger: {
                        trigger: card,
                        start: "top 80%",
                        toggleActions: "play none none reverse"
                    }
                });
            });
        });
    </script>

</body>
</html>
