        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        document.querySelectorAll('.detail-button').forEach(button => {
            button.addEventListener('click', function() {
                const targetId = this.dataset.target;
                const detailPanel = document.getElementById(targetId);
                detailPanel.classList.toggle('expanded');
                const icon = this.querySelector('i');
                if (detailPanel.classList.contains('expanded')) {
                    icon.dataset.lucide = 'chevron-up';
                } else {
                    icon.dataset.lucide = 'chevron-down';
                }
                lucide.createIcons();
            });
        });

        gsap.registerPlugin(ScrollTrigger);

        gsap.from('.hero-section .container > *', {
            y: 60,
            opacity: 0,
            duration: 1.5,
            ease: 'power3.out',
            stagger: 0.2
        });

        gsap.utils.toArray('.product-carousel > div').forEach(card => {
            gsap.from(card, {
                xPercent: 50,
                opacity: 0,
                duration: 1,
                scrollTrigger: {
                    trigger: card,
                    start: 'top 80%',
                    end: 'bottom 20%',
                    toggleActions: 'play none none reverse'
                }
            });
        });

        gsap.from('#shop h2, #shop .grid > div', {
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.2,
            scrollTrigger: {
                trigger: '#shop',
                start: 'top 80%',
                end: 'bottom 20%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.from('#about h2, #about p', {
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.2,
            scrollTrigger: {
                trigger: '#about',
                start: 'top 80%',
                end: 'bottom 20%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.from('#contact h2, #contact .max-w-md > *', {
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.2,
            scrollTrigger: {
                trigger: '#contact',
                start: 'top 80%',
                end: 'bottom 20%',
                toggleActions: 'play none none reverse'
            }
        });

        window.addEventListener('scroll', function() {
            let heroBackground = document.querySelector('.hero-background');
            let scrolled = window.pageYOffset;
            heroBackground.style.transform = 'translateZ(-1px) scale(1.5) translateY(' + scrolled * 0.5 + 'px)';
        });

    </script>
</body>
</html>
