    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Inter', sans-serif; }
        .dark-mode { background-color: #111827; color: #f9fafb; }
        .dark-mode h1, .dark-mode h2, .dark-mode h3, .dark-mode h4, .dark-mode h5, .dark-mode h6, .dark-mode p, .dark-mode a, .dark-mode span, .dark-mode div, .dark-mode button, .dark-mode li { color: #f9fafb; }
