        .dark-mode .hover\:text-blue-600:hover { color: #60a5fa; }
        .dark-mode .text-blue-600 { color: #60a5fa; }
        .dark-mode .ring-blue-500 { ring-color: #60a5fa; }
        .dark-mode .shadow-lg { box-shadow: 0 10px 15px -3px rgba(255, 255, 255, 0.1), 0 4px 6px -2px rgba(255, 255, 255, 0.05); }
        .dark-mode .bg-white\/80 { background-color: rgba(31, 41, 55, 0.8); }
        .dark-mode .shadow-lg { box-shadow: 0 10px 15px -3px rgba(255, 225, 255, 0.1), 0 4px 6px -2px rgba(255, 255, 255, 0.05); }

        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.5s ease-out forwards; }

        @keyframes floatElement {
            0%, 100% { transform: translateY(0px); }
            50% { transform: translateY(-10px); }
        }
        .animate-float { animation: floatElement 3s ease-in-out infinite; }

        .gallery-item { overflow: hidden; position: relative; }
        .gallery-item img { transition: transform 0.3s ease; display: block; }
        .gallery-item:hover img { transform: scale(1.1); }
        .gallery-item::after {
            content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(0, 0, 0, 0.0); transition: background 0.3s ease;
        }
        .gallery-item:hover::after { background: rgba(0, 0, 0, 0.2); }

        .project-title { position: absolute; bottom: 20px; left: 20px; color: white; font-weight: bold; font-size: 1.2rem; opacity: 0; transition: opacity 0.3s ease; }
        .gallery-item:hover .project-title { opacity: 1; }

    </style>
