    <script>
        const darkModeToggle = document.getElementById('darkModeToggle');
        const darkModeToggleMobile = document.getElementById('darkModeToggleMobile');
        const body = document.body;
        const mobileMenuButton = document.getElementById('mobileMenuButton');
        const mobileMenu = document.getElementById('mobileMenu');
        const navbar = document.getElementById('navbar');

        function enableDarkMode() {
            body.classList.add('dark-mode');
            localStorage.setItem('darkMode', 'enabled');
            darkModeToggle.querySelector('span:last-child').classList.add('translate-x-5');
            darkModeToggleMobile.querySelector('span:last-child').classList.add('translate-x-5');
        }

        function disableDarkMode() {
            body.classList.remove('dark-mode');
            localStorage.setItem('darkMode', null);
            darkModeToggle.querySelector('span:last-child').classList.remove('translate-x-5');
            darkModeToggleMobile.querySelector('span:last-child').classList.remove('translate-x-5');
        }

        if (localStorage.getItem('darkMode') === 'enabled') {
            enableDarkMode();
        }

        darkModeToggle.addEventListener('click', () => {
            if (localStorage.getItem('darkMode') !== 'enabled') {
                enableDarkMode();
            } else {
                disableDarkMode();
            }
        });

        darkModeToggleMobile.addEventListener('click', () => {
            if (localStorage.getItem('darkMode') !== 'enabled') {
                enableDarkMode();
            } else {
                disableDarkMode();
            }
        });

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        window.addEventListener('scroll', () => {
            if (window.scrollY > 100) {
                navbar.classList.add('shadow-md');
            } else {
                navbar.classList.remove('shadow-md');
            }
        });
    </script>
</body>
</html>
