    <style>
        body { font-family: 'Poppins', sans-serif; }
        .furniture-card {
            perspective: 1000px;
        }
        .furniture-card-inner {
            transition: transform 0.6s;
            transform-style: preserve-3d;
        }
        .furniture-card:hover .furniture-card-inner {
            transform: rotateY(10deg);
        }
        .furniture-card-front, .furniture-card-back {
            backface-visibility: hidden;
        }
        .furniture-card-back {
            transform: rotateY(180deg);
            position: absolute;
            top: 0;
            left: 0;
        }
        .material-collapsible-header {
            transition: background-color 0.3s ease;
        }
        .material-collapsible-header.active {
            background-color: rgba(209, 213, 219, 0.5);
        }
        .material-collapsible-content {
            overflow: hidden;
            transition: max-height 0.4s ease-in-out;
            max-height: 0;
        }
        .material-collapsible-content.open {
            max-height: 1000px;
        }
        .furniture-image-layer {
            transition: transform 1s cubic-bezier(0.25, 1, 0.5, 1);
        }
        .furniture-card:hover .furniture-image-layer {
            transform: translateY(-10px);
        }
        .furniture-customize-button {
            transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
        }
        .furniture-customize-button:hover {
            transform: scale(1.05);
            box-shadow: 0 5px 15px rgba(0,0,0,0.2);
        }
        .furniture-customize-button:active {
            transform: scale(0.98);
            box-shadow: 0 2px 5px rgba(0,0,0,0.2);
        }
        .material-option-item {
            transition: transform 0.2s ease-in-out;
        }
        .material-option-item:hover {
            transform: scale(1.05);
        }
        .color-swatch {
            transition: border-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
        }
        .color-swatch:hover, .color-swatch.selected {
            border-color: #000;
            box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.3);
        }
        .material-group {
            opacity: 0.9;
            transition: opacity 0.3s ease-in-out;
        }
        .material-group:hover {
            opacity: 1.0;
        }
        .material-group-header {
             transition: color 0.3s ease-in-out;
        }
        .material-group:hover .material-group-header {
            color: #333;
        }
        .material-option-image {
            transition: transform 0.4s ease-out;
        }
        .material-option-item:hover .material-option-image {
            transform: translateY(-5px);
        }
        .customization-panel {
            transform: translateX(100%);
            transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
        }
        .customization-panel.open {
            transform: translateX(0%);
        }
        .panel-overlay {
            opacity: 0;
            visibility: hidden;
            transition: opacity 0.3s ease-in-out, visibility 0s linear 0.3s;
        }
        .panel-overlay.open {
            opacity: 0.5;
            visibility: visible;
            transition: opacity 0.3s ease-in-out, visibility 0s linear 0s;
