    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const collapsibleHeaders = document.querySelectorAll('.material-collapsible-header');

            collapsibleHeaders.forEach(header => {
                header.addEventListener('click', () => {
                    const targetId = header.getAttribute('data-target');
                    const content = document.getElementById(targetId);
                    const isActive = header.classList.contains('active');

                    collapsibleHeaders.forEach(h => {
                        if (h !== header) {
                            h.classList.remove('active');
                            const otherContentId = h.getAttribute('data-target');
                            const otherContent = document.getElementById(otherContentId);
                            otherContent.classList.remove('open');
                            otherContent.style.maxHeight = null;
                            h.querySelector('i').classList.remove('rotate-180');
                        }
                    });

                    header.classList.toggle('active');
                    content.classList.toggle('open');
                    header.querySelector('i').classList.toggle('rotate-180');

                    if (content.classList.contains('open')) {
                        content.style.maxHeight = content.scrollHeight + "px";
                    } else {
                        content.style.maxHeight = null;
                    }
                });
            });

             const colorSwatches = document.querySelectorAll('.color-swatch');
            colorSwatches.forEach(swatch => {
                swatch.addEventListener('click', () => {
                    colorSwatches.forEach(s => s.classList.remove('selected', 'border-black'));
                    swatch.classList.add('selected', 'border-black');
                });
            });
        });
    </script>

</body>
</html>
