    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Roboto', sans-serif; }
        .calendar-day:hover { background-color: rgba(165, 180, 252, 0.3); }
        .event-item {
            @apply bg-blue-500 text-white p-2 rounded-md shadow-md cursor-grab hover:shadow-lg transition-shadow duration-200;
        }
        .event-item.dragging {
            @apply opacity-50;
        }
        .scheduler-slot {
            @apply border-dashed border-2 border-gray-300 bg-gray-50 rounded-md cursor-pointer;
        }
        .scheduler-slot.hovered {
            @apply bg-blue-100 border-blue-300;
        }
        .dynamic-shadow {
            transition: box-shadow 0.3s ease;
        }
        .dynamic-shadow:hover {
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
        }
        .fade-in-slide-up {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.5s ease-out, transform 0.5s ease-out;
        }
        .fade-in-slide-up.active {
            opacity: 1;
            transform: translateY(0);
        }
        .pulse-icon {
            animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: .5; }
        }
        .scale-up-hover {
            transition: transform 0.3s ease-in-out;
        }
        .scale-up-hover:hover {
            transform: scale(1.05);
        }
    </style>
</head>
