                </div>
            </div>

            <div class="mt-8 bg-white shadow-lg rounded-lg p-6 fade-in-slide-up" style="transition-delay: 0.4s;">
                <h2 class="text-xl font-bold text-gray-800 mb-4"><i class="fas fa-list-alt mr-2 text-blue-500"></i> Upcoming Events</h2>
                <div class="event-list space-y-3">
                    <div draggable="true" class="event-item dynamic-shadow scale-up-hover">
                        <h3 class="font-semibold">Team Meeting</h3>
                        <p class="text-sm">Discuss project progress and next steps.</p>
                    </div>
                    <div draggable="true" class="event-item dynamic-shadow scale-up-hover">
                        <h3 class="font-semibold">Client Presentation</h3>
                        <p class="text-sm">Final presentation for potential client.</p>
                    </div>
                    <div draggable="true" class="event-item dynamic-shadow scale-up-hover">
                        <h3 class="font-semibold">Workshop Session</h3>
                        <p class="text-sm">Interactive workshop for team skills enhancement.</p>
                    </div>
                </div>
            </div>
        </main>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            document.querySelectorAll('.fade-in-slide-up').forEach(element => {
                element.classList.add('active');
            });

            const profileMenuButton = document.getElementById('profile-menu-button');
            const profileDropdown = document.getElementById('profile-dropdown');

            profileMenuButton.addEventListener('click', () => {
                profileDropdown.classList.toggle('hidden');
            });

            window.addEventListener('click', (event) => {
                if (!profileMenuButton.contains(event.target) && !profileDropdown.contains(event.target)) {
                    profileDropdown.classList.add('hidden');
                }
            });

            const calendarDaysContainer = document.getElementById('calendar-days');
            const currentMonthDisplay = document.getElementById('current-month');
            const prevMonthButton = document.getElementById('prev-month');
            const nextMonthButton = document.getElementById('next-month');

            let currentDate = new Date();

            function generateCalendar(date) {
                calendarDaysContainer.innerHTML = '';
                currentMonthDisplay.textContent = `${date.toLocaleString('default', { month: 'long' })} ${date.getFullYear()}`;

                const firstDayOfMonth = new Date(date.getFullYear(), date.getMonth(), 1);
                const daysInMonth = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
                const startingDay = firstDayOfMonth.getDay();

                for (let i = 0; i < startingDay; i++) {
                    const emptyDay = document.createElement('div');
                    calendarDaysContainer.appendChild(emptyDay);
                }

                for (let day = 1; day <= daysInMonth; day++) {
                    const dayElement = document.createElement('div');
                    dayElement.textContent = day;
                    dayElement.classList.add('calendar-day', 'py-2', 'rounded-md', 'hover:bg-blue-100', 'cursor-pointer', 'dynamic-shadow', 'scale-up-hover');
                    dayElement.addEventListener('click', () => {
                        alert(`You clicked on ${date.toLocaleString('default', { month: 'long' })} ${day}, ${date.getFullYear()}`);
                    });
                    calendarDaysContainer.appendChild(dayElement);
                }
            }

            generateCalendar(currentDate);

            prevMonthButton.addEventListener('click', () => {
                currentDate.setMonth(currentDate.getMonth() - 1);
                generateCalendar(currentDate);
            });

            nextMonthButton.addEventListener('click', () => {
                currentDate.setMonth(currentDate.getMonth() + 1);
                generateCalendar(currentDate);
            });

            let draggedEvent = null;
            const eventItems = document.querySelectorAll('.event-item');
            const schedulerSlots = document.querySelectorAll('.scheduler-slot');

            eventItems.forEach(eventItem => {
                eventItem.addEventListener('dragstart', (event) => {
                    draggedEvent = event.target;
                    event.target.classList.add('dragging');
                });

                eventItem.addEventListener('dragend', (event) => {
                    event.target.classList.remove('dragging');
                    draggedEvent = null;
                });
            });

            schedulerSlots.forEach(slot => {
                slot.addEventListener('dragover', (event) => {
                    event.preventDefault();
                });

                slot.addEventListener('dragenter', (event) => {
                    event.preventDefault();
                    slot.classList.add('hovered');
                });

                slot.addEventListener('dragleave', () => {
                    slot.classList.remove('hovered');
                });

                slot.addEventListener('drop', (event) => {
                    slot.classList.remove('hovered');
                    if (draggedEvent) {
                        slot.appendChild(draggedEvent);
                        draggedEvent = null;
                        alert(`Event scheduled for ${slot.dataset.time}! (Functionality not fully implemented)`);
                    }
                });
            });
        });
    </script>
</body>
</html>
