<script>
    const sidebarToggle = document.getElementById('sidebar-toggle');
    const sidebar = document.querySelector('.sidebar');
    const sidebarItems = document.querySelectorAll('.sidebar-item');

    sidebarToggle.addEventListener('click', () => {
        sidebar.classList.toggle('sidebar-collapsed');
        sidebarItems.forEach(item => {
            item.classList.toggle('hidden');
        });
    });

    function loadLesson(lessonId) {
        const currentLesson = document.querySelector('section:not(.hidden)');
        const nextLesson = document.getElementById(lessonId);

        if (currentLesson) {
            currentLesson.classList.remove('opacity-100', 'transform', 'translate-y-0');
            currentLesson.classList.add('opacity-0', 'transform', 'translate-y-10');
            setTimeout(() => {
                currentLesson.classList.add('hidden');
                nextLesson.classList.remove('hidden');
                nextLesson.classList.remove('opacity-0', 'transform', 'translate-y-10');
                nextLesson.classList.add('opacity-100', 'transform', 'translate-y-0');
            }, 300);
        } else {
            nextLesson.classList.remove('hidden');
            nextLesson.classList.remove('opacity-0', 'transform', 'translate-y-10');
            nextLesson.classList.add('opacity-100', 'transform', 'translate-y-0');
        }
         if (document.getElementById('quiz-section') && lessonId !== 'quiz-section'){
             document.getElementById('quiz-section').classList.add('hidden');
         }
    }

    function loadQuiz() {
        loadLesson('quiz-section');
    }

    document.getElementById('quiz-form').addEventListener('submit', function(event) {
        event.preventDefault();
        let q1 = document.querySelector('input[name="q1"]:checked');
        let q2 = document.querySelector('input[name="q2"]:checked');
        let q3 = document.querySelectorAll('input[name="q3"]:checked');

        let score = 0;
        if (q1 && q1.value === 'a') score++;
        if (q2 && q2.value === 'b') score++;

        let q3_correct = 0;
        q3.forEach(checkbox => {
            if (checkbox.value === 'b' || checkbox.value === 'c') {
                q3_correct++;
            }
        });
        if (q3_correct === 2 && q3.length === 2) score++;


        document.getElementById('results-text').textContent = `You scored ${score} out of 3!`;
        document.getElementById('quiz-results').classList.remove('hidden');
    });


</script>

</body>
</html>
