        <div class="container mx-auto px-6 text-center">
            <p class="text-gray-500">&copy; 2024 VR-Verse. All rights reserved.</p>
            <div class="mt-4 flex justify-center space-x-6">
                <a href="#" class="hover:text-cyan-400 transition-colors"><i class="fab fa-facebook-f text-lg"></i></a>
                <a href="#" class="hover:text-cyan-400 transition-colors"><i class="fab fa-twitter text-lg"></i></a>
                <a href="#" class="hover:text-cyan-400 transition-colors"><i class="fab fa-instagram text-lg"></i></a>
                <a href="#" class="hover:text-cyan-400 transition-colors"><i class="fab fa-linkedin-in text-lg"></i></a>
            </div>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenuClose = document.getElementById('mobile-menu-close');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.remove('hidden');
            });

            mobileMenuClose.addEventListener('click', () => {
                mobileMenu.classList.add('hidden');
            });

            document.querySelectorAll('a[href^="#"]').forEach(anchor => {
                anchor.addEventListener('click', function (e) {
                    e.preventDefault();

                    mobileMenu.classList.add('hidden');

                    document.querySelector(this.getAttribute('href')).scrollIntoView({
                        behavior: 'smooth'
                    });
                });
            });

            const parallaxLayers = document.querySelectorAll('.parallax-layer');

            window.addEventListener('scroll', () => {
                parallaxLayers.forEach(layer => {
                    const speed = parseFloat(layer.getAttribute('data-speed')) || 0.5;
                    layer.style.transform = `translateZ(${speed * window.scrollY}px) scale(${1 - speed})`;
                });
            });
        });
    </script>
</body>
</html>
