    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Montserrat', sans-serif;
            background-color: #121212;
            color: #e0e0e0;
        }
        .album-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
            gap: 2rem;
        }
        .album-item {
            background-color: #1e1e1e;
            border-radius: 0.5rem;
            overflow: hidden;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .album-item:hover {
            transform: scale(1.05);
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
        }
        .album-image {
            width: 100%;
            display: block;
        }
        .album-details {
            padding: 1rem;
        }
        .equalizer-container {
            display: flex;
            align-items: center;
            justify-content: center;
            height: 50px;
        }
        .bar {
            background-color: #6a1b9a;
            width: 5px;
            margin: 0 2px;
            border-radius: 4px;
            animation: equalize 1.2s infinite alternate;
        }
        .bar:nth-child(2) { animation-delay: -0.4s; }
        .bar:nth-child(3) { animation-delay: -0.8s; }

        @keyframes equalize {
            0% { transform: scaleY(0.4); }
            100% { transform: scaleY(1.2); }
        }
        .playlist-card {
            background-color: #1e1e1e;
            border-radius: 0.75rem;
            overflow: hidden;
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
        }
        .playlist-header {
            padding: 1.5rem;
            background-color: #282828;
            border-bottom: 1px solid #333;
        }
        .playlist-body {
            padding: 1.5rem;
        }
        .playlist-item {
            padding: 0.75rem 0;
            border-bottom: 1px solid #333;
        }
        .playlist-item:last-child {
            border-bottom: none;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
            background: linear-gradient(135deg, #2193b0, #6dd5ed);
            color: white;
        }

        .hero-content {
            position: relative;
            z-index: 10;
        }

        .hero-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.6);
        }
        .glass-panel {
            background-color: rgba(255, 255, 255, 0.08);
            border-radius: 1rem;
            border: 1px solid rgba(255, 255, 255, 0.1);
            backdrop-filter: blur(10px);
            box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.3);
        }
        .library-section {
            background-color: #181818;
        }
        .gradient-text {
            background: linear-gradient(45deg, #6a1b9a, #e91e63);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            text-fill-color: transparent;
        }
        .sidebar {
            background-color: #1e1e1e;
        }
        .sidebar-item:hover {
            background-color: #282828;
        }
        .active-sidebar-item {
            background-color: #6a1b9a;
            color: white;
        }
        .active-sidebar-item:hover {
            background-color: #6a1b9a;
        }
        .player-controls button:hover {
            color: #fff;
            transform: scale(1.1);
        }
        .seek-bar-container {
            background-color: #333;
        }
        input[type="range"]::-webkit-slider-thumb {
            background-color: #6a1b9a;
            border: 3px solid #fff;
        }
        input[type="range"]::-moz-range-thumb {
            background-color: #6a1b9a;
            border: 3px solid #fff;
        }
        input[type="range"]::-ms-thumb {
            background-color: #6a1b9a;
            border: 3px solid #fff;
        }
        .album-cover-large {
            border-radius: 1rem;
            box-shadow: 0 15px 30px rgba(0, 0, 0, 0.5);
        }
        .playlist-hero {
            background: linear-gradient(135deg, #e91e63, #9c27b0);
        }
        .playlist-hero-overlay {
            background-color: rgba(0, 0, 0, 0.4);
        }
        .playlist-details-card {
