    </main>

    <footer class="bg-gray-200 text-gray-700 p-4 text-center mt-10">
        <p>&copy; 2024 Weather Dashboard. All rights reserved.</p>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const heroSection = document.querySelector('.hero');
            const dailyForecastSection = document.querySelector('.daily-forecast');
            const hourlyForecastSection = document.querySelector('.hourly-forecast');
            const additionalDataSection = document.querySelector('.additional-data');
            const animateFadeElements = document.querySelectorAll('.animate-fade');
            const animateSlideUpElements = document.querySelectorAll('.animate-slide-up');

            animateFadeElements.forEach(element => {
                element.classList.remove('opacity-0');
            });
            animateSlideUpElements.forEach(element => {
                element.classList.remove('opacity-0', 'translate-y-10');
            });

            animateSlideUpElements.forEach((element, index) => {
                gsap.from(element, {
                    y: 20,
                    opacity: 0,
                    duration: 0.6,
                    delay: 0.3 + (index * 0.05),
                    ease: "power2.out",
                });
            });

            gsap.from(heroSection, { opacity: 0, y: 30, duration: 0.8, ease: "power2.out", delay: 0.1 });
            gsap.from(dailyForecastSection, { opacity: 0, y: 30, duration: 0.8, ease: "power2.out", delay: 0.3 });
            gsap.from(hourlyForecastSection, { opacity: 0, y: 30, duration: 0.8, ease: "power2.out", delay: 0.5 });
            gsap.from(additionalDataSection, { opacity: 0, y: 30, duration: 0.8, ease: "power2.out", delay: 0.7 });

            const thermometerCanvas = document.getElementById('thermometerChart');
            const ctx = thermometerCanvas.getContext('2d');

            function drawThermometer(temperature) {
                const tempPercent = Math.max(0, Math.min(1, (temperature + 5) / 40));
                const fillHeight = 250 * tempPercent;

                ctx.clearRect(0, 0, thermometerCanvas.width, thermometerCanvas.height);

                ctx.fillStyle = '#e0e0e0';
                ctx.fillRect(50, 20, 50, 250);
                ctx.beginPath();
                ctx.arc(75, 270, 25, 0, Math.PI * 2);
                ctx.fill();

                ctx.fillStyle = '#ff5e62';
                ctx.fillRect(50, 270 - fillHeight, 50, fillHeight);
                ctx.fillStyle = '#ff5e62';
                ctx.beginPath();
                ctx.arc(75, 270, 25, Math.PI, 0);
                ctx.fill();

                ctx.fillStyle = 'black';
                ctx.font = '16px Montserrat';
                ctx.textAlign = 'center';
                ctx.fillText(`${temperature}°C`, 75, 310);
            }

            drawThermometer(15);
        });
    </script>
</body>
</html>
