    <style>
        body { font-family: 'Inter', sans-serif; }
        h1, h2, h3, h4, h5, h6 { font-family: 'Poppins', sans-serif; }
        .hero-section {
            background-color: #f7f7f7;
        }
        .filter-button.active {
            background-color: #008080;
            color: white;
        }
        .profile-card {
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .profile-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
        }
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
        .animate-fade-up {
            animation: fadeInUp 0.5s ease-out forwards;
        }
    </style>
</head>
<body class="bg-gray-50">

    <header class="hero-section py-20 md:py-32">
        <div class="container mx-auto px-6">
            <div class="max-w-2xl mx-auto text-center animate-fade-up">
                <h1 class="text-4xl md:text-5xl font-bold text-gray-900 mb-4">
                    Find Your Perfect Coworking Space
                </h1>
                <p class="text-gray-700 text-lg mb-8">
                    Join a vibrant community of professionals and elevate your work experience.
                </p>
                <div class="flex justify-center space-x-4">
                    <button class="bg-teal-500 hover:bg-teal-600 text-white font-semibold py-3 px-6 rounded-full transition-colors">
                        Explore Spaces
                    </button>
                    <button class="bg-gray-200 hover:bg-gray-300 text-gray-700 font-semibold py-3 px-6 rounded-full transition-colors">
