                <button class="filter-button px-4 py-2 rounded-full bg-gray-100 text-gray-700 hover:bg-gray-200 transition-colors" data-filter="private">Private Offices</button>
                <button class="filter-button px-4 py-2 rounded-full bg-gray-100 text-gray-700 hover:bg-gray-200 transition-colors" data-filter="dedicated">Dedicated Desks</button>
                <button class="filter-button px-4 py-2 rounded-full bg-gray-100 text-gray-700 hover:bg-gray-200 transition-colors" data-filter="hot">Hot Desks</button>
