                            <button class="bg-teal-500 hover:bg-teal-600 text-white py-2 px-4 rounded-full transition-colors">View Details</button>
                        </div>
                    </div>
                </div>

                 <div class="space-item profile-card rounded-xl overflow-hidden shadow-md bg-white" data-space-type="dedicated">
                    <img src="https://picsum.photos/200/300?random=6" alt="Space" class="w-full h-48 object-cover">
