                            <button class="bg-teal-500 hover:bg-teal-600 text-white py-2 px-4 rounded-full transition-colors">View Details</button>
                        </div>
                    </div>
                </div>

            </div>
        </div>
    </section>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const filterButtons = document.querySelectorAll('.filter-button');
            const spaceItems = document.querySelectorAll('.space-item');

            filterButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const filterValue = this.dataset.filter;

                    filterButtons.forEach(btn => btn.classList.remove('active'));
                    this.classList.add('active');

                    spaceItems.forEach(item => {
                        if (filterValue === 'all' || item.dataset.spaceType === filterValue) {
                            item.style.display = 'block';
                        } else {
                            item.style.display = 'none';
                        }
                    });
                });
            });
        });
    </script>

</body>
</html>
