                    </div>
                </div>

                <div class="company-card bg-white rounded-2xl p-6 layer-depth">
                    <img src="https://picsum.photos/200/300?random=6" alt="Company Logo" class="w-20 h-20 rounded-xl mb-4 vibrant-shadow">
                    <h3 class="text-xl font-semibold accent-text mb-2">SecurePay Solutions</h3>
                    <p class="text-gray-600 mb-4">Secure and seamless payment solutions for businesses.</p>
                    <div class="flex justify-between items-center">
                        <span class="text-sm text-gray-500"><i class="fa-solid fa-tag mr-1"></i> Finance</span>
                        <a href="#" class="text-accent-text hover:underline">Learn More</a>
                    </div>
                </div>

            </div>
        </div>
    </section>

    <section id="submit" class="py-20 bg-gray-100">
        <div class="container mx-auto px-6 text-center">
            <h2 class="text-3xl font-bold accent-text mb-8">Submit Your Startup</h2>
            <p class="text-gray-700 text-lg mb-12">
                Join our directory and reach a wider audience of investors and enthusiasts.
            </p>
            <a href="#" class="accent-bg text-white font-bold py-3 px-8 rounded-full hover:opacity-90 transition-opacity vibrant-shadow">
                Submit Startup <i class="fa-solid fa-arrow-right ml-2"></i>
            </a>
        </div>
    </section>

    <footer class="bg-white py-12 border-t border-gray-200">
        <div class="container mx-auto px-6 text-center">
            <p class="text-gray-500">
                &copy; 2024 Startup Directory. All rights reserved.
            </p>
        </div>
    </footer>

    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        const filterButtons = document.querySelectorAll('.filter-button');
        const companyCards = document.querySelectorAll('.company-card');

        filterButtons.forEach(button => {
            button.addEventListener('click', function() {
                filterButtons.forEach(btn => btn.classList.remove('filter-active'));
                this.classList.add('filter-active');
                const filterCategory = this.id.split('-')[1];

                companyCards.forEach(card => {
                    const categorySpan = card.querySelector('.text-sm span');
                    const cardCategory = categorySpan.textContent.trim().toLowerCase();

                    if (filterCategory === 'all' || cardCategory === filterCategory) {
                        card.style.display = 'block';
                        card.classList.add('animate-fade-up');
                    } else {
                        card.style.display = 'none';
                        card.classList.remove('animate-fade-up');
                    }
                });
            });
        });
    </script>

</body>
</html>
