    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            const mobileMenuClose = document.querySelector('#mobile-menu button[aria-label="Close menu"]');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.remove('closed');
                mobileMenu.classList.add('open');
            });

            document.addEventListener('click', (event) => {
                if (!mobileMenu.contains(event.target) && !mobileMenuButton.contains(event.target)) {
                    mobileMenu.classList.remove('open');
                    mobileMenu.classList.add('closed');
                }
            });

            const date = new Date();
            let currentMonth = date.getMonth();
            let currentYear = date.getFullYear();

            const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
            const currentMonthDisplay = document.getElementById('current-month');
            const calendarDaysContainer = document.getElementById('calendar-days');
            const prevMonthButton = document.getElementById('prev-month');
            const nextMonthButton = document.getElementById('next-month');
            const selectedDateDisplay = document.getElementById('selected-date-display');
            let selectedDate = new Date();

            function updateCalendar() {
                currentMonthDisplay.textContent = monthNames[currentMonth] + " " + currentYear;
                calendarDaysContainer.innerHTML = '';

                const firstDayOfMonth = new Date(currentYear, currentMonth, 1);
                const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
                const startingDayOfWeek = firstDayOfMonth.getDay();

                for (let i = 0; i < startingDayOfWeek; i++) {
                    const emptyDay = document.createElement('div');
                    calendarDaysContainer.appendChild(emptyDay);
                }

                for (let day = 1; day <= daysInMonth; day++) {
                    const dayElement = document.createElement('div');
                    dayElement.textContent = day;
                    dayElement.classList.add('calendar-day', 'p-2', 'rounded-full', 'cursor-pointer', 'hover:bg-blue-100', 'transition-colors');
                    if (new Date(currentYear, currentMonth, day).toDateString() === selectedDate.toDateString()) {
                        dayElement.classList.add('active');
                    }
                    dayElement.addEventListener('click', () => {
                        selectedDate = new Date(currentYear, currentMonth, day);
                        updateCalendar();
                        updateSelectedDateDisplay();
                    });
                    calendarDaysContainer.appendChild(dayElement);
                }
            }

            function updateSelectedDateDisplay() {
                const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
                selectedDateDisplay.textContent = selectedDate.toLocaleDateString(undefined, options);
            }

            prevMonthButton.addEventListener('click', () => {
                currentMonth--;
                if (currentMonth < 0) {
                    currentMonth = 11;
                    currentYear--;
                }
                updateCalendar();
            });

            nextMonthButton.addEventListener('click', () => {
                currentMonth++;
                if (currentMonth > 11) {
                    currentMonth = 0;
                    currentYear++;
                }
                updateCalendar();
            });

            updateCalendar();
            updateSelectedDateDisplay();

            const scheduleItems = document.querySelectorAll('#schedule-list .schedule-item');
            scheduleItems.forEach(item => {
                item.addEventListener('click', () => {
                    scheduleItems.forEach(si => si.classList.remove('active'));
                    item.classList.add('active');
                });
            });
        });
    </script>

</body>
</html>
