    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const itemLibrary = document.getElementById('item-library');
            const itineraryItemsContainer = document.getElementById('itinerary-items-container');
            let draggedItem = null;

            itemLibrary.addEventListener('dragstart', (event) => {
                draggedItem = event.target;
                event.dataTransfer.setData('text/plain', event.target.dataset.name);
                event.target.classList.add('opacity-50');
            });

            itemLibrary.addEventListener('dragend', (event) => {
                event.target.classList.remove('opacity-50');
                draggedItem = null;
            });

            itineraryItemsContainer.addEventListener('dragover', (event) => {
                event.preventDefault();
            });

            itineraryItemsContainer.addEventListener('drop', (event) => {
                event.preventDefault();
                if (draggedItem) {
                    const newItem = draggedItem.cloneNode(true);
                    newItem.classList.remove('opacity-50');
                    itineraryItemsContainer.appendChild(newItem);

                    if (itineraryItemsContainer.querySelector('.text-gray-500')) {
                        itineraryItemsContainer.innerHTML = '';
                        itineraryItemsContainer.appendChild(newItem);
                    }

                    newItem.addEventListener('dragstart', handleItineraryItemDragStart);
                    newItem.addEventListener('dragend', handleItineraryItemDragEnd);
                }
            });

            itineraryItemsContainer.querySelectorAll('[data-type="item"]').forEach(item => {
                item.setAttribute('draggable', true);
                item.addEventListener('dragstart', handleItineraryItemDragStart);
                item.addEventListener('dragend', handleItineraryItemDragEnd);
            });

            function handleItineraryItemDragStart(event) {
                draggedItem = event.target;
                event.dataTransfer.setData('text/plain', event.target.dataset.name);
                event.target.classList.add('opacity-50');
            }

            function handleItineraryItemDragEnd(event) {
                event.target.classList.remove('opacity-50');
                draggedItem = null;
            }

             itineraryItemsContainer.addEventListener('dragover', (event) => {
                event.preventDefault();
                const afterElement = getDragAfterElement(itineraryItemsContainer, event.clientY);
                const draggable = document.querySelector('.opacity-50');
                if (afterElement == null) {
                    itineraryItemsContainer.appendChild(draggable);
                } else {
                    itineraryItemsContainer.insertBefore(draggable, afterElement);
                }
            });

            function getDragAfterElement(container, y) {
                const draggableElements = [...container.querySelectorAll('[draggable]:not(.opacity-50)')];

                return draggableElements.reduce((closest, child) => {
                    const box = child.getBoundingClientRect();
                    const offset = y - box.top - box.height / 2;
                    if (offset < 0 && offset > closest.offset) {
                        return { offset: offset, element: child };
                    } else {
                        return closest;
                    }
                }, { offset: Number.NEGATIVE_INFINITY }).element;
            }
        });
    </script>

</body>
</html>
