            });

            gsap.from('#amenities h2, #amenities .grid > div', {
                y: 50,
                opacity: 0,
                stagger: 0.2,
                duration: 1,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: '#amenities',
                    start: 'top 80%',
                }
            });

            gsap.from('#dining h2, #dining > div', {
                y: 50,
                opacity: 0,
                stagger: 0.2,
                duration: 1,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: '#dining',
                    start: 'top 80%',
                }
            });

            gsap.from('#gallery h2, #gallery .grid > div', {
                y: 50,
                opacity: 0,
                stagger: 0.1,
                duration: 1,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: '#gallery',
                    start: 'top 80%',
                }
            });

            gsap.from('#contact h2, #contact form', {
                y: 50,
                opacity: 0,
                duration: 1,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: '#contact',
                    start: 'top 80%',
                }
            });
        });
    </script>
