                        </form>
                        <div class="bid-animation absolute top-0 left-0 w-full h-full bg-purple-500 opacity-20 transform scale-0 rounded-3xl" style="transition: transform 0.3s ease;"></div>
                    </div>
                </div>

            </div>
        </div>
    </section>

    <section id="upcoming-auctions" class="py-16 bg-gray-50">
