            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">

                <div class="auction-item-card">
                    <img src="https://picsum.photos/200/300?random=4" alt="Artwork 4" class="w-full h-64 object-cover">
                    <div class="p-6">
                        <h3 class="text-xl font-semibold text-gray-800 mb-2">Modern Sculpture</h3>
                        <p class="text-gray-600 mb-4">By Peter Green</p>
                        <p class="text-sm text-gray-500">Auction starts in: 3 days</p>
                    </div>
                </div>

                <div class="auction-item-card">
                    <img src="https://picsum.photos/200/300?random=5" alt="Artwork 5" class="w-full h-64 object-cover">
                    <div class="p-6">
                        <h3 class="text-xl font-semibold text-gray-800 mb-2">Still Life with Flowers</h3>
                        <p class="text-gray-600 mb-4">By Olivia Brown</p>
                        <p class="text-sm text-gray-500">Auction starts in: 5 days</p>
                    </div>
                </div>

                <div class="auction-item-card">
                    <img src="https://picsum.photos/200/300?random=6" alt="Artwork 6" class="w-full h-64 object-cover">
                    <div class="p-6">
                        <h3 class="text-xl font-semibold text-gray-800 mb-2">Surreal Landscape</h3>
                        <p class="text-gray-600 mb-4">By David Lee</p>
                        <p class="text-sm text-gray-500">Auction starts in: 1 week</p>
                    </div>
                </div>

            </div>
        </div>
    </section>

    <footer class="bg-gray-800 text-gray-300 py-12">
        <div class="container mx-auto px-6 text-center">
            <p>&copy; 2024 Exquisite Bids. All rights reserved.</p>
            <div class="mt-4 space-x-4">
                <a href="#" class="hover:text-white"><i class="fab fa-facebook-f"></i></a>
                <a href="#" class="hover:text-white"><i class="fab fa-twitter"></i></a>
                <a href="#" class="hover:text-white"><i class="fab fa-instagram"></i></a>
            </div>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const bidForms = document.querySelectorAll('#live-auctions .auction-item-card form');

            bidForms.forEach(form => {
                form.addEventListener('submit', function(event) {
                    event.preventDefault();
                    const bidButton = form.querySelector('button[type="submit"]');
                    const bidAnimation = form.nextElementSibling;

                    bidAnimation.classList.add('scale-100');
                    setTimeout(() => {
                        bidAnimation.classList.remove('scale-100');
                    }, 300);

                    bidButton.disabled = true;
                    bidButton.textContent = 'Bidding...';

                    setTimeout(() => {
                        bidButton.disabled = false;
                        bidButton.innerHTML = '<i class="fa fa-hammer mr-2"></i>Bid Placed!';
                        setTimeout(() => {
                            bidButton.innerHTML = '<i class="fa fa-hammer mr-2"></i>Bid';
                        }, 2000);
                    }, 1500);
                });
            });

            const timerRings = document.querySelectorAll('.timer-ring');
            const timerSpans = document.querySelectorAll('.relative span');

            timerRings.forEach((ring, index) => {
                let timeLeft = 60 + (index * 30);

                function updateTimer() {
                    const minutes = Math.floor(timeLeft / 60);
                    const seconds = timeLeft % 60;
                    timerSpans[index].textContent = `${minutes}:${seconds.toString().padStart(2, '0')}`;

                    const dashOffset = (timeLeft / (60 + (index * 30))) * 100;
                    ring.style.strokeDashoffset = dashOffset;

                    timeLeft--;

                    if (timeLeft < 0) {
                        clearInterval(timerInterval);
                        timerSpans[index].textContent = "Auction Ended";
                    }
                }

                updateTimer();
                const timerInterval = setInterval(updateTimer, 1000);
            });
        });
    </script>

</body>
</html>
