        .inset-shadow { box-shadow: inset 5px 5px 10px #d1d9e6, inset -5px -5px 10px #ffffff; }
        .glass-effect { background-color: rgba(255, 255, 255, 0.6); backdrop-filter: blur(10px); }
        .hover-float:hover { transform: translateY(-5px); transition-duration: 0.3s;}
        .press-pop:active { transform: scale(0.95); transition-duration: 0.1s;}
        .slide-in-right { animation: slideInRight 0.5s ease-out forwards; transform: translateX(100%); opacity: 0; }
        @keyframes slideInRight { to { transform: translateX(0); opacity: 1; } }

    </style>
</head>
