                    <a href="#" class="hover:text-white"><i class="fa-brands fa-twitter-square text-2xl"></i></a>
                </div>
            </div>
        </footer>
    </div>

    <script>
        gsap.registerPlugin(ScrollTrigger);

        gsap.utils.toArray('.fade-in').forEach(element => {
            gsap.from(element, {
                opacity: 0,
                y: 30,
                duration: 1,
                delay: parseFloat(element.style.animationDelay) || 0,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: element,
                    start: 'top 80%',
                    toggleActions: 'play none none none'
                }
            });
        });

        gsap.utils.toArray('.slide-in-left').forEach(element => {
            gsap.from(element, {
                x: -100,
                opacity: 0,
                duration: 1,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: element,
                    start: 'top 80%',
                    toggleActions: 'play none none none'
                }
            });
        });

        gsap.utils.toArray('.slide-in-right').forEach(element => {
            gsap.from(element, {
                x: 100,
                opacity: 0,
                duration: 1,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: element,
                    start: 'top 80%',
                    toggleActions: 'play none none none'
                }
            });
        });

        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    window.scrollTo({
                        top: target.offsetTop - (document.querySelector('nav')?.offsetHeight || 0),
                        behavior: 'smooth'
                    });
                }
            });
        });
    </script>

</body>
</html>
