<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>SereneScape - Meditation App</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;600;700&display=swap" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <script src="https://unpkg.com/lucide@latest"></script>
    <style>
        body {
            font-family: 'Poppins', sans-serif;
            background-color: #f0f9ff;
            color: #334155;
        }
        .calm-gradient {
            background: linear-gradient(135deg, #a7c957, #f2e8cf, #386641, #a7c957);
            background-size: 300% 300%;
            animation: calm-bg 30s ease infinite;
        }
        @keyframes calm-bg {
            0%{background-position:0% 50%}
            50%{background-position:100% 50%}
            100%{background-position:0% 50%}
        }
        .progress-bar {
            position: relative;
            height: 10px;
            background-color: #e2e8f0;
            border-radius: 5px;
            overflow: hidden;
        }
        .progress-bar-fill {
            position: absolute;
            top: 0;
            left: 0;
            height: 100%;
            width: 0%;
            background-color: #64748b;
            border-radius: 5px;
            transition: width 0.3s ease-in-out;
        }
        .ambient-animation {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            opacity: 0.6;
            z-index: -1;
        }
        .ambient-animation span {
            position: absolute;
            border-radius: 50%;
            background: rgba(100, 116, 139, 0.15);
            animation: float-pulse 6s linear infinite;
            opacity: 0;
        }
        @keyframes float-pulse {
            0% {
                transform: translateY(0) scale(0);
                opacity: 0;
            }
            50% {
                opacity: 0.8;
            }
            100% {
                transform: translateY(-100px) scale(1);
                opacity: 0;
            }
        }
        .fade-in-up {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.5s ease-out, transform 0.5s ease-out;
        }
        .fade-in-up.animate {
            opacity: 1;
            transform: translateY(0);
        }
    </style>
</head>
<body class="bg-f0f9ff">

    <div class="ambient-animation">
        <span style="width: 8px; height: 8px; left: 20%; top: 20%; animation-delay: 0s;"></span>
        <span style="width: 12px; height: 12px; left: 40%; top: 60%; animation-delay: 1s;"></span>
        <span style="width: 6px; height: 6px; left: 60%; top: 30%; animation-delay: 2s;"></span>
        <span style="width: 10px; height: 10px; left: 80%; top: 80%; animation-delay: 3s;"></span>
        <span style="width: 9px; height: 9px; left: 10%; top: 70%; animation-delay: 4s;"></span>
        <span style="width: 7px; height: 7px; left: 50%; top: 10%; animation-delay: 5s;"></span>
        <span style="width: 11px; height: 11px; left: 90%; top: 40%; animation-delay: 6s;"></span>
    </div>

    <header class="bg-white shadow-md sticky top-0 z-50">
