            <div class="flex flex-col md:flex-row items-center justify-around">
                <div class="text-center mb-6 md:mb-0">
                    <i data-lucide="clock-4" class="h-12 w-12 text-gray-600 mx-auto block mb-2"></i>
                    <span class="text-3xl font-bold text-indigo-700">35</span>
                    <span class="text-gray-500 block">Minutes Meditated</span>
                </div>
                <div class="border-l border-gray-200 h-24 hidden md:block"></div>
                <div class="text-center">
                    <i data-lucide="activity" class="h-12 w-12 text-gray-600 mx-auto block mb-2"></i>
                    <span class="text-3xl font-bold text-green-700">7</span>
                    <span class="text-gray-500 block">Sessions Completed</span>
                </div>
            </div>
            <div class="mt-8">
                <h3 class="text-lg font-semibold text-gray-700 mb-3">Session Progress</h3>
                <div class="progress-bar">
                    <div class="progress-bar-fill" style="width: 60%;"></div>
                </div>
                <div class="flex justify-between text-sm text-gray-500 mt-1">
