    <footer class="container mx-auto mt-20 px-6 py-12 text-center text-gray-500 border-t border-gray-200">
        <p>&copy; 2024 SereneScape. All rights reserved.</p>
    </footer>

    <script>
        lucide.createIcons();

        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        const fadeElements = document.querySelectorAll('.fade-in-up');
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('animate');
                    observer.unobserve(entry.target);
                }
            });
        }, {
            threshold: 0.1
        });

        fadeElements.forEach(el => {
            observer.observe(el);
        });

        function createFloatingParticles() {
            const animationContainer = document.querySelector('.ambient-animation');
            for (let i = 0; i < 15; i++) {
                const span = document.createElement('span');
                const size = Math.random() * 10 + 5;
                span.style.width = `${size}px`;
                span.style.height = `${size}px`;
                span.style.left = `${Math.random() * 100}%`;
                span.style.top = `${Math.random() * 100}%`;
                span.style.animationDelay = `${Math.random() * 7}s`;
                animationContainer.appendChild(span);
            }
        }

        if (document.querySelector('.ambient-animation')) {
            createFloatingParticles();
        }
    </script>

</body>
</html>
