                @apply bg-rose-500 hover:bg-rose-600 text-white font-semibold py-2 px-4 rounded-md focus:outline-none focus:ring-2 focus:ring-rose-400 transition-colors;
            }
        }
    </style>
    <script>
        document.addEventListener('alpine:init', () => {
            Alpine.data('exchangeApp', () => ({
                selectedCurrency: 'BTC',
                currencies: ['BTC', 'ETH', 'LTC'],
                chartData: {
                    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
                    datasets: [{
                        label: 'Price (USD)',
                        data: [65, 59, 80, 81, 56, 75],
                        borderColor: '#6366f1',
                        borderWidth: 2,
                        tension: 0.4,
                        fill: false
                    }]
                },
                buyOrders: [
                    { price: 42000, amount: 1.5 },
                    { price: 41990, amount: 2.0 },
                    { price: 41980, amount: 0.8 },
                    { price: 41970, amount: 3.1 },
                    { price: 41960, amount: 1.2 }
                ],
                sellOrders: [
                    { price: 42010, amount: 2.5 },
                    { price: 42020, amount: 1.8 },
                    { price: 42030, amount: 0.5 },
                    { price: 42040, amount: 2.7 },
                    { price: 42050, amount: 1.9 }
                ],
                init() {
                    this.startChartUpdates();
                    this.startOrderBookUpdates();
                },
                startChartUpdates() {
                    setInterval(() => {
                        this.updateChartData();
                    }, 3000);
                },
                startOrderBookUpdates() {
                    setInterval(() => {
                        this.updateOrderBook();
                    }, 2000);
                },
                updateChartData() {
                    const newData = this.chartData.datasets[0].data.map(val => val + (Math.random() * 10 - 5));
                    this.chartData.datasets[0].data = newData;
                },
                updateOrderBook() {
                    this.buyOrders.unshift({ price: 41950 - Math.floor(Math.random() * 50), amount: Math.random() * 2 + 0.5 });
                    this.sellOrders.unshift({ price: 42060 + Math.floor(Math.random() * 50), amount: Math.random() * 1.5 + 0.5 });
                    this.buyOrders.pop();
                    this.sellOrders.pop();
                    this.buyOrders.sort((a, b) => b.price - a.price);
                    this.sellOrders.sort((a, b) => a.price - b.price);
                },
                selectCurrency(currency) {
                    this.selectedCurrency = currency;
                },
                placeBuyOrder() {
                    alert('Buy order placed (simulated)');
                },
                placeSellOrder() {
                    alert('Sell order placed (simulated)');
                }
            }))
        })
    </script>
    <script src="https://unpkg.com/alpinejs" defer></script>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
</head>
<body class="bg-zinc-50 font-['DM_Sans'] text-zinc-900 antialiased">
    <div x-data="exchangeApp()" class="min-h-screen flex flex-col">
        <header class="bg-white shadow-md sticky top-0 z-50">
            <nav class="container mx-auto px-6 py-4">
                <div class="flex justify-between items-center">
                    <div class="text-xl font-bold text-indigo-700">
                        <i class="fa fa-chart-line mr-2"></i>Cryptoverse Exchange
                    </div>
                    <div class="currency-toggle-container">
                        <template x-for="currency in currencies" :key="currency">
                            <button
                                class="currency-toggle-button"
                                :class="{'currency-toggle-button-active': selectedCurrency === currency}"
                                @click="selectCurrency(currency)"
                                x-text="currency"
                            ></button>
                        </template>
                    </div>
                </div>
            </nav>
        </header>

        <main class="container mx-auto px-6 py-8 flex-grow">
            <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
