    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const chartCanvas = document.getElementById('priceChart').getContext('2d');
            const chart = new Chart(chartCanvas, {
                type: 'line',
                data: {
                    labels: [],
                    datasets: [{
                        label: 'Price',
                        data: [],
                        borderColor: '#06b6d4',
                        borderWidth: 2,
                        fill: false,
                        tension: 0.4
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        x: {
                            display: false
                        },
                        y: {
                            beginAtZero: false,
                            grid: {
                                display: false
                            }
                        }
                    },
                    plugins: {
                        legend: {
                            display: false
                        }
                    }
                }
            });

            function updateChart(chartInstance, newData) {
                chartInstance.data.labels = newData.labels;
                chartInstance.data.datasets.forEach((dataset) => {
                    dataset.data = newData.datasets[0].data;
                });
                chartInstance.update();
            }

            document.addEventListener('alpine:updated', () => {
                const alpineData = Alpine.$data('exchangeApp');
                if (alpineData && chart) {
                    updateChart(chart, alpineData.chartData);
                }
            });
             const initialAlpineData = Alpine.$data('exchangeApp');
             if (initialAlpineData && chart) {
                 updateChart(chart, initialAlpineData.chartData);
             }
        });
    </script>
</body>
</html>
