                        <li><a href="#slideshows" class="hover:text-magazine-text-light transition-colors">Slideshows</a></li>
                    </ul>
                </div>
                <div>
                    <h4 class="text-xl font-semibold mb-4">Subscribe</h4>
                    <p class="text-gray-400 mb-4">Stay updated with our latest content. Subscribe to our newsletter.</p>
                    <div class="flex">
                        <input type="email" placeholder="Your email address" class="bg-gray-700 text-white px-4 py-2 rounded-l-full focus:outline-none focus:ring-2 focus:ring-magazine-primary">
