    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const slidesWrapper = document.querySelector('.slides-wrapper');
            const slidesContainer = document.querySelector('.slides');
            const slides = document.querySelectorAll('.slide');
            const prevButton = document.querySelector('.prev-slide');
            const nextButton = document.querySelector('.next-slide');
            const slideIndicatorsContainer = document.querySelector('.slide-indicators');
            const slideIndicatorButtons = document.querySelectorAll('.slide-indicator-btn');

            let slideIndex = 0;
            const slideWidth = slides[0].offsetWidth;
            let isTransitioning = false;

            function updateSlidePosition() {
                slidesContainer.style.transform = `translateX(-${slideIndex * slideWidth}px)`;
            }

            function setActiveIndicator(index) {
                slideIndicatorButtons.forEach(btn => btn.classList.remove('bg-magazine-primary', 'opacity-100'));
                slideIndicatorButtons[index].classList.add('bg-magazine-primary', 'opacity-100');
            }
            setActiveIndicator(slideIndex);

            function nextSlide() {
                if(isTransitioning) return;
                isTransitioning = true;
                slideIndex = (slideIndex + 1) % slides.length;
                updateSlidePosition();
                setActiveIndicator(slideIndex);
                setTimeout(() => isTransitioning = false, 500);
            }

            function prevSlide() {
                if(isTransitioning) return;
                isTransitioning = true;
                slideIndex = (slideIndex - 1 + slides.length) % slides.length;
                updateSlidePosition();
                setActiveIndicator(slideIndex);
                setTimeout(() => isTransitioning = false, 500);
            }

            nextButton.addEventListener('click', nextSlide);
            prevButton.addEventListener('click', prevSlide);

            slideIndicatorsContainer.addEventListener('click', (event) => {
                if (event.target.classList.contains('slide-indicator-btn')) {
                    const index = parseInt(event.target.dataset.slideIndex);
                    slideIndex = index;
                    updateSlidePosition();
                    setActiveIndicator(slideIndex);
                }
            });

            setInterval(nextSlide, 5000);

            const fadeElements = document.querySelectorAll('.fade-in');
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if(entry.isIntersecting){
                        entry.target.classList.add('active');
                        observer.unobserve(entry.target);
                    }
                });
            });

            fadeElements.forEach((el) => observer.observe(el));
        });
    </script>

</body>
</html>
