        gsap.fromTo('.hero-gradient', {opacity: 0}, {opacity: 1, duration: 1.5, ease: "power2.out"});
        gsap.fromTo('.hero-gradient h1', {y: 50, opacity: 0}, {y: 0, opacity: 1, duration: 1, delay: 0.5, ease: "power3.out"});
        gsap.fromTo('.hero-gradient p', {y: 50, opacity: 0}, {y: 0, opacity: 1, duration: 1, delay: 0.7, ease: "power3.out"});
        gsap.fromTo('.hero-gradient button', {y: 50, opacity: 0}, {y: 0, opacity: 1, duration: 1, delay: 0.9, ease: "power3.out"});

        document.querySelectorAll('section').forEach(section => {
            gsap.from(section.querySelectorAll('.game-card, .text-center, .grid > div, .container > p, .container > h2, .container > h3'), {
                y: 50,
                opacity: 0,
                duration: 1,
                stagger: 0.2,
                scrollTrigger: {
                    trigger: section,
                    start: "top 80%",
                    end: "bottom 20%",
                    toggleActions: "play none none reverse"
                }
            });
        });

        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();

                const targetId = this.getAttribute('href').substring(1);
                const targetElement = document.getElementById(targetId);

                if (targetElement) {
                    window.scrollTo({
                        top: targetElement.offsetTop - 50,
                        behavior: 'smooth'
                    });
                }
            });
        });
    </script>

