        .risk-low { @apply text-green-500; }
        .risk-medium { @apply text-amber-500; }
        .risk-high { @apply text-red-500; }
        .trend-up { @apply text-green-500; }
        .trend-down { @apply text-red-500; }
        .trend-neutral { @apply text-gray-500; }
        .btn-primary {
            @apply bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg transition-colors duration-200;
        }
        .btn-secondary {
            @apply bg-gray-200 hover:bg-gray-300 text-gray-700 font-semibold py-2 px-4 rounded-lg transition-colors duration-200;
        }
        .input-field {
            @apply shadow-sm bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-full p-2.5;
        }
        .select-field {
            @apply shadow-sm bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-full p-2.5;
        }
        .toggle-icon {
            @apply text-gray-500 hover:text-gray-300 cursor-pointer transition-colors duration-200;
        }
        .sidebar-link {
            @apply flex items-center space-x-3 p-4 rounded-md hover:bg-gray-800 transition-colors duration-200;
        }
        .sidebar-link.active {
            @apply bg-blue-700 text-white hover:bg-blue-700;
        }
        .sidebar-link:hover .toggle-icon {
            @apply text-gray-100;
        }
        .dropdown-menu {
            @apply absolute right-0 mt-2 w-48 bg-white rounded-md shadow-xl z-10 opacity-0 pointer-events-none transform translate-y-2 transition-all duration-300 ease-in-out;
        }
        .dropdown-menu.open {
            @apply opacity-100 pointer-events-auto transform translate-y-0;
        }
        .dropdown-item {
            @apply block px-4 py-2 text-gray-700 hover:bg-gray-100 hover:text-gray-900 transition-colors duration-200;
        }
        .hero-section {
            @apply bg-gray-100 py-20 rounded-3xl overflow-hidden relative;
        }
        .hero-overlay {
            @apply absolute inset-0 bg-gradient-to-br from-blue-900 to-blue-700 opacity-60;
        }
        .hero-content {
            @apply relative z-10 text-center text-white;
        }
        .hero-title {
            @apply text-5xl md:text-6xl font-bold mb-6;
        }
        .hero-subtitle {
            @apply text-lg md:text-xl mb-8 opacity-80;
        }
        .hero-button {
            @apply btn-primary text-xl px-8 py-3;
        }
        .feature-card {
            @apply bg-white rounded-2xl shadow-md p-6 hover:shadow-lg transition-shadow duration-300;
        }
        .feature-icon {
            @apply text-blue-500 text-4xl mb-4;
        }
        .feature-title {
            @apply text-xl font-semibold text-gray-900 mb-2;
        }
        .feature-description {
            @apply text-gray-600;
        }
        .gradient-bg {
            background: linear-gradient(135deg, #60a5fa, #3b82f6, #1e40af);
            background-size: 200% 200%;
            animation: gradient-animation 10s ease infinite;
        }

        @keyframes gradient-animation {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .loading-skeleton {
            background: linear-gradient(90deg, #e2e8f0 25%, #f8fafc 50%, #e2e8f0 75%);
            background-size: 200% 100%;
            animation: skeleton-loading 1.5s linear infinite;
        }

        @keyframes skeleton-loading {
            0% { background-position: 200% 0; }
            100% { background-position: -200% 0; }
        }
    </style>
</head>
