<script>
    const sidebarToggle = document.getElementById('sidebarToggle');
    const sidebar = document.getElementById('sidebar');
    const mainContent = document.getElementById('mainContent');
    let sidebarCollapsed = false;

    sidebarToggle.addEventListener('click', () => {
        sidebarCollapsed = !sidebarCollapsed;
        sidebar.classList.toggle('sidebar-collapsed', sidebarCollapsed);
        mainContent.classList.toggle('main-content-sidebar-collapsed', sidebarCollapsed);

        if (sidebarCollapsed) {
            sidebarToggle.innerHTML = '<i class="fa fa-chevron-right"></i>';
        } else {
            sidebarToggle.innerHTML = '<i class="fa fa-chevron-left"></i>';
        }
    });

    const dropdownButton = document.getElementById('dropdownButton');
    const dropdownMenu = document.getElementById('dropdownMenu');

    dropdownButton.addEventListener('click', () => {
        dropdownMenu.classList.toggle('open');
    });

    window.addEventListener('click', (event) => {
        if (!dropdownButton.contains(event.target) && !dropdownMenu.contains(event.target)) {
            dropdownMenu.classList.remove('open');
        }
    });
</script>

</body>
</html>
