                            <label for="startTime" class="block text-gray-700 text-sm font-bold mb-2">Start Time</label>
                            <input type="time" id="startTime" name="startTime" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline">
                        </div>
                        <div class="mb-4">
                            <label for="endDate" class="block text-gray-700 text-sm font-bold mb-2">End Date</label>
                            <input type="date" id="endDate" name="endDate" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline">
                        </div>
                        <div class="mb-6">
                            <label for="endTime" class="block text-gray-700 text-sm font-bold mb-2">End Time</label>
                            <input type="time" id="endTime" name="endTime" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline">
                        </div>
                        <div class="flex justify-between">
                            <button type="button" onclick="prevStep(2)" class="bg-gray-300 hover:bg-gray-400 text-gray-700 rounded-full px-6 py-2 font-semibold transition-colors">Previous</button>
                            <button type="button" onclick="nextStep(2)" class="bg-teal-500 hover:bg-teal-600 text-white rounded-full px-8 py-2 font-semibold transition-colors">Next: Your Details</button>
                        </div>
                    </div>

                    <div class="booking-form-step inactive" id="step3">
                        <h3 class="text-2xl font-semibold mb-6 text-teal-700">Step 3: Your Details</h3>
                        <div class="mb-4">
                            <label for="name" class="block text-gray-700 text-sm font-bold mb-2">Name</label>
                            <input type="text" id="name" name="name" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline">
                        </div>
                        <div class="mb-4">
                            <label for="email" class="block text-gray-700 text-sm font-bold mb-2">Email</label>
                            <input type="email" id="email" name="email" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline">
                        </div>
                        <div class="mb-6">
                            <label for="phone" class="block text-gray-700 text-sm font-bold mb-2">Phone</label>
                            <input type="tel" id="phone" name="phone" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline">
                        </div>
                        <div class="flex justify-between">
                            <button type="button" onclick="prevStep(3)" class="bg-gray-300 hover:bg-gray-400 text-gray-700 rounded-full px-6 py-2 font-semibold transition-colors">Previous</button>
                            <button type="submit" class="bg-teal-500 hover:bg-teal-600 text-white rounded-full px-8 py-2 font-semibold transition-colors">Confirm Booking</button>
                        </div>
                    </div>
                </form>
            </div>
        </div>
    </section>

    <section id="contact" class="py-20 bg-gray-900 text-white">
        <div class="container mx-auto px-6 text-center">
            <h2 class="text-3xl font-bold mb-12">Contact Us</h2>
            <p class="mb-8 opacity-80">Have questions? Reach out to our team, we're here to help.</p>
            <div class="flex justify-center space-x-8 mb-8">
                <a href="#" class="text-teal-300 hover:text-teal-200 transition-colors"><i class="fab fa-facebook fa-2x"></i></a>
                <a href="#" class="text-teal-300 hover:text-teal-200 transition-colors"><i class="fab fa-twitter fa-2x"></i></a>
                <a href="#" class="text-teal-300 hover:text-teal-200 transition-colors"><i class="fab fa-instagram fa-2x"></i></a>
            </div>
            <p class="opacity-70">Email: <a href="mailto:info@bikeverse.com" class="text-teal-300 hover:text-teal-200 transition-colors">info@bikeverse.com</a></p>
            <p class="opacity-70">Phone: +1-555-BIKE-RENT</p>
        </div>
    </section>

    <footer class="bg-gray-800 text-white py-12">
        <div class="container mx-auto px-6 text-center opacity-70">
            <p>&copy; 2024 BikeVerse. All rights reserved.</p>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const mobileMenuButton = document.querySelector('.mobile-menu-button');
            const mobileMenu = document.querySelector('.mobile-menu');

            mobileMenuButton.addEventListener('click', function() {
                mobileMenu.classList.toggle('hidden');
            });
        });

        let currentStep = 1;
        const bookingSteps = document.querySelectorAll('.booking-form-step');

        function openBookingForm(bikeType) {
            document.getElementById('bikeType').value = bikeType;
            document.getElementById('bookingFormContainer').scrollIntoView({ behavior: 'smooth' });
        }

        function nextStep(step) {
            bookingSteps[step - 1].classList.remove('active');
            bookingSteps[step - 1].classList.add('inactive');
            bookingSteps[step].classList.remove('inactive');
            bookingSteps[step].classList.add('active');
            currentStep = step + 1;
        }

        function prevStep(step) {
            bookingSteps[step - 1].classList.remove('active');
            bookingSteps[step - 1].classList.add('inactive');
            bookingSteps[step - 2].classList.remove('inactive');
            bookingSteps[step - 2].classList.add('active');
            currentStep = step - 1;
        }

        document.getElementById('bikeBookingForm').addEventListener('submit', function(event) {
            event.preventDefault();
            alert('Booking Confirmed! Thank you for choosing BikeVerse.');
            // In a real application, you would send the form data to a server here.
            document.getElementById('bikeBookingForm').reset();
            currentStep = 1;
            bookingSteps.forEach((step, index) => {
                if (index === 0) {
                    step.classList.remove('inactive');
                    step.classList.add('active');
                } else {
                    step.classList.remove('active');
                    step.classList.add('inactive');
                }
            });
        });
    </script>

</body>
</html>
