    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        document.addEventListener('DOMContentLoaded', () => {
            const sections = document.querySelectorAll('section');
            sections.forEach(section => {
                const elements = section.querySelectorAll('.fade-in, .slide-in-left, .slide-in-right');
                elements.forEach(element => {
                    element.classList.add('opacity-0');
                });
            });

            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.querySelectorAll('.fade-in').forEach((el, index) => {
                            setTimeout(() => {
                                el.classList.remove('opacity-0', 'fade-in');
                                el.classList.add('fade-in');
                            }, index * 150);
                        });
                        entry.target.querySelectorAll('.slide-in-left').forEach((el, index) => {
                            setTimeout(() => {
                                el.classList.remove('opacity-0', 'slide-in-left');
                                el.classList.add('slide-in-left');
                            }, index * 200);
                        });
                        entry.target.querySelectorAll('.slide-in-right').forEach((el, index) => {
                            setTimeout(() => {
                                el.classList.remove('opacity-0', 'slide-in-right');
                                el.classList.add('slide-in-right');
                            }, index * 200);
                        });
                    }
                });
            }, {
                threshold: 0.1
            });

            sections.forEach(section => {
                observer.observe(section);
            });
        });

        const nav = document.querySelector('header');
        let lastScrollY = window.scrollY;

        window.addEventListener('scroll', () => {
            if (window.scrollY > 100) {
                nav.classList.add('shadow-md');
            } else {
                nav.classList.remove('shadow-md');
            }

            if (window.scrollY > lastScrollY && window.scrollY > 300) {
                nav.classList.add('-translate-y-full');
            } else {
                nav.classList.remove('-translate-y-full');
            }
            lastScrollY = window.scrollY;
        });


    </script>
</body>
</html>
