    <script>
        function nextPage(currentPageId, nextPageId) {
            const currentPage = document.getElementById(currentPageId);
            const nextPage = document.getElementById(nextPageId);

            currentPage.classList.add('slide-left');
            nextPage.classList.remove('slide-right');

            setTimeout(() => {
                currentPage.style.display = 'none';
                nextPage.style.display = 'flex';
                nextPage.classList.remove('slide-left', 'slide-right');
            }, 1000); // Match transition duration
        }

        function previousPage(currentPageId, previousPageId) {
            const currentPage = document.getElementById(currentPageId);
            const previousPage = document.getElementById(previousPageId);

            currentPage.classList.add('slide-right');
            previousPage.classList.remove('slide-left');
            previousPage.style.display = 'flex'; // Make sure previous page is visible before transition

            setTimeout(() => {
                currentPage.style.display = 'none';
                previousPage.classList.remove('slide-left', 'slide-right');
            }, 1000); // Match transition duration
        }
        function restartStory() {
            const pages = ['page-introduction', 'page-chapter-1', 'page-chapter-2', 'page-chapter-3', 'page-conclusion'];
            const coverPage = document.getElementById('page-cover');

            pages.forEach(pageId => {
                document.getElementById(pageId).style.display = 'none';
            });
            coverPage.style.display = 'flex';
        }

        document.addEventListener('DOMContentLoaded', () => {
            const pages = ['page-introduction', 'page-chapter-1', 'page-chapter-2', 'page-chapter-3', 'page-conclusion'];
            pages.forEach(pageId => {
                document.getElementById(pageId).style.display = 'none';
            });
        });
    </script>

</body>
</html>
