    <script>
        const articles = document.querySelectorAll('.article-reveal');
        const header = document.querySelector('.sticky-header');

        function revealArticles() {
            articles.forEach(article => {
                if (isElementInViewport(article)) {
                    article.classList.add('revealed');
                }
            });
        }

        function isElementInViewport(el) {
            const rect = el.getBoundingClientRect();
            return (
                rect.top >= 0 &&
                rect.left >= 0 &&
                rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
                rect.right <= (window.innerWidth || document.documentElement.clientWidth)
            );
        }

        function handleScroll() {
            revealArticles();
            if (window.scrollY > 50) {
                header.classList.add('sticky-header-shadow');
            } else {
                header.classList.remove('sticky-header-shadow');
            }
        }

        window.addEventListener('scroll', handleScroll);
        window.addEventListener('load', handleScroll);


        let loadingMore = false;
        let articleCount = 10;

        function loadMoreArticles() {
            if (loadingMore) return;
            loadingMore = true;

            setTimeout(() => {
                const feed = document.getElementById('magazine-feed');
                for (let i = 0; i < 4; i++) {
                    articleCount++;
                    const articleDiv = document.createElement('div');
                    articleDiv.className = 'magazine-item article-reveal';
                    articleDiv.innerHTML = `
                        <img src="https://picsum.photos/200/300?random=${articleCount}" alt="Article Image" class="magazine-item-image">
                        <div class="magazine-item-content">
                            <span class="category-badge">Random</span>
                            <h2 class="article-title">New Article Title ${articleCount}</h2>
                            <p class="article-excerpt">This is a dynamically loaded article excerpt ${articleCount} for infinite scroll demonstration.</p>
                            <a href="#" class="read-more-link">Read More <i class="fa fa-arrow-right ml-1"></i></a>
                        </div>
                    `;
                    feed.appendChild(articleDiv);
                }
                articles.push(...document.querySelectorAll('.article-reveal:not(.revealed)'));
                revealArticles();
                loadingMore = false;
            }, 1000);
        }


        function handleInfiniteScroll() {
            if (!loadingMore && window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 200) {
                loadMoreArticles();
            }
        }

        window.addEventListener('scroll', handleInfiniteScroll);

    </script>

</body>
</html>
