    <script>
        const mobileMenuButton = document.querySelector('.mobile-menu-button');
        const mobileMenu = document.querySelector('.mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        const petListings = [
            { name: 'Buddy', type: 'dog', breed: 'labrador', age: 'young', gender: 'male', image: 'https://picsum.photos/200/300?random=1', description: 'Friendly Labrador looking for a family.' },
            { name: 'Whiskers', type: 'cat', breed: 'siamese', age: 'adult', gender: 'female', image: 'https://picsum.photos/200/300?random=2', description: 'Playful Siamese cat, loves cuddles.' },
            { name: 'Rocky', type: 'dog', breed: 'golden_retriever', age: 'young', gender: 'male', image: 'https://picsum.photos/200/300?random=3', description: 'Energetic Golden Retriever, great with kids.' },
            { name: 'Cleo', type: 'cat', breed: 'persian', age: 'adult', gender: 'female', image: 'https://picsum.photos/200/300?random=4', description: 'Gentle Persian cat, loves to relax.' },
            { name: 'Max', type: 'dog', breed: 'bulldog', age: 'senior', gender: 'male', image: 'https://picsum.photos/200/300?random=5', description: 'Loyal Bulldog, needs a loving owner.' },
            { name: 'Luna', type: 'cat', breed: 'maine_coon', age: 'young', gender: 'female', image: 'https://picsum.photos/200/300?random=6', description: 'Majestic Maine Coon, very affectionate.' },
        ];

        function filterPets() {
            const typeFilter = document.getElementById('type-filter').value;
            const breedFilter = document.getElementById('breed-filter').value;
            const ageFilter = document.getElementById('age-filter').value;
            const genderFilter = document.getElementById('gender-filter').value;
            const listingsContainer = document.getElementById('pet-listings');
            listingsContainer.innerHTML = '';

            const filteredPets = petListings.filter(pet => {
                if (typeFilter && pet.type !== typeFilter) return false;
                if (breedFilter && pet.breed !== breedFilter.replace('_', ' ')) return false;
                if (ageFilter && pet.age !== ageFilter) return false;
                if (genderFilter && pet.gender !== genderFilter) return false;
                return true;
            });

            filteredPets.forEach(pet => {
                const petCard = document.createElement('div');
                petCard.className = 'pet-card bg-white rounded-xl shadow-md overflow-hidden';
                petCard.innerHTML = `
                    <img src="${pet.image}" alt="Pet Image" class="w-full h-64 object-cover">
                    <div class="p-6">
                        <h3 class="text-xl font-bold mb-2">${pet.name}</h3>
                        <p class="text-gray-700 mb-4">${pet.description}</p>
                        <div class="flex justify-between items-center">
                            <span class="text-sm text-gray-500">${pet.type.charAt(0).toUpperCase() + pet.type.slice(1)} - ${pet.breed.charAt(0).toUpperCase() + pet.breed.slice(1).replace('_', ' ')}</span>
                            <button class="bg-teal-500 hover:bg-teal-700 text-white font-bold py-2 px-4 rounded-full transition-colors open-inquiry-modal" data-pet-name="${pet.name}">
                                Inquire
                            </button>
                        </div>
                    </div>
                `;
                listingsContainer.appendChild(petCard);
            });
             attachInquiryModalListeners(); // Re-attach listeners after re-rendering listings
        }


        document.getElementById('type-filter').addEventListener('change', filterPets);
        document.getElementById('breed-filter').addEventListener('change', filterPets);
        document.getElementById('age-filter').addEventListener('change', filterPets);
        document.getElementById('gender-filter').addEventListener('change', filterPets);


        let currentSlide = 0;
        const slider = document.querySelector('.image-slider');
        const slides = document.querySelectorAll('.image-slider img');
        const prevButton = document.querySelector('.slider-prev');
        const nextButton = document.querySelector('.slider-next');
        const slideWidth = slides[0].clientWidth;

        function updateSlider() {
            slider.style.transform = `translateX(${-currentSlide * slideWidth}px)`;
        }

        nextButton.addEventListener('click', () => {
            if (currentSlide < slides.length - 1) {
                currentSlide++;
            } else {
                currentSlide = 0;
            }
            updateSlider();
        });

        prevButton.addEventListener('click', () => {
            if (currentSlide > 0) {
                currentSlide--;
            } else {
                currentSlide = slides.length - 1;
            }
            updateSlider();
        });


        const inquiryModal = document.getElementById('inquiryModal');
        const closeModalButton = document.getElementById('closeModalButton');
        const petNamePlaceholder = document.getElementById('petNamePlaceholder');
        let currentPetName = '';


        function attachInquiryModalListeners() {
            const openModalButtons = document.querySelectorAll('.open-inquiry-modal');

            openModalButtons.forEach(button => {
                button.addEventListener('click', () => {
                    currentPetName = button.dataset.petName;
                    petNamePlaceholder.textContent = currentPetName;
                    inquiryModal.classList.remove('hidden');
                    inquiryModal.style.display = 'grid'; // Use grid to center modal
                    document.body.classList.add('overflow-hidden'); // Prevent scrolling behind modal
                });
            });
        }
        attachInquiryModalListeners();


        closeModalButton.addEventListener('click', () => {
            inquiryModal.classList.add('hidden');
            inquiryModal.style.display = 'none';
            document.body.classList.remove('overflow-hidden');
        });

        window.addEventListener('click', (event) => {
            if (event.target === inquiryModal) {
                inquiryModal.classList.add('hidden');
                inquiryModal.style.display = 'none';
                document.body.classList.remove('overflow-hidden');
            }
        });

        document.getElementById('inquiryForm').addEventListener('submit', function(event) {
            event.preventDefault();
            const name = document.getElementById('name').value;
            const email = document.getElementById('email').value;
            const message = document.getElementById('message').value;

            alert(`Inquiry sent for ${currentPetName}!\nName: ${name}\nEmail: ${email}\nMessage: ${message}`);
            inquiryModal.classList.add('hidden');
            inquiryModal.style.display = 'none';
            document.body.classList.remove('overflow-hidden');
            document.getElementById('inquiryForm').reset();
        });


    </script>

</body>
</html>
