    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });

        function toggleSessionDetails(sessionId) {
            const details = document.getElementById(sessionId);
            details.classList.toggle('open');
        }

        document.querySelectorAll('.timer-container').forEach(timerContainer => {
            const startButton = timerContainer.querySelector('.timer-button');
            const timeDisplay = timerContainer.querySelector('.timer-time');
            const progressCircle = timerContainer.querySelector('.timer-progress');
            const minutes = parseInt(timeDisplay.dataset.minutes);
            let duration = minutes * 60;
            let timerInterval;

            startButton.addEventListener('click', () => {
                if (startButton.textContent === 'Start') {
                    startButton.textContent = 'Pause';
                    startTimer();
                } else if (startButton.textContent === 'Pause') {
                    startButton.textContent = 'Resume';
                    pauseTimer();
                } else if (startButton.textContent === 'Resume') {
                    startButton.textContent = 'Pause';
                    resumeTimer();
                }
            });

            function startTimer() {
                let timeLeft = duration;
                timerInterval = setInterval(function () {
                    if (timeLeft <= 0) {
                        clearInterval(timerInterval);
                        startButton.textContent = 'Start';
                        timeLeft = duration;
                    } else {
                        timeLeft--;
                    }
                    updateDisplay(timeLeft);
                    updateCircle(timeLeft, duration);
                }, 1000);
            }

            function pauseTimer() {
                clearInterval(timerInterval);
            }
            function resumeTimer() {
                startTimer();
            }


            function updateDisplay(timeLeft) {
                const minutes = Math.floor(timeLeft / 60);
                const seconds = timeLeft % 60;
                timeDisplay.textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
            }

            function updateCircle(timeLeft, duration) {
                const circumference = 565.487;
                const offset = circumference - (timeLeft / duration) * circumference;
                progressCircle.style.strokeDashoffset = offset;
            }
        });
    </script>

</body>
</html>
