    <script>
        document.querySelectorAll('.star-rating').forEach(ratingContainer => {
            const ratingValue = parseFloat(ratingContainer.dataset.rating);
            const stars = ratingContainer.querySelectorAll('.star');

            stars.forEach((star, index) => {
                if (index + 0.5 < ratingValue) {
                    star.classList.add('active', 'fa-star');
                    star.classList.remove('fa-star-o', 'fa-star-half-o');
                } else if (index < ratingValue) {
                    star.classList.add('active', 'fa-star-half-o');
                    star.classList.remove('fa-star-o', 'fa-star');
                } else {
                    star.classList.remove('active', 'fa-star', 'fa-star-half-o');
                    star.classList.add('fa-star-o');
                }
            });
        });
    </script>

