<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Luxury Escapes</title>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700&family=Montserrat:wght@400;500&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Montserrat', sans-serif;
            background-color: #f8f8ff;
            color: #0A192F;
        }
        h1, h2, h3 {
            font-family: 'Playfair Display', serif;
            color: #0A192F;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .parallax-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            transform: translateZ(-1px) scale(1.5);
            z-index: -1;
        }
        .hero-content {
            position: relative;
            z-index: 1;
        }
        .destination-slider {
            position: relative;
            overflow: hidden;
        }
        .slider-wrapper {
            display: flex;
            transition: transform 0.5s ease-in-out;
        }
        .slider-item {
            min-width: 100%;
            padding: 2rem;
            box-sizing: border-box;
        }
        .slider-nav {
            position: absolute;
            top: 50%;
            left: 0;
            right: 0;
            display: flex;
            justify-content: space-between;
            padding: 0 2rem;
            transform: translateY(-50%);
        }
        .slider-nav button {
            background: rgba(255, 255, 255, 0.5);
            color: #0A192F;
            border: none;
            padding: 0.5rem 1rem;
            border-radius: 0.375rem;
            cursor: pointer;
            opacity: 0.7;
            transition: opacity 0.3s;
        }
        .slider-nav button:hover {
            opacity: 1;
        }
        .booking-button {
            background-color: #64FFDA;
            color: #0A192F;
            transition: background-color 0.3s ease;
        }
        .booking-button:hover {
            background-color: #42e2c3;
        }
        .luxury-card {
            background-color: white;
            border-radius: 1rem;
            overflow: hidden;
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .luxury-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 30px rgba(0, 0, 0, 0.12);
        }
        .parallax-hero {
            perspective: 1px;
            height: 100vh;
            overflow-x: hidden;
            overflow-y: auto;
        }
        .parallax-group {
            position: relative;
            height: 100vh;
            transform-style: preserve-3d;
        }
        .parallax-layer {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
        }
        .parallax-layer-base {
            transform: translateZ(-0.9px) scale(1.9);
            z-index: -1;
        }
        .parallax-layer-deeper {
            transform: translateZ(-0.5px) scale(1.5);
            z-index: -2;
        }
        .parallax-content {
            position: relative;
            z-index: 1;
            background-color: rgba(255, 255, 255, 0.8);
            padding: 4rem 2rem;
            border-radius: 0.5rem;
        }
        .fade-in {
            opacity: 0;
            transition: opacity 1s ease-out;
        }
        .fade-in.active {
            opacity: 1;
        }
        .zoom-in {
            transform: scale(0.95);
            transition: transform 0.5s ease-out, opacity 0.5s ease-out;
            opacity: 0;
        }
        .zoom-in.active {
            transform: scale(1);
            opacity: 1;
        }
        .slide-up {
            transform: translateY(50px);
            opacity: 0;
            transition: transform 0.8s ease-out, opacity 0.8s ease-out;
        }
        .slide-up.active {
            transform: translateY(0);
            opacity: 1;
        }

    </style>
</head>
<body class="bg-gray-50">

    <nav class="bg-white shadow-md sticky top-0 z-50">
