    <script>
        let sliderIndex = 0;
        const sliderWrapper = document.getElementById('slider-wrapper');
        const sliderItems = document.querySelectorAll('.slider-item');
        const totalItems = sliderItems.length;

        function updateSlider() {
            sliderWrapper.style.transform = `translateX(-${sliderIndex * 100}%)`;
        }

        function nextSlide() {
            sliderIndex = (sliderIndex + 1) % totalItems;
            updateSlider();
        }

        function prevSlide() {
            sliderIndex = (sliderIndex - 1 + totalItems) % totalItems;
            updateSlider();
        }

        document.addEventListener('DOMContentLoaded', () => {
            const fadeInElements = document.querySelectorAll('.fade-in');
            const zoomInElements = document.querySelectorAll('.zoom-in');
            const slideUpElements = document.querySelectorAll('.slide-up');

            const observerConfig = {
                threshold: 0.15
            };

            const fadeInObserver = new IntersectionObserver((entries, observer) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('active');
                        observer.unobserve(entry.target);
                    }
                });
            }, observerConfig);

            fadeInElements.forEach(element => fadeInObserver.observe(element));
            zoomInElements.forEach(element => fadeInObserver.observe(element));
            slideUpElements.forEach(element => fadeInObserver.observe(element));


            const mobileMenuButton = document.querySelector('[aria-controls="mobile-menu"]');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });


    </script>

</body>
</html>
