    <title>ChronoNews - Your Personalized Newsfeed</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Poppins', sans-serif;
            background-color: #f3f4f6;
            color: #1e293b;
        }
        .news-card {
            background-color: white;
            border-radius: 1rem;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
            transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
        }
        .news-card:hover {
            transform: scale(1.03);
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
        }
        .news-card-image {
            border-radius: 1rem 1rem 0 0;
            overflow: hidden;
        }
        .news-card-content {
            padding: 1.5rem;
        }
        .category-badge {
            background-color: #bae6fd;
            color: #0369a1;
            padding: 0.25rem 0.5rem;
            border-radius: 0.375rem;
            font-size: 0.75rem;
            font-weight: 500;
        }
        .article-title {
            font-size: 1.5rem;
            font-weight: 600;
            line-height: 1.25;
            margin-bottom: 0.75rem;
        }
        .article-excerpt {
            color: #4b5563;
            font-size: 1rem;
            line-height: 1.5;
        }
        .read-more-link {
            display: inline-flex;
            align-items: center;
            color: #0ea5e9;
            font-weight: 500;
            transition: color 0.2s ease-in-out;
        }
        .read-more-link:hover {
            color: #059669;
        }
        .topic-filter-button {
            background-color: #e5e7eb;
            color: #374151;
            padding: 0.5rem 1rem;
            border-radius: 0.5rem;
            font-weight: 500;
            transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out;
        }
        .topic-filter-button:hover, .topic-filter-button.active {
            background-color: #0ea5e9;
            color: white;
        }
        .topic-filter-button.active {
            box-shadow: 0 0 0 2px rgba(14, 165, 233, 0.5);
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .hero-overlay {
            position: absolute;
            inset-0;
            background: linear-gradient(to bottom, rgba(243, 244, 246, 0.1), rgba(243, 244, 246, 0.8));
        }
        .animated-underline {
            position: relative;
            display: inline-block;
            cursor: pointer;
        }

        .animated-underline::after {
            content: '';
            position: absolute;
            width: 100%;
            transform: scaleX(0);
            height: 2px;
            bottom: 0;
            left: 0;
            background-color: #0ea5e9;
            transform-origin: bottom right;
            transition: transform 0.3s ease-out;
        }

        .animated-underline:hover::after {
            transform: scaleX(1);
            transform-origin: bottom left;
        }
        .mobile-menu-button {
            background-color: #f9fafb;
            color: #1e293b;
            border-radius: 0.5rem;
            padding: 0.5rem;
            box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
            transition: background-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
        }

        .mobile-menu-button:hover {
            background-color: #f0f0f0;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
        }
        .mobile-menu {
            background-color: #f9fafb;
        }
        .mobile-menu a {
            color: #1e293b;
            transition: color 0.2s ease-in-out;
        }

        .mobile-menu a:hover {
            color: #0ea5e9;
        }
    </style>
</head>
