    <script>
        const topicFilterButtons = document.querySelectorAll('.topic-filter-button');
        const newsCards = document.querySelectorAll('.news-card');
        const mobileMenuOpenButton = document.getElementById('mobile-menu-open');
        const mobileMenuCloseButton = document.getElementById('mobile-menu-close');
        const mobileMenu = document.getElementById('mobile-menu');

        topicFilterButtons.forEach(button => {
            button.addEventListener('click', () => {
                topicFilterButtons.forEach(btn => btn.classList.remove('active'));
                button.classList.add('active');
                const selectedTopic = button.dataset.topic;

                newsCards.forEach(card => {
                    const cardTopics = card.dataset.topics.split(' ');
                    if (selectedTopic === 'all' || cardTopics.includes(selectedTopic)) {
                        card.style.display = 'block';
                    } else {
                        card.style.display = 'none';
                    }
                });
            });
        });

        mobileMenuOpenButton.addEventListener('click', () => {
            mobileMenu.classList.remove('hidden');
        });

        mobileMenuCloseButton.addEventListener('click', () => {
            mobileMenu.classList.add('hidden');
        });
    </script>

</body>
</html>
