    <style>
        body {
            font-family: 'Roboto Flex', sans-serif;
            background-color: #f3f4f6;
            color: #1e293b;
        }
        .card {
            background-color: white;
            border-radius: 1.25rem;
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);
            overflow: hidden;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
