            background-color: #3b82f6;
            transform: scale(1.05);
        }
        .news-source {
            letter-spacing: 0.05em;
            font-weight: 500;
            color: #9ca3af;
        }
        .news-title {
            font-size: 1.5rem;
            line-height: 1.2;
            font-weight: 700;
            color: #1e293b;
        }
        .news-summary {
            color: #4b5563;
            line-height: 1.6;
        }
        .filter-bar {
            background-color: #f9fafb;
            box-shadow: 0 2px 5px rgba(0, 0, 0, 0.06);
        }
        .hero-section {
            background: linear-gradient(45deg, #e0f2fe, #bae6fd);
        }
        .hero-title {
            font-size: 3rem;
            font-weight: 800;
            color: #1e3a8a;
            letter-spacing: -0.02em;
        }
        .hero-subtitle {
            font-size: 1.25rem;
            color: #4338ca;
        }
    </style>
</head>
<body class="bg-gray-100">

    <header class="filter-bar sticky top-0 z-50">
        <nav class="container mx-auto px-6 py-4">
            <div class="flex items-center justify-between">
                <div>
                    <span class="text-xl font-bold text-blue-700"><i class="fa fa-newspaper"></i> Daily Brief</span>
                </div>
                <div class="hidden md:flex space-x-4">
                    <div class="topic-filter active" data-topic="all">All</div>
                    <div class="topic-filter" data-topic="technology">Technology</div>
                    <div class="topic-filter" data-topic="business">Business</div>
                    <div class="topic-filter" data-topic="sports">Sports</div>
                    <div class="topic-filter" data-topic="politics">Politics</div>
                </div>
                <div class="md:hidden">
                    <button id="mobile-menu-button" class="text-gray-500 hover:text-gray-700 focus:outline-none">
                        <i class="fa fa-bars"></i>
                    </button>
                </div>
            </div>
            <div class="hidden md:hidden mt-2" id="mobile-menu">
                <div class="flex flex-col space-y-2">
                    <div class="topic-filter active" data-topic="all">All</div>
                    <div class="topic-filter" data-topic="technology">Technology</div>
                    <div class="topic-filter" data-topic="business">Business</div>
                    <div class="topic-filter" data-topic="sports">Sports</div>
                    <div class="topic-filter" data-topic="politics">Politics</div>
                </div>
            </div>
        </nav>
    </header>

    <section class="hero-section py-20">
        <div class="container mx-auto px-6 text-center">
            <h1 class="hero-title mb-4">Stay Informed, Effortlessly.</h1>
            <p class="hero-subtitle mb-8">Curated news summaries, just for you.</p>
            <button id="refresh-feed" class="refresh-button">
                <i class="fa fa-sync"></i> Refresh Feed
            </button>
        </div>
    </section>

    <main class="container mx-auto px-6 py-8">
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6" id="news-feed">
            </div>
    </main>

    <footer class="bg-white py-6 border-t border-gray-200">
        <div class="container mx-auto px-6 text-center text-gray-500">
            &copy; 2024 Daily Brief. All rights reserved.
        </div>
    </footer>

    <script>
        const newsFeedContainer = document.getElementById('news-feed');
        const topicFilters = document.querySelectorAll('.topic-filter');
        const refreshButton = document.getElementById('refresh-feed');
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        let currentTopic = 'all';
        let allNewsData = [];

        const newsSources = [
            "TechCrunch", "The Wall Street Journal", "ESPN", "Reuters", "BBC News",
            "Wired", "Bloomberg", "Sports Illustrated", "Associated Press", "CNN"
        ];
        const topics = ["technology", "business", "sports", "politics", "world"];

        function generatePlaceholderNews(topic = 'all') {
            const news = [];
            for (let i = 0; i < 9; i++) {
                const randomTopic = topics[Math.floor(Math.random() * topics.length)];
                const storyTopic = topic === 'all' ? randomTopic : topic;
                const source = newsSources[Math.floor(Math.random() * newsSources.length)];
                const imageId = Math.floor(Math.random() * 100) + i;
                news.push({
                    topic: storyTopic,
                    source: source,
                    title: `Headline for ${storyTopic} story ${i+1}`,
                    summary: `This is a brief summary of a news story related to ${storyTopic}. It includes key details and context.`,
                    image: `https://picsum.photos/id/${imageId}/400/225`
                });
            }
            return news;
        }

        function displayNews(newsData) {
            newsFeedContainer.innerHTML = '';
            newsData.forEach(story => {
                if (currentTopic === 'all' || story.topic === currentTopic) {
                    const card = document.createElement('div');
                    card.classList.add('card');
                    card.innerHTML = `
                        <img src="${story.image}" alt="${story.title}" class="card-image">
                        <div class="p-6">
                            <span class="news-source uppercase text-sm block mb-2">${story.source} - ${story.topic}</span>
                            <h2 class="news-title mb-3">${story.title}</h2>
                            <p class="news-summary">${story.summary}</p>
                            <a href="#" class="inline-block mt-4 text-blue-600 hover:underline">Read more <i class="fa fa-arrow-right"></i></a>
                        </div>
                    `;
                    newsFeedContainer.appendChild(card);
                }
            });
        }

        function loadNews(topic = 'all') {
            const loadingCards = Array(6).fill(null).map(() => {
                const card = document.createElement('div');
                card.classList.add('card', 'animate-pulse');
                card.innerHTML = `
                    <div class="bg-gray-200 h-48 w-full"></div>
                    <div class="p-6">
                        <div class="bg-gray-200 h-4 w-32 mb-2"></div>
                        <div class="bg-gray-200 h-6 w-full mb-3"></div>
                        <div class="bg-gray-200 h-4 w-48"></div>
                    </div>
                `;
                return card;
            });
            newsFeedContainer.innerHTML = '';
            loadingCards.forEach(card => newsFeedContainer.appendChild(card));

            setTimeout(() => {
                allNewsData = generatePlaceholderNews(topic);
                displayNews(allNewsData);
            }, 1000);
        }

        loadNews();

        topicFilters.forEach(filter => {
            filter.addEventListener('click', function() {
                topicFilters.forEach(f => f.classList.remove('active'));
                this.classList.add('active');
                currentTopic = this.dataset.topic;
                loadNews(currentTopic);
            });
        });

        refreshButton.addEventListener('click', function() {
            loadNews(currentTopic);
        });

        mobileMenuButton.addEventListener('click', function() {
            mobileMenu.classList.toggle('hidden');
        });
    </script>

</body>
</html>
