                    <label for="booking-date" class="label">Date</label>
                    <input type="date" id="booking-date" class="input-field" disabled>
                </div>
                <div>
                    <label for="booking-time" class="label">Time</label>
                    <input type="time" id="booking-time" class="input-field" disabled>
                </div>
