    <script>
        document.addEventListener('DOMContentLoaded', function() {
            initializeTableMap();
            initializeCalendar();
        });

        let selectedDate = null;
        let selectedTime = null;
        let selectedTable = null;

        const tableData = [
            { id: 1, seats: 2, position: { top: '20%', left: '20%' }, status: 'available' },
            { id: 2, seats: 4, position: { top: '20%', right: '20%' }, status: 'available' },
            { id: 3, seats: 2, position: { bottom: '10%', left: '30%' }, status: 'available' },
            { id: 4, seats: 4, position: { bottom: '10%', right: '30%' }, status: 'reserved' },
            { id: 5, seats: 6, position: { top: '50%', left: '50%' }, status: 'available' },
        ];

        function initializeTableMap() {
            const tableMapContainer = document.getElementById('table-map');
            tableData.forEach(table => {
                const tableElement = document.createElement('div');
                tableElement.classList.add('table');
                tableElement.classList.add(table.status);
                tableElement.style.top = table.position.top;
                tableElement.style.left = table.position.left;
                tableElement.textContent = `Table ${table.id} (${table.seats}-seats)`;

                if (table.status === 'available') {
                    tableElement.addEventListener('click', () => selectTable(table, tableElement));
                }

                tableMapContainer.appendChild(tableElement);
            });
        }

        function selectTable(table, element) {
            if (selectedTable) {
                selectedTable.classList.remove('ring-2', 'ring-amber-500', 'ring-offset-2');
            }
            selectedTable = element;
            selectedTable.classList.add('ring-2', 'ring-amber-500', 'ring-offset-2');
        }


        let currentDate = new Date();

        function initializeCalendar() {
            renderCalendar(currentDate.getFullYear(), currentDate.getMonth());
        }

        function renderCalendar(year, month) {
            const calendarContainer = document.getElementById('calendar');
            calendarContainer.innerHTML = '';

            const calendar = document.createElement('div');
            calendar.classList.add('booking-calendar');

            const header = createCalendarHeader(year, month);
            calendar.appendChild(header);

            const daysOfWeek = createDaysOfWeek();
            calendar.appendChild(daysOfWeek);

            const grid = createCalendarGrid(year, month);
            calendar.appendChild(grid);

            calendarContainer.appendChild(calendar);
        }

        function createCalendarHeader(year, month) {
            const header = document.createElement('div');
            header.classList.add('calendar-header');

            const monthYear = document.createElement('h2');
            monthYear.classList.add('calendar-month');
            monthYear.textContent = new Date(year, month).toLocaleString('default', { month: 'long', year: 'numeric' });

            const controls = document.createElement('div');
            controls.classList.add('calendar-controls');

            const prevButton = document.createElement('button');
            prevButton.textContent = '<';
            prevButton.onclick = () => {
                currentDate.setMonth(currentDate.getMonth() - 1);
                renderCalendar(currentDate.getFullYear(), currentDate.getMonth());
            };

            const nextButton = document.createElement('button');
            nextButton.textContent = '>';
            nextButton.onclick = () => {
                currentDate.setMonth(currentDate.getMonth() + 1);
                renderCalendar(currentDate.getFullYear(), currentDate.getMonth());
            };

            controls.appendChild(prevButton);
            controls.appendChild(nextButton);

            header.appendChild(monthYear);
            header.appendChild(controls);
            return header;
        }

        function createDaysOfWeek() {
            const daysOfWeek = document.createElement('div');
            daysOfWeek.classList.add('calendar-grid');

            const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
            dayNames.forEach(dayName => {
                const dayHeader = document.createElement('div');
                dayHeader.classList.add('calendar-day-header');
                dayHeader.textContent = dayName;
                daysOfWeek.appendChild(dayHeader);
            });
            return daysOfWeek;
        }

        function createCalendarGrid(year, month) {
            const grid = document.createElement('div');
            grid.classList.add('calendar-grid');

            const firstDayOfMonth = new Date(year, month, 1);
            const daysInMonth = new Date(year, month + 1, 0).getDate();
            const startingDay = firstDayOfMonth.getDay();

            for (let i = 0; i < startingDay; i++) {
                const emptyDay = document.createElement('div');
                emptyDay.classList.add('calendar-day', 'other-month');
                grid.appendChild(emptyDay);
            }

            for (let day = 1; day <= daysInMonth; day++) {
                const date = new Date(year, month, day);
                const dayElement = document.createElement('div');
                dayElement.classList.add('calendar-day', 'current-month', 'available-date');
                dayElement.textContent = day;

                dayElement.addEventListener('click', () => selectDate(date, dayElement));

                grid.appendChild(dayElement);
            }
            return grid;
        }


        function selectDate(date, element) {
            if (selectedDate) {
                document.querySelectorAll('.calendar-day.selected-date').forEach(el => el.classList.remove('selected-date'));
            }
            selectedDate = date;
            element.classList.add('selected-date');
            updateBookingModalDate();
        }

        function updateBookingModalDate() {
            if (selectedDate) {
                const formattedDate = selectedDate.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
                document.getElementById('booking-date').value = formattedDate;
            }
        }


        function openBookingModal() {
            if (!selectedDate) {
                alert('Please select a date from the calendar.');
                return;
            }
            if (!selectedTable) {
                alert('Please select a table from the table map.');
                return;
            }

            const timeSlot = document.getElementById('time-slot').value;
            const formattedTime = new Date(`1970-01-01T${timeSlot}:00Z`).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

            document.getElementById('booking-date').value = selectedDate.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
            document.getElementById('booking-time').value = formattedTime;

            document.getElementById('bookingModal').classList.remove('hidden');
        }

        function closeBookingModal() {
            document.getElementById('bookingModal').classList.add('hidden');
        }

        document.getElementById('bookingForm').addEventListener('submit', function(event) {
            event.preventDefault();
            alert('Reservation confirmed! Thank you for booking with Elevated Eats.');
            closeBookingModal();
            resetReservationState();
        });

        function resetReservationState() {
            selectedDate = null;
            selectedTime = null;
            selectedTable = null;
            document.querySelectorAll('.calendar-day.selected-date').forEach(el => el.classList.remove('selected-date'));
            if (selectedTable) {
                selectedTable.classList.remove('ring-2', 'ring-amber-500', 'ring-offset-2');
            }
        }


        gsap.registerPlugin(ScrollTrigger);

        gsap.from('.hero-section .relative > *', {
            y: 50,
            opacity: 0,
            duration: 1.5,
            stagger: 0.2,
            ease: 'power3.out'
        });

        gsap.utils.toArray('.menu-item').forEach(item => {
            gsap.from(item, {
                y: 50,
                opacity: 0,
                duration: 1,
                scrollTrigger: {
                    trigger: item,
                    start: 'top 80%',
                    toggleActions: 'play none none reverse'
                }
            });
        });

        gsap.from('#reservations h2, #reservations .grid', {
            y: 50,
            opacity: 0,
            duration: 1,
            scrollTrigger: {
                trigger: '#reservations',
                start: 'top 80%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.from('#about h2, #about .grid', {
            y: 50,
            opacity: 0,
            duration: 1,
            scrollTrigger: {
                trigger: '#about',
                start: 'top 80%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.from('#contact h2, #contact .grid', {
            y: 50,
            opacity: 0,
            duration: 1,
            scrollTrigger: {
                trigger: '#contact',
                start: 'top 80%',
                toggleActions: 'play none none reverse'
            }
        });
    </script>

</body>
</html>
