<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Virtual Museum Tour</title>
    <link href="https://fonts.googleapis.com/css2?family=Lora:wght@400;700&family=Montserrat:wght@400;600&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Montserrat', sans-serif;
            color: #333;
        }
        h1, h2, h3 {
            font-family: 'Lora', serif;
            font-weight: 700;
            color: #1e3a8a;
        }
        .artifact-popup {
            display: none;
            position: fixed;
            z-index: 50;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            overflow: auto;
            background-color: rgba(0,0,0,0.8);
        }
        .artifact-popup-content {
            background-color: #f9f9f9;
            margin: 15% auto;
            padding: 30px;
            border: 1px solid #888;
            width: 80%;
            position: relative;
            border-radius: 12px;
        }
        .artifact-close-button {
            color: #aaa;
            position: absolute;
            top: 10px;
            right: 20px;
            font-size: 28px;
            font-weight: bold;
        }
        .artifact-close-button:hover,
        .artifact-close-button:focus {
            color: black;
            text-decoration: none;
            cursor: pointer;
        }
        .gallery-section {
            background: linear-gradient(135deg, #f0f4f8, #e0e7ef);
        }
        .audio-guide-controls button {
            background-color: #a7f3d0;
            color: #15803d;
            border: none;
            padding: 10px 15px;
            border-radius: 8px;
            cursor: pointer;
            transition: background-color 0.3s ease;
        }
        .audio-guide-controls button:hover {
            background-color: #86efac;
        }
        .artifact-hotspot {
            position: absolute;
            background-color: rgba(255, 255, 255, 0.7);
            border-radius: 50%;
            width: 20px;
            height: 20px;
            cursor: pointer;
            border: 2px solid #d97706;
            opacity: 0.8;
            transition: opacity 0.3s ease, transform 0.3s ease;
        }
        .artifact-hotspot:hover {
            opacity: 1;
            transform: scale(1.2);
        }
        .artifact-image-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
            gap: 20px;
        }
        .artifact-image-grid img {
            border-radius: 12px;
            box-shadow: 0 4px 8px rgba(0,0,0,0.1);
            transition: transform 0.3s ease;
        }
        .artifact-image-grid img:hover {
            transform: scale(1.03);
        }
        .gallery-navigation button {
            background-color: #93c5fd;
            color: #1e40af;
            padding: 12px 24px;
            border-radius: 8px;
            cursor: pointer;
            transition: background-color 0.3s ease, transform 0.3s ease;
            font-weight: 600;
        }
        .gallery-navigation button:hover {
            background-color: #60a5fa;
            transform: scale(1.05);
        }
        .hero-section {
            background: linear-gradient(to right, #e6f7ff, #ccebff);
        }
        .hero-content {
            text-shadow: 2px 2px 4px rgba(0,0,0,0.1);
        }
        .hero-button {
            background-color: #ffedd5;
            color: #d97706;
            font-weight: 600;
            transition: background-color 0.3s ease, transform 0.3s ease;
        }
        .hero-button:hover {
            background-color: #fed7aa;
            transform: scale(1.08);
        }
        .section-title {
            color: #1e3a8a;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.05);
        }
        .feature-card {
            background-color: #fff;
            border-radius: 12px;
            box-shadow: 0 6px 12px rgba(0,0,0,0.08);
            transition: box-shadow 0.3s ease, transform 0.3s ease;
        }
        .feature-card:hover {
            box-shadow: 0 8px 16px rgba(0,0,0,0.12);
            transform: scale(1.03);
        }
        .footer-section {
            background-color: #f0f0f0;
            color: #555;
        }
        .footer-link:hover {
            color: #333;
            text-decoration: underline;
        }
        .gallery-image-container {
            position: relative;
            overflow: hidden;
            border-radius: 12px;
            box-shadow: 0 8px 16px rgba(0,0,0,0.1);
        }
        .gallery-image-container img {
            transition: transform 0.8s ease-in-out;
        }
        .gallery-image-container:hover img {
            transform: scale(1.1);
        }
        .gallery-image-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(30, 58, 138, 0.5);
            color: white;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            opacity: 0;
            transition: opacity 0.4s ease-in-out;
            border-radius: 12px;
        }
        .gallery-image-container:hover .gallery-image-overlay {
            opacity: 1;
        }
        .gallery-image-overlay h3 {
            color: white;
            font-size: 1.8rem;
            margin-bottom: 10px;
            text-shadow: none;
        }
        .gallery-image-overlay p {
            font-size: 1.1rem;
            padding: 0 20px;
            text-align: center;
        }
        .artifact-popup-image {
            border-radius: 12px;
            box-shadow: 0 6px 12px rgba(0,0,0,0.15);
            max-width: 100%;
            height: auto;
            margin-bottom: 20px;
        }
        .artifact-popup-title {
            font-size: 2.2rem;
            margin-bottom: 15px;
            color: #1e3a8a;
        }
        .artifact-popup-description {
            font-size: 1.1rem;
            line-height: 1.6;
            color: #4a5568;
            margin-bottom: 25px;
        }
        .audio-controls-container {
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 15px;
            margin-top: 20px;
        }
        .audio-controls-container button {
            padding: 12px 20px;
            border-radius: 8px;
            border: none;
            background-color: #bae6fd;
            color: #0c4a6e;
            cursor: pointer;
            transition: background-color 0.3s ease, transform 0.3s ease;
            font-weight: 600;
        }
        .audio-controls-container button:hover {
            background-color: #7dd3fc;
            transform: scale(1.05);
        }
        .audio-controls-container button:disabled {
            background-color: #e0f2fe;
            color: #94a3b8;
            cursor: not-allowed;
            transform: none;
        }

    </style>
</head>
<body class="bg-gray-50">

    <header class="hero-section py-20">
        <div class="container mx-auto px-6 text-center hero-content">
            <h1 class="text-5xl md:text-6xl font-bold mb-6 section-title">Welcome to the Virtual Museum</h1>
            <p class="text-lg md:text-xl text-gray-700 mb-12">Explore artifacts from around the world in stunning detail.</p>
            <button class="hero-button px-8 py-4 rounded-full text-lg shadow-md hover:shadow-lg"><i class="fas fa-compass mr-2"></i> Start Your Tour</button>
        </div>
    </header>

    <section class="gallery-section py-24">
        <div class="container mx-auto px-6">
            <h2 class="text-3xl md:text-4xl font-bold text-center mb-16 section-title">Featured Galleries</h2>
            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                <div class="gallery-image-container">
                    <img src="https://picsum.photos/400/300?gallery=ancient" alt="Ancient Civilizations" class="w-full block">
                    <div class="gallery-image-overlay">
                        <h3>Ancient Civilizations</h3>
                        <p>Discover relics from forgotten empires and ancient cultures.</p>
                        <button class="mt-4 gallery-navigation button">Explore Gallery</button>
                    </div>
                </div>
                <div class="gallery-image-container">
                    <img src="https://picsum.photos/400/301?gallery=modern" alt="Modern Art" class="w-full block">
                    <div class="gallery-image-overlay">
                        <h3>Modern Art</h3>
                        <p>Experience groundbreaking masterpieces of the 20th and 21st centuries.</p>
                        <button class="mt-4 gallery-navigation button">Explore Gallery</button>
                    </div>
                </div>
                <div class="gallery-image-container">
                    <img src="https://picsum.photos/400/302?gallery=natural" alt="Natural History" class="w-full block">
                    <div class="gallery-image-overlay">
                        <h3>Natural History</h3>
                        <p>Journey through the wonders of the natural world and its diverse inhabitants.</p>
                        <button class="mt-4 gallery-navigation button">Explore Gallery</button>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <section class="py-24 bg-white">
        <div class="container mx-auto px-6">
            <h2 class="text-3xl md:text-4xl font-bold text-center mb-16 section-title">Explore Artifacts</h2>
            <div class="artifact-image-grid">
                <div class="feature-card p-6">
                    <img src="https://picsum.photos/250/200?artifact=1" alt="Artifact 1" class="w-full mb-4">
                    <h3 class="text-xl font-semibold mb-2">Ancient Sculpture</h3>
                    <p class="text-gray-600">Exquisite marble sculpture from the Hellenistic period.</p>
                    <button class="mt-4 text-blue-600 font-semibold hover:underline artifact-link" data-artifact-id="artifact1">Learn More</button>
                </div>
                <div class="feature-card p-6">
                    <img src="https://picsum.photos/250/201?artifact=2" alt="Artifact 2" class="w-full mb-4">
                    <h3 class="text-xl font-semibold mb-2">Medieval Manuscript</h3>
                    <p class="text-gray-600">Illuminated manuscript detailing life in the Middle Ages.</p>
                    <button class="mt-4 text-blue-600 font-semibold hover:underline artifact-link" data-artifact-id="artifact2">Learn More</button>
                </div>
                <div class="feature-card p-6">
                    <img src="https://picsum.photos/250/202?artifact=3" alt="Artifact 3" class="w-full mb-4">
                    <h3 class="text-xl font-semibold mb-2">Renaissance Painting</h3>
                    <p class="text-gray-600">Masterpiece painting from the Italian Renaissance era.</p>
                    <button class="mt-4 text-blue-600 font-semibold hover:underline artifact-link" data-artifact-id="artifact3">Learn More</button>
                </div>
                <div class="feature-card p-6">
                    <img src="https://picsum.photos/250/203?artifact=4" alt="Artifact 4" class="w-full mb-4">
                    <h3 class="text-xl font-semibold mb-2">Egyptian Artifact</h3>
                    <p class="text-gray-600">Ancient Egyptian sarcophagus with hieroglyphic inscriptions.</p>
                    <button class="mt-4 text-blue-600 font-semibold hover:underline artifact-link" data-artifact-id="artifact4">Learn More</button>
                </div>
            </div>
        </div>
    </section>

    <section class="gallery-section py-24 relative">
        <div class="container mx-auto px-6 text-center">
            <h2 class="text-3xl md:text-4xl font-bold mb-16 section-title">Virtual Gallery Walkthrough</h2>
            <div class="gallery-image-container mx-auto max-w-5xl relative">
                <img src="https://picsum.photos/1200/600?galleryview" alt="Virtual Gallery" class="w-full rounded-xl shadow-xl">
                <div class="artifact-hotspot" style="top: 30%; left: 20%;" data-artifact-id="hotspot1"></div>
                <div class="artifact-hotspot" style="top: 50%; right: 15%;" data-artifact-id="hotspot2"></div>
                <div class="artifact-hotspot" style="bottom: 25%; left: 40%;" data-artifact-id="hotspot3"></div>
            </div>
        </div>
    </section>

    <div id="artifactPopup" class="artifact-popup">
        <div class="artifact-popup-content">
            <span class="artifact-close-button">&times;</span>
            <img src="https://picsum.photos/600/400?popup" alt="Artifact Detail" class="artifact-popup-image">
            <h2 class="artifact-popup-title">Artifact Title</h2>
            <p class="artifact-popup-description">Detailed description of the artifact goes here. This can include historical context, cultural significance, and interesting facts about its creation and discovery. Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</p>
            <div class="audio-controls-container">
                <button id="playAudio"><i class="fas fa-play"></i> Play Guide</button>
                <button id="pauseAudio" disabled><i class="fas fa-pause"></i> Pause</button>
                <button id="stopAudio" disabled><i class="fas fa-stop"></i> Stop</button>
            </div>
        </div>
    </div>

    <footer class="footer-section py-12">
        <div class="container mx-auto px-6 text-center">
            <p>&copy; 2024 Virtual Museum. All rights reserved.</p>
            <nav class="mt-4">
                <a href="#" class="text-blue-600 hover:underline footer-link">About</a>
                <a href="#" class="text-blue-600 hover:underline ml-4 footer-link">Contact</a>
                <a href="#" class="text-blue-600 hover:underline ml-4 footer-link">Privacy Policy</a>
            </nav>
        </div>
    </footer>

    <script>
        const artifactLinks = document.querySelectorAll('.artifact-link, .artifact-hotspot');
        const artifactPopup = document.getElementById('artifactPopup');
        const closeButton = document.querySelector('.artifact-close-button');
        const popupTitle = artifactPopup.querySelector('.artifact-popup-title');
        const popupDescription = artifactPopup.querySelector('.artifact-popup-description');
        const popupImage = artifactPopup.querySelector('.artifact-popup-image');
        const playButton = document.getElementById('playAudio');
        const pauseButton = document.getElementById('pauseAudio');
        const stopButton = document.getElementById('stopAudio');
        let audio = new Audio('https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3');

        artifactLinks.forEach(link => {
            link.addEventListener('click', (event) => {
                event.preventDefault();
                artifactPopup.style.display = "block";
                popupTitle.textContent = "Artifact Title";
                popupDescription.textContent = "Detailed description of the artifact goes here. This is example content.";
                popupImage.src = "https://picsum.photos/600/400?popup-detail";
                audio.pause();
                audio.currentTime = 0;
                pauseButton.disabled = true;
                stopButton.disabled = true;
                playButton.disabled = false;
            });
        });

        closeButton.addEventListener('click', () => {
            artifactPopup.style.display = "none";
            audio.pause();
            audio.currentTime = 0;
            pauseButton.disabled = true;
            stopButton.disabled = true;
            playButton.disabled = false;
        });

        window.addEventListener('click', (event) => {
            if (event.target == artifactPopup) {
                artifactPopup.style.display = "none";
                audio.pause();
                audio.currentTime = 0;
                pauseButton.disabled = true;
                stopButton.disabled = true;
                playButton.disabled = false;
            }
        });

        playButton.addEventListener('click', () => {
            audio.play();
            playButton.disabled = true;
            pauseButton.disabled = false;
            stopButton.disabled = false;
        });

        pauseButton.addEventListener('click', () => {
            audio.pause();
            playButton.disabled = false;
            pauseButton.disabled = true;
            stopButton.disabled = false;
        });

        stopButton.addEventListener('click', () => {
            audio.pause();
            audio.currentTime = 0;
            playButton.disabled = false;
            pauseButton.disabled = true;
            stopButton.disabled = true;
        });
    </script>

</body>
</html>
