        document.getElementById('mobile-menu-button').addEventListener('click', function() {
            document.getElementById('mobile-menu').classList.toggle('hidden');
        });

        function slideImage(direction, sliderId) {
            const track = document.getElementById(sliderId);
            const itemWidth = document.querySelector(`#${sliderId} .product-image-item`).offsetWidth;
            const currentPosition = track.style.transform ? parseInt(track.style.transform.split('translateX(')[1]) || 0 : 0;
            let newPosition = currentPosition - direction * itemWidth;

            const maxPosition = 0;
            const minPosition = -itemWidth * (track.children.length - 1);

            if (newPosition > maxPosition) newPosition = maxPosition;
            if (newPosition < minPosition) newPosition = minPosition;

            track.style.transform = `translateX(${newPosition}px)`;
        }

    </script>

