<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ApexFin - Revolutionizing Finance</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600;700&family=Inter:wght@400;500&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Inter', sans-serif;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }
        h1, h2, h3, h4, h5, h6 {
            font-family: 'Poppins', sans-serif;
        }
        .chart-container {
            position: relative;
            width: 100%;
            height: 0;
            padding-top: 50%;
        }
        .chart {
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
        }
        .transaction-flow {
            position: relative;
            width: 100%;
            height: 300px;
        }
        .transaction-flow::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 0;
            right: 0;
            height: 2px;
            background: linear-gradient(to right, #2DD4CF, #0E2A47);
            transform: translateY(-50%);
        }
        .flow-node {
            position: absolute;
            top: 50%;
            border-radius: 50%;
            width: 20px;
            height: 20px;
            background-color: #F9FAFB;
            border: 2px solid #2DD4CF;
            transform: translate(-50%, -50%);
            z-index: 1;
            animation: flow 2s linear infinite alternate;
        }
        .flow-node:nth-child(2) {
            left: 25%;
            animation-delay: 0.5s;
        }
        .flow-node:nth-child(3) {
            left: 50%;
            animation-delay: 1s;
        }
        .flow-node:nth-child(4) {
            left: 75%;
            animation-delay: 1.5s;
        }
        .flow-node:nth-child(5) {
            left: 100%;
            animation-delay: 2s;
        }


        @keyframes flow {
            0% { transform: translate(-50%, -50%) scale(1); }
            100% { transform: translate(-50%, -50%) scale(1.2); }
        }

        .pulse {
            animation: pulse-animation 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulse-animation {
            0% {
                transform: scale(1);
                opacity: 1;
            }
            100% {
                transform: scale(1.3);
                opacity: 0;
            }
        }

        .slide-in-left {
            animation: slideInLeft 0.5s ease-out forwards;
            opacity: 0;
        }

        @keyframes slideInLeft {
            0% { transform: translateX(-100%); opacity: 0; }
            100% { transform: translateX(0); opacity: 1; }
        }


    </style>
</head>
