    <style>
        body { font-family: 'Nunito Sans', sans-serif; }
        .hero-section {
            background: linear-gradient(135deg, #06b6d4, #2dd4cf);
            background-size: 200% 200%;
            animation: gradient 10s ease infinite;
        }
        @keyframes gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .marker {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            background-color: #a3e635;
            animation: pulse 1.5s infinite cubic-bezier(0.66, 0, 0, 1);
        }
        @keyframes pulse {
            50% { transform: scale(1.5); opacity: 0.5; }
            100% { transform: scale(1); opacity: 1; }
        }
        .smooth-shadow {
            box-shadow: 5px 5px 20px rgba(0,0,0,0.1);
        }
        .layered-card {
            box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.05);
            transition: transform 0.3s ease-out, box-shadow 0.3s ease-out;
        }
        .layered-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.05);
        }
        .notification-card {
            background-color: #f0f9ff;
            border-left: 4px solid #63b3ed;
        }
        .optimized-route-line {
            stroke-dasharray: 10;
            animation: dash 5s linear infinite;
        }
        @keyframes dash {
            to {
                stroke-dashoffset: 1000;
            }
        }
        .fade-in-delayed {
            opacity: 0;
            transition: opacity 1s ease-out 0.3s;
        }
        .fade-in-delayed.visible {
            opacity: 1;
        }

    </style>
