<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Aura Smart Wearable</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&family=Inter:wght@400;500&display=swap" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <script src="https://unpkg.com/lucide@latest"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>
    <style>
        body {
            font-family: 'Inter', sans-serif;
        }
        h1, h2, h3, h4, h5, h6 {
            font-family: 'Poppins', sans-serif;
        }
        .hero-gradient {
            background: linear-gradient(135deg, #1E3A8A, #2DD4CF);
            background-size: 200% 200%;
            animation: gradient 10s ease infinite;
        }
        @keyframes gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .float {
            animation: floatAnim 3s ease-in-out infinite;
        }
        @keyframes floatAnim {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-10px); }
        }
        .pulse-teal {
            animation: pulseTeal 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulseTeal {
            0%, 100% {
                opacity: 1;
            }
            50% {
                opacity: .5;
            }
        }
        .tilt-on-hover {
            transition: transform 0.3s ease;
        }
        .tilt-on-hover:hover {
            transform: rotateX(10deg) rotateY(10deg);
        }
        .slide-in-left {
            transform: translateX(-100%);
            transition: transform 1s ease-out;
        }
        .slide-in-left.active {
            transform: translateX(0);
        }
        .slide-in-right {
            transform: translateX(100%);
            transition: transform 1s ease-out;
        }
        .slide-in-right.active {
            transform: translateX(0);
        }
        .fade-in {
            opacity: 0;
            transition: opacity 1s ease-out;
        }
        .fade-in.active {
            opacity: 1;
        }
    </style>
</head>
<body class="bg-gray-100 text-gray-900">

    <nav class="bg-gray-100/90 backdrop-blur-sm fixed w-full top-0 z-50 shadow-md">
