<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>CanvasCraft Pro</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;800&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Poppins', sans-serif; }
        .dynamic-shadow { transition: box-shadow 0.3s ease; }
        .dynamic-shadow:hover { box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3); }
        .tool-active { border-color: #6366f1; background-color: #e0e7ff; }
        .layer-active { background-color: #e0e7ff; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .fade-in { animation: fadeIn 0.5s ease-in-out forwards; }
        @keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .slide-up { animation: slideUp 0.5s ease-out forwards; }
        .export-option { transition: transform 0.2s ease-in-out; }
        .export-option:hover { transform: scale(1.1); }
        .brush-preview { border: 1px solid #ccc; }
        .brush-settings-panel { transform: translateY(100%); transition: transform 0.3s ease-out; }
        .brush-settings-panel.open { transform: translateY(0); }
        .layer-panel { transform: translateX(-100%); transition: transform 0.3s ease-out; }
        .layer-panel.open { transform: translateX(0); }
        .color-picker-panel { transform: translateY(100%); transition: transform 0.3s ease-out; }
        .color-picker-panel.open { transform: translateY(0); }
        .canvas-container { overflow: hidden; }
        .canvas-layer { position: absolute; top: 0; left: 0; }
    </style>
</head>
<body class="bg-gray-100 text-gray-900 overflow-hidden">

