            </div>
            <div class="mb-4">
                <label for="lightness-slider" class="block text-sm font-medium text-gray-700">Lightness</label>
                <input type="range" id="lightness-slider" min="0" max="100" value="50" class="w-full">
            </div>
            <div class="flex justify-end">
                <button id="apply-color" class="bg-blue-500 hover:bg-blue-700 text-white py-2 px-4 rounded">Apply Color</button>
            </div>
        </div>

        <div id="export-modal" class="fixed hidden top-0 left-0 w-full h-full bg-black bg-opacity-50 z-50 flex justify-center items-center">
            <div class="bg-white p-8 rounded-lg shadow-xl">
                <h2 class="text-2xl font-bold mb-6">Export Options</h2>
                <div class="grid grid-cols-2 md:grid-cols-3 gap-4 mb-6">
                    <button class="export-option bg-gray-100 hover:bg-gray-200 p-4 rounded-lg flex flex-col items-center justify-center">
                        <i class="fa-solid fa-image text-2xl mb-2"></i>
                        <span>PNG</span>
                    </button>
                    <button class="export-option bg-gray-100 hover:bg-gray-200 p-4 rounded-lg flex flex-col items-center justify-center">
                        <i class="fa-solid fa-file-jpg text-2xl mb-2"></i>
                        <span>JPG</span>
                    </button>
                    <button class="export-option bg-gray-100 hover:bg-gray-200 p-4 rounded-lg flex flex-col items-center justify-center">
                        <i class="fa-solid fa-file-svg text-2xl mb-2"></i>
                        <span>SVG</span>
                    </button>
                    <button class="export-option bg-gray-100 hover:bg-gray-200 p-4 rounded-lg flex flex-col items-center justify-center">
                        <i class="fa-solid fa-file-pdf text-2xl mb-2"></i>
                        <span>PDF</span>
                    </button>
                    <button class="export-option bg-gray-100 hover:bg-gray-200 p-4 rounded-lg flex flex-col items-center justify-center">
                        <i class="fa-solid fa-file-gif text-2xl mb-2"></i>
                        <span>GIF</span>
                    </button>
                    <button class="export-option bg-gray-100 hover:bg-gray-200 p-4 rounded-lg flex flex-col items-center justify-center">
                        <i class="fa-solid fa-file-bitmap text-2xl mb-2"></i>
                        <span>BMP</span>
                    </button>
                </div>
                <div class="flex justify-end">
                    <button id="close-export-modal" class="bg-gray-300 hover:bg-gray-400 px-4 py-2 rounded-md mr-2">Cancel</button>
                    <button id="confirm-export" class="bg-blue-500 hover:bg-blue-700 text-white px-4 py-2 rounded-md">Export</button>
                </div>
            </div>
        </div>

    </div>

    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenuClose = document.getElementById('mobile-menu-close');
        const mobileMenu = document.getElementById('mobile-menu');
        const layerPanelToggleMobile = document.getElementById('layer-panel-toggle-mobile');
        const brushSettingsToggleMobile = document.getElementById('brush-settings-toggle-mobile');
        const exportButtonMobile = document.getElementById('export-button-mobile');

        mobileMenuButton.addEventListener('click', () => mobileMenu.classList.remove('hidden'));
        mobileMenuClose.addEventListener('click', () => mobileMenu.classList.add('hidden'));
        layerPanelToggleMobile.addEventListener('click', () => {layerPanel.classList.toggle('open'); mobileMenu.classList.add('hidden');});
        brushSettingsToggleMobile.addEventListener('click', () => {brushSettingsPanel.classList.add('open'); colorPickerPanel.classList.remove('open'); mobileMenu.classList.add('hidden');});
        exportButtonMobile.addEventListener('click', () => {exportModal.classList.remove('hidden'); mobileMenu.classList.add('hidden');});

        const layerPanelToggle = document.getElementById('layer-panel-toggle');
        const brushSettingsToggle = document.getElementById('brush-settings-toggle');
        const exportButton = document.getElementById('export-button');
        const layerPanel = document.getElementById('layer-panel');
        const brushSettingsPanel = document.getElementById('brush-settings-panel');
        const exportModal = document.getElementById('export-modal');
        const closeExportModal = document.getElementById('close-export-modal');

        layerPanelToggle.addEventListener('click', () => { layerPanel.classList.toggle('open'); brushSettingsPanel.classList.remove('open'); colorPickerPanel.classList.remove('open'); });
        brushSettingsToggle.addEventListener('click', () => { brushSettingsPanel.classList.toggle('open'); layerPanel.classList.remove('open'); colorPickerPanel.classList.remove('open'); });
        exportButton.addEventListener('click', () => { exportModal.classList.remove('hidden'); layerPanel.classList.remove('open'); brushSettingsPanel.classList.remove('open'); colorPickerPanel.classList.remove('open'); });
        closeExportModal.addEventListener('click', () => exportModal.classList.add('hidden'));

        const mainCanvas = document.getElementById('main-canvas');
        const tempCanvas = document.getElementById('temp-canvas');
        const ctx = mainCanvas.getContext('2d');
        const tempCtx = tempCanvas.getContext('2d');

        let drawingMode = 'brush';
        let isDrawing = false;
        let brushSize = 5;
        let brushColor = '#000000';
        let brushOpacity = 1;
        let brushType = 'basic';

        mainCanvas.width = 1200;
        mainCanvas.height = 800;
        tempCanvas.width = 1200;
        tempCanvas.height = 800;

        const brushSizeInput = document.getElementById('brush-size');
        const brushOpacityInput = document.getElementById('brush-opacity');
        const colorSelector = document.getElementById('color-selector');
        const brushPreview = document.querySelector('.brush-preview');
        const brushTypeBasic = document.getElementById('brush-type-basic');
        const brushTypeSoft = document.getElementById('brush-type-soft');
        const brushTypePattern = document.getElementById('brush-type-pattern');
        const toolButtons = document.querySelectorAll('.tool-button');
        const colorPickerToolButton = document.getElementById('color-picker-tool');
        const colorPickerPanel = document.getElementById('color-picker-panel');
        const openColorPickerButton = document.getElementById('open-color-picker');
        const closeColorPickerButton = document.getElementById('close-color-picker');
        const hueSlider = document.getElementById('hue-slider');
        const saturationSlider = document.getElementById('saturation-slider');
        const lightnessSlider = document.getElementById('lightness-slider');
        const applyColorButton = document.getElementById('apply-color');
        const brushToolButton = document.getElementById('brush-tool');
        const eraserToolButton = document.getElementById('eraser-tool');

        function setBrushPreview() {
            brushPreview.style.backgroundColor = brushColor;
            brushPreview.style.opacity = brushOpacity;
            brushPreview.style.width = `${brushSize}px`;
            brushPreview.style.height = `${brushSize}px`;
        }

        brushSizeInput.addEventListener('input', () => { brushSize = brushSizeInput.value; setBrushPreview(); });
        brushOpacityInput.addEventListener('input', () => { brushOpacity = brushOpacityInput.value; setBrushPreview(); });
        colorSelector.addEventListener('input', () => { brushColor = colorSelector.value; setBrushPreview(); });
        brushTypeBasic.addEventListener('click', () => brushType = 'basic');
        brushTypeSoft.addEventListener('click', () => brushType = 'soft');
        brushTypePattern.addEventListener('click', () => brushType = 'pattern');

        toolButtons.forEach(button => {
            button.addEventListener('click', () => {
                toolButtons.forEach(btn => btn.classList.remove('tool-active'));
                button.classList.add('tool-active');
                drawingMode = button.id.replace('-tool', '');
                mainCanvas.style.cursor = 'crosshair';
                tempCanvas.style.cursor = 'crosshair';
                if (drawingMode === 'eraser') {
                    mainCanvas.style.cursor = 'eraser';
                    tempCanvas.style.cursor = 'eraser';
                }
            });
        });

        colorPickerToolButton.addEventListener('click', () => drawingMode = 'color-picker');
        openColorPickerButton.addEventListener('click', () => { colorPickerPanel.classList.add('open'); brushSettingsPanel.classList.remove('open'); layerPanel.classList.remove('open'); });
        closeColorPickerButton.addEventListener('click', () => colorPickerPanel.classList.remove('open'));

        applyColorButton.addEventListener('click', () => {
            const hslColor = `hsl(${hueSlider.value}, ${saturationSlider.value}%, ${lightnessSlider.value}%)`;
            colorSelector.value = hslToHex(hueSlider.value, saturationSlider.value, lightnessSlider.value);
            brushColor = colorSelector.value;
            setBrushPreview();
            colorPickerPanel.classList.remove('open');
        });

        function hslToHex(h, s, l) {
            l /= 100;
            const a = s * Math.min(l, 1 - l) / 100;
            const f = n => {
                const k = (n + h / 30) % 12;
                const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
                return Math.round(255 * color).toString(16).padStart(2, '0');
            };
            return `#${f(0)}${f(8)}${f(4)}`;
        }

        mainCanvas.addEventListener('mousedown', startDrawing);
        mainCanvas.addEventListener('mouseup', stopDrawing);
        mainCanvas.addEventListener('mouseout', stopDrawing);
        mainCanvas.addEventListener('mousemove', draw);

        tempCanvas.addEventListener('mousedown', startDrawing);
        tempCanvas.addEventListener('mouseup', stopDrawing);
        tempCanvas.addEventListener('mouseout', stopDrawing);
        tempCanvas.addEventListener('mousemove', draw);

        function startDrawing(e) {
            isDrawing = true;
            drawPoint(e.offsetX, e.offsetY);
        }

        function draw(e) {
            if (!isDrawing) return;
            drawLine(e.offsetX, e.offsetY);
        }

        function stopDrawing() {
            if (isDrawing) {
                ctx.drawImage(tempCanvas, 0, 0);
                tempCtx.clearRect(0, 0, tempCanvas.width, tempCanvas.height);
                isDrawing = false;
            }
        }

        function drawPoint(x, y) {
            tempCtx.beginPath();
            tempCtx.arc(x, y, brushSize / 2, 0, Math.PI * 2);
            tempCtx.fillStyle = drawingMode === 'eraser' ? 'white' : brushColor;
            tempCtx.globalAlpha = brushOpacity;
            tempCtx.fill();
            tempCtx.closePath();
        }

        function drawLine(x, y) {
            tempCtx.lineWidth = brushSize;
            tempCtx.lineCap = 'round';
            tempCtx.strokeStyle = drawingMode === 'eraser' ? 'white' : brushColor;
            tempCtx.globalAlpha = brushOpacity;
            tempCtx.lineTo(x, y);
            tempCtx.stroke();
            tempCtx.beginPath();
            tempCtx.moveTo(x, y);
        }

        setBrushPreview();
    </script>

</body>
</html>
