            this.nextElementSibling.style.left = `${(value / 100) * (this.offsetWidth - this.nextElementSibling.offsetWidth) + (this.nextElementSibling.offsetWidth/2)}px`;
            this.nextElementSibling.nextElementSibling.style.width = `${value}%`;
            console.log('Living Room Lights Brightness:', value + '%');
        });

        const thermostatSlider = document.getElementById('thermostatSlider');
