                    </div>
                    <button class="ar-button bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-6 rounded-full focus:outline-none shadow-md">
                        <i class="fa-solid fa-augmented-reality mr-2"></i> View in AR
                    </button>
                </div>
                <p class="text-sm text-gray-500">Explore and discover more about this exhibit.</p>
            </div>
        </div>
