    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');
        const exhibitModal = document.getElementById('exhibit-modal');
        let activeNavLink = null;
        let activeMobileNavLink = null;

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        function openModal(exhibitId) {
            const modalTitle = document.getElementById('modal-title');
            const modalImage = document.getElementById('modal-image');
            const modalDescription = document.getElementById('modal-description');

            if (exhibitId === 'exhibit-1') {
                modalTitle.textContent = "Ancient Artifacts";
                modalImage.src = "https://picsum.photos/600/400?random=6";
                modalDescription.textContent = "Step back in time and explore our collection of ancient artifacts. From pottery and tools to sculptures and jewelry, these relics offer a glimpse into the lives and cultures of civilizations long past. Discover the stories behind these objects and marvel at the craftsmanship of ancient artisans.";
            } else if (exhibitId === 'exhibit-2') {
                modalTitle.textContent = "Modern Art Collection";
                modalImage.src = "https://picsum.photos/600/400?random=7";
                modalDescription.textContent = "Immerse yourself in the vibrant world of modern art. Our collection features paintings, sculptures, and mixed media pieces from influential artists of the 20th and 21st centuries. Explore various styles and movements, and contemplate the ideas and emotions expressed through these groundbreaking works.";
            } else if (exhibitId === 'exhibit-3') {
                modalTitle.textContent = "Natural History Showcase";
                modalImage.src = "https://picsum.photos/600/400?random=8";
                modalDescription.textContent = "Journey through the wonders of the natural world in our Natural History Showcase. Encounter fascinating specimens of flora and fauna, from towering dinosaur skeletons to delicate insects and rare botanical samples. Learn about biodiversity, evolution, and the interconnectedness of life on Earth.";
            }

            exhibitModal.classList.add('open');
        }

        function closeModal() {
            exhibitModal.classList.remove('open');
        }

        function playAudio(audioId) {
            alert('Play audio for ' + audioId);
        }

        function pauseAudio(audioId) {
            alert('Pause audio for ' + audioId);
        }

        function playModalAudio() {
            alert('Play modal audio');
        }

        function pauseModalAudio() {
            alert('Pause modal audio');
        }

        function setActiveNav(link) {
            if (activeNavLink) {
                activeNavLink.classList.remove('active');
            }
            link.classList.add('active');
            activeNavLink = link;
        }

        function setActiveNavMobile(link) {
            if (activeMobileNavLink) {
                activeMobileNavLink.classList.remove('active');
            }
            link.classList.add('active');
            activeMobileNavLink = link;
            mobileMenu.classList.add('hidden');
        }
    </script>

</body>
</html>
