        .pet-area {
            background-image: url('https://picsum.photos/800/600?environment');
            background-size: cover;
            background-position: center;
            transition: background-image 0.5s ease-in-out;
        }
        .pet-animation {
            animation-duration: 1.5s;
            animation-timing-function: ease-in-out;
            animation-iteration-count: infinite;
        }
        @keyframes pet-idle {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-10px); }
        }
        .pet-idle { animation-name: pet-idle; }
        @keyframes pet-eat {
            0%, 50%, 100% { transform: rotate(0); }
            25%, 75% { transform: rotate(10deg); }
        }
        .pet-eat { animation-name: pet-eat; animation-iteration-count: 1; }
        @keyframes pet-play {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.1); }
        }
        .pet-play { animation-name: pet-play; animation-iteration-count: 1; }
        .environment-option.active {
            outline: 4px solid #a78bfa;
            @apply shadow-md;
        }
        .mini-game-card:hover {
            @apply shadow-lg transform scale-105 transition-transform duration-300;
        }
        .stat-bar {
