            happinessBar.style.width = `${happiness}%`;
            hungerBar.style.width = `${hunger}%`;
            cleanlinessBar.style.width = `${cleanliness}%`;
            happinessLevel.textContent = `${happiness}%`;
            hungerLevel.textContent = `${hunger}%`;
            cleanlinessLevel.textContent = `${cleanliness}%`;
        }

        function setPetAnimation(animationClass) {
            petImage.classList.remove(currentPetAnimation);
            petImage.classList.add(animationClass);
            currentPetAnimation = animationClass;
        }

        feedButton.addEventListener('click', () => {
            setPetAnimation('pet-eat');
            hunger = Math.max(0, hunger - 20);
            happiness = Math.min(100, happiness + 10);
            updateStats();
            setTimeout(() => { setPetAnimation('pet-idle'); }, 1500);
        });

        playButton.addEventListener('click', () => {
            setPetAnimation('pet-play');
            happiness = Math.min(100, happiness + 15);
            hunger = Math.min(100, hunger + 5);
            cleanliness = Math.max(0, cleanliness - 10);
            updateStats();
            setTimeout(() => { setPetAnimation('pet-idle'); }, 1500);
        });

        environmentOptions.forEach(option => {
            option.addEventListener('click', () => {
                environmentOptions.forEach(opt => opt.classList.remove('active'));
                option.classList.add('active');
                const imageUrl = option.dataset.image;
                petArea.style.backgroundImage = `url('${imageUrl}')`;
            });
        });

        updateStats();
    </script>

</body>
</html>
```

