    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        const quizAreaSection = document.getElementById('quiz-area');
        const liveQuizSection = document.getElementById('live-quiz');
        const startQuizButtons = liveQuizSection.querySelectorAll('.btn-primary');

        startQuizButtons.forEach(button => {
            button.addEventListener('click', () => {
                liveQuizSection.classList.add('hidden');
                quizAreaSection.classList.remove('hidden');
                startQuiz();
            });
        });

        let timerInterval;
        let timeLeft;
        const timerDisplay = document.getElementById('timer');
        const timerRing = document.querySelector('.timer-ring');
        const questionTextElement = document.getElementById('question-text');
        const answerOptionsElements = document.querySelectorAll('.answer-option');
        const answerFeedbackElement = document.getElementById('answer-feedback');
        const questionNumberElement = document.getElementById('question-number');

        const questions = [
            {
                question: "What is the highest mountain in the world?",
                options: ["Mount Everest", "K2", "Kangchenjunga", "Lhotse"],
                correctAnswer: "A"
            },
            {
                question: "Which planet is known as the 'Red Planet'?",
                options: ["Mars", "Venus", "Jupiter", "Mercury"],
                correctAnswer: "A"
            },
            {
                question: "What is the chemical symbol for gold?",
                options: ["Au", "Ag", "Fe", "Cu"],
                correctAnswer: "A"
            },
             {
                question: "In which country would you find the Eiffel Tower?",
                options: ["Germany", "Spain", "Italy", "France"],
                correctAnswer: "D"
            }
        ];

        let currentQuestionIndex = 0;
        let score = 0;

        function startQuiz() {
            currentQuestionIndex = 0;
            score = 0;
            loadQuestion();
        }

        function loadQuestion() {
            resetAnswerFeedback();
            if (currentQuestionIndex < questions.length) {
                const questionData = questions[currentQuestionIndex];
                questionNumberElement.textContent = `Question ${currentQuestionIndex + 1}/${questions.length}`;
                questionTextElement.textContent = questionData.question;
                for (let i = 0; i < answerOptionsElements.length; i++) {
                    answerOptionsElements[i].textContent = String.fromCharCode(65 + i) + ". " + questions[currentQuestionIndex].options[i];
                    answerOptionsElements[i].dataset.answer = String.fromCharCode(65 + i);
                    answerOptionsElements[i].disabled = false;
                }
                startTimer();
            } else {
                endQuiz();
            }
        }

        function startTimer() {
            timeLeft = 20;
            timerDisplay.textContent = timeLeft;
            timerRing.style.strokeDashoffset = '0';
            timerInterval = setInterval(() => {
                timeLeft--;
                timerDisplay.textContent = timeLeft;
                const dashoffset = 188.5 * (1 - timeLeft / 20);
                timerRing.style.strokeDashoffset = dashoffset;

                if (timeLeft <= 0) {
                    clearInterval(timerInterval);
                    showAnswerFeedback(false);
                }
            }, 1000);
        }

        answerOptionsElements.forEach(option => {
            option.addEventListener('click', function() {
                clearInterval(timerInterval);
                const selectedAnswer = this.dataset.answer;
                const isCorrect = selectedAnswer === questions[currentQuestionIndex].correctAnswer;
                showAnswerFeedback(isCorrect, selectedAnswer);
            });
        });

        function showAnswerFeedback(isCorrect, selectedAnswer = null) {
            answerOptionsElements.forEach(option => {
                option.disabled = true;
                if (option.dataset.answer === questions[currentQuestionIndex].correctAnswer) {
                    option.classList.add('bg-secondary-color', 'text-text-color-light');
                }
                if (selectedAnswer && option.dataset.answer === selectedAnswer && !isCorrect) {
                    option.classList.add('bg-red-500', 'text-text-color-light');
                }
            });

            if (isCorrect) {
                answerFeedbackElement.textContent = "Correct!";
                answerFeedbackElement.classList.remove('text-red-500');
                answerFeedbackElement.classList.add('text-secondary-color');
                score++;
            } else {
                answerFeedbackElement.textContent = "Incorrect. The correct answer was " + questions[currentQuestionIndex].correctAnswer;
                answerFeedbackElement.classList.remove('text-secondary-color');
                answerFeedbackElement.classList.add('text-red-500');
            }
            answerFeedbackElement.classList.remove('hidden');

            setTimeout(() => {
                currentQuestionIndex++;
                loadQuestion();
            }, 2000);
        }

        function resetAnswerFeedback() {
            answerFeedbackElement.classList.add('hidden');
            answerOptionsElements.forEach(option => {
                option.classList.remove('bg-secondary-color', 'text-text-color-light', 'bg-red-500');
            });
        }


        function endQuiz() {
            clearInterval(timerInterval);
            quizAreaSection.innerHTML = `
                <div class="container mx-auto px-6">
                    <div class="quiz-card rounded-3xl p-12 max-w-2xl mx-auto text-center">
                        <h2 class="text-3xl font-bold text-primary-color mb-8">Quiz Completed!</h2>
                        <p class="text-xl text-gray-700 mb-8">Your final score is:</p>
                        <p class="text-5xl font-bold text-secondary-color mb-12">${score}/${questions.length}</p>
                        <button onclick="restartQuiz()" class="btn-secondary btn-primary px-8 py-4 rounded-full text-xl font-semibold hover:scale-105 transition-transform shadow-lg">Play Again <i class="fa-solid fa-rotate-right ml-2"></i></button>
                    </div>
                </div>
            `;
        }

        function restartQuiz() {
            quizAreaSection.innerHTML = originalQuizAreaHTML;
            quizAreaSection.classList.remove('hidden');
            liveQuizSection.classList.add('hidden');
            timerDisplay = document.getElementById('timer');
            timerRing = document.querySelector('.timer-ring');
            questionTextElement = document.getElementById('question-text');
            answerOptionsElements = document.querySelectorAll('.answer-option');
            answerFeedbackElement = document.getElementById('answer-feedback');
            questionNumberElement = document.getElementById('question-number');
            startQuiz();
        }

        const originalQuizAreaHTML = quizAreaSection.innerHTML;
        timerRing.style.strokeDashoffset = '188.5';
    </script>

</body>
</html>
