        @keyframes scale-up-center { 0% { transform: scale(0.5); } 100% { transform: scale(1); } }
        .gradient-bg { background: linear-gradient(45deg, #6366F1, #3B82F6, #0EA5E9, #14B8A6); background-size: 400% 400%; animation: gradient 15s ease infinite; }
