</head>
<body class="bg-gray-100 text-gray-800">

<div class="gradient-bg fixed inset-0 -z-10"></div>

<div class="flex flex-col h-screen">

    <header class="bg-white bg-opacity-75 backdrop-blur-sm p-6 shadow-md sticky top-0 z-40">
        <div class="container mx-auto flex justify-between items-center">
            <div class="text-xl font-bold text-blue-700">Voice Dashboard</div>
            <div class="flex space-x-4">
                <button class="hover:text-blue-600 transition-colors"><i class="fas fa-cog"></i></button>
                <button class="hover:text-blue-600 transition-colors"><i class="fas fa-user-circle"></i></button>
            </div>
