    </header>

    <div class="flex-1 p-8 container mx-auto flex flex-col md:flex-row space-y-8 md:space-y-0 md:space-x-8">

        <aside class="md:w-1/4 bg-white bg-opacity-75 backdrop-blur-sm p-6 rounded-xl shadow-lg flex flex-col">
            <div class="mb-6">
                <div id="voice-input-container" class="relative">
                    <button id="voice-button" class="w-full p-4 bg-blue-500 hover:bg-blue-600 text-white rounded-lg transition-colors focus:outline-none voice-shadow pulse-animation">
