                <div id="command-feedback" class="mt-2 text-sm text-gray-600 italic text-center fade-in opacity-0 h-6"></div>
            </div>

            <div class="mb-8">
                <h3 class="font-semibold text-lg mb-3 text-gray-700">Quick Shortcuts</h3>
                <div class="grid grid-cols-2 gap-2">
                    <button onclick="handleShortcut('weather')" class="bg-gray-200 hover:bg-gray-300 p-3 rounded-md transition-colors text-sm">
                        <i class="fas fa-sun text-yellow-500 mr-2"></i> Weather
                    </button>
                    <button onclick="handleShortcut('news')" class="bg-gray-200 hover:bg-gray-300 p-3 rounded-md transition-colors text-sm">
                        <i class="fas fa-newspaper text-blue-500 mr-2"></i> News
                    </button>
                    <button onclick="handleShortcut('calendar')" class="bg-gray-200 hover:bg-gray-300 p-3 rounded-md transition-colors text-sm">
                        <i class="fas fa-calendar text-red-500 mr-2"></i> Calendar
                    </button>
                    <button onclick="handleShortcut('settings')" class="bg-gray-200 hover:bg-gray-300 p-3 rounded-md transition-colors text-sm">
                        <i class="fas fa-cog text-green-500 mr-2"></i> Settings
                    </button>
                </div>
            </div>

            <div class="flex-1 overflow-y-auto">
                <h3 class="font-semibold text-lg mb-3 text-gray-700">Command History</h3>
                <div id="command-history" class="space-y-2">
                    <!-- Command history items will be added here -->
                </div>
            </div>
