        <main class="md:w-3/4 bg-white bg-opacity-75 backdrop-blur-sm p-8 rounded-xl shadow-lg">
            <h2 class="text-2xl font-bold mb-6 text-gray-700">Dashboard Overview</h2>

            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
                <div class="bg-blue-100 bg-opacity-75 p-6 rounded-lg shadow-md border-b-4 border-blue-400 transition-transform hover:scale-105">
                    <i class="fas fa-chart-line text-blue-500 text-3xl mb-4"></i>
                    <h4 class="font-semibold text-gray-700 mb-2">System Performance</h4>
                    <p class="text-gray-600">Real-time metrics and insights.</p>
                    <div class="mt-4 text-blue-700 font-bold">98% Uptime</div>
                </div>

                <div class="bg-green-100 bg-opacity-75 p-6 rounded-lg shadow-md border-b-4 border-green-400 transition-transform hover:scale-105">
