                </div>

                <div class="bg-purple-100 bg-opacity-75 p-6 rounded-lg shadow-md border-b-4 border-purple-400 transition-transform hover:scale-105">
                    <i class="fas fa-bell text-purple-500 text-3xl mb-4"></i>
                    <h4 class="font-semibold text-gray-700 mb-2">Notifications</h4>
                    <p class="text-gray-600">Important alerts and updates.</p>
                    <div class="mt-4 text-purple-700 font-bold">5 New Alerts</div>
                </div>
