    </footer>

</div>

<script>
    const voiceButton = document.getElementById('voice-button');
    const commandFeedback = document.getElementById('command-feedback');
    const commandHistory = document.getElementById('command-history');
    const listeningIndicator = document.getElementById('listening-indicator');

    const recognition = new webkitSpeechRecognition() || new SpeechRecognition();
    recognition.continuous = false;
    recognition.lang = 'en-US';
    recognition.interimResults = false;

    voiceButton.addEventListener('click', () => {
        startVoiceRecognition();
    });

    function startVoiceRecognition() {
        voiceButton.classList.remove('pulse-animation');
        listeningIndicator.classList.remove('opacity-0');
        commandFeedback.classList.remove('fade-in', 'opacity-0');
        commandFeedback.classList.add('fade-out', 'opacity-100');
        setTimeout(() => {
            commandFeedback.textContent = "Listening...";
            commandFeedback.classList.remove('fade-out', 'opacity-100');
            commandFeedback.classList.add('fade-in', 'opacity-100');
        }, 300);

        try {
            recognition.start();
        } catch(e) {
            commandFeedback.textContent = "Voice recognition error.";
            resetVoiceButton();
        }
    }

    recognition.onstart = () => {
        voiceButton.classList.add('voice-shadow');
    };

    recognition.onspeechstart = () => {
        listeningIndicator.classList.add('opacity-100');
    };

    recognition.onspeechend = () => {
        listeningIndicator.classList.remove('opacity-100');
    };

    recognition.onresult = (event) => {
        const transcript = event.results[0][0].transcript.toLowerCase();
        commandFeedback.classList.remove('fade-in', 'opacity-0');
        commandFeedback.classList.add('fade-out', 'opacity-100');
        setTimeout(() => {
            commandFeedback.textContent = `Processing: "${transcript}"`;
            commandFeedback.classList.remove('fade-out', 'opacity-100');
            commandFeedback.classList.add('fade-in', 'opacity-100');
        }, 300);
        processCommand(transcript);
    };

    recognition.onerror = (event) => {
        let message;
        if (event.error == 'no-speech') {
            message = 'No speech detected. Try again.';
        } else if (event.error == 'audio-capture') {
            message = 'No microphone detected. Ensure microphone is connected.';
        } else if (event.error == 'not-allowed') {
            message = 'Permission to use microphone was denied.';
        } else {
            message = 'Error occurred in speech recognition: ' + event.error;
        }
        commandFeedback.classList.remove('fade-in', 'opacity-0');
        commandFeedback.classList.add('fade-out', 'opacity-100');
        setTimeout(() => {
            commandFeedback.textContent = message;
            commandFeedback.classList.remove('fade-out', 'opacity-100');
            commandFeedback.classList.add('fade-in', 'opacity-100');
        }, 300);
        resetVoiceButton();
    };

    recognition.onend = () => {
        resetVoiceButton();
    };

    function resetVoiceButton() {
        voiceButton.classList.remove('voice-shadow');
        voiceButton.classList.add('pulse-animation');
        listeningIndicator.classList.add('opacity-0');
    }

    function processCommand(command) {
        const commandItem = document.createElement('div');
        commandItem.className = 'bg-gray-100 p-3 rounded-md shadow-sm text-sm';

        let response = '';
        if (command.includes('weather')) {
            response = 'Displaying weather information...';
            commandItem.innerHTML = `<i class="fas fa-microphone text-blue-500 mr-2"></i> "${command}" <br> <i class="fas fa-reply text-green-500 ml-5 mr-2"></i> <span class="font-semibold">Response:</span> ${response}`;
            // Placeholder for weather display logic
        } else if (command.includes('news')) {
            response = 'Fetching latest news headlines...';
            commandItem.innerHTML = `<i class="fas fa-microphone text-blue-500 mr-2"></i> "${command}" <br> <i class="fas fa-reply text-green-500 ml-5 mr-2"></i> <span class="font-semibold">Response:</span> ${response}`;
            // Placeholder for news display logic
        } else if (command.includes('calendar')) {
            response = 'Opening calendar...';
            commandItem.innerHTML = `<i class="fas fa-microphone text-blue-500 mr-2"></i> "${command}" <br> <i class="fas fa-reply text-green-500 ml-5 mr-2"></i> <span class="font-semibold">Response:</span> ${response}`;
            // Placeholder for calendar display logic
        } else if (command.includes('settings')) {
            response = 'Navigating to settings...';
            commandItem.innerHTML = `<i class="fas fa-microphone text-blue-500 mr-2"></i> "${command}" <br> <i class="fas fa-reply text-green-500 ml-5 mr-2"></i> <span class="font-semibold">Response:</span> ${response}`;
            // Placeholder for settings display logic
        } else {
            response = 'Command not recognized.';
            commandItem.innerHTML = `<i class="fas fa-microphone text-red-500 mr-2"></i> "${command}" <br> <i class="fas fa-exclamation-triangle text-yellow-500 ml-5 mr-2"></i> <span class="font-semibold">Response:</span> ${response}`;
        }

        commandHistory.prepend(commandItem);
        commandFeedback.classList.remove('fade-in', 'opacity-0');
        commandFeedback.classList.add('fade-out', 'opacity-100');
        setTimeout(() => {
            commandFeedback.textContent = response;
            commandFeedback.classList.remove('fade-out', 'opacity-100');
            commandFeedback.classList.add('fade-in', 'opacity-100');
        }, 300);
    }

    function handleShortcut(shortcut) {
        let response = '';
        if (shortcut === 'weather') {
            response = 'Displaying weather...';
        } else if (shortcut === 'news') {
            response = 'Fetching news...';
        } else if (shortcut === 'calendar') {
            response = 'Opening calendar...';
        } else if (shortcut === 'settings') {
            response = 'Navigating to settings...';
        }
        commandFeedback.classList.remove('fade-in', 'opacity-0');
        commandFeedback.classList.add('fade-out', 'opacity-100');
        setTimeout(() => {
            commandFeedback.textContent = response;
            commandFeedback.classList.remove('fade-out', 'opacity-100');
            commandFeedback.classList.add('fade-in', 'opacity-100');
        }, 300);
        processCommand(shortcut);
    }
</script>

</body>
</html>
```

