                start: 'top 80%',
                onEnter: () => element.classList.add('active'),
                onLeaveBack: () => element.classList.remove('active'),
                once: true,
            });
        });

        gsap.utils.toArray('.slide-in-left').forEach((element) => {
            ScrollTrigger.create({
                trigger: element,
                start: 'top 80%',
                onEnter: () => element.classList.add('active'),
                onLeaveBack: () => element.classList.remove('active'),
                once: true,
            });
        });
        gsap.utils.toArray('.slide-in-right').forEach((element) => {
            ScrollTrigger.create({
                trigger: element,
                start: 'top 80%',
                onEnter: () => element.classList.add('active'),
                onLeaveBack: () => element.classList.remove('active'),
                once: true,
            });
        });

        gsap.to('.hero-image-parallax', {
            yPercent: 20,
            ease: "none",
            scrollTrigger: {
              trigger: '.hero-gradient',
              start: "top bottom",
              end: "bottom top",
              scrub: true
            },
          });
    });
</script>

