    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Nunito Sans', sans-serif;
        }
        .panel-transition-enter-active,
        .panel-transition-leave-active {
            transition: opacity 0.5s;
        }
        .panel-transition-enter-from,
        .panel-transition-leave-to {
            opacity: 0;
        }
        .zoom-in-enter-active,
        .zoom-in-leave-active {
            transition: transform 0.3s ease-out, opacity 0.3s ease-out;
        }
        .zoom-in-enter-from,
        .zoom-in-leave-to {
            transform: scale(0.8);
            opacity: 0;
        }
        .chapter-button {
            transition: transform 0.2s ease-in-out;
        }
        .chapter-button:hover {
            transform: scale(1.1);
        }
        .panel-number {
            pointer-events: none;
        }
    </style>
</head>
<body class="bg-gray-100 text-gray-900">
    <header class="bg-white shadow-md sticky top-0 z-50">
        <div class="container mx-auto px-6 py-4 flex justify-between items-center">
            <h1 class="text-xl font-bold">Comic Reader</h1>
            <nav class="hidden md:flex space-x-6">
                <button id="prevChapterBtn" class="chapter-button text-blue-600 hover:text-blue-800"><i class="fa-solid fa-arrow-left"></i> Previous Chapter</button>
                <button id="nextChapterBtn" class="chapter-button text-blue-600 hover:text-blue-800">Next Chapter <i class="fa-solid fa-arrow-right"></i></button>
            </nav>
            <div class="md:hidden">
                <button id="mobileNavBtn" class="text-gray-600 hover:text-gray-800 focus:outline-none">
                    <i class="fa-solid fa-bars"></i>
                </button>
            </div>
        </div>
        <div id="mobileNav" class="hidden md:hidden bg-gray-50 p-4">
