                <button id="mobileNextChapterBtn" class="chapter-button text-blue-600 hover:text-blue-800">Next Chapter <i class="fa-solid fa-arrow-right"></i></button>
            </nav>
        </div>
    </header>

    <main class="container mx-auto mt-8">
        <div class="relative bg-white rounded-lg shadow-xl overflow-hidden">
            <div id="comicPanel" class="aspect-w-1 aspect-h-1 transition-opacity duration-500 ease-in-out">
                <img id="panelImage" src="https://picsum.photos/600/800?random=1" alt="Comic Panel" class="w-full h-full object-contain cursor-zoom-in" style="transform: scale(1); transform-origin: 0 0;">
                <div id="zoomOverlay" class="hidden absolute inset-0 bg-black opacity-50 cursor-zoom-out"></div>
                <div id="zoomControls" class="hidden absolute bottom-4 left-4 bg-white bg-opacity-75 rounded-md p-2 space-x-2">
                    <button id="zoomInBtn" class="p-1 rounded-md hover:bg-gray-200"><i class="fa-solid fa-plus"></i></button>
                    <button id="zoomOutBtn" class="p-1 rounded-md hover:bg-gray-200"><i class="fa-solid fa-minus"></i></button>
                    <button id="resetZoomBtn" class="p-1 rounded-md hover:bg-gray-200"><i class="fa-solid fa-sync-alt"></i></button>
                </div>
            </div>

            <div class="px-6 py-4 flex justify-between items-center bg-gray-50 border-t border-gray-200">
                <div id="panelCounter" class="text-sm text-gray-600 panel-number">Panel 1/10</div>
                <div class="flex space-x-4">
                    <button id="prevPanelBtn" class="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md transition-colors disabled:opacity-50 disabled:cursor-not-allowed" disabled><i class="fa-solid fa-arrow-left"></i> Prev</button>
                    <button id="nextPanelBtn" class="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md transition-colors"><i class="fa-solid fa-arrow-right"></i> Next</button>
                </div>
            </div>
        </div>
    </main>

    <footer class="bg-gray-200 py-8 mt-8">
        <div class="container mx-auto px-6 text-center text-gray-700">
            <p>&copy; 2024 Digital Comic Reader. All rights reserved.</p>
        </div>
    </footer>

    <script>
        const panelImage = document.getElementById('panelImage');
        const prevPanelBtn = document.getElementById('prevPanelBtn');
        const nextPanelBtn = document.getElementById('nextPanelBtn');
        const panelCounter = document.getElementById('panelCounter');
        const prevChapterBtn = document.getElementById('prevChapterBtn');
        const nextChapterBtn = document.getElementById('nextChapterBtn');
        const mobilePrevChapterBtn = document.getElementById('mobilePrevChapterBtn');
        const mobileNextChapterBtn = document.getElementById('mobileNextChapterBtn');
        const mobileNavBtn = document.getElementById('mobileNavBtn');
        const mobileNav = document.getElementById('mobileNav');

        const zoomOverlay = document.getElementById('zoomOverlay');
        const zoomControls = document.getElementById('zoomControls');
        const zoomInBtn = document.getElementById('zoomInBtn');
        const zoomOutBtn = document.getElementById('zoomOutBtn');
        const resetZoomBtn = document.getElementById('resetZoomBtn');

        let chapterIndex = 0;
        let panelIndex = 0;
        let chapters = [
            {
                title: "Chapter 1",
                panels: [
                    "https://picsum.photos/600/800?random=1",
                    "https://picsum.photos/600/800?random=2",
                    "https://picsum.photos/600/800?random=3",
                    "https://picsum.photos/600/800?random=4",
                    "https://picsum.photos/600/800?random=5",
                    "https://picsum.photos/600/800?random=6",
                    "https://picsum.photos/600/800?random=7",
                    "https://picsum.photos/600/800?random=8",
                    "https://picsum.photos/600/800?random=9",
                    "https://picsum.photos/600/800?random=10"
                ]
            },
            {
                title: "Chapter 2",
                panels: [
                    "https://picsum.photos/600/800?random=11",
                    "https://picsum.photos/600/800?random=12",
                    "https://picsum.photos/600/800?random=13",
                    "https://picsum.photos/600/800?random=14",
                    "https://picsum.photos/600/800?random=15"
                ]
            }
        ];

        let currentZoom = 1;
        let isZoomed = false;

        function loadPanel() {
            panelImage.src = chapters[chapterIndex].panels[panelIndex];
            panelCounter.textContent = `Panel ${panelIndex + 1}/${chapters[chapterIndex].panels.length}`;
            prevPanelBtn.disabled = panelIndex === 0;
            nextPanelBtn.disabled = panelIndex === chapters[chapterIndex].panels.length - 1;
            panelImage.style.transform = 'scale(1)';
            currentZoom = 1;
            isZoomed = false;
            zoomOverlay.classList.add('hidden');
            zoomControls.classList.add('hidden');
            panelImage.classList.remove('cursor-zoom-out');
            panelImage.classList.add('cursor-zoom-in');
        }

        function nextPanel() {
            if (panelIndex < chapters[chapterIndex].panels.length - 1) {
                panelIndex++;
                loadPanel();
            } else if (chapterIndex < chapters.length - 1) {
                nextChapter();
            }
        }

        function prevPanel() {
            if (panelIndex > 0) {
                panelIndex--;
                loadPanel();
            } else if (chapterIndex > 0) {
                prevChapter();
            }
        }

        function nextChapter() {
            if (chapterIndex < chapters.length - 1) {
                chapterIndex++;
                panelIndex = 0;
                loadPanel();
            }
        }

        function prevChapter() {
            if (chapterIndex > 0) {
                chapterIndex--;
                panelIndex = 0;
                loadPanel();
            }
        }

        function zoomIn() {
            currentZoom += 0.5;
            panelImage.style.transform = `scale(${currentZoom})`;
        }

        function zoomOut() {
            if (currentZoom > 1) {
                currentZoom -= 0.5;
                panelImage.style.transform = `scale(${currentZoom})`;
            }
        }

        function resetZoom() {
            currentZoom = 1;
            panelImage.style.transform = `scale(${currentZoom})`;
        }

        panelImage.addEventListener('click', () => {
            if (!isZoomed) {
                isZoomed = true;
                zoomOverlay.classList.remove('hidden');
                zoomControls.classList.remove('hidden');
                panelImage.classList.remove('cursor-zoom-in');
                panelImage.classList.add('cursor-zoom-out');
            } else {
                isZoomed = false;
                zoomOverlay.classList.add('hidden');
                zoomControls.classList.add('hidden');
                panelImage.classList.remove('cursor-zoom-out');
                panelImage.classList.add('cursor-zoom-in');
                resetZoom();
            }
        });

        zoomInBtn.addEventListener('click', zoomIn);
        zoomOutBtn.addEventListener('click', zoomOut);
        resetZoomBtn.addEventListener('click', resetZoom);

        nextPanelBtn.addEventListener('click', nextPanel);
        prevPanelBtn.addEventListener('click', prevPanel);
        nextChapterBtn.addEventListener('click', nextChapter);
        prevChapterBtn.addEventListener('click', prevChapter);
        mobileNextChapterBtn.addEventListener('click', nextChapter);
        mobilePrevChapterBtn.addEventListener('click', prevChapter);

        mobileNavBtn.addEventListener('click', () => {
            mobileNav.classList.toggle('hidden');
        });

        loadPanel();
    </script>
</body>
</html>
