                        Close
                    </button>
                </div>
            </div>
        </div>
    </div>

    <script>
        lucide.createIcons();

        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenuClose = document.getElementById('mobile-menu-close');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.remove('hidden');
        });

        mobileMenuClose.addEventListener('click', () => {
            mobileMenu.classList.add('hidden');
        });

        const projectItems = document.querySelectorAll('.project-item');
        const projectModal = document.getElementById('project-modal');
        const modalCloseButton = document.getElementById('modal-close-button');
        const modalOverlay = document.getElementById('modal-overlay');
        const modalImage = document.getElementById('modal-image');
        const modalDescription = document.getElementById('modal-description');

        projectItems.forEach(item => {
            item.addEventListener('click', () => {
                const projectId = item.dataset.projectId;
                modalImage.src = `https://picsum.photos/600/400?random=project-${projectId}`;
                modalDescription.textContent = `Detailed description for project ${projectId}. Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.`;
                projectModal.classList.remove('hidden');
                document.body.classList.add('overflow-hidden');
            });
        });

        modalCloseButton.addEventListener('click', () => {
            projectModal.classList.add('hidden');
            document.body.classList.remove('overflow-hidden');
        });

        modalOverlay.addEventListener('click', () => {
            projectModal.classList.add('hidden');
            document.body.classList.remove('overflow-hidden');
        });

        document.addEventListener('keydown', (event) => {
            if (event.key === 'Escape') {
                projectModal.classList.add('hidden');
                document.body.classList.remove('overflow-hidden');
            }
        });

        gsap.registerPlugin(ScrollTrigger);

        gsap.utils.toArray(".parallax-group").forEach(group => {
            const layers = group.children;
            gsap.to(layers, {
                yPercent: (i) => -100 * i,
                ease: "none",
                scrollTrigger: {
                    trigger: group,
                    start: "top bottom",
                    end: "bottom top",
                    scrub: true,
                }
            });
        });

    </script>

</body>
</html>
