            cursor: pointer;
        }
        .nav-item:hover {
            background-color: #20202d;
        }
        .nav-item.active {
            background-color: #00FFFF;
            color: #181825;
            font-weight: 600;
        }
        .nav-item.active:hover {
            background-color: #00BFFF;
            color: #F0F0F0;
        }
        .chart-container {
            height: 300px;
            width: 100%;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .fade-in {
            animation: fadeIn 0.5s ease-out forwards;
        }
        .hero-section {
            background: linear-gradient(135deg, #12121A, #20202d);
            padding: 6rem 0;
            text-align: center;
        }
        .hero-title {
            font-size: 3.5rem;
            font-weight: 800;
            letter-spacing: -0.05em;
            margin-bottom: 1rem;
            color: #00FFFF;
            text-shadow: 0 0 10px rgba(0, 255, 255, 0.5);
        }
        .hero-subtitle {
            font-size: 1.5rem;
            color: #E0E0E0;
            margin-bottom: 2rem;
        }
        .feature-card {
            background-color: #20202d;
            padding: 2rem;
            border-radius: 1rem;
            box-shadow: 0 6px 8px -3px rgba(0, 0, 0, 0.2);
            transition: transform 0.3s ease-in-out;
        }
        .feature-card:hover {
            transform: translateY(-5px);
        }
        .gradient-bg {
            background: linear-gradient(45deg, #00FFFF, #00BFFF);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
        }
        .gradient-border {
            border-image: linear-gradient(45deg, #00FFFF, #00BFFF) 1;
        }
        .data-highlight {
            color: #00FFFF;
            font-weight: 600;
        }
        .interactive-btn {
            position: relative;
            overflow: hidden;
        }
        .interactive-btn::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 255, 255, 0.1);
            opacity: 0;
            transition: opacity 0.3s ease-in-out;
        }
        .interactive-btn:hover::before {
            opacity: 1;
        }
        @keyframes pulse {
            0% { transform: scale(1); }
            50% { transform: scale(1.05); }
            100% { transform: scale(1); }
        }
        .pulse-icon {
            animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }

        @media (max-width: 768px) {
            .dashboard-container {
                grid-template-columns: 1fr;
                grid-template-rows: auto auto 1fr;
            }
            .sidebar {
                grid-column: 1 / 2;
                grid-row: 1 / 2;
                position: static;
                height: auto;
                flex-direction: row;
                overflow-x: auto;
                padding: 1rem;
                border-bottom: 1px solid #282835;
            }
            .header {
                grid-column: 1 / 2;
                grid-row: 2 / 3;
                padding: 1rem;
            }
            .main-content {
                grid-column: 1 / 2;
                grid-row: 3 / 4;
                padding: 1rem;
            }
            .sidebar {
                display: flex;
                overflow-x: auto;
                justify-content: space-around;
            }
