<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Wanderlust Vista - Your Ultimate Travel Blog</title>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Nunito+Sans:wght@400;600&display=swap" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <style>
        body {
            font-family: 'Nunito Sans', sans-serif;
            background-color: #f9f5f0; /* Beige background */
            color: #333;
        }
        h1, h2, h3, h4, h5, h6, .font-serif {
            font-family: 'Playfair Display', serif;
            color: #1e3a8a; /* Dark blue headings */
        }
        .blog-container {
            display: grid;
            grid-template-columns: 250px 1fr;
            grid-template-rows: auto 1fr;
            min-height: 100vh;
        }
        .blog-nav {
            grid-column: 1;
            grid-row: 1 / span 2;
            position: sticky;
            top: 20px;
            height: calc(100vh - 40px);
            overflow-y: auto;
            padding: 2rem 1rem;
            border-right: 1px solid #e5e7eb; /* Light gray border */
        }
        .blog-header {
            grid-column: 2;
            grid-row: 1;
            padding: 2rem;
        }
        .blog-content {
            grid-column: 2;
            grid-row: 2;
            padding: 0 2rem 2rem 2rem;
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 2rem;
        }
        .post-card {
            background-color: white;
            border-radius: 0.75rem; /* Rounded corners */
            overflow: hidden;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
            transition: transform 0.2s ease-in-out;
        }
        .post-card:hover {
            transform: scale(1.03);
        }
        .post-image {
            width: 100%;
            height: 200px;
            object-fit: cover;
        }
        .post-body {
            padding: 1.5rem;
        }
        .post-title {
            font-size: 1.5rem;
            margin-bottom: 0.5rem;
            line-height: 1.2;
        }
        .post-excerpt {
            color: #71717a; /* Gray text */
            font-size: 1rem;
            line-height: 1.5;
        }
        .read-more-btn {
            display: inline-block;
            margin-top: 1rem;
            padding: 0.5rem 1rem;
            background-color: #3b82f6; /* Blue button */
            color: white;
            border-radius: 0.375rem;
            transition: background-color 0.2s ease-in-out;
        }
        .read-more-btn:hover {
            background-color: #2563eb; /* Darker blue hover */
        }
        .related-posts-panel {
            margin-top: 2rem;
            border-top: 1px solid #e5e7eb;
            padding-top: 1.5rem;
        }
        .related-posts-title {
            font-size: 1.25rem;
            margin-bottom: 1rem;
            cursor: pointer;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
        .related-posts-list {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
            gap: 1rem;
        }
        .related-post-item {
            background-color: #f0f0f0; /* Light gray related post background */
            padding: 1rem;
            border-radius: 0.5rem;
            transition: background-color 0.2s ease-in-out;
        }
        .related-post-item:hover {
            background-color: #e0e0e0; /* Slightly darker hover */
        }
        .related-post-image {
            width: 100%;
            height: 120px;
            object-fit: cover;
            border-radius: 0.375rem;
            margin-bottom: 0.5rem;
        }
        .related-post-title-small {
            font-size: 1rem;
            line-height: 1.3;
        }
        .mobile-nav-toggle {
            display: none;
            position: fixed;
            top: 1rem;
            left: 1rem;
            background-color: white;
            color: #333;
            border: 1px solid #e5e7eb;
            padding: 0.5rem;
            border-radius: 0.375rem;
            cursor: pointer;
            z-index: 50;
        }
        @media (max-width: 768px) {
            .blog-container {
                grid-template-columns: 1fr;
            }
            .blog-nav {
                position: fixed;
                top: 0;
                left: -250px;
                height: 100%;
                z-index: 40;
                background-color: white;
                box-shadow: 2px 0 5px rgba(0, 0, 0, 0.1);
                transition: left 0.3s ease-in-out;
                padding-top: 4rem;
            }
            .blog-nav.open {
                left: 0;
            }
            .blog-header, .blog-content {
                grid-column: 1;
            }
            .mobile-nav-toggle {
                display: block;
            }
        }
        .animate-fade-in {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.5s ease-out, transform 0.5s ease-out;
        }
        .animate-fade-in.in-view {
            opacity: 1;
            transform: translateY(0);
        }
        .hero-section {
            position: relative;
            height: 600px;
            overflow: hidden;
            background-image: url('https://picsum.photos/1920/1080?travel');
            background-size: cover;
            background-position: center;
            display: flex;
            justify-content: center;
            align-items: center;
            text-align: center;
            color: white;
        }
        .hero-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.5); /* Dark overlay */
        }
        .hero-content {
            position: relative;
            z-index: 10;
            padding: 2rem;
        }
        .hero-title {
            font-size: 3rem;
            font-weight: bold;
            margin-bottom: 1rem;
        }
        .hero-subtitle {
            font-size: 1.5rem;
            opacity: 0.8;
        }
        .category-link.active {
            font-weight: 600;
            color: #3b82f6; /* Active category link color */
        }
        .category-link:hover {
            color: #60a5fa; /* Hover category link color */
        }
        .collapsible-content {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-out;
        }
        .collapsible-content.open {
            max-height: 500px; /* Adjust as needed, or use 'auto' with JS for dynamic height */
        }

    </style>
</head>
<body class="bg-beige-100">

<div class="mobile-nav-toggle" id="mobileNavToggle">
    <i class="fa fa-bars"></i>
</div>

<div class="blog-container">

    <nav class="blog-nav" id="blogNavigation">
        <div class="sticky top-4">
            <h2 class="text-2xl font-bold mb-4 font-serif">Categories</h2>
            <ul class="space-y-2">
                <li><a href="#" class="block category-link py-1 hover:text-blue-500 transition-colors active" data-category="all">All</a></li>
                <li><a href="#" class="block category-link py-1 hover:text-blue-500 transition-colors" data-category="adventure">Adventure</a></li>
                <li><a href="#" class="block category-link py-1 hover:text-blue-500 transition-colors" data-category="nature">Nature</a></li>
                <li><a href="#" class="block category-link py-1 hover:text-blue-500 transition-colors" data-category="city">City Breaks</a></li>
                <li><a href="#" class="block category-link py-1 hover:text-blue-500 transition-colors" data-category="food">Food & Culture</a></li>
                <li><a href="#" class="block category-link py-1 hover:text-blue-500 transition-colors" data-category="tips">Travel Tips</a></li>
            </ul>
        </div>
    </nav>

    <header class="blog-header">
        <section class="hero-section">
            <div class="hero-overlay"></div>
            <div class="hero-content animate-fade-in">
                <h1 class="hero-title font-serif">Explore the World with Wanderlust Vista</h1>
                <p class="hero-subtitle">Your guide to the most breathtaking destinations and unforgettable travel experiences.</p>
            </div>
        </section>
    </header>

    <main class="blog-content" id="blogContent">
        <!-- Blog posts will be loaded here -->
    </main>

</div>

<script>
    document.addEventListener('DOMContentLoaded', function() {
        const blogContent = document.getElementById('blogContent');
        let page = 1;
        let loading = false;
        let categoryFilter = 'all';
        const categoryLinks = document.querySelectorAll('.category-link');
        const mobileNavToggle = document.getElementById('mobileNavToggle');
        const blogNavigation = document.getElementById('blogNavigation');

        function createPostCard(post) {
            const card = document.createElement('div');
            card.classList.add('post-card', 'animate-fade-in');
            card.innerHTML = `
                <img src="https://picsum.photos/200/300?random=${post.id}" alt="${post.title}" class="post-image">
                <div class="post-body">
                    <h2 class="post-title font-serif">${post.title}</h2>
                    <p class="post-excerpt">${post.excerpt}</p>
                    <a href="#" class="read-more-btn">Read More</a>
                    <div class="related-posts-panel">
                        <div class="related-posts-title" onclick="toggleRelatedPosts(this)">
                            Related Posts <i class="fa fa-chevron-down"></i>
                        </div>
                        <div class="related-posts-list collapsible-content">
                            ${generateRelatedPostsHTML(post.relatedPosts)}
                        </div>
                    </div>
                </div>
            `;
            return card;
        }

        function generateRelatedPostsHTML(relatedPosts) {
            if (!relatedPosts || relatedPosts.length === 0) {
                return '<p>No related posts found.</p>';
            }
            let html = '';
            relatedPosts.forEach(relatedPost => {
                html += `
                    <div class="related-post-item">
                        <img src="https://picsum.photos/200/300?related=${relatedPost.id}" alt="${relatedPost.title}" class="related-post-image">
                        <h4 class="related-post-title-small font-serif">${relatedPost.title}</h4>
                        <a href="#" class="read-more-btn small inline-block mt-2">Read More</a>
                    </div>
                `;
            });
            return html;
        }

        window.toggleRelatedPosts = function(element) {
            const content = element.nextElementSibling;
            content.classList.toggle('open');
            const icon = element.querySelector('i');
            icon.classList.toggle('fa-chevron-down');
            icon.classList.toggle('fa-chevron-up');
        };


        function loadPosts() {
            if (loading) return;
            loading = true;
            fetchPosts(page, categoryFilter).then(posts => {
                if (posts.length > 0) {
                    posts.forEach(post => {
                        blogContent.appendChild(createPostCard(post));
                    });
                    page++;
                } else if (page === 1) {
                    blogContent.innerHTML = '<p>No posts found in this category yet.</p>';
                } else {
                    // Optionally display "No more posts" message
                }
                loading = false;
                observeElements(); // Re-observe new elements for fade-in
            });
        }

        async function fetchPosts(page, category) {
            await new Promise(resolve => setTimeout(resolve, 500)); // Simulate loading delay
            let dummyPosts = [];
            for (let i = 1; i <= 6; i++) {
                let postId = (page - 1) * 6 + i;
                let postCategory = category === 'all' ? getRandomCategory() : category;
                dummyPosts.push({
                    id: postId,
                    title: `Post Title ${postId} - ${postCategory.charAt(0).toUpperCase() + postCategory.slice(1)}`,
                    excerpt: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.',
                    category: postCategory,
                    relatedPosts: generateDummyRelatedPosts(postId)
                });
            }

            if (category !== 'all') {
                dummyPosts = dummyPosts.filter(post => post.category === category);
            }

            return dummyPosts;
        }

        function getRandomCategory() {
            const categories = ['adventure', 'nature', 'city', 'food', 'tips'];
            return categories[Math.floor(Math.random() * categories.length)];
        }

        function generateDummyRelatedPosts(postId) {
            const related = [];
            for (let i = 1; i <= 3; i++) {
                related.push({
                    id: postId * 10 + i,
                    title: `Related Post ${i} to ${postId}`
                });
            }
            return related;
        }


        const observer = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('in-view');
                }
            });
        }, { threshold: 0.1 });

        function observeElements() {
            blogContent.querySelectorAll('.animate-fade-in:not(.in-view)').forEach(el => {
                observer.observe(el);
            });
        }

        window.addEventListener('scroll', () => {
            if (window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 300) {
                loadPosts();
            }
        });

        categoryLinks.forEach(link => {
            link.addEventListener('click', function(event) {
                event.preventDefault();
                categoryLinks.forEach(l => l.classList.remove('active'));
                this.classList.add('active');
                categoryFilter = this.dataset.category;
                blogContent.innerHTML = '';
                page = 1;
                loadPosts();
            });
        });

        mobileNavToggle.addEventListener('click', () => {
            blogNavigation.classList.toggle('open');
        });

        loadPosts();
    });
</script>

</body>
</html>
```

