        gsap.registerPlugin(ScrollTrigger);

        gsap.utils.toArray(".parallax-hero").forEach(hero => {
            let base = hero.querySelector(".parallax-base");
            let fore = hero.querySelector(".parallax-fore");

            gsap.to(base, {
                yPercent: -30,
                scrollTrigger: {
                    trigger: hero,
                    start: "top bottom",
                    end: "bottom top",
                    scrub: true
                }
            });

            gsap.to(fore, {
                yPercent: 30,
                scrollTrigger: {
                    trigger: hero,
                    start: "top bottom",
                    end: "bottom top",
                    scrub: true
                }
            });
        });

        gsap.utils.toArray('section').forEach(section => {
            gsap.from(section.querySelectorAll('.rounded-2xl, .grid > div, .text-center > *, form > div, form > button, .md\\:grid-cols-3 > div, .md\\:grid-cols-2 > div'), {
                y: 50,
                opacity: 0,
                duration: 1,
                stagger: 0.2,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: section,
                    start: "top 80%",
                    end: "bottom 20%",
                    toggleActions: "play none none reverse"
                }
            });
        });

        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                document.querySelector(this.getAttribute('href')).scrollIntoView({
                    behavior: 'smooth'
                });
            });
        });
    </script>
</body>
</html>
