            text-shadow: 0 0 5px #fff, 0 0 10px #fff, 0 0 15px #6200ea, 0 0 20px #6200ea;
        }
        .feature-item:hover .icon-neon {
            animation: icon-glow 1s infinite alternate;
        }
        @keyframes icon-glow {
            0% { text-shadow: 0 0 5px #fff, 0 0 10px #fff, 0 0 15px #6200ea, 0 0 20px #6200ea; }
            100% { text-shadow: 0 0 5px #fff, 0 0 15px #fff, 0 0 25px #6200ea, 0 0 30px #6200ea; }
        }
        .pulse-neon {
            animation: pulse-glow 2s infinite alternate;
        }
        @keyframes pulse-glow {
            0% { box-shadow: 0 0 10px #6200ea; }
            100% { box-shadow: 0 0 20px #7b1fa2; }
        }
    </style>
</head>
