                    <a href="#" class="hover:text-white"><i class="fa-brands fa-facebook-square text-xl"></i></a>
                    <a href="#" class="hover:text-white"><i class="fa-brands fa-instagram-square text-xl"></i></a>
                    <a href="#" class="hover:text-white"><i class="fa-brands fa-twitter-square text-xl"></i></a>
                </div>
            </div>
            <div>
                <h4 class="text-lg font-semibold text-white mb-4">Quick Links</h4>
                <ul class="space-y-2">
                    <li><a href="#destinations" class="hover:text-white transition-colors">Destinations</a></li>
                    <li><a href="#experiences" class="hover:text-white transition-colors">Experiences</a></li>
                    <li><a href="#about" class="hover:text-white transition-colors">About Us</a></li>
                    <li><a href="#contact" class="hover:text-white transition-colors">Contact</a></li>
                </ul>
            </div>
            <div>
                <h4 class="text-lg font-semibold text-white mb-4">Subscribe to Newsletter</h4>
                <p class="mb-4">Stay updated with our latest travel deals and offers.</p>
                <form class="flex">
                    <input type="email" placeholder="Your Email" class="bg-gray-800 text-gray-100 px-4 py-2 rounded-l-md focus:outline-none focus:ring-2 focus:ring-indigo-500">
                    <button type="submit" class="bg-indigo-500 hover:bg-indigo-600 text-white px-6 rounded-r-md transition-colors">Subscribe</button>
                </form>
            </div>
        </div>
        <div class="text-center mt-12 border-t border-gray-700 pt-8">
            <p>&copy; 2024 Wanderlust Journeys. All rights reserved.</p>
        </div>
    </footer>

    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        let slideIndex = 0;
        const slides = document.querySelectorAll('.hero-slide');
        const navButtons = document.querySelectorAll('.hero-slide-nav');
        let sliderInterval;

        function showSlide(index) {
            slides.forEach(slide => slide.classList.remove('active'));
            navButtons.forEach(nav => nav.classList.remove('active'));
            slides[index].classList.add('active');
            navButtons[index].classList.add('active');
        }

        function nextSlide() {
            slideIndex = (slideIndex + 1) % slides.length;
            showSlide(slideIndex);
        }

        function startSlider() {
            sliderInterval = setInterval(nextSlide, 5000);
        }

        function stopSlider() {
            clearInterval(sliderInterval);
        }

        navButtons.forEach((button, index) => {
            button.addEventListener('click', () => {
                stopSlider();
                slideIndex = index;
                showSlide(slideIndex);
                startSlider();
            });
        });

        startSlider();
    </script>

</body>
</html>
