    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const readMoreButtons = document.querySelectorAll('.read-more-btn');

            readMoreButtons.forEach(button => {
                button.addEventListener('click', () => {
                    const articleCard = button.closest('.article-card');
                    const articlePreview = articleCard.querySelector('.article-preview');
                    articlePreview.classList.toggle('expanded');
                    if (articlePreview.classList.contains('expanded')) {
                        button.textContent = 'Read less';
                    } else {
                        button.textContent = 'Read more';
                    }
                });
            });

            const fadeInElements = document.querySelectorAll('.fade-in');
            fadeInElements.forEach((element, index) => {
                setTimeout(() => {
                    element.style.opacity = '1';
                    element.style.transform = 'translateY(0)';
                }, 100 * index);
            });

            const mobileMenuButton = document.querySelector('.mobile-menu-button');
            const navLinks = document.querySelector('.nav-links');

            if (mobileMenuButton) {
                mobileMenuButton.addEventListener('click', () => {
                    navLinks.classList.toggle('hidden');
                    navLinks.classList.toggle('flex');
                    navLinks.classList.toggle('flex-col');
                    navLinks.classList.toggle('absolute');
                    navLinks.classList.toggle('top-full');
                    navLinks.classList.toggle('left-0');
                    navLinks.classList.toggle('w-full');
                    navLinks.classList.toggle('bg-white');
                    navLinks.classList.toggle('shadow-md');
                    navLinks.classList.toggle('p-4');
                    if (navLinks.classList.contains('flex')) {
                        mobileMenuButton.innerHTML = '<i class="fa fa-times text-xl text-gray-700"></i>';
                    } else {
                        mobileMenuButton.innerHTML = '<i class="fa fa-bars text-xl text-gray-700"></i>';
                    }
                });
            }
        });
    </script>

</body>
</html>
