            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            gsap.registerPlugin(ScrollTrigger);

            gsap.utils.toArray('.hero-section').forEach(section => {
                let parallaxBg = section.querySelector('.parallax-bg');
                gsap.to(parallaxBg, {
                    yPercent: -30,
                    ease: "none",
                    scrollTrigger: {
                        trigger: section,
                        start: "top bottom",
                        end: "bottom top",
                        scrub: 0.5
                    }
                });
            });

            gsap.from('.hero-section .parallax-content > *', {
                y: 60,
                opacity: 0,
                duration: 1.5,
                stagger: 0.2,
                ease: 'power3.out'
            });

            gsap.from('#services .feature-item', {
                y: 50,
                opacity: 0,
                duration: 1,
                stagger: 0.15,
                scrollTrigger: {
                    trigger: '#services',
                    start: 'top 80%',
                    end: 'bottom 20%',
                    toggleActions: 'play none none reverse'
                }
            });

            gsap.from('#team .team-member', {
                y: 50,
                opacity: 0,
                duration: 1,
                stagger: 0.2,
                scrollTrigger: {
                    trigger: '#team',
                    start: 'top 80%',
                    end: 'bottom 20%',
                    toggleActions: 'play none none reverse'
                }
            });

            gsap.from('#clients .grid > div', {
                opacity: 0,
                duration: 1.2,
                stagger: 0.1,
                scrollTrigger: {
                    trigger: '#clients',
                    start: 'top 80%',
                    end: 'bottom 20%',
                    toggleActions: 'play none none reverse'
                }
            });

            gsap.from('#contact form > *', {
                y: 30,
                opacity: 0,
                duration: 1,
                stagger: 0.1,
                scrollTrigger: {
                    trigger: '#contact',
                    start: 'top 80%',
                    end: 'bottom 20%',
                    toggleActions: 'play none none reverse'
                }
            });
        });
    </script>
</body>
</html>
