                    <div class="input-animation">
                        <input type="text" id="name" placeholder="Your Name" required>
                        <label for="name">Name</label>
                    </div>
                    <div class="input-animation">
                        <input type="email" id="email" placeholder="Your Email" required>
                        <label for="email">Email</label>
                    </div>
                    <div class="input-animation">
                        <textarea id="message" rows="5" placeholder="Your Message" required></textarea>
                        <label for="message">Message</label>
                    </div>
                    <div>
                        <button type="submit" class="inline-flex items-center px-6 py-3 rounded-full bg-cyan-600 hover:bg-cyan-700 text-white font-semibold transition-colors duration-300">
                            Send Message
                            <i class="fa-solid fa-paper-plane ml-2"></i>
                        </button>
                    </div>
                </form>
            </div>
        </section>

        <footer class="py-12 border-t border-gray-200 text-center text-gray-500">
            <p>&copy; 2024 Photography Portfolio. All rights reserved.</p>
        </footer>
    </main>

    <script>
        const contactToggle = document.getElementById('contact-toggle');
        const contactFormContainer = document.getElementById('contact-form');
        const toggleContactFormButton = document.getElementById('toggle-contact-form');
        const contactFormToggleText = document.getElementById('contact-form-toggle-text');
        const contactFormToggleIcon = document.getElementById('contact-form-toggle-icon');

        contactToggle.addEventListener('click', () => {
            contactFormContainer.classList.toggle('expanded');
            contactFormContainer.classList.toggle('collapsed');
        });

        toggleContactFormButton.addEventListener('click', () => {
            contactFormContainer.classList.toggle('expanded');
            contactFormContainer.classList.toggle('collapsed');
            if (contactFormContainer.classList.contains('expanded')) {
                contactFormToggleText.textContent = 'Collapse';
                contactFormToggleIcon.classList.remove('fa-chevron-down');
                contactFormToggleIcon.classList.add('fa-chevron-up');
            } else {
                contactFormToggleText.textContent = 'Expand';
                contactFormToggleIcon.classList.remove('fa-chevron-up');
                contactFormToggleIcon.classList.add('fa-chevron-down');
            }
        });
    </script>

</body>
</html>
