<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Financial Services Portal - Hero Section</title>
    <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Nunito', sans-serif; }
        .hero-gradient {
            background: linear-gradient(135deg, #0f172a, #1e3a8a, #475569);
            background-size: 200% 200%;
            animation: gradient 15s ease infinite;
        }
        @keyframes gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .animate-fade-in {
            animation: fade-in 1s ease-out forwards;
            opacity: 0;
        }
        @keyframes fade-in {
            to { opacity: 1; }
        }
        .card-shadow {
            box-shadow: 0 15px 25px rgba(0, 0, 0, 0.1);
        }
        .pulse-chart {
            animation: pulse-line 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulse-line {
            0%, 100% { transform: scaleY(1); }
            50% { transform: scaleY(1.2); }
        }
        .slide-up {
            animation: slide-up-anim 0.7s ease-out forwards;
            transform: translateY(20px);
            opacity: 0;
        }
        @keyframes slide-up-anim {
