    <script>
        document.addEventListener('DOMContentLoaded', () => {
            gsap.registerPlugin(ScrollTrigger);

            gsap.to('.parallax-bg', {
                yPercent: -30,
                ease: "none",
                scrollTrigger: {
                    trigger: ".parallax-hero",
                    start: "top top",
                    end: "bottom top",
                    scrub: true
                },
            });

            const caseStudyButtons = document.querySelectorAll('.case-study-button');
            const caseStudyModals = document.querySelectorAll('.case-study-modal');
            const closeModalButtons = document.querySelectorAll('.close-modal');

            caseStudyButtons.forEach(button => {
                button.addEventListener('click', function(event) {
                    event.preventDefault();
                    const modalTarget = this.getAttribute('data-modal-target');
                    document.getElementById(modalTarget).style.display = "block";
                    document.body.style.overflow = 'hidden';
                });
            });

            closeModalButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const modalTarget = this.getAttribute('data-modal-target');
                    document.getElementById(modalTarget).style.display = "none";
                    document.body.style.overflow = 'auto';
                });
            });

            window.addEventListener('click', function(event) {
                caseStudyModals.forEach(modal => {
                    if (event.target == modal) {
                        modal.style.display = "none";
                        document.body.style.overflow = 'auto';
                    }
                });
            });

            const servicesButton = document.getElementById('services-button');
            const servicesDropdown = document.getElementById('services-dropdown');

            servicesButton.addEventListener('click', () => {
                servicesDropdown.style.display = servicesDropdown.style.display === 'block' ? 'none' : 'block';
            });

            window.addEventListener('click', (event) => {
                if (!servicesButton.contains(event.target) && !servicesDropdown.contains(event.target)) {
                    servicesDropdown.style.display = 'none';
                }
            });

            const mobileServicesButton = document.getElementById('mobile-services-button');
            const mobileServicesDropdown = document.getElementById('mobile-services-dropdown');

            mobileServicesButton.addEventListener('click', () => {
                mobileServicesDropdown.style.display = mobileServicesDropdown.style.display === 'block' ? 'none' : 'block';
            });

            const mobileMenuToggle = document.getElementById('mobile-menu-toggle');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuToggle.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const mobileServicesButtonNav = document.getElementById('mobile-services-button');
            const mobileServicesDropdownNav = document.getElementById('mobile-services-dropdown');

            mobileServicesButtonNav.addEventListener('click', () => {
                mobileServicesDropdownNav.style.display = mobileServicesDropdownNav.style.display === 'block' ? 'none' : 'block';
            });
        });
    </script>

</body>
</html>
