    <style>
        body { font-family: 'Roboto', sans-serif; }
        .hero-section {
            background: linear-gradient(135deg, #e0f7fa, #b2ebf2, #80deea, #4dd0e1);
            background-size: 300% 300%;
            animation: gradient-animation 12s ease infinite;
        }
        @keyframes gradient-animation {
            0%{background-position:0% 50%}
            50%{background-position:100% 50%}
            100%{background-position:0% 50%}
        }
        .pulse-blue {
            animation: pulse-animation 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulse-animation {
            0%, 100% { opacity: 1; }
            50% { opacity: .5; }
        }
        .fade-in {
            animation: fade-in-animation 0.5s ease-out forwards;
            opacity: 0;
        }
        @keyframes fade-in-animation {
            to { opacity: 1; }
        }
        .slide-up {
            animation: slide-up-animation 0.5s ease-out forwards;
            transform: translateY(20px);
            opacity: 0;
        }
        @keyframes slide-up-animation {
            to { transform: translateY(0); opacity: 1; }
        }
        .appointment-card {
            transition: transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out;
        }
        .appointment-card:hover {
            transform: scale(1.03);
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
        }
        .booking-form-container {
            perspective: 1000px;
        }
        .booking-form-card {
            transition: transform 0.6s ease-in-out;
            transform-style: preserve-3d;
        }
        .booking-form-card.flipped {
            transform: rotateY(180deg);
        }
        .booking-form-front, .booking-form-back {
            backface-visibility: hidden;
        }
        .booking-form-back {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            transform: rotateY(180deg);
        }

    </style>
