                    <p class="text-sm"><i class="fas fa-map-marker-alt mr-2"></i> 123 Health Street, Cityville</p>
                    <p class="text-sm"><i class="fas fa-phone mr-2"></i> (123) 456-7890</p>
                    <p class="text-sm"><i class="fas fa-envelope mr-2"></i> info@healthfirst.com</p>
                </div>
            </div>
            <div class="mt-8 border-t border-gray-700 pt-8 text-center text-sm">
                <p>&copy; 2024 HealthFirst Portal. All rights reserved.</p>
            </div>
        </div>
    </footer>

    <script>
        document.getElementById('mobile-menu-button').addEventListener('click', function() {
            document.getElementById('mobile-menu').classList.toggle('hidden');
        });

        function toggleDetails(id) {
            const details = document.getElementById(id + '-details');
            details.classList.toggle('hidden');
            const icon = document.querySelector(`#${id} h3 button i`);
            icon.classList.toggle('fa-chevron-down');
            icon.classList.toggle('fa-chevron-up');
        }

        function flipCard() {
            const card = document.querySelector('.booking-form-card');
            card.classList.toggle('flipped');
        }

        document.getElementById('bookingForm').addEventListener('submit', function(event) {
            event.preventDefault();
            document.getElementById('confirm-department').textContent = document.getElementById('department').value;
            document.getElementById('confirm-doctor').textContent = document.getElementById('doctor').value || 'No preference';
            document.getElementById('confirm-date').textContent = new Date(document.getElementById('date').value).toLocaleDateString();
            flipCard();
            alert('Appointment Booked! (Confirmation details are shown on the back of the card).');
        });

    </script>

</body>
</html>
