    <script>
        lucide.createIcons();

        const mobileMenuButton = document.querySelector('.mobile-menu-button');
        const mobileMenu = document.querySelector('.mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        const counters = document.querySelectorAll('.animated-counter');
        counters.forEach(counter => {
            const target = parseInt(counter.getAttribute('data-target'));
            const duration = 2000;
            let startTimestamp = null;

            const updateCounter = (timestamp) => {
                if (!startTimestamp) startTimestamp = timestamp;
                const progress = Math.min((timestamp - startTimestamp) / duration, 1);
                counter.innerText = Math.floor(progress * target);
                if (progress < 1) {
                    requestAnimationFrame(updateCounter);
                }
            };

            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        requestAnimationFrame(updateCounter);
                        observer.unobserve(counter);
                    }
                });
            }, { threshold: 0.8 });

            observer.observe(counter);
        });

        gsap.registerPlugin(ScrollTrigger);

        gsap.utils.toArray('.animate-fade-in-up').forEach(element => {
            gsap.from(element, {
                y: 30,
                opacity: 0,
                duration: 1,
                delay: parseFloat(element.classList.contains('delay-100') ? 0.1 : (element.classList.contains('delay-200') ? 0.2 : (element.classList.contains('delay-300') ? 0.3 : 0))),
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: element,
                    start: 'top 80%',
                    toggleActions: 'play none none none'
                }
            });
        });

        gsap.utils.toArray('.animate-counter-in').forEach(element => {
            gsap.from(element, {
                opacity: 0,
                y: 30,
                duration: 1,
                delay: parseFloat(element.classList.contains('delay-100') ? 0.1 : (element.classList.contains('delay-200') ? 0.2 : (element.classList.contains('delay-300') ? 0.3 : 0))),
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: element,
                    start: 'top 80%',
                    toggleActions: 'play none none none'
                }
            });
        });


    </script>
</body>
</html>
