<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Startup Accelerator - Ignite Your Vision</title>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Inter', sans-serif;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .hero-content {
            position: relative;
            z-index: 10;
        }
        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-image: url('https://picsum.photos/1920/1080');
            background-size: cover;
            background-position: center;
            filter: brightness(70%);
        }
        .accent-turquoise {
            color: #40E0D0;
        }
        .accent-bg-turquoise {
            background-color: #40E0D0;
        }
        .registration-step {
            display: none;
        }
        .registration-step.active {
            display: block;
        }
        .step-indicator.active {
            background-color: #40E0D0;
            color: white;
        }
        .dynamic-shadow {
            transition: box-shadow 0.3s ease;
        }
        .dynamic-shadow:hover {
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
        }
        .float-element {
            animation: float 3s ease-in-out infinite;
        }
        @keyframes float {
            0%, 100% {
                transform: translateY(0);
            }
            50% {
                transform: translateY(-10px);
            }
        }
        .pulse-icon {
            animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulse {
            0%, 100% {
                opacity: 1;
            }
            50% {
                opacity: .5;
            }
        }

    </style>
</head>
<body class="bg-gray-50 text-gray-900">

    <div class="hero-section relative bg-white">
        <div class="hero-bg"></div>
        <div class="hero-content container mx-auto px-4 py-32 text-center relative">
            <h1 class="text-5xl md:text-7xl font-bold text-white mb-6 dynamic-shadow">
                <span class="accent-turquoise">Ignite</span> Your Startup Journey
            </h1>
            <p class="text-lg md:text-xl text-gray-100 mb-12 dynamic-shadow">
                Launch your innovative startup with our elite accelerator program. We provide the resources, mentorship, and network to propel your vision to reality.
            </p>
            <div class="flex justify-center space-x-4">
                <button id="registerButton" class="accent-bg-turquoise text-white font-semibold py-3 px-8 rounded-full hover:bg-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 dynamic-shadow hover:scale-105 transition-transform duration-200">
                    Register Now <i class="fa-solid fa-arrow-right ml-2"></i>
                </button>
                <button class="border-2 border-white text-white font-semibold py-3 px-8 rounded-full hover:bg-white hover:text-gray-900 focus:outline-none focus:ring-2 focus:ring-white focus:ring-opacity-50 dynamic-shadow hover:scale-105 transition-transform duration-200">
                    Learn More <i class="fa-solid fa-circle-info ml-2"></i>
                </button>
            </div>
        </div>
    </div>

    <section id="registrationSection" class="hidden bg-gray-50 py-20">
        <div class="container mx-auto px-4">
            <div class="max-w-3xl mx-auto bg-white p-12 rounded-3xl shadow-xl">
                <h2 class="text-3xl font-bold text-center mb-8">
                    Join Our Accelerator Program
                </h2>
                <nav class="flex justify-center mb-8">
                    <div class="flex space-x-4">
                        <button class="step-indicator w-8 h-8 rounded-full border-2 border-gray-300 flex items-center justify-center text-gray-500 hover:border-turquoise-500 hover:text-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 transition-colors duration-200 step-indicator-1 active" data-step="1">1</button>
                        <button class="step-indicator w-8 h-8 rounded-full border-2 border-gray-300 flex items-center justify-center text-gray-500 hover:border-turquoise-500 hover:text-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 transition-colors duration-200 step-indicator-2" data-step="2">2</button>
                        <button class="step-indicator w-8 h-8 rounded-full border-2 border-gray-300 flex items-center justify-center text-gray-500 hover:border-turquoise-500 hover:text-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 transition-colors duration-200 step-indicator-3" data-step="3">3</button>
                    </div>
                </nav>

                <form id="registrationForm">
                    <div class="registration-step active" data-step="1">
                        <h3 class="text-xl font-semibold mb-4">Step 1: Basic Information</h3>
                        <div class="mb-4">
                            <label for="fullName" class="block text-gray-700 text-sm font-bold mb-2">Full Name</label>
                            <input type="text" id="fullName" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline border-turquoise-300 focus:border-turquoise-500" placeholder="Your Full Name">
                        </div>
                        <div class="mb-4">
                            <label for="email" class="block text-gray-700 text-sm font-bold mb-2">Email Address</label>
                            <input type="email" id="email" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline border-turquoise-300 focus:border-turquoise-500" placeholder="Your Email">
                        </div>
                        <div class="mb-4">
                            <label for="password" class="block text-gray-700 text-sm font-bold mb-2">Password</label>
                            <input type="password" id="password" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline border-turquoise-300 focus:border-turquoise-500" placeholder="Create Password">
                        </div>
                        <div class="flex justify-end">
                            <button type="button" class="next-step accent-bg-turquoise text-white font-semibold py-2 px-6 rounded-full hover:bg-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 dynamic-shadow hover:scale-105 transition-transform duration-200">Next <i class="fa-solid fa-arrow-right ml-2"></i></button>
                        </div>
                    </div>

                    <div class="registration-step" data-step="2">
                        <h3 class="text-xl font-semibold mb-4">Step 2: Startup Details</h3>
                        <div class="mb-4">
                            <label for="startupName" class="block text-gray-700 text-sm font-bold mb-2">Startup Name</label>
                            <input type="text" id="startupName" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline border-turquoise-300 focus:border-turquoise-500" placeholder="Your Startup Name">
                        </div>
                        <div class="mb-4">
                            <label for="startupDescription" class="block text-gray-700 text-sm font-bold mb-2">Startup Description</label>
                            <textarea id="startupDescription" rows="3" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline border-turquoise-300 focus:border-turquoise-500" placeholder="Briefly describe your startup"></textarea>
                        </div>
                        <div class="flex justify-between">
                            <button type="button" class="prev-step border border-gray-300 text-gray-700 font-semibold py-2 px-6 rounded-full hover:border-turquoise-500 hover:text-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 dynamic-shadow hover:scale-105 transition-transform duration-200"><i class="fa-solid fa-arrow-left mr-2"></i> Previous</button>
                            <button type="button" class="next-step accent-bg-turquoise text-white font-semibold py-2 px-6 rounded-full hover:bg-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 dynamic-shadow hover:scale-105 transition-transform duration-200">Next <i class="fa-solid fa-arrow-right ml-2"></i></button>
                        </div>
                    </div>

                    <div class="registration-step" data-step="3">
                        <h3 class="text-xl font-semibold mb-4">Step 3: Program Interest</h3>
                        <div class="mb-4">
                            <label for="programStage" class="block text-gray-700 text-sm font-bold mb-2">Startup Stage</label>
                            <select id="programStage" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline border-turquoise-300 focus:border-turquoise-500">
                                <option value="">Select Stage</option>
                                <option value="idea">Idea Stage</option>
                                <option value="prototype">Prototype Stage</option>
                                <option value="early-stage">Early Stage</option>
                                <option value="growth-stage">Growth Stage</option>
                            </select>
                        </div>
                        <div class="mb-6">
                            <label for="expectations" class="block text-gray-700 text-sm font-bold mb-2">What do you hope to achieve?</label>
                            <textarea id="expectations" rows="3" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline border-turquoise-300 focus:border-turquoise-500" placeholder="Your expectations from the program"></textarea>
                        </div>
                        <div class="flex justify-between">
                            <button type="button" class="prev-step border border-gray-300 text-gray-700 font-semibold py-2 px-6 rounded-full hover:border-turquoise-500 hover:text-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 dynamic-shadow hover:scale-105 transition-transform duration-200"><i class="fa-solid fa-arrow-left mr-2"></i> Previous</button>
                            <button type="submit" class="accent-bg-turquoise text-white font-semibold py-2 px-6 rounded-full hover:bg-turquoise-700 focus:outline-none focus:ring-2 focus:ring-turquoise-500 focus:ring-opacity-50 dynamic-shadow hover:scale-105 transition-transform duration-200">Submit Application <i class="fa-solid fa-check ml-2"></i></button>
                        </div>
                    </div>
                </form>
            </div>
        </div>
    </section>

    <footer class="bg-gray-900 text-gray-300 py-12">
        <div class="container mx-auto px-4 text-center">
            <p>&copy; 2024 Startup Accelerator. All rights reserved.</p>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const registerButton = document.getElementById('registerButton');
            const registrationSection = document.getElementById('registrationSection');
            const registrationSteps = document.querySelectorAll('.registration-step');
            const stepIndicators = document.querySelectorAll('.step-indicator');
            const nextStepButtons = document.querySelectorAll('.next-step');
            const prevStepButtons = document.querySelectorAll('.prev-step');
            const registrationForm = document.getElementById('registrationForm');

            registerButton.addEventListener('click', function() {
                registrationSection.classList.remove('hidden');
                document.querySelector('.hero-section').classList.add('hidden');
                scrollToSection(registrationSection);
            });

            nextStepButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const currentStep = parseInt(this.closest('.registration-step').dataset.step);
                    navigateToStep(currentStep + 1);
                });
            });

            prevStepButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const currentStep = parseInt(this.closest('.registration-step').dataset.step);
                    navigateToStep(currentStep - 1);
                });
            });

            registrationForm.addEventListener('submit', function(event) {
                event.preventDefault();
                alert('Application Submitted!');
                registrationForm.reset();
                navigateToStep(1);
                registrationSection.classList.add('hidden');
                document.querySelector('.hero-section').classList.remove('hidden');
                scrollToSection(document.querySelector('.hero-section'));
            });

            function navigateToStep(stepNumber) {
                registrationSteps.forEach(step => step.classList.remove('active'));
                stepIndicators.forEach(indicator => indicator.classList.remove('active'));
                document.querySelector(`.registration-step[data-step="${stepNumber}"]`).classList.add('active');
                document.querySelector(`.step-indicator-${stepNumber}`).classList.add('active');
            }

            function scrollToSection(section) {
                window.scrollTo({
                    top: section.offsetTop,
                    behavior: 'smooth'
                });
            }
        });
    </script>

</body>
</html>
