<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Indie Film Fest - Experience Cinema</title>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Montserrat:wght@400;500&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Montserrat', sans-serif;
            background-color: #000;
            color: #fff;
        }
        h1, h2, h3, h4, h5, h6 {
            font-family: 'Playfair Display', serif;
            font-weight: 700;
            color: #f0c571;
        }
        .hero-section {
            position: relative;
            height: 80vh;
            overflow: hidden;
        }
        .hero-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.6);
            z-index: 1;
        }
        .film-reel-container {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 300px;
            height: 300px;
            z-index: 2;
            pointer-events: none;
        }
        .film-reel {
            width: 100%;
            height: 100%;
            border-radius: 50%;
            border: 4px solid #f0c571;
            display: flex;
            justify-content: center;
            align-items: center;
            animation: rotateReel 10s linear infinite;
        }
        .film-reel-inner {
            width: 60%;
            height: 60%;
            border-radius: 50%;
            background-color: #f0c571;
            position: relative;
        }
        .film-reel-hole {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 20px;
            height: 20px;
            border-radius: 50%;
            background-color: #000;
        }
        .film-strip {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            justify-content: space-around;
            align-items: center;
            border-radius: 50%;
            overflow: hidden;
            clip-path: circle(50% at 50% 50%);
        }
        .film-frame {
            width: 20px;
            height: 40px;
            background-color: rgba(240, 197, 113, 0.8);
            margin: 0 5px;
            animation: moveFrames 2s linear infinite alternate;
        }

        @keyframes rotateReel {
            to { transform: translate(-50%, -50%) rotate(360deg); }
        }
        @keyframes moveFrames {
            to { transform: translateY(20px); }
        }
        .minimal-nav {
            background-color: rgba(0, 0, 0, 0.7);
            backdrop-filter: blur(10px);
        }
        .minimal-nav a {
            color: #f0c571;
            transition: color 0.3s ease;
        }
        .minimal-nav a:hover {
            color: #fff;
        }
        .btn-gold {
            background-color: #f0c571;
            color: #000;
            transition: background-color 0.3s ease, color 0.3s ease;
        }
        .btn-gold:hover {
            background-color: #fff;
            color: #f0c571;
        }
        .section-title {
            position: relative;
            padding-bottom: 1rem;
            margin-bottom: 2rem;
        }
        .section-title:after {
            content: '';
            position: absolute;
            left: 0;
            bottom: 0;
            height: 2px;
            width: 50px;
            background-color: #f0c571;
        }
        .feature-item {
            background-color: #1a1a1a;
            border-radius: 0.5rem;
            padding: 2rem;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .feature-item:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 20px rgba(0, 0, 0, 0.4);
        }
        .footer-section {
            background-color: #1a1a1a;
        }
        .footer-link:hover {
            color: #fff;
        }
        .social-icon {
            color: #f0c571;
            font-size: 1.25rem;
            transition: color 0.3s ease;
        }
        .social-icon:hover {
            color: #fff;
        }
        .image-zoom {
            overflow: hidden;
        }
        .image-zoom img {
            transition: transform 0.6s ease;
        }
        .image-zoom:hover img {
            transform: scale(1.1);
        }

    </style>
</head>
<body class="bg-black text-white">

