        <div id="mobile-menu" class="hidden md:hidden fixed top-0 left-0 w-full h-full bg-black bg-opacity-90 z-50 flex flex-col justify-center items-center">
            <button id="mobile-menu-close" class="absolute top-6 right-6 text-white focus:outline-none">
                <i class="fa fa-times fa-lg"></i>
            </button>
            <a href="#films" class="block py-2 text-lg hover:text-white">Films</a>
