            background: #f0f0f0;
            position: relative;
            overflow: hidden;
        }
        .futuristic-hero::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(135deg, rgba(173, 216, 230, 0.1), rgba(152, 251, 152, 0.1));
            pointer-events: none;
        }
        .neon-text {
            text-shadow: 0 0 5px #0fa, 0 0 10px #0fa, 0 0 15px #0fa, 0 0 20px #0fa;
        }
        .slider-container {
            display: flex;
            align-items: center;
            gap: 20px;
        }
        .slider {
            flex: 1;
        }
        .slider-thumb {
            width: 20px;
            height: 20px;
            background-color: #0fa;
            border-radius: 50%;
            pointer-events: auto;
            cursor: grab;
        }
        .slider-track {
            height: 5px;
            background-color: #ddd;
            border-radius: 5px;
            position: relative;
            overflow: hidden;
        }
        .slider-track::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            height: 100%;
            background-color: #0fa;
            width: 50%;
            border-radius: 5px;
            transition: width 0.2s ease-in-out;
        }
        .product-card {
            transition: transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out;
        }
        .product-card:hover {
            transform: scale(1.05);
            box-shadow: 0 10px 20px rgba(0,0,0,0.15);
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .fade-in {
            animation: fadeIn 1s ease-out forwards;
        }
        .hero-image-parallax {
            transform: translateZ(-2px) scale(3);
        }
        .gradient-border {
            border: 2px solid transparent;
            background-image: linear-gradient(silver, silver), linear-gradient(to right, #aaff00, #ccff00);
