                    <p class="text-gray-600 mb-3">Effortless power, stylish design.</p>
                    <a href="#" class="text-green-500 hover:text-green-600 font-semibold transition-colors">Learn More</a>
                </div>
            </div>
        </div>
    </section>

    <footer class="bg-gray-900 text-gray-300 py-12">
        <div class="container mx-auto px-6 text-center">
            <p>&copy; 2024 TechPulse Reviews. All rights reserved.</p>
            <div class="mt-4 space-x-6">
                <a href="#" class="hover:text-white"><i class="fa-brands fa-facebook-f"></i></a>
                <a href="#" class="hover:text-white"><i class="fa-brands fa-twitter"></i></a>
                <a href="#" class="hover:text-white"><i class="fa-brands fa-instagram"></i></a>
            </div>
        </div>
    </footer>

    <script>
        document.querySelectorAll('.slider').forEach(slider => {
            const thumb = slider.querySelector('.slider-thumb');
            const trackFill = slider.querySelector('.slider-track::before');

            thumb.addEventListener('mousedown', dragStart);
            thumb.addEventListener('touchstart', dragStart);

            let isDragging = false;
            let offsetX = 0;

            function dragStart(e) {
                isDragging = true;
                offsetX = e.clientX - thumb.getBoundingClientRect().left || e.touches[0].clientX - thumb.getBoundingClientRect().left;
                document.addEventListener('mousemove', dragMove);
                document.addEventListener('mouseup', dragEnd);
                document.addEventListener('touchmove', dragMove);
                document.addEventListener('touchend', dragEnd);
            }

            function dragMove(e) {
                if (!isDragging) return;
                e.preventDefault();

                const sliderRect = slider.getBoundingClientRect();
                const mouseX = e.clientX || e.touches[0].clientX;
                let newThumbPos = mouseX - sliderRect.left - offsetX;

                if (newThumbPos < 0) newThumbPos = 0;
                if (newThumbPos > sliderRect.width - thumb.offsetWidth) newThumbPos = sliderRect.width - thumb.offsetWidth;

                thumb.style.left = `${newThumbPos}px`;
                const fillWidth = ((newThumbPos + thumb.offsetWidth / 2) / sliderRect.width) * 100;
                slider.querySelector('.slider-track::before').style.width = `${fillWidth}%`;
                slider.nextElementSibling.textContent = `${Math.round(fillWidth)}%`;
            }

            function dragEnd() {
                isDragging = false;
                document.removeEventListener('mousemove', dragMove);
                document.removeEventListener('mouseup', dragEnd);
                document.removeEventListener('touchmove', dragMove);
                document.removeEventListener('touchend', dragEnd);
            }
        });
    </script>

</body>
</html>
