    <link href="https://fonts.googleapis.com/css2?family=Mrs+Saint+Delafield&family=Poppins:wght@400;500;600&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Poppins', sans-serif;
        }
        .script-font {
            font-family: 'Mrs Saint Delafield', cursive;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .hero-overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(to bottom, rgba(248, 237, 227, 0.6), rgba(248, 237, 227, 0.8));
        }
        .timeline-slider {
            -webkit-appearance: none;
            width: 100%;
            height: 6px;
            border-radius: 3px;
            background: #ddd;
            outline: none;
            opacity: 0.7;
            -webkit-transition: .2s;
            transition: opacity .2s;
        }

        .timeline-slider::-webkit-slider-thumb {
            -webkit-appearance: none;
            appearance: none;
            width: 16px;
            height: 16px;
            border-radius: 50%;
            background: #CDB5BA;
            cursor: pointer;
        }

        .timeline-slider::-moz-range-thumb {
            width: 16px;
            height: 16px;
            border-radius: 50%;
            background: #CDB5BA;
            cursor: pointer;
        }
        .timeline-label {
            position: absolute;
            top: -25px;
            font-size: 0.875rem;
            color: #777;
            white-space: nowrap;
        }
        .timeline-label.active {
            color: #333;
            font-weight: 600;
        }
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .animate-fade-up {
            animation: fadeInUp 0.8s ease-out forwards;
        }

        .parallax {
            background-attachment: fixed;
            background-position: center;
            background-repeat: no-repeat;
            background-size: cover;
        }

        .button-primary {
            background-color: #CDB5BA;
            color: #F8EDE3;
            transition: background-color 0.3s ease, color 0.3s ease, transform 0.2s ease;
        }

        .button-primary:hover {
            background-color: #E8D5C4;
            color: #333;
            transform: scale(1.05);
        }

        .button-secondary {
            background-color: transparent;
            color: #CDB5BA;
            border: 2px solid #CDB5BA;
            transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease, transform 0.2s ease;
        }

        .button-secondary:hover {
            background-color: #CDB5BA;
            color: #F8EDE3;
            border-color: #CDB5BA;
            transform: scale(1.05);
        }
    </style>
</head>
