            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const timelineSlider = document.getElementById('timelineRange');
            const timelineLabels = document.querySelectorAll('.timeline-label');
            const timelineContents = {
                '0': document.getElementById('timeline-content-ceremony'),
                '25': document.getElementById('timeline-content-cocktail'),
                '50': document.getElementById('timeline-content-reception'),
                '100': document.getElementById('timeline-content-dancing')
            };

            function updateTimeline(value) {
                timelineLabels.forEach(label => label.classList.remove('active'));
                Object.values(timelineContents).forEach(content => content.classList.add('hidden'));

                if (value <= 12.5) {
                    timelineLabels[0].classList.add('active');
                    timelineContents['0'].classList.remove('hidden');
                } else if (value <= 37.5) {
                    timelineLabels[1].classList.add('active');
                    timelineContents['25'].classList.remove('hidden');
                } else if (value <= 75) {
                    timelineLabels[2].classList.add('active');
                    timelineContents['50'].classList.remove('hidden');
                } else {
                    timelineLabels[3].classList.add('active');
                    timelineContents['100'].classList.remove('hidden');
                }
            }

            timelineSlider.addEventListener('input', (event) => {
                updateTimeline(event.target.value);
            });
            updateTimeline(timelineSlider.value);
        });
    </script>

</body>
</html>
