                    <img src="https://picsum.photos/300/200?tempchart" alt="Temperature Chart" class="w-full object-cover h-48 rounded-xl">
                </div>
                <div class="p-4 rounded-2xl bg-white shadow-depth-1">
                    <h3 class="font-semibold text-gray-700 mb-3">Humidity Levels</h3>
