    </main>

    <footer class="bg-gray-200 py-8 text-center text-gray-600">
        <p>&copy; 2024 Home Automation Dashboard. All rights reserved.</p>
    </footer>

    <script>
        document.addEventListener('mousemove', function(e) {
            const heroImage = document.querySelector('.hero-image-parallax');
            const heroArea = document.querySelector('.hero-area');

            if (!heroImage || !heroArea) return;

            const heroRect = heroArea.getBoundingClientRect();
            const centerX = heroRect.left + heroRect.width / 2;
            const centerY = heroRect.top + heroRect.height / 2;
            const mouseX = e.clientX;
            const mouseY = e.clientY;

            const offsetX = (mouseX - centerX) / 100;
            const offsetY = (mouseY - centerY) / 100;

            heroImage.style.transform = `translateZ(-1px) scale(2.02) translate(${offsetX}px, ${offsetY}px)`;
        });

        document.addEventListener('mouseout', function() {
            const heroImage = document.querySelector('.hero-image-parallax');
            if (heroImage) {
                heroImage.style.transform = `translateZ(-1px) scale(2)`;
            }
        });
    </script>

</body>
</html>
