    <style>
        body {
            font-family: 'Poppins', sans-serif;
        }
        .hero-section {
            background: linear-gradient(180deg, #f0fdf4 0%, #dcfce7 10%, #a7f3d0 30%, #6ee7b7 70%, #34d399 100%);
        }
        .hero-section-dark {
            background: linear-gradient(180deg, #0f172a 0%, #1e293b 10%, #334155 30%, #475569 70%, #64748b 100%);
        }
        .map-container {
            position: relative;
            overflow: hidden;
            padding-top: 50%;
        }
        .map-container iframe {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
        }
        .bike-icon {
            animation: bikeFloat 3s ease-in-out infinite;
        }
        @keyframes bikeFloat {
            0%, 100% {
                transform: translateY(0);
            }
            50% {
                transform: translateY(-10px);
            }
        }
        .pulse-green {
            animation: pulseEffectGreen 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulseEffectGreen {
            0%, 100% {
                opacity: 1;
            }
            50% {
                opacity: .5;
            }
        }
        .station-card {
            transition: transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out;
        }
        .station-card:hover {
            transform: scale(1.05);
            box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.2);
        }
        .btn-primary {
            background-color: #10b981;
            color: white;
            transition: background-color 0.3s ease-in-out, transform 0.2s ease-in-out;
        }
        .btn-primary:hover {
            background-color: #059669;
            transform: scale(1.03);
        }
        .btn-secondary {
            background-color: #000;
            color: white;
            transition: background-color 0.3s ease-in-out, transform 0.2s ease-in-out;
        }
        .btn-secondary:hover {
            background-color: #1e293b;
            transform: scale(1.03);
        }
        .shadow-hero {
            box-shadow: 0 8px 6px -6px black;
        }
        .fade-in {
            opacity: 0;
            transition: opacity 1s ease-out;
        }
        .fade-in.active {
            opacity: 1;
        }
        .slide-up {
            transform: translateY(50px);
            transition: transform 1s ease-out, opacity 1s ease-out;
            opacity: 0;
        }
        .slide-up.active {
            transform: translateY(0);
            opacity: 1;
        }
    </style>
</head>
