<script>
    document.addEventListener('DOMContentLoaded', () => {
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenuClose = document.getElementById('mobile-menu-close');
        const mobileMenu = document.getElementById('mobile-menu');
        const artistProfileModal = document.getElementById('artist-profile-modal');
        const closeArtistProfileButton = document.getElementById('close-artist-profile');
        const viewArtistProfileButtons = document.querySelectorAll('.view-artist-profile');
        const artistProfileImage = document.getElementById('artist-profile-image');
        const artistProfileName = document.getElementById('artist-profile-name');
        const artistProfileBio = document.getElementById('artist-profile-bio');
        const artistProfileGallery = document.getElementById('artist-profile-gallery');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.remove('hidden');
        });

        mobileMenuClose.addEventListener('click', () => {
            mobileMenu.classList.add('hidden');
        });

        viewArtistProfileButtons.forEach(button => {
            button.addEventListener('click', () => {
                const artistId = button.dataset.artistId;
                loadArtistProfile(artistId);
                artistProfileModal.classList.remove('hidden');
                setTimeout(() => {
                    artistProfileModal.classList.remove('opacity-0');
                }, 10);

            });
        });

        closeArtistProfileButton.addEventListener('click', () => {
            artistProfileModal.classList.add('opacity-0');
             setTimeout(() => {
                artistProfileModal.classList.add('hidden');
            }, 150);
        });

        function loadArtistProfile(artistId) {
            let artistData = getArtistData(artistId);
            artistProfileImage.src = artistData.image;
            artistProfileName.textContent = artistData.name;
            artistProfileBio.textContent = artistData.bio;
            artistProfileGallery.innerHTML = '';
            artistData.galleryImages.forEach(image => {
                const imgElement = document.createElement('img');
                imgElement.src = image;
                imgElement.alt = 'Artist Artwork';
                imgElement.className = 'inline-block w-64 h-48 object-cover rounded-md px-2 slider-item';
                artistProfileGallery.appendChild(imgElement);
            });
        }

        function getArtistData(artistId) {
            switch(artistId) {
                case '1':
                    return {
                        image: 'https://picsum.photos/id/241/400/300',
                        name: 'Anya Petrova',
                        bio: 'Anya Petrova is a portrait artist known for her striking monochrome works that often feature a single, vibrant splash of red to emphasize emotion and depth. Her work has been featured in galleries worldwide, exploring themes of identity and inner strength.',
                        galleryImages: [
                            'https://picsum.photos/id/250/400/300',
                            'https://picsum.photos/id/251/400/300',
                            'https://picsum.photos/id/252/400/300',
                            'https://picsum.photos/id/253/400/300'
                        ]
                    };
                case '2':
                    return {
                        image: 'https://picsum.photos/id/242/400/300',
                        name: 'Kenji Tanaka',
                        bio: 'Kenji Tanaka is an abstract landscape artist who masterfully uses black, white, and shades of blue to create serene and contemplative scenes. His art reflects his Japanese heritage, focusing on minimalism and the beauty of natural forms. Kenji’s pieces invite viewers into a world of quiet reflection.',
                        galleryImages: [
                            'https://picsum.photos/id/254/400/300',
