    <script>
        function playVideo(videoId) {
            alert('Playing video demo: ' + videoId);
        }

        let timers = {};

        function startTimer(timerId, durationInSeconds) {
            if (timers[timerId]) return;

            let seconds = durationInSeconds;
            let display = document.getElementById(timerId + '-display');
            timers[timerId] = setInterval(function () {
                let minutes = parseInt(seconds / 60, 10);
                let remainingSeconds = parseInt(seconds % 60, 10);

                minutes = minutes < 10 ? "0" + minutes : minutes;
                remainingSeconds = remainingSeconds < 10 ? "0" + remainingSeconds : remainingSeconds;

                display.textContent = minutes + ":" + remainingSeconds;

                if (--seconds < 0) {
                    clearInterval(timers[timerId]);
                    delete timers[timerId];
                    alert('Timer ' + timerId + ' finished!');
                }
            }, 1000);
        }

        function pauseTimer(timerId) {
            if (timers[timerId]) {
                clearInterval(timers[timerId]);
                delete timers[timerId];
            }
        }

        function resetTimer(timerId) {
            pauseTimer(timerId);
            document.getElementById(timerId + '-display').textContent = '00:00';
        }
    </script>

</body>
</html>
