    <style>
        body {
            font-family: 'DM Sans', sans-serif;
        }
        .hero-section {
            background-color: #F5F5DC;
        }
        .steam-container {
            position: absolute;
            top: 10%;
            left: 50%;
            transform: translateX(-50%);
            width: 100%;
            height: 400px;
            overflow: hidden;
            pointer-events: none;
        }
        .steam {
            position: absolute;
            left: 50%;
            bottom: 0;
            width: 80px;
            height: 80px;
            margin-left: -40px;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 50%;
            filter: blur(15px);
            opacity: 0;
            animation: steam-animation 4s linear infinite;
        }
        .steam:nth-child(1) {
            left: 30%;
            animation-delay: 0s;
        }
        .steam:nth-child(2) {
            left: 70%;
            width: 60px;
            height: 60px;
            margin-left: -30px;
            animation-delay: 1s;
            animation-duration: 3s;
        }
        .steam:nth-child(3) {
            left: 40%;
            width: 90px;
            height: 90px;
            margin-left: -45px;
            animation-delay: 2s;
            animation-duration: 5s;
        }
        @keyframes steam-animation {
            0% {
                transform: translateY(0) scale(1);
                opacity: 0;
            }
            10% {
                opacity: 0.8;
            }
            100% {
                transform: translateY(-300px) scale(1.5);
                opacity: 0;
            }
        }
        .side-nav {
            position: fixed;
            top: 0;
            left: 0;
            height: 100vh;
            width: 80px;
            background-color: rgba(250, 240, 230, 0.9);
            backdrop-filter: blur(10px);
            padding: 20px 0;
            display: flex;
            flex-direction: column;
            align-items: center;
            z-index: 40;
        }
        .side-nav a {
            margin-bottom: 20px;
            color: #4E342E;
            transition: color 0.3s ease;
            display: block;
            padding: 10px;
        }
        .side-nav a:hover {
            color: #8B4513;
        }
        .side-nav-icon {
            font-size: 1.5rem;
        }
        .hero-content-wrapper {
            position: relative;
            z-index: 10;
        }
        .layered-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            overflow: hidden;
        }
        .layered-bg::before, .layered-bg::after {
            content: '';
            position: absolute;
            width: 120%;
            height: 120%;
            background-repeat: repeat;
            background-position: center;
            opacity: 0.6;
            animation: parallaxBg 60s linear infinite;
        }
        .layered-bg::before {
            background-image: url('https://www.transparenttextures.com/patterns/brushed-alum.png');
            top: -10%;
            left: -10%;
        }
        .layered-bg::after {
            background-image: url('https://www.transparenttextures.com/patterns/diagonal-striped-brick.png');
            bottom: -10%;
            right: -10%;
            animation-direction: reverse;
        }

        @keyframes parallaxBg {
            0% { transform: translate(0, 0); }
            100% { transform: translate(5%, 5%); }
        }

    </style>
