                @apply text-burgundy hover:text-burgundy-dark transition-colors inline-flex items-center gap-2 mt-4;
            }
            .btn-primary {
                @apply bg-burgundy text-cream py-2 px-6 rounded-full hover:bg-burgundy-dark transition-colors;
            }
            .btn-secondary {
                @apply border-2 border-cream text-cream py-2 px-6 rounded-full hover:bg-cream hover:text-burgundy transition-colors;
            }
        }
        @layer utilities {
            .text-cream { color: #f8f0e3; }
            .bg-cream { background-color: #f8f0e3; }
            .text-burgundy { color: #900c3f; }
            .bg-burgundy { background-color: #900c3f; }
            .burgundy-dark { color: #580827; }
            .bg-burgundy-dark { background-color: #580827; }
