    </style>
    <style>
        .hero-area {
            position: relative;
            overflow: hidden;
        }
        .hero-background {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.6;
        }
        .hero-content {
            position: relative;
            z-index: 10;
        }
        .recipe-card {
            perspective: 1000px;
        }
        .recipe-card-inner {
            position: relative;
            width: 100%;
            height: 100%;
            transition: transform 0.8s;
            transform-style: preserve-3d;
        }
        .recipe-card.hovered .recipe-card-inner {
            transform: rotateY(180deg);
        }
        .recipe-card-front, .recipe-card-back {
            position: absolute;
            width: 100%;
            height: 100%;
            backface-visibility: hidden;
        }
        .recipe-card-back {
            background-color: #f8f0e3;
            color: #900c3f;
            transform: rotateY(180deg);
            @apply p-6 flex flex-col justify-center items-center text-center;
        }
        .recipe-card-back-title {
            @apply text-xl font-bold mb-2;
        }
        .recipe-card-back-description {
            @apply text-sm text-gray-700 mb-4;
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .animate-fade-up {
            animation: fadeInUp 1s ease-out forwards;
            opacity: 0;
        }
    </style>
</head>
