<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cosmic Comics - Dive into the Universe</title>
    <link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;700&family=Open+Sans:wght@400;600&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Open Sans', sans-serif; }
        h1, h2, h3, h4, h5, h6 { font-family: 'Montserrat', sans-serif; }
        .hero-gradient {
            background: linear-gradient(135deg, #ff0000, #0000ff, #ffff00);
            background-size: 600% 600%;
            animation: gradient-animation 12s ease infinite;
        }
        @keyframes gradient-animation {
            0%{background-position:0% 50%}
            50%{background-position:100% 50%}
            100%{background-position:0% 50%}
        }
        .panel-transition-fade { transition: opacity 0.5s ease-in-out; }
    </style>
</head>
<body class="bg-gray-50 text-gray-900">

    <header class="sticky top-0 z-50 bg-white border-b border-gray-200">
        <nav class="container mx-auto px-6 py-4">
            <div class="flex items-center justify-between">
                <div class="text-xl font-bold text-red-600">Cosmic Comics</div>
                <div class="hidden md:flex space-x-6">
                    <a href="#comics" class="hover:text-blue-600">Comics</a>
                    <a href="#creators" class="hover:text-blue-600">Creators</a>
                    <a href="#about" class="hover:text-blue-600">About</a>
                </div>
                <div class="md:hidden">
                    <button id="mobile-menu-button" class="text-gray-500 hover:text-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-500">
                        <i class="fa fa-bars fa-lg"></i>
                    </button>
                </div>
            </div>
        </nav>
        <div class="md:hidden hidden" id="mobile-menu">
            <div class="px-2 pt-2 pb-3 space-y-1">
                <a href="#comics" class="block px-3 py-2 rounded-md text-base font-medium text-gray-700 hover:text-blue-600">Comics</a>
                <a href="#creators" class="block px-3 py-2 rounded-md text-base font-medium text-gray-700 hover:text-blue-600">Creators</a>
                <a href="#about" class="block px-3 py-2 rounded-md text-base font-medium text-gray-700 hover:text-blue-600">About</a>
            </div>
        </div>
    </header>

    <section class="hero-gradient py-24 md:py-48 text-center text-white overflow-hidden relative">
        <div class="absolute inset-0 bg-black opacity-20"></div>
        <div class="container mx-auto px-6 relative z-10">
            <h1 class="text-4xl md:text-6xl font-bold mb-6 drop-shadow-md">Dive into a Universe of Stories</h1>
            <p class="text-lg md:text-xl mb-12 opacity-90 drop-shadow-md">Experience comics like never before with dynamic panels and interactive narratives.</p>
            <button class="bg-yellow-500 hover:bg-yellow-600 text-gray-900 font-bold py-3 px-8 rounded-full shadow-lg transition-colors duration-300">
                Explore Now <i class="fa fa-arrow-right ml-2"></i>
            </button>
        </div>
        <div class="absolute bottom-0 left-0 w-full h-1/3 bg-gradient-to-t from-gray-900 to-transparent"></div>
    </section>

    <section id="comics" class="py-20 container mx-auto px-6">
        <h2 class="text-3xl font-bold text-center mb-12">Featured Comics</h2>
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            <div class="rounded-xl shadow-lg overflow-hidden hover:shadow-2xl transition-shadow duration-300">
                <img src="https://picsum.photos/200/300?1" alt="Comic Cover 1" class="w-full h-64 object-cover">
                <div class="p-6">
                    <h3 class="text-xl font-semibold mb-2">Cosmic Crusaders #1</h3>
                    <p class="text-gray-600 mb-4">The galaxy's last hope against the dark armada.</p>
                    <a href="#" class="text-blue-600 hover:text-blue-800 font-medium">Read Now <i class="fa fa-arrow-right ml-1"></i></a>
                </div>
            </div>
            <div class="rounded-xl shadow-lg overflow-hidden hover:shadow-2xl transition-shadow duration-300">
                <img src="https://picsum.photos/200/300?2" alt="Comic Cover 2" class="w-full h-64 object-cover">
                <div class="p-6">
                    <h3 class="text-xl font-semibold mb-2">Mystic Mayhem #1</h3>
                    <p class="text-gray-600 mb-4">When magic clashes with technology, chaos ensues.</p>
                    <a href="#" class="text-blue-600 hover:text-blue-800 font-medium">Read Now <i class="fa fa-arrow-right ml-1"></i></a>
                </div>
            </div>
            <div class="rounded-xl shadow-lg overflow-hidden hover:shadow-2xl transition-shadow duration-300">
                <img src="https://picsum.photos/200/300?3" alt="Comic Cover 3" class="w-full h-64 object-cover">
                <div class="p-6">
                    <h3 class="text-xl font-semibold mb-2">Neon Knights #1</h3>
                    <p class="text-gray-600 mb-4">Cyberpunk adventures in a dazzling future city.</p>
                    <a href="#" class="text-blue-600 hover:text-blue-800 font-medium">Read Now <i class="fa fa-arrow-right ml-1"></i></a>
