    <section id="reader" class="bg-gray-100 py-20">
        <div class="container mx-auto px-6">
            <h2 class="text-3xl font-bold text-center mb-12">Comic Reader</h2>
            <div class="max-w-4xl mx-auto bg-white rounded-xl shadow-2xl p-8">
                <div id="comic-panel" class="relative overflow-hidden h-[500px] md:h-[600px]">
                    <img id="panel-image" src="https://picsum.photos/600/800?comic1-1" alt="Comic Panel 1" class="w-full h-full object-contain panel-transition-fade">
                    <div id="panel-overlay" class="absolute inset-0 bg-black opacity-0 transition-opacity duration-300 flex items-center justify-center">
                        <p id="panel-text" class="text-white text-xl md:text-2xl font-semibold"></p>
                    </div>
                </div>
                <div class="flex justify-between mt-6">
                    <button id="prev-panel" class="bg-gray-200 hover:bg-gray-300 text-gray-700 font-bold py-2 px-4 rounded-full" disabled>
                        <i class="fa fa-arrow-left"></i> Prev
                    </button>
                    <button id="next-panel" class="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-full">
                        Next <i class="fa fa-arrow-right"></i>
                    </button>
                </div>
                <div id="navigation-dots" class="flex justify-center mt-4 space-x-2">
                </div>
            </div>
        </div>
