    <section id="creators" class="py-20 container mx-auto px-6">
        <h2 class="text-3xl font-bold text-center mb-12">Meet the Creators</h2>
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            <div class="text-center">
                <img src="https://picsum.photos/200/300?creator1" alt="Creator 1" class="w-40 h-40 rounded-full mx-auto mb-4 shadow-md">
                <h3 class="text-xl font-semibold mb-1">Jane Doe</h3>
                <p class="text-gray-600">Writer</p>
            </div>
            <div class="text-center">
                <img src="https://picsum.photos/200/300?creator2" alt="Creator 2" class="w-40 h-40 rounded-full mx-auto mb-4 shadow-md">
                <h3 class="text-xl font-semibold mb-1">John Smith</h3>
                <p class="text-gray-600">Artist</p>
            </div>
            <div class="text-center">
                <img src="https://picsum.photos/200/300?creator3" alt="Creator 3" class="w-40 h-40 rounded-full mx-auto mb-4 shadow-md">
                <h3 class="text-xl font-semibold mb-1">Emily White</h3>
                <p class="text-gray-600">Colorist</p>
            </div>
        </div>
    </section>

    <section id="about" class="py-20 bg-gray-100">
        <div class="container mx-auto px-6 text-center">
            <h2 class="text-3xl font-bold mb-8">About Cosmic Comics</h2>
            <p class="text-lg text-gray-700 max-w-2xl mx-auto mb-12">Cosmic Comics is a digital platform dedicated to bringing you the most exciting and visually stunning comic book experiences. We collaborate with top creators to deliver stories that push boundaries and ignite imaginations. Dive into our universe and discover your next favorite adventure!</p>
            <button class="bg-red-600 hover:bg-red-700 text-white font-bold py-3 px-8 rounded-full shadow-lg transition-colors duration-300">
                Learn More <i class="fa fa-info-circle ml-2"></i>
            </button>
        </div>
    </section>

    <footer class="bg-gray-900 text-gray-300 py-12">
        <div class="container mx-auto px-6 text-center">
            <p>&copy; 2024 Cosmic Comics. All rights reserved.</p>
            <div class="mt-4 space-x-4">
                <a href="#" class="hover:text-white"><i class="fab fa-facebook-square fa-lg"></i></a>
                <a href="#" class="hover:text-white"><i class="fab fa-twitter-square fa-lg"></i></a>
                <a href="#" class="hover:text-white"><i class="fab fa-instagram-square fa-lg"></i></a>
            </div>
        </div>
    </footer>

    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        const comicPanels = [
            "https://picsum.photos/600/800?comic1-1",
            "https://picsum.photos/600/800?comic1-2",
            "https://picsum.photos/600/800?comic1-3",
            "https://picsum.photos/600/800?comic1-4",
            "https://picsum.photos/600/800?comic1-5"
        ];
        let currentPanelIndex = 0;
        const panelImage = document.getElementById('panel-image');
        const prevPanelButton = document.getElementById('prev-panel');
        const nextPanelButton = document.getElementById('next-panel');
        const navigationDots = document.getElementById('navigation-dots');

        function loadPanel(index) {
            panelImage.style.opacity = 0;
            setTimeout(() => {
                panelImage.src = comicPanels[index];
                panelImage.style.opacity = 1;
            }, 250);

            updateNavigation();
        }

        function updateNavigation() {
            prevPanelButton.disabled = currentPanelIndex === 0;
            nextPanelButton.disabled = currentPanelIndex === comicPanels.length - 1;

            navigationDots.innerHTML = '';
            comicPanels.forEach((_, index) => {
                const dot = document.createElement('button');
                dot.classList.add('w-3', 'h-3', 'rounded-full', 'block');
                if (index === currentPanelIndex) {
                    dot.classList.add('bg-blue-600');
                } else {
                    dot.classList.add('bg-gray-300', 'hover:bg-gray-400');
                }
                dot.addEventListener('click', () => {
                    currentPanelIndex = index;
                    loadPanel(currentPanelIndex);
                });
                navigationDots.appendChild(dot);
            });
        }

        prevPanelButton.addEventListener('click', () => {
            if (currentPanelIndex > 0) {
                currentPanelIndex--;
                loadPanel(currentPanelIndex);
            }
        });

        nextPanelButton.addEventListener('click', () => {
            if (currentPanelIndex < comicPanels.length - 1) {
                currentPanelIndex++;
                loadPanel(currentPanelIndex);
            }
        });

        loadPanel(currentPanelIndex);
    </script>

</body>
</html>
