    <title>Apex Coach - Level Up Your Game</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="YOUR_SRI_HASH_HERE" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Poppins', sans-serif; }
        .module-content {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.5s ease-in-out;
        }
        .module-content.expanded {
            max-height: 1000px;
        }
        .progress-tracker {
            position: relative;
            width: 100px;
            height: 100px;
        }
        .progress-tracker svg {
            transform: rotate(-90deg);
        }
        .progress-tracker svg circle {
            fill: none;
            stroke-width: 10;
            stroke-dasharray: 283;
            stroke-dashoffset: 283;
            stroke-linecap: round;
            animation: progress-animation 1s linear forwards;
        }
        @keyframes progress-animation {
            to { stroke-dashoffset: var(--dashoffset); }
        }
        .progress-tracker-number {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            font-size: 1.5rem;
            font-weight: 600;
        }
        .scheduler-day {
            transition: background-color 0.3s ease;
        }
        .scheduler-day:hover {
            background-color: rgba(209, 213, 219, 0.5);
        }
        .session-card {
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .session-card:hover {
            transform: scale(1.03);
            box-shadow: 0 10px 25px rgba(0,0,0,0.1);
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .fade-in {
            animation: fadeIn 0.8s ease-out forwards;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .hero-overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(to bottom, rgba(30, 41, 59, 0.8), rgba(30, 41, 59, 0.6));
        }
        .dynamic-text {
            animation: dynamicTextAnimation 5s infinite alternate;
        }

        @keyframes dynamicTextAnimation {
            0% { transform: translateY(0); opacity: 1; }
            100% { transform: translateY(-10px); opacity: 0.8; }
        }
        .module-header {
            cursor: pointer;
            transition: background-color 0.3s ease;
        }
        .module-header:hover {
            background-color: rgba(209, 213, 219, 0.2);
        }
        .module-border {
            border-color: rgba(209, 213, 219, 0.3);
        }
        .scheduler-border {
             border-color: rgba(209, 213, 219, 0.5);
        }
        .scheduler-header-border {
             border-color: rgba(209, 213, 219, 0.7);
        }
        .scheduler-day-border {
             border-color: rgba(209, 213, 219, 0.4);
        }

    </style>
</head>
