        mobileMenuButton.addEventListener('click', () => mobileMenu.classList.remove('hidden'));
        mobileMenuClose.addEventListener('click', () => mobileMenu.classList.add('hidden'));

        document.querySelectorAll('section').forEach(section => {
            gsap.from(section.querySelectorAll('.fade-in'), {
                opacity: 0,
                duration: 1.2,
                stagger: 0.2,
                scrollTrigger: {
                    trigger: section,
                    start: "top 80%",
                    toggleActions: "play none none reverse"
                }
            });
            gsap.from(section.querySelectorAll('.slide-up'), {
                y: 50,
                opacity: 0,
                duration: 1.2,
                stagger: 0.2,
                scrollTrigger: {
                    trigger: section,
                    start: "top 80%",
                    toggleActions: "play none none reverse"
                }
            });
             gsap.from(section.querySelectorAll('.plant-card-animation'), {
                opacity: 0,
                x: -50,
                duration: 1,
                stagger: 0.1,
                ease: "power2.out",
                scrollTrigger: {
                    trigger: section,
                    start: "top 80%",
                    toggleActions: "play none none reverse"
                }
            });
        });
    </script>

</body>
</html>
