    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const ratingStarsGroups = document.querySelectorAll('.rating-stars');
            ratingStarsGroups.forEach(group => {
                const stars = group.querySelectorAll('.rating-star');
                stars.forEach((star, index) => {
                    star.addEventListener('click', () => {
                        stars.forEach((s, i) => {
                            if (i <= index) {
                                s.classList.add('active', 'text-orange-400');
                                s.classList.remove('text-gray-300');
                            } else {
                                s.classList.remove('active', 'text-orange-400');
                                s.classList.add('text-gray-300');
                            }
                        });
                        const recipeId = group.dataset.recipeId;
                        const ratingValue = index + 1;
                        console.log(`Recipe ${recipeId} rated: ${ratingValue} stars`);
                    });
                    star.addEventListener('mouseover', () => {
                        stars.forEach((s, i) => {
                            if (i <= index) {
                                s.classList.add('text-orange-300');
                            } else {
                                s.classList.remove('text-orange-300');
                            }
                        });
                    });
                    star.addEventListener('mouseout', () => {
                        stars.forEach((s, i) => {
                            if (!s.classList.contains('active')) {
                                s.classList.remove('text-orange-300');
                            }
                        });
                    });
                });
            });
        });
    </script>
</body>
</html>
