<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Virtual Art Gallery</title>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Inter', sans-serif; }
        .artwork-description { max-height: 0; overflow: hidden; transition: max-height 0.6s ease-in-out; }
        .artwork-description.expanded { max-height: 500px; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .fade-in { animation: fadeIn 0.5s ease-out forwards; }
        @keyframes slideIn { from { transform: translateX(-20px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        .slide-in { animation: slideIn 0.5s ease-out forwards; }
        @keyframes zoomIn { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .zoom-in { animation: zoomIn 0.3s ease-out forwards; }
        .fullscreen-gallery { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.95); z-index: 50; display: flex; justify-content: center; align-items: center; overflow: auto; }
        .fullscreen-content { max-width: 90%; max-height: 90%; }
        .gallery-container { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 3rem; }
        .artwork-card { position: relative; overflow: hidden; border-radius: 0.5rem; background-color: #f9f9f9; transition: transform 0.3s ease-in-out; }
        .artwork-card:hover { transform: scale(1.03); }
        .artwork-image { display: block; width: 100%; aspect-ratio: 4/3; object-fit: cover; border-bottom: 1px solid #e2e8f0; }
        .artwork-info { padding: 1.5rem; }
        .artwork-title { font-size: 1.25rem; font-weight: 600; color: #1e293b; margin-bottom: 0.5rem; }
        .artwork-artist { font-size: 1rem; color: #4b5563; margin-bottom: 1rem; }
        .description-button { display: flex; align-items: center; justify-content: space-between; width: 100%; padding: 0.75rem 1.5rem; border-top: 1px solid #e2e8f0; background-color: #fff; color: #3b82f6; font-weight: 600; cursor: pointer; transition: background-color 0.3s ease-in-out; border-radius: 0 0 0.5rem 0.5rem; }
        .description-button:hover { background-color: #f2f2f2; }
        .description-icon { margin-left: 0.5rem; transition: transform 0.3s ease-in-out; }
        .description-button.expanded .description-icon { transform: rotate(180deg); }
        .fullscreen-image { max-width: 100%; max-height: 100%; object-fit: contain; }
        .close-fullscreen { position: absolute; top: 2rem; right: 2rem; color: white; font-size: 2rem; cursor: pointer; }
        .section-transition { opacity: 0; transform: translateY(20px); transition: opacity 0.7s ease-out, transform 0.7s ease-out; }
        .section-transition.active { opacity: 1; transform: translateY(0); }
        .hero-section { position: relative; background-color: #f3f4f6; padding: 8rem 0; overflow: hidden; }
        .hero-content { max-width: 7xl; margin-left: auto; margin-right: auto; padding-left: 1.5rem; padding-right: 1.5rem; text-align: center; }
        .hero-title { font-size: 3.75rem; line-height: 1; font-weight: 800; letter-spacing: -0.025em; color: #1e293b; margin-bottom: 1.5rem; }
        .hero-subtitle { font-size: 1.5rem; line-height: 1.75rem; color: #4b5563; margin-bottom: 3rem; }
        .hero-buttons { display: flex; justify-content: center; gap: 1rem; }
        .hero-button-primary { background-color: #3b82f6; color: white; padding: 1rem 2rem; border-radius: 0.375rem; font-weight: 600; transition: background-color 0.3s ease-in-out; }
        .hero-button-primary:hover { background-color: #2563eb; }
        .hero-button-secondary { border: 2px solid #3b82f6; color: #3b82f6; padding: 0.9rem 1.9rem; border-radius: 0.375rem; font-weight: 600; transition: background-color 0.3s ease-in-out, color 0.3s ease-in-out; }
        .hero-button-secondary:hover { background-color: #eff6ff; color: #2563eb; }
        .gallery-section { padding: 6rem 0; background-color: #fff; }
        .section-title { text-align: center; font-size: 2.5rem; font-weight: 700; color: #1e293b; margin-bottom: 4rem; }
        .footer-section { background-color: #1e293b; color: #f9f9f9; padding: 3rem 0; text-align: center; }
