<script>
    function toggleDescription(descriptionId, button) {
        const description = document.getElementById(descriptionId);
        description.classList.toggle('expanded');
        button.classList.toggle('expanded');
    }

    let fullscreenView = document.getElementById('fullscreen-view');
    let fullscreenImg = document.getElementById('fullscreen-img');

    function openFullscreen(imgSrc) {
        fullscreenImg.src = imgSrc;
        fullscreenView.classList.remove('hidden');
        fullscreenView.classList.add('fade-in');
        document.body.style.overflow = 'hidden';
    }

    function closeFullscreen() {
        fullscreenView.classList.add('hidden');
        fullscreenView.classList.remove('fade-in');
        document.body.style.overflow = 'auto';
    }

    const sections = document.querySelectorAll('.section-transition');
    const observer = new IntersectionObserver(entries => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('active');
            } else {
                entry.target.classList.remove('active');
            }
        });
    }, {
        threshold: 0.1
    });

    sections.forEach(section => {
        observer.observe(section);
    });
</script>

</body>
</html>
