    <script>
        lucide.createIcons();

        document.getElementById('mobile-menu-button').addEventListener('click', () => {
            document.getElementById('mobile-menu').classList.toggle('hidden');
        });

        function getTimeRemaining(endtime) {
            const total = Date.parse(endtime) - Date.parse(new Date());
            const seconds = Math.floor((total / 1000) % 60);
            const minutes = Math.floor((total / 1000 / 60) % 60);
            const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
            return {
                total,
                hours,
                minutes,
                seconds
            };
        }

        function updateTimers() {
            const timers = document.querySelectorAll('.timer');
            timers.forEach(timerElement => {
                const endTimeSeconds = timerElement.dataset.countdown;
                const endTime = new Date(endTimeSeconds * 1000);

                function updateClock() {
                    const t = getTimeRemaining(endTime);
                    let hours = String(t.hours).padStart(2, '0');
                    let minutes = String(t.minutes).padStart(2, '0');
                    let seconds = String(t.seconds).padStart(2, '0');

                    timerElement.innerHTML = `${hours}:${minutes}:${seconds}`;

                    if (t.total <= 0) {
                        clearInterval(timeinterval);
                        timerElement.innerHTML = 'Auction Ended';
                    }
                }

                updateClock();
                const timeinterval = setInterval(updateClock, 1000);
            });
        }

        updateTimers();
    </script>
</body>
</html>
