    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            const scheduleCells = document.querySelectorAll('.schedule-cell.available');
            const bookingForm = document.getElementById('booking-form');
            const classTimeInput = document.getElementById('class-time');
            const cancelBookingButton = document.getElementById('cancel-booking');
            const classBookingForm = document.getElementById('class-booking-form');
            const contactForm = document.getElementById('contact-form');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            scheduleCells.forEach(cell => {
                cell.addEventListener('click', () => {
                    const time = cell.dataset.time;
                    classTimeInput.value = time;
                    bookingForm.classList.remove('hidden');
                    window.scrollTo({
                        top: document.getElementById('booking-form').offsetTop - 100,
                        behavior: 'smooth'
                    });
                });
            });

            cancelBookingButton.addEventListener('click', () => {
                bookingForm.classList.add('hidden');
            });

            classBookingForm.addEventListener('submit', (event) => {
                event.preventDefault();
                alert('Booking Confirmed! Check your email for details.');
                bookingForm.classList.add('hidden');
                classBookingForm.reset();
            });

            contactForm.addEventListener('submit', (event) => {
                event.preventDefault();
                alert('Message Sent! We will get back to you soon.');
                contactForm.reset();
            });
        });
    </script>

</body>
</html>
