        .bg-maroon {
            background-color: #800000;
        }
        .carousel-container {
            overflow: hidden;
        }
        .carousel-track {
            display: flex;
            transition: transform 0.5s ease-in-out;
        }
        .carousel-item {
            flex: 0 0 auto;
            width: 200px;
            margin-right: 20px;
        }
        .book-cover {
            aspect-ratio: 2/3;
            object-fit: cover;
            border-radius: 0.5rem;
        }
        .filter-form {
            background-color: rgba(255, 255, 255, 0.8);
            backdrop-filter: blur(10px);
            border-radius: 1rem;
            padding: 2rem;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
        }
        .layered-card {
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
            border-radius: 1rem;
            overflow: hidden;
        }
        .layered-content {
            position: relative;
            padding: 2rem;
            background-color: #f5f5dc;
        }
        .layered-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.1);
            opacity: 0;
            transition: opacity 0.3s ease-in-out;
        }
        .layered-card:hover .layered-overlay {
            opacity: 1;
        }
        .btn-maroon {
            background-color: #800000;
            color: #f5f5dc;
            transition: background-color 0.3s ease-in-out, color 0.3s ease-in-out;
        }
        .btn-maroon:hover {
            background-color: #a60000;
            color: #ffffff;
        }
        .input-serif {
            font-family: 'Playfair Display', serif;
            border-color: #800000;
            background-color: #f5f5dc;
            color: #800000;
        }
        .input-serif:focus {
            border-color: #a60000;
            box-shadow: 0 0 0 2px rgba(166, 0, 0, 0.3);
        }
        .select-serif {
             font-family: 'Playfair Display', serif;
            border-color: #800000;
            background-color: #f5f5dc;
            color: #800000;
        }
        .select-serif:focus {
            border-color: #a60000;
            box-shadow: 0 0 0 2px rgba(166, 0, 0, 0.3);
        }
        .animate-fade-in {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.7s ease-out, transform 0.7s ease-out;
        }
        .animate-fade-in.in-view {
            opacity: 1;
            transform: translateY(0);
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .hero-background {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.6;
        }
        .hero-content {
            position: relative;
