        }
        .parallax-bg {
            background-attachment: fixed;
            background-position: center;
            background-repeat: no-repeat;
            background-size: cover;
        }
        .category-button {
            @apply px-4 py-2 rounded-full text-sm font-semibold transition-colors duration-300 ease-in-out;
        }
        .category-button-active {
            @apply bg-maroon text-cream;
