    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const fadeInElements = document.querySelectorAll('.animate-fade-in');

            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('in-view');
                        observer.unobserve(entry.target);
                    }
                });
            }, {
                threshold: 0.1
            });

            fadeInElements.forEach(element => {
                observer.observe(element);
            });

            const track = document.getElementById('bookCarouselTrack');
            const prevButton = document.getElementById('carouselPrev');
            const nextButton = document.getElementById('carouselNext');
            const items = document.querySelectorAll('.carousel-item');
            let currentIndex = 0;
            const itemWidth = items[0].offsetWidth + 20;
            const visibleItems = 3;

            nextButton.addEventListener('click', () => {
                if (currentIndex < items.length - visibleItems) {
                    currentIndex++;
                    track.style.transform = `translateX(-${currentIndex * itemWidth}px)`;
                }
            });

            prevButton.addEventListener('click', () => {
                if (currentIndex > 0) {
                    currentIndex--;
                    track.style.transform = `translateX(-${currentIndex * itemWidth}px)`;
                }
            });

            const categoryButtons = document.querySelectorAll('.category-button');
            categoryButtons.forEach(button => {
                button.addEventListener('click', function() {
                    categoryButtons.forEach(btn => {
                        btn.classList.remove('category-button-active');
                        btn.classList.add('category-button-inactive');
                    });
                    this.classList.remove('category-button-inactive');
                    this.classList.add('category-button-active');
                    const genre = this.dataset.genre;
                    console.log(`Filtering by genre: ${genre}`);
                });
            });


            gsap.registerPlugin(ScrollTrigger);

            gsap.utils.toArray('.animate-fade-in').forEach(section => {
                gsap.from(section, {
                    opacity: 0,
                    y: 50,
                    duration: 1,
                    ease: "power3.out",
                    scrollTrigger: {
                        trigger: section,
                        start: "top 80%",
                        end: "top 20%",
                        toggleActions: "play none none reverse"
                    }
                });
            });
        });
    </script>

</body>
</html>
