<!DOCTYPE html>
<html lang="en" class="bg-black">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Home Automation Dashboard</title>
    <link href="https://fonts.googleapis.com/css2?family=Roboto+Mono:wght@400;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Roboto Mono', monospace;
            color: #fff;
        }
        .device-card {
            background: rgba(0, 0, 0, 0.6);
            border: 1px solid #0f172a;
            box-shadow: 0 0 20px rgba(0, 173, 255, 0.3);
        }
        .btn-neon {
            background-color: #00aaff;
            box-shadow: 0 0 10px #00aaff, 0 0 20px #00aaff;
            transition: box-shadow 0.3s ease-in-out, background-color 0.3s ease-in-out;
        }
        .btn-neon:hover {
            background-color: #00cfff;
            box-shadow: 0 0 15px #00cfff, 0 0 30px #00cfff;
        }
        .chart-bar {
            background-color: #00aaff;
            transition: height 0.5s ease-out;
        }
        .chart-label {
            color: #64748b;
        }
        .status-indicator {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            display: inline-block;
            margin-left: 8px;
        }
        .status-online {
            background-color: #00ff00;
            box-shadow: 0 0 5px #00ff00;
        }
        .status-offline {
            background-color: #ff0000;
            box-shadow: 0 0 5px #ff0000;
        }
        .status-idle {
            background-color: #ffff00;
            box-shadow: 0 0 5px #ffff00;
        }
        .slider-thumb {
            -webkit-appearance: none;
            appearance: none;
            width: 20px;
            height: 20px;
            background: #00aaff;
            cursor: pointer;
            border-radius: 50%;
            box-shadow: 0 0 5px #00aaff;
        }
        .slider-thumb::-webkit-slider-thumb {
            -webkit-appearance: none;
            appearance: none;
            width: 20px;
            height: 20px;
            background: #00aaff;
            cursor: pointer;
            border-radius: 50%;
            box-shadow: 0 0 5px #00aaff;
        }
        .slider-thumb::-moz-range-thumb {
            width: 20px;
            height: 20px;
            background: #00aaff;
            cursor: pointer;
            border-radius: 50%;
            box-shadow: 0 0 5px #00aaff;
        }
        .slider-track {
            width: 100%;
            height: 4px;
            cursor: pointer;
            background: #1e293b;
            border-radius: 2px;
        }
        input[type="range"] {
            -webkit-appearance: none;
            width: 100%;
            height: 4px;
            background: transparent;
        }
        input[type="range"]::-webkit-slider-runnable-track {
            background: #1e293b;
            height: 4px;
            border-radius: 2px;
        }
        input[type="range"]::-moz-range-track {
            background: #1e293b;
            height: 4px;
            border-radius: 2px;
        }
        input[type="range"]::-webkit-slider-thumb {
            -webkit-appearance: none;
            appearance: none;
            margin-top: -8px;
        }
        input[type="range"]::-moz-range-thumb {
            margin-top: -8px;
        }

        @keyframes pulse-neon {
            0% { box-shadow: 0 0 10px #00aaff, 0 0 20px #00aaff; }
            50% { box-shadow: 0 0 15px #00cfff, 0 0 30px #00cfff; }
            100% { box-shadow: 0 0 10px #00aaff, 0 0 20px #00aaff; }
        }

        .btn-neon-animate {
            animation: pulse-neon 2s infinite;
        }


    </style>
</head>
<body class="bg-black text-white">
    <div class="container mx-auto p-4 md:p-8">
        <header class="mb-8">
            <h1 class="text-3xl md:text-4xl font-bold text-center mb-2">
                <i class="fa-solid fa-house-laptop text-blue-400 mr-2"></i>
                <span class="text-blue-400">Neon</span> Home Dashboard
            </h1>
            <p class="text-gray-500 text-center">Real-time Device Monitoring & Control</p>
        </header>

        <main class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">

            <section class="device-card rounded-2xl p-4 md:p-6 flex flex-col justify-between">
                <div>
                    <div class="flex items-center mb-4">
                        <i class="fa-solid fa-lightbulb text-blue-400 text-xl md:text-2xl mr-3"></i>
                        <h2 class="text-xl md:text-2xl font-semibold">Living Room Lights</h2>
                        <span class="status-indicator status-online ml-2" title="Online"></span>
                    </div>
                    <div class="chart-container h-24 md:h-32 w-full relative">
                        <div class="absolute bottom-0 left-0 w-full h-full flex items-end justify-around">
                            <div class="chart-bar w-4 md:w-6 rounded-t-md" style="height: 60%;"></div>
                            <div class="chart-bar w-4 md:w-6 rounded-t-md" style="height: 80%;"></div>
                            <div class="chart-bar w-4 md:w-6 rounded-t-md" style="height: 70%;"></div>
                            <div class="chart-bar w-4 md:w-6 rounded-t-md" style="height: 90%;"></div>
                            <div class="chart-bar w-4 md:w-6 rounded-t-md" style="height: 75%;"></div>
                        </div>
                        <div class="absolute bottom-0 left-0 w-full text-xs chart-label flex justify-around mt-2">
                            <span>Mon</span>
                            <span>Tue</span>
                            <span>Wed</span>
                            <span>Thu</span>
