            <p>&copy; 2024 Home Automation Dashboard. Crafted with <span class="text-red-500"><i class="fa-solid fa-heart"></i></span> using Tailwind CSS.</p>
        </footer>
    </div>

    <script>
        document.querySelectorAll('input[type="range"]').forEach(slider => {
            slider.addEventListener('input', function() {
                this.closest('.device-card').querySelector('.text-blue-300').innerText = `${this.value}%`;
            });
        });

        function generateRandomChartData() {
            document.querySelectorAll('.chart-container').forEach(container => {
                const bars = container.querySelectorAll('.chart-bar');
                bars.forEach(bar => {
                    const randomHeight = Math.floor(Math.random() * 80) + 20;
                    bar.style.height = `${randomHeight}%`;
                });
            });
        }

        setInterval(generateRandomChartData, 3000);
    </script>
</body>
</html>
