    <script>
        let currentStep = 1;
        let donationAmount = 0;

        function setDonationAmount(amount) {
            donationAmount = amount === 'other' ? 0 : amount;
            document.getElementById('otherAmountInput').classList.toggle('step-active', amount === 'other');
            document.getElementById('otherAmountInput').classList.toggle('step-inactive', amount !== 'other');

            if (amount !== 'other') {
                const buttons = document.querySelectorAll('#step-1 .grid button');
                buttons.forEach(button => {
                    button.classList.remove('bg-blue-100', 'text-blue-700', 'shadow-depth-2', 'border-2', 'border-blue-500');
                    button.classList.add('bg-white', 'text-gray-700', 'shadow-depth-1');
                });
                const selectedButton = Array.from(buttons).find(button => button.textContent.trim() === (amount === 'other' ? 'Other' : '$' + amount));
                if (selectedButton) {
                    selectedButton.classList.remove('bg-white', 'text-gray-700', 'shadow-depth-1');
                    selectedButton.classList.add('bg-blue-100', 'text-blue-700', 'shadow-depth-2', 'border-2', 'border-blue-500');
                }
            } else {
                const buttons = document.querySelectorAll('#step-1 .grid button');
                buttons.forEach(button => {
                    button.classList.remove('bg-blue-100', 'text-blue-700', 'shadow-depth-2', 'border-2', 'border-blue-500');
                    button.classList.add('bg-white', 'text-gray-700', 'shadow-depth-1');
                });
                const otherButton = Array.from(buttons).find(button => button.textContent.trim() === 'Other');
                if (otherButton) {
                    otherButton.classList.remove('bg-white', 'text-gray-700', 'shadow-depth-1');
                    otherButton.classList.add('bg-blue-100', 'text-blue-700', 'shadow-depth-2', 'border-2', 'border-blue-500');
                }
            }
        }

        function nextStep(currentStepNum, nextStepNum) {
            const currentStepElement = document.getElementById(`step-${currentStepNum}`);
            const nextStepElement = document.getElementById(`step-${nextStepNum}`);
            currentStepElement.classList.replace('step-active', 'step-inactive');
            nextStepElement.classList.replace('step-inactive', 'step-active');
            nextStepElement.classList.add('animate-slide-in');
            currentStep = nextStepNum;
        }

        function prevStep(currentStepNum, prevStepNum) {
            const currentStepElement = document.getElementById(`step-${currentStepNum}`);
            const prevStepElement = document.getElementById(`step-${prevStepNum}`);
            currentStepElement.classList.replace('step-active', 'step-inactive');
            prevStepElement.classList.replace('step-inactive', 'step-active');
            prevStepElement.classList.add('animate-slide-in');
            currentStep = prevStepNum;
        }

        function submitDonation() {
            alert('Thank you for your generous donation!');
            // In a real application, you would handle form submission and payment processing here.
        }
    </script>
</body>
</html>
