            background-color: #f0f0f0;
            color: #333;
        }
        .container {
            max-width: 1200px;
            margin-left: auto;
            margin-right: auto;
            padding-left: 1rem;
            padding-right: 1rem;
        }
        .accordion-content {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-out;
        }
        .accordion-content.open {
            max-height: 500px;
        }
        .live-chat-button {
            position: fixed;
            bottom: 2rem;
            right: 2rem;
            z-index: 100;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .hero-overlay {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(to bottom, rgba(29, 52, 83, 0.8), rgba(29, 52, 83, 0.6));
            z-index: 1;
        }
        .hero-content {
            position: relative;
            z-index: 2;
        }
        .parallax-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.6;
            transform: translateZ(-1px) scale(1.2);
            z-index: 0;
        }
        @keyframes pulse {
            0% {
                transform: scale(1);
                opacity: 1;
            }
            50% {
                transform: scale(1.05);
                opacity: 0.8;
            }
            100% {
                transform: scale(1);
                opacity: 1;
            }
        }
        .pulse-animation {
            animation: pulse 2s infinite;
        }
    </style>
</head>
