                    <a href="tel:+15551234567" class="inline-block bg-teal-500 hover:bg-teal-600 text-white py-2 px-4 rounded-full transition-colors">Call Now</a>
                </div>

                <div class="bg-navy-700 rounded-lg p-8 text-center shadow-md hover:shadow-lg transition-shadow duration-300">
                    <i class="fa fa-comments text-3xl mb-4 text-teal-400"></i>
                    <h3 class="font-semibold text-xl mb-2">Live Chat</h3>
                    <p class="text-gray-300 mb-4">Chat with a support agent instantly.</p>
                    <button class="bg-teal-500 hover:bg-teal-600 text-white py-2 px-4 rounded-full transition-colors pulse-animation">Start Chat</button>
                </div>
            </div>
        </div>
    </section>

    <footer class="bg-gray-900 text-gray-400 py-12">
        <div class="container text-center">
            <p>&copy; 2024 Customer Support Portal. All rights reserved.</p>
            <p class="mt-2">
                <a href="#" class="hover:text-white transition-colors">Terms of Service</a> | <a href="#" class="hover:text-white transition-colors">Privacy Policy</a>
            </p>
        </div>
    </footer>

    <div class="live-chat-button">
        <button class="bg-teal-500 hover:bg-teal-600 text-white p-3 rounded-full shadow-lg focus:outline-none pulse-animation">
            <i class="fa fa-comment-dots fa-lg"></i> Live Chat
        </button>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const accordionHeaders = document.querySelectorAll('.accordion-header');
            accordionHeaders.forEach(header => {
                header.addEventListener('click', () => {
                    const content = header.nextElementSibling;
                    content.classList.toggle('open');
                    header.querySelector('i').classList.toggle('fa-chevron-down');
                    header.querySelector('i').classList.toggle('fa-chevron-up');

                    accordionHeaders.forEach(otherHeader => {
                        if (otherHeader !== header) {
                            const otherContent = otherHeader.nextElementSibling;
                            if (otherContent.classList.contains('open')) {
                                otherContent.classList.remove('open');
                                otherHeader.querySelector('i').classList.remove('fa-chevron-up');
                                otherHeader.querySelector('i').classList.add('fa-chevron-down');
                            }
                        }
                    });
                });
            });

            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });
    </script>

</body>
</html>
