<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Amazing Online Survey</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Poppins', sans-serif; }
        .progress-circle {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            border: 4px solid #ddd;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
        }
        .progress-circle.active { border-color: #ff8a00; }
        .progress-circle.active::after {
            content: '';
            position: absolute;
            top: -4px;
            left: -4px;
            right: -4px;
            bottom: -4px;
            border-radius: 50%;
            border: 4px solid transparent;
            border-top-color: #ff8a00;
            animation: spin 1.2s linear infinite;
        }
        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
        .radio-input:checked + .radio-label {
            background-color: #ff8a00;
            color: white;
            border-color: #ff8a00;
        }
        .radio-label {
            transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
        }
        .btn-primary {
            transition: background-color 0.3s ease-in-out, transform 0.2s ease;
        }
        .btn-primary:hover {
            transform: scale(1.05);
        }
        .question-card {
            transform: translateY(20px);
            opacity: 0;
            transition: transform 0.5s ease-out, opacity 0.5s ease-out;
        }
        .question-card.active {
            transform: translateY(0);
            opacity: 1;
        }
    </style>
</head>
<body class="bg-white text-gray-900">
    <header class="bg-orange-50 py-6">
        <div class="container mx-auto px-4 flex justify-center">
            <h1 class="text-3xl font-bold text-orange-700">Amazing Survey Platform</h1>
        </div>
    </header>

    <main class="container mx-auto px-4 py-12">
        <div class="max-w-3xl mx-auto bg-white rounded-2xl shadow-xl p-8 md:p-12 relative overflow-hidden">
            <div id="progress-bar" class="flex justify-around mb-8 z-10 relative">
                <div class="progress-circle active" data-step="1">1</div>
                <div class="progress-circle" data-step="2">2</div>
                <div class="progress-circle" data-step="3">3</div>
            </div>

            <div id="questions-container" class="space-y-8 relative">

                <div class="question-card active" data-question="1">
                    <h2 class="text-2xl font-semibold mb-6 text-orange-800">Question 1:</h2>
                    <p class="mb-4 text-lg">What is your favorite color?</p>
                    <div class="space-y-3">
                        <div>
                            <input type="radio" id="color-red" name="fav_color_1" value="red" class="radio-input hidden">
                            <label for="color-red" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Red</span>
                            </label>
                        </div>
                        <div>
                            <input type="radio" id="color-blue" name="fav_color_1" value="blue" class="radio-input hidden">
                            <label for="color-blue" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Blue</span>
                            </label>
                        </div>
                        <div>
                            <input type="radio" id="color-green" name="fav_color_1" value="green" class="radio-input hidden">
                            <label for="color-green" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Green</span>
                            </label>
                        </div>
                    </div>
                </div>

                <div class="question-card" data-question="2">
                    <h2 class="text-2xl font-semibold mb-6 text-orange-800">Question 2:</h2>
                    <p class="mb-4 text-lg">What is your favorite animal?</p>
                    <div class="space-y-3">
                        <div>
                            <input type="radio" id="animal-dog" name="fav_animal_2" value="dog" class="radio-input hidden">
                            <label for="animal-dog" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Dog</span>
                            </label>
                        </div>
                        <div>
                            <input type="radio" id="animal-cat" name="fav_animal_2" value="cat" class="radio-input hidden">
                            <label for="animal-cat" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Cat</span>
                            </label>
                        </div>
                        <div>
                            <input type="radio" id="animal-bird" name="fav_animal_2" value="bird" class="radio-input hidden">
                            <label for="animal-bird" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Bird</span>
                            </label>
                        </div>
                    </div>
                </div>

                <div class="question-card" data-question="3">
                    <h2 class="text-2xl font-semibold mb-6 text-orange-800">Question 3:</h2>
                    <p class="mb-4 text-lg">What is your favorite food?</p>
                    <div class="space-y-3">
                        <div>
                            <input type="radio" id="food-pizza" name="fav_food_3" value="pizza" class="radio-input hidden">
                            <label for="food-pizza" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Pizza</span>
                            </label>
                        </div>
                        <div>
                            <input type="radio" id="food-burger" name="fav_food_3" value="burger" class="radio-input hidden">
                            <label for="food-burger" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Burger</span>
                            </label>
                        </div>
                        <div>
                            <input type="radio" id="food-pasta" name="fav_food_3" value="pasta" class="radio-input hidden">
                            <label for="food-pasta" class="radio-label inline-flex items-center space-x-2 px-4 py-2 bg-gray-100 rounded-full cursor-pointer hover:bg-orange-100 hover:border-orange-200 border border-transparent">
                                <i class="fa-solid fa-circle-check text-orange-500 hidden radio-checked-icon"></i>
                                <span>Pasta</span>
                            </label>
                        </div>
                    </div>
                </div>
            </div>

            <div class="flex justify-between mt-12 z-10 relative">
                <button id="prev-btn" class="hidden btn-primary bg-gray-200 hover:bg-gray-300 text-gray-700 font-semibold py-3 px-6 rounded-full">Previous</button>
                <button id="next-btn" class="btn-primary bg-orange-500 hover:bg-orange-600 text-white font-semibold py-3 px-6 rounded-full">Next</button>
                <button id="submit-btn" class="hidden btn-primary bg-green-500 hover:bg-green-600 text-white font-semibold py-3 px-6 rounded-full">Submit</button>
            </div>

            <div class="absolute top-0 left-0 w-full h-full bg-orange-100 opacity-10 rounded-2xl pointer-events-none"></div>
            <div class="absolute bottom-0 right-0 w-48 h-48 bg-orange-200 rounded-full blur-3xl -mr-12 -mb-12 pointer-events-none"></div>
            <div class="absolute top-0 left-0 w-32 h-32 bg-orange-200 rounded-full blur-3xl -ml-8 -mt-8 pointer-events-none"></div>
        </div>
    </main>

    <footer class="bg-gray-50 py-8 text-center text-gray-500 border-t border-gray-200 mt-12">
        <p>&copy; 2024 Amazing Survey Platform. All rights reserved.</p>
    </footer>

    <script>
        const progressCircles = document.querySelectorAll('.progress-circle');
        const questionCards = document.querySelectorAll('.question-card');
        const prevButton = document.getElementById('prev-btn');
        const nextButton = document.getElementById('next-btn');
        const submitButton = document.getElementById('submit-btn');
        let currentQuestion = 1;

        function updateProgress() {
            progressCircles.forEach((circle, index) => {
                circle.classList.remove('active');
                if (index + 1 <= currentQuestion) {
                    circle.classList.add('active');
                }
            });

            questionCards.forEach(card => {
                card.classList.remove('active');
            });
            document.querySelector(`.question-card[data-question="${currentQuestion}"]`).classList.add('active');

            if (currentQuestion === 1) {
                prevButton.classList.add('hidden');
            } else {
                prevButton.classList.remove('hidden');
            }

            if (currentQuestion === questionCards.length) {
                nextButton.classList.add('hidden');
                submitButton.classList.remove('hidden');
            } else {
                nextButton.classList.remove('hidden');
                submitButton.classList.add('hidden');
            }
        }

        nextButton.addEventListener('click', () => {
            if (currentQuestion < questionCards.length) {
                currentQuestion++;
                updateProgress();
            }
        });

        prevButton.addEventListener('click', () => {
            if (currentQuestion > 1) {
                currentQuestion--;
                updateProgress();
            }
        });

        submitButton.addEventListener('click', () => {
            alert('Survey submitted!');
        });

        updateProgress();

        document.querySelectorAll('.radio-label').forEach(label => {
            label.addEventListener('click', () => {
                const radio = label.previousElementSibling;
                radio.checked = true;
                label.parentElement.parentElement.querySelectorAll('.radio-label').forEach(otherLabel => {
                    otherLabel.classList.remove('bg-orange-100', 'border-orange-200', 'bg-orange-500', 'text-white', 'border-orange-500');
                    otherLabel.classList.add('bg-gray-100', 'border-transparent');
                });
                label.classList.remove('bg-gray-100', 'border-transparent', 'hover:bg-orange-100', 'hover:border-orange-200');
                label.classList.add('bg-orange-500', 'text-white', 'border-orange-500');
            });
        });
    </script>
</body>
</html>
