            background-color: #3b82f6;
            color: white;
            padding: 0.75rem 1.5rem;
            border-radius: 0.375rem;
            font-weight: 700;
            transition: background-color 0.2s ease-in-out;
        }
        .btn-primary:hover {
            background-color: #2563eb;
        }
        .btn-secondary {
            background-color: white;
            color: #374151;
            border: 1px solid #d1d5db;
            padding: 0.75rem 1.5rem;
            border-radius: 0.375rem;
            font-weight: 700;
            transition: background-color 0.2s ease-in-out, border-color 0.2s ease-in-out, color 0.2s ease-in-out;
        }
        .btn-secondary:hover {
            background-color: #f3f4f6;
            border-color: #9ca3af;
        }
        .progress-bar-container {
            display: flex;
            justify-content: space-between;
            margin-bottom: 2rem;
        }
        .progress-step {
            flex-grow: 1;
            text-align: center;
            position: relative;
            padding-bottom: 1.5rem;
        }
        .progress-step:not(:last-child)::after {
            content: '';
            position: absolute;
            top: 0.75rem;
            left: 50%;
            width: 50%;
            height: 0.25rem;
            transform: translateX(-50%);
            background-color: #d1d5db;
            z-index: 1;
        }
        .progress-step:not(:first-child)::before {
            content: '';
            position: absolute;
            top: 0.75rem;
            right: 50%;
            width: 50%;
            height: 0.25rem;
            transform: translateX(50%);
            background-color: #d1d5db;
            z-index: 1;
        }
        .progress-step-circle {
            width: 1.5rem;
            height: 1.5rem;
            border-radius: 50%;
            background-color: #d1d5db;
            border: 0.25rem solid white;
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 2;
            position: relative;
        }
        .progress-step-text {
            position: absolute;
            bottom: 0;
            left: 50%;
            transform: translateX(-50%);
            white-space: nowrap;
            color: #4b5563;
        }
        .progress-active .progress-step-circle {
            background-color: #3b82f6;
        }
        .progress-active .progress-step-text {
            color: #3b82f6;
        }
        .step-content {
            opacity: 1;
            transform: translateY(0);
            transition: opacity 0.3s ease-in-out, transform 0.3s ease-in-out;
        }
        .step-content.fade-out {
            opacity: 0;
            transform: translateY(-20px);
        }
    </style>
</head>
