    <script>
        lucide.createIcons();

        const steps = document.querySelectorAll('.step');
        const progressSteps = document.querySelectorAll('.progress-step');
        const nextButtons = document.querySelectorAll('.next-step');
        const prevButtons = document.querySelectorAll('.prev-step');
        const form = document.getElementById('registrationForm');
        let currentStep = 1;

        function updateProgress() {
            progressSteps.forEach((step, index) => {
                if (index < currentStep) {
                    step.classList.add('progress-active');
                    step.classList.remove('progress-inactive');
                } else {
                    step.classList.remove('progress-active');
                    step.classList.add('progress-inactive');
                }
            });
        }

        function showStep(stepNumber) {
            steps.forEach(step => {
                step.classList.remove('step-active');
                step.classList.add('step-inactive');
                const content = step.querySelector('.step-content');
                if (content) {
                    content.classList.add('fade-out');
                    setTimeout(() => {
                        content.classList.remove('fade-out');
                    }, 300);
                }
            });

            const stepToShow = document.getElementById(`step${stepNumber}`);
            if (stepToShow) {
                stepToShow.classList.remove('step-inactive');
                stepToShow.classList.add('step-active');
            }
        }

        nextButtons.forEach(button => {
            button.addEventListener('click', () => {
                const nextStep = parseInt(button.dataset.step);
                if (nextStep <= steps.length) {
                    currentStep = nextStep;
                    updateProgress();
                    showStep(currentStep);
                }
            });
        });

        prevButtons.forEach(button => {
            button.addEventListener('click', () => {
                const prevStep = parseInt(button.dataset.step);
                if (prevStep >= 1) {
                    currentStep = prevStep;
                    updateProgress();
                    showStep(currentStep);
                }
            });
        });

        form.addEventListener('submit', function(event) {
            event.preventDefault();
            const formData = new FormData(form);
            let confirmationHTML = '<h3>Registration Details:</h3><ul>';
            for (let pair of formData.entries()) {
                confirmationHTML += `<li><strong>${pair[0]}:</strong> ${pair[1]}</li>`;
            }
            confirmationHTML += '</ul><p>Thank you for registering!</p>';
            document.getElementById('confirmationDetails').innerHTML = confirmationHTML;
            currentStep = steps.length;
            updateProgress();
            showStep(currentStep);
        });
    </script>
</body>
</html>
