    <script>
        const sourceLanguageButton = document.getElementById('language-menu-button-source');
        const targetLanguageButton = document.getElementById('language-menu-button-target');
        const sourceDropdown = document.getElementById('language-dropdown-source');
        const targetDropdown = document.getElementById('language-dropdown-target');
        let currentSourceLanguage = 'Detect Language';
        let currentTargetLanguage = 'Translate To';

        sourceLanguageButton.addEventListener('click', () => {
            targetDropdown.classList.add('hidden');
            sourceDropdown.classList.toggle('hidden');
        });

        targetLanguageButton.addEventListener('click', () => {
            sourceDropdown.classList.add('hidden');
            targetDropdown.classList.toggle('hidden');
        });

        function setSourceLanguage(language) {
            currentSourceLanguage = language;
            sourceLanguageButton.innerHTML = `<i class="fa-solid fa-globe text-gray-400 mr-2"></i>${language} <i class="fa-solid fa-chevron-down ml-2 text-gray-400"></i>`;
            sourceDropdown.classList.add('hidden');
        }

        function setTargetLanguage(language) {
            currentTargetLanguage = language;
            targetLanguageButton.innerHTML = `<i class="fa-solid fa-flag text-gray-400 mr-2"></i>${language} <i class="fa-solid fa-chevron-down ml-2 text-gray-400"></i>`;
            targetDropdown.classList.add('hidden');
        }

        function translateText() {
            const textToTranslate = document.getElementById('sourceText').value;
            if (!textToTranslate.trim()) {
                alert('Please enter text to translate.');
                return;
            }
            document.getElementById('translatedText').value = `Translating "${textToTranslate}" from ${currentSourceLanguage} to ${currentTargetLanguage}... (Placeholder)`;
            gsap.fromTo('#translatedText', { opacity: 0 }, { opacity: 1, duration: 0.5, delay: 0.3 });
        }

        gsap.from('.animate-slide-up', {
            y: 30,
            opacity: 0,
            duration: 0.7,
            stagger: 0.1,
            ease: 'power2.out'
        });
    </script>

</body>
</html>
