    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Roboto Mono', monospace;
        }
        .toggle-container {
            @apply relative inline-block w-14 h-8 rounded-full bg-gray-700 transition-colors duration-200 ease-in-out;
        }
        .toggle-container.active {
            @apply bg-green-500;
        }
        .toggle-slider {
            @apply absolute top-0.5 left-0.5 w-7 h-7 rounded-full bg-gray-900 shadow-md transform transition-transform duration-200 ease-in-out;
        }
        .toggle-container.active .toggle-slider {
            @apply translate-x-6 bg-gray-900;
        }
        .device-card {
            @apply bg-gray-800 rounded-2xl shadow-lg overflow-hidden relative;
        }
        .device-card-overlay {
            @apply absolute inset-0 bg-gradient-to-b from-transparent to-gray-900 opacity-0 hover:opacity-80 transition-opacity duration-300;
        }
        .device-card:hover .device-card-overlay {
            opacity: 80%;
        }
        .device-icon {
            @apply text-4xl text-green-400 mb-4;
        }
        .device-title {
            @apply text-white text-xl font-bold mb-2;
        }
        .device-status {
            @apply text-gray-400 text-sm;
        }
        .futuristic-button {
            @apply bg-green-500 hover:bg-green-600 text-gray-900 font-bold py-2 px-4 rounded-full transition-colors duration-300;
        }
        .futuristic-input {
            @apply bg-gray-700 text-white rounded-md px-4 py-2 focus:outline-none focus:ring-2 focus:ring-green-500;
        }
        .neon-text {
            text-shadow: 0 0 5px rgba(52, 211, 168, 0.8), 0 0 10px rgba(52, 211, 168, 0.8), 0 0 15px rgba(52, 211, 168, 0.8);
        }
        .layer-depth {
            box-shadow: 0 0 30px rgba(0, 0, 0, 0.7);
        }
        .loading-spinner {
            border: 4px solid rgba(255, 255, 255, 0.3);
            border-top: 4px solid #fff;
            border-radius: 50%;
            width: 30px;
            height: 30px;
            animation: spin 1s linear infinite;
        }
        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
    </style>
</head>
