<!DOCTYPE html>
<html lang="en" class="bg-black">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Productivity Timer</title>
    <link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="REMOVED-SHA-FROM-HERE-FOR-INSTRUCTIONS" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Space Grotesk', sans-serif;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }
        .timer-container {
            perspective: 1000px;
        }
        .timer-circle {
            transform-style: preserve-3d;
        }
        .timer-circle::before,
        .timer-circle::after {
            content: '';
            position: absolute;
            border-radius: 50%;
            inset: 0;
        }
        .timer-circle::before {
            border: 3px solid rgba(255, 255, 255, 0.1);
            z-index: -1;
        }
        .timer-circle::after {
            border-top: 6px solid #00ff00;
            clip-path: polygon(50% 50%, 50% 0, 0 50%, 50% 50%);
            transform: rotateZ(-90deg);
            animation: timer-progress linear forwards;
            animation-play-state: paused;
        }
        @keyframes timer-progress {
            to {
                transform: rotateZ(270deg);
            }
        }
        .timer-running .timer-circle::after {
            animation-play-state: running;
        }
        .btn-neon {
            box-shadow: 0 0 0.5rem #00ff00, 0 0 1rem #00ff00;
        }
        .btn-neon:hover {
            box-shadow: 0 0 0.75rem #00ff00, 0 0 1.5rem #00ff00;
        }
        .digit-flicker {
            animation: digit-flicker-animation 0.3s steps(2, end) infinite;
        }

        @keyframes digit-flicker-animation {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.7; }
        }
        .pulse-neon {
            animation: pulse-neon-animation 1.5s ease-in-out infinite;
        }

        @keyframes pulse-neon-animation {
            0% { box-shadow: 0 0 0.5rem #00ff00, 0 0 1rem #00ff00; }
            50% { box-shadow: 0 0 0.75rem #00ff00, 0 0 1.5rem #00ff00, 0 0 0.25rem #00ff00 inset; }
            100% { box-shadow: 0 0 0.5rem #00ff00, 0 0 1rem #00ff00; }
        }
    </style>
</head>
<body class="text-white">
    <div class="min-h-screen flex flex-col justify-center items-center p-8">
        <div class="text-center mb-16">
            <h1 class="text-4xl font-bold mb-2">Productivity Timer</h1>
            <p class="text-gray-300">Focus and Achieve</p>
        </div>

        <div class="timer-container relative mb-12 w-80 h-80 md:w-96 md:h-96">
            <div class="timer-circle absolute inset-0 flex items-center justify-center">
                <div id="timeDisplay" class="text-6xl md:text-8xl font-bold tracking-tight">25:00</div>
            </div>
        </div>

        <div class="flex space-x-6">
            <button id="startButton" class="group relative h-12 w-24 overflow-hidden rounded-lg bg-green-500 text-white btn-neon transition-all hover:bg-green-600 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2">
                <span class="absolute inset-0 flex items-center justify-center px-5 text-white transition-opacity duration-300 group-hover:opacity-0"><i class="fa-solid fa-play"></i></span>
                <span class="absolute inset-0 opacity-0 flex items-center justify-center px-5 text-white transition-opacity duration-300 group-hover:opacity-100">Start</span>
            </button>
            <button id="stopButton" class="group relative h-12 w-24 overflow-hidden rounded-lg bg-red-500 text-white btn-neon transition-all hover:bg-red-600 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2">
                <span class="absolute inset-0 flex items-center justify-center px-5 text-white transition-opacity duration-300 group-hover:opacity-0"><i class="fa-solid fa-stop"></i></span>
                <span class="absolute inset-0 opacity-0 flex items-center justify-center px-5 text-white transition-opacity duration-300 group-hover:opacity-100">Stop</span>
            </button>
            <button id="resetButton" class="group relative h-12 w-24 overflow-hidden rounded-lg bg-gray-700 text-white btn-neon transition-all hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-700 focus:ring-offset-2">
                <span class="absolute inset-0 flex items-center justify-center px-5 text-white transition-opacity duration-300 group-hover:opacity-0"><i class="fa-solid fa-rotate-right"></i></span>
                <span class="absolute inset-0 opacity-0 flex items-center justify-center px-5 text-white transition-opacity duration-300 group-hover:opacity-100">Reset</span>
            </button>
        </div>
    </div>

    <script>
        const timeDisplay = document.getElementById('timeDisplay');
        const startButton = document.getElementById('startButton');
        const stopButton = document.getElementById('stopButton');
        const resetButton = document.getElementById('resetButton');
        const timerContainer = document.querySelector('.timer-container');

        let timerInterval;
        let timeLeft = 25 * 60;
        let isRunning = false;

        function updateDisplay() {
            const minutes = Math.floor(timeLeft / 60);
            const seconds = timeLeft % 60;
            timeDisplay.textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
            timerContainer.style.setProperty('--timer-progress-rotation', `${(timeLeft / (25 * 60)) * 360}deg`);
        }

        function startTimer() {
            if (!isRunning) {
                isRunning = true;
                timerContainer.classList.add('timer-running');
                timerInterval = setInterval(() => {
                    if (timeLeft > 0) {
                        timeLeft--;
                        updateDisplay();
                        if (timeLeft <= 5) {
                            timeDisplay.classList.add('digit-flicker');
                        }
                    } else {
                        stopTimer();
                        timeDisplay.classList.remove('digit-flicker');
                        timeDisplay.classList.add('pulse-neon');
                    }
                }, 1000);
            }
        }

        function stopTimer() {
            isRunning = false;
            timerContainer.classList.remove('timer-running');
            clearInterval(timerInterval);
            timeDisplay.classList.remove('digit-flicker');
        }

        function resetTimer() {
            stopTimer();
            timeLeft = 25 * 60;
            updateDisplay();
            timeDisplay.classList.remove('pulse-neon');
        }

        startButton.addEventListener('click', startTimer);
        stopButton.addEventListener('click', stopTimer);
        resetButton.addEventListener('click', resetTimer);

        updateDisplay();
    </script>
</body>
</html>
