        lucide.createIcons();

        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        gsap.registerPlugin(ScrollTrigger);

        gsap.from('.hero-section .container > *', {
            y: 60,
            opacity: 0,
            duration: 1.5,
            stagger: 0.2,
            ease: 'power3.out'
        });

        gsap.from('.form-section h2, .form-section form > div', {
            scrollTrigger: {
                trigger: '.form-section',
                start: 'top 80%',
                toggleActions: 'play none none none'
            },
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.15,
            ease: 'power2.out'
        });

        gsap.from('.timeline-section h2', {
            scrollTrigger: {
                trigger: '.timeline-section',
                start: 'top 80%',
                toggleActions: 'play none none none'
            },
            y: 50,
            opacity: 0,
            duration: 1,
            ease: 'power2.out'
        });

        gsap.from('.timeline-item', {
            scrollTrigger: {
                trigger: '.timeline-section',
                start: 'top 60%',
                toggleActions: 'play none none none',
                stagger: 0.2
            },
            opacity: 0,
            x: -50,
            duration: 0.8,
            ease: 'power2.out'
        });

        gsap.from('.timeline-item:nth-child(even)', {
            scrollTrigger: {
                trigger: '.timeline-section',
                start: 'top 60%',
                toggleActions: 'play none none none',
                stagger: 0.2
            },
            opacity: 0,
            x: 50,
            duration: 0.8,
            ease: 'power2.out'
        });

        gsap.from('.footer-section > div > *', {
            scrollTrigger: {
                trigger: '.footer-section',
                start: 'top 80%',
                toggleActions: 'play none none none'
            },
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.2,
            ease: 'power2.out'
        });

        const parallaxBg = document.querySelector('.parallax-bg');
        if(parallaxBg) {
            gsap.to(parallaxBg, {
                scrollTrigger: {
                    trigger: '.hero-section',
                    start: 'top top',
                    end: 'bottom top',
                    scrub: 0.5
                },
                yPercent: -30,
                ease: 'none'
            });
        }

        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();

                document.querySelector(this.getAttribute('href')).scrollIntoView({
                    behavior: 'smooth'
                });

                if (mobileMenu.classList.contains('hidden') === false) {
                    mobileMenu.classList.add('hidden');
                }
            });
        });

    </script>
</body>
</html>
