    <script>
        const sidebarMenuItems = document.querySelectorAll('.sidebar-menu-item');
        const sidebarSubmenus = document.querySelectorAll('.sidebar-submenu');
        const customizeMenuHeaders = document.querySelectorAll('.customize-menu-header');
        const customizeMenuContents = document.querySelectorAll('.customize-menu-content');
        const colorSwatches = document.querySelectorAll('.color-swatch');
        const fontSelect = document.querySelector('.font-select');
        const fontSizeRange = document.querySelector('.input-range');
        const transitionSelect = document.getElementById('transition-select');
        const previewFrameContent = document.getElementById('preview-frame-content');
        const portfolioGrid = document.getElementById('portfolio-grid');
        let draggedItem = null;

        sidebarMenuItems.forEach(item => {
            item.addEventListener('click', function() {
                sidebarMenuItems.forEach(mi => mi.classList.remove('active'));
                this.classList.add('active');

                const target = this.getAttribute('data-target');
                if (target === 'design') {
                    const submenu = this.nextElementSibling;
                    submenu.classList.toggle('hidden');
                } else {
                    sidebarSubmenus.forEach(sm => sm.classList.add('hidden'));
                }
            });
        });

        customizeMenuHeaders.forEach(header => {
            header.addEventListener('click', function() {
                const targetId = this.getAttribute('data-menu-target');
                const content = document.getElementById(targetId);
                content.classList.toggle('collapsed');
            });
        });

        colorSwatches.forEach(swatch => {
            swatch.addEventListener('click', function() {
                colorSwatches.forEach(s => s.classList.remove('selected'));
                this.classList.add('selected');
                const selectedColor = this.getAttribute('data-color');
                document.body.style.setProperty('--primary-color', selectedColor);
            });
        });

        fontSelect.addEventListener('change', function() {
            document.body.style.fontFamily = this.value;
        });

        fontSizeRange.addEventListener('input', function() {
            document.body.style.fontSize = `${this.value}px`;
        });

        transitionSelect.addEventListener('change', function() {
            const transition = this.value;
            previewFrameContent.className = 'preview-frame';
            if (transition) {
                previewFrameContent.classList.add(transition);
                setTimeout(() => {
                    previewFrameContent.className = 'preview-frame fade-in';
                }, 500);
            } else {
                previewFrameContent.classList.add('fade-in');
            }
        });

        portfolioGrid.addEventListener('dragstart', (event) => {
            draggedItem = event.target.closest('.draggable');
            event.dataTransfer.setData('text/plain', null);
            setTimeout(() => {
                draggedItem.classList.add('dragging');
            }, 0);
        });

        portfolioGrid.addEventListener('dragend', (event) => {
            draggedItem.classList.remove('dragging');
            draggedItem = null;
        });

        portfolioGrid.addEventListener('dragover', (event) => {
            event.preventDefault();
            const afterElement = getDragAfterElement(portfolioGrid, event.clientY);
            const draggable = document.querySelector('.dragging');
            if (afterElement == null) {
                portfolioGrid.appendChild(draggable);
            } else {
                portfolioGrid.insertBefore(draggable, afterElement);
            }
        });

        function getDragAfterElement(container, y) {
            const draggableElements = [...container.querySelectorAll('.draggable:not(.dragging)')];

            return draggableElements.reduce((closest, child) => {
                const box = child.getBoundingClientRect();
                const offset = y - box.top - box.height / 2;
                if (offset < 0 && offset > closest.offset) {
                    return { offset: offset, element: child };
                } else {
                    return closest;
                }
            }, { offset: Number.NEGATIVE_INFINITY }).element;
        }
    </script>
</body>
</html>
