    <script>
        lucide.createIcons();

        document.addEventListener('DOMContentLoaded', () => {
            document.querySelectorAll('.star-rating--stars').forEach(starsElement => {
                const rating = parseFloat(starsElement.style.getPropertyValue('--rating'));
                const percentage = (rating / 5) * 100;
                starsElement.style.setProperty('--percent', percentage + '%');
                starsElement.nextElementSibling.style.width = percentage + '%';
            });
        });

        const mobileMenuButton = document.querySelector('.mobile-menu-button');
        const mobileMenu = document.querySelector('.mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });
    </script>
</body>
</html>
