    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            const filterButtons = document.querySelectorAll('.filter-button');
            const recipeCards = Array.from(document.querySelectorAll('.recipe-card'));

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const recipesData = [
                { category: 'dinner', cuisine: 'italian', dietary: 'all', prepTime: 25, element: recipeCards[0] },
                { category: 'lunch', cuisine: 'mexican', dietary: 'all', prepTime: 40, element: recipeCards[1] },
                { category: 'dessert', cuisine: 'american', dietary: 'all', prepTime: 75, element: recipeCards[2] },
                { category: 'breakfast', cuisine: 'american', dietary: 'all', prepTime: 15, element: recipeCards[3] },
                { category: 'dinner', cuisine: 'american', dietary: 'all', prepTime: 35, element: recipeCards[4] },
                { category: 'dessert', cuisine: 'all', dietary: 'all', prepTime: 10, element: recipeCards[5] },
            ];

            let filters = {
                category: 'all',
                cuisine: 'all',
                dietary: 'all',
                prepTime: 'all'
            };

            function applyFilters() {
                recipesData.forEach(recipe => {
                    let showRecipe = true;

                    if (filters.category !== 'all' && recipe.category !== filters.category) {
                        showRecipe = false;
                    }
                    if (filters.cuisine !== 'all' && recipe.cuisine !== filters.cuisine) {
                        showRecipe = false;
                    }
                    if (filters.dietary !== 'all' && recipe.dietary !== filters.dietary) {
                        showRecipe = false;
                    }
                    if (filters['prepTime'] !== 'all') {
                        if (filters['prepTime'] === '30' && recipe.prepTime > 30) {
                            showRecipe = false;
                        } else if (filters['prepTime'] === '60' && recipe.prepTime > 60) {
                            showRecipe = false;
                        } else if (filters['prepTime'] === '61' && recipe.prepTime <= 60) {
                            showRecipe = false;
                        }
                    }

                    recipe.element.style.display = showRecipe ? 'block' : 'none';
                });
            }

            filterButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const filterType = this.dataset.filter;
                    const filterValue = this.dataset.value;

                    filters[filterType] = filterValue;
                    applyFilters();

                    filterButtons.forEach(btn => {
                        if (btn.dataset.filter === filterType) {
                            btn.classList.remove('filter-active');
                        }
                    });
                    if (filterValue !== 'all') {
                        this.classList.add('filter-active');
                    } else {
                        filterButtons.forEach(btn => {
                            if (btn.dataset.filter === filterType && btn.dataset.value === 'all') {
                                btn.classList.add('filter-active');
                            }
                        });
                    }
                });
            });

             filterButtons.forEach(btn => {
                if (btn.dataset.value === 'all') {
                    btn.classList.add('filter-active');
                }
            });

            window.addEventListener('scroll', function() {
                const parallaxBg = document.querySelector('.parallax-bg');
                let scrollPosition = window.pageYOffset;
                parallaxBg.style.transform = `translateZ(-1px) scale(1.2) translateY(${scrollPosition * 0.3}px)`;
            });
        });
    </script>

</body>
</html>
