                        </button>
                        <button class="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline">
                            <i class="fas fa-arrow-down"></i> Close
                        </button>
                    </div>
                </div>
            </div>

        </main>
    </div>

    <script>
        function toggleControlPanel(deviceId) {
            const controlPanel = document.getElementById(`control-panel-${deviceId}`);
            controlPanel.classList.toggle('expanded');
        }

        function updateSliderValue(sliderId, valueId, unit = '%') {
            const slider = document.getElementById(sliderId);
            const valueSpan = document.getElementById(valueId);
            valueSpan.textContent = slider.value + unit;
        }

        function toggleLockButton(doorId) {
            const lockButton = document.getElementById(`${doorId}-lock-button`);
            const unlockButton = document.getElementById(`${doorId}-unlock-button`);
            lockButton.classList.toggle('hidden');
            unlockButton.classList.toggle('hidden');

            const doorStatus = document.getElementById(`${doorId}-status`);
            if (!lockButton.classList.contains('hidden')) {
                doorStatus.classList.remove('status-online');
                doorStatus.classList.add('status-offline');
            } else {
                doorStatus.classList.remove('status-offline');
                doorStatus.classList.add('status-online');
            }
        }
    </script>
</body>
</html>
