        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        gsap.registerPlugin(ScrollTrigger);

        gsap.from('.hero-section .text-center > *', {
            y: 60,
            opacity: 0,
            duration: 1.2,
            stagger: 0.2,
            ease: 'power3.out'
        });

        gsap.from('.float-element', {
            y: 40,
            opacity: 0,
            duration: 1.5,
            delay: 0.5,
            ease: 'power3.out'
        });

        gsap.utils.toArray('section:not(.hero-section)').forEach(section => {
            gsap.from(section.querySelectorAll('.container > *'), {
                y: 50,
                opacity: 0,
                duration: 1,
                stagger: 0.15,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: section,
                    start: 'top 70%',
                    toggleActions: 'play none none reverse'
                }
            });
        });
    </script>
</body>
</html>
