            </div>

            <div class="modal-content py-4 text-left px-6">

                <div class="flex justify-between items-center pb-3">
                    <p class="text-2xl font-bold">Job Details</p>
                    <div class="modal-close cursor-pointer z-50">
                        <svg class="fill-current text-black hover:text-gray-dark" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 18 18">
                            <path fill="currentColor" d="M14.53 4.53l-1.06-1.06L9 7.94 4.53 3.47 3.47 4.53 7.94 9l-4.47 4.47 1.06 1.06L9 10.06l4.47 4.47 1.06-1.06L10.06 9z"></path>
                        </svg>
                    </div>
                </div>

                <div id="job-modal-content">
                    <h3 id="modal-job-title" class="text-xl font-bold mb-2 text-gray-800"></h3>
                    <p id="modal-company" class="text-gray-700 text-base mb-2"></p>
                    <p id="modal-location" class="text-gray-600 text-sm mb-4"><i class="fa-solid fa-location-dot"></i> </p>
                    <p id="modal-salary" class="text-gray-900 font-semibold mb-4"></p>
                    <img id="modal-company-logo" src="" alt="Company Logo" class="w-32 h-32 object-contain mb-4">
                    <p id="modal-description" class="text-gray-800"></p>
                </div>

                <div class="flex justify-end pt-2">
                    <button class="modal-close px-4 bg-gray-400 p-3 rounded-lg text-black hover:bg-gray-300">Close</button>
                    <button class="ml-3 px-4 bg-blue-500 p-3 rounded-lg text-white hover:bg-blue-600">Apply Now</button>
                </div>
            </div>
        </div>
