    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const modal = document.getElementById('jobModal');
            const modalContent = document.getElementById('job-modal-content');
            const modalJobTitle = document.getElementById('modal-job-title');
            const modalCompany = document.getElementById('modal-company');
            const modalLocation = document.getElementById('modal-location');
            const modalSalary = document.getElementById('modal-salary');
            const modalCompanyLogo = document.getElementById('modal-company-logo');
            const modalDescription = document.getElementById('modal-description');
            const applyButtons = document.querySelectorAll('.apply-button');
            const modalCloseButtons = document.querySelectorAll('.modal-close');
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            applyButtons.forEach(button => {
                button.addEventListener('click', function(event) {
                    event.preventDefault();
                    let jobId = this.dataset.jobId;
                    if (jobId === '1') {
                        modalJobTitle.textContent = "Software Engineer";
                        modalCompany.textContent = "Tech Company Inc.";
                        modalLocation.textContent = "San Francisco, CA";
                        modalSalary.textContent = "$120,000 - $150,000";
                        modalCompanyLogo.src = "https://picsum.photos/200/300?random=1";
                        modalDescription.textContent = "We are looking for a talented software engineer to join our team...";
                    } else if (jobId === '2') {
                        modalJobTitle.textContent = "Data Scientist";
                        modalCompany.textContent = "Analytics Corp.";
                        modalLocation.textContent = "New York, NY";
                        modalSalary.textContent = "$110,000 - $140,000";
                        modalCompanyLogo.src = "https://picsum.photos/200/300?random=2";
                        modalDescription.textContent = "Join our data science team and help us analyze complex datasets...";
                    } else if (jobId === '3') {
                        modalJobTitle.textContent = "UX Designer";
                        modalCompany.textContent = "Design Solutions Ltd.";
                        modalLocation.textContent = "London, UK";
                        modalSalary.textContent = "$90,000 - $120,000";
                        modalCompanyLogo.src = "https://picsum.photos/200/300?random=3";
                        modalDescription.textContent = "We need a creative UX designer to enhance our user experience...";
                    } else if (jobId === '4') {
                        modalJobTitle.textContent = "Project Manager";
                        modalCompany.textContent = "Global Enterprises";
                        modalLocation.textContent = "Remote";
                        modalSalary.textContent = "$100,000 - $130,000";
                        modalCompanyLogo.src = "https://picsum.photos/200/300?random=4";
                        modalDescription.textContent = "Seeking an experienced project manager to oversee key projects...";
                    } else if (jobId === '5') {
                        modalJobTitle.textContent = "Marketing Manager";
                        modalCompany.textContent = "Creative Agency Co.";
                        modalLocation.textContent = "Chicago, IL";
                        modalSalary.textContent = "$95,000 - $125,000";
                        modalCompanyLogo.src = "https://picsum.photos/200/300?random=5";
                        modalDescription.textContent = "Looking for a dynamic marketing manager to drive our brand growth...";
                    } else if (jobId === '6') {
                        modalJobTitle.textContent = "Financial Analyst";
                        modalCompany.textContent = "Finance Group Inc.";
                        modalLocation.textContent = "New York, NY";
                        modalSalary.textContent = "$85,000 - $115,000";
                        modalCompanyLogo.src = "https://picsum.photos/200/300?random=6";
                        modalDescription.textContent = "Seeking a detail-oriented financial analyst for market research...";
                    }

                    modal.classList.remove('opacity-0', 'pointer-events-none');
                    document.body.classList.add('overflow-hidden');
                });
            });

            modalCloseButtons.forEach(button => {
                button.addEventListener('click', function() {
                    modal.classList.add('opacity-0', 'pointer-events-none');
                    document.body.classList.remove('overflow-hidden');
                });
            });

            document.addEventListener('keydown', function(event) {
                if (event.key === 'Escape') {
                    modal.classList.add('opacity-0', 'pointer-events-none');
                    document.body.classList.remove('overflow-hidden');
                }
            });

            mobileMenuButton.addEventListener('click', function() {
                mobileMenu.classList.toggle('hidden');
            });
        });
    </script>

</body>
</html>
