<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Interactive Resume</title>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>
    <style>
        body {
            font-family: 'Poppins', sans-serif;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: #1e293b;
            opacity: 0.9;
        }
        .vibrant-color {
            color: #2dd4cf;
        }
        .skill-bar {
            position: relative;
            background-color: #4b5563;
            height: 10px;
            border-radius: 5px;
            overflow: hidden;
        }
        .skill-bar-fill {
            background-color: #2dd4cf;
            height: 100%;
            border-radius: 5px;
            width: 0%;
            transition: width 1s ease-out;
        }
        .timeline-container {
            position: relative;
            padding: 2rem 0;
        }

        .timeline-container::before {
            content: '';
            position: absolute;
            top: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 2px;
            background-color: #4b5563;
            height: 100%;
        }

        .timeline-item {
            margin-bottom: 2rem;
            position: relative;
            width: 50%;
        }

        .timeline-item:nth-child(odd) {
            left: 0;
            padding-right: 2rem;
        }

        .timeline-item:nth-child(even) {
            left: 50%;
            padding-left: 2rem;
        }

        .timeline-item-content {
            background-color: #1e293b;
            color: white;
            padding: 1.5rem;
            border-radius: 0.5rem;
            box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.1);
        }

        .timeline-item-content::before {
            content: '';
            position: absolute;
            top: 1rem;
            width: 0;
            height: 0;
            border-top: 1rem solid transparent;
            border-bottom: 1rem solid transparent;
        }

        .timeline-item:nth-child(odd) .timeline-item-content::before {
            right: -1rem;
            border-left: 1rem solid #1e293b;
        }

        .timeline-item:nth-child(even) .timeline-item-content::before {
            left: -1rem;
            border-right: 1rem solid #1e293b;
        }

        .timeline-item-date {
            position: absolute;
            top: 0;
            transform: translateY(-50%);
            background-color: #2dd4cf;
            color: #1e293b;
            padding: 0.5rem 1rem;
            border-radius: 0.375rem;
        }

        .timeline-item:nth-child(odd) .timeline-item-date {
            right: 0;
        }

        .timeline-item:nth-child(even) .timeline-item-date {
            left: 0;
        }
        .project-card {
            transition: transform 0.3s ease-in-out;
        }

        .project-card:hover {
            transform: scale(1.05);
        }

    </style>
</head>
<body class="bg-gray-100 text-gray-300">

