    <script>
        document.addEventListener('DOMContentLoaded', function() {
            gsap.registerPlugin(ScrollTrigger);

            const skillBars = gsap.utils.toArray('.skill-bar-fill');
            skillBars.forEach(bar => {
                let percentage = bar.dataset.skillPercentage;
                gsap.to(bar, {
                    width: percentage + '%',
                    duration: 1.5,
                    ease: 'power3.out',
                    scrollTrigger: {
                        trigger: bar.closest('div'),
                        start: 'top bottom',
                        onEnter: () => { if (!bar.classList.contains('animated')) { bar.classList.add('animated'); } },
                        once: true
                    }
                });
            });

            gsap.from('.hero-section .container > *', {
                y: 30,
                opacity: 0,
                duration: 1,
                stagger: 0.2,
                ease: 'power2.out'
            });

            gsap.from('.timeline-item', {
                opacity: 0,
                y: 50,
                stagger: 0.3,
                duration: 1,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: '.timeline-container',
                    start: 'top 80%',
                }
            });

            gsap.from('.project-card', {
                opacity: 0,
                y: 50,
                stagger: 0.2,
                duration: 0.8,
                ease: 'power2.out',
                scrollTrigger: {
                    trigger: '#projects',
                    start: 'top 80%',
                }
            });
        });
    </script>

</body>
</html>
