<!DOCTYPE html>
<html lang="en" class="antialiased">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Microblogging Platform</title>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;700&family=Montserrat:wght@700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'DM Sans', sans-serif;
            background-color: #f9fafb;
            color: #1e293b;
        }
        .montserrat {
            font-family: 'Montserrat', sans-serif;
        }
        .like-button.liked {
            color: #f472b6;
        }
        .retweet-button.retweeted {
            color: #3b82f6;
        }
        .comment-section {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-out;
        }
        .comment-section.expanded {
            max-height: 500px;
        }
        @keyframes like-pop {
            0% { transform: scale(1); }
            50% { transform: scale(1.2); }
            100% { transform: scale(1); }
        }
        .like-pop-animation {
            animation: like-pop 0.3s ease-in-out;
        }
        @keyframes retweet-rotate {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
