    <script>
        function likePost(buttonElement) {
            const likeCountSpan = buttonElement.querySelector('.like-count');
            let likeCount = parseInt(likeCountSpan.textContent);
            const heartIcon = buttonElement.querySelector('i');

            if (buttonElement.classList.contains('liked')) {
                likeCount--;
                buttonElement.classList.remove('liked');
                heartIcon.classList.remove('fas');
                heartIcon.classList.add('far');
            } else {
                likeCount++;
                buttonElement.classList.add('liked');
                heartIcon.classList.remove('far');
                heartIcon.classList.add('fas');
                buttonElement.classList.add('like-pop-animation');
                setTimeout(() => {
                    buttonElement.classList.remove('like-pop-animation');
                }, 300);
            }
            likeCountSpan.textContent = likeCount;
        }

        function retweetPost(buttonElement) {
            const retweetCountSpan = buttonElement.querySelector('.retweet-count');
            let retweetCount = parseInt(retweetCountSpan.textContent);
            const retweetIcon = buttonElement.querySelector('i');

            if (buttonElement.classList.contains('retweeted')) {
                retweetCount--;
                buttonElement.classList.remove('retweeted');
            } else {
                retweetCount++;
                buttonElement.classList.add('retweeted');
                buttonElement.classList.add('retweet-rotate-animation');
                setTimeout(() => {
                    buttonElement.classList.remove('retweet-rotate-animation');
                }, 500);
            }
            retweetCountSpan.textContent = retweetCount;
        }

        function toggleComments(buttonElement) {
            const post = buttonElement.closest('.bg-white.rounded-lg.shadow-md.overflow-hidden');
            const commentSection = post.querySelector('.comment-section');
            commentSection.classList.toggle('expanded');
        }
    </script>
</body>
</html>
