    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const itineraryCards = document.getElementById('itinerary-cards');
            let draggedCard = null;

            itineraryCards.addEventListener('dragstart', (event) => {
                draggedCard = event.target.closest('.draggable-card');
                if (draggedCard) {
                    draggedCard.classList.add('dragging');
                    event.dataTransfer.setData('text/plain', null);
                }
            });

            itineraryCards.addEventListener('dragend', (event) => {
                if (draggedCard) {
                    draggedCard.classList.remove('dragging');
                    draggedCard = null;
                }
            });

            itineraryCards.addEventListener('dragover', (event) => {
                event.preventDefault();
                if (!draggedCard) return;
                const afterElement = getDragAfterElement(itineraryCards, event.clientY);
                if (afterElement == null) {
                    itineraryCards.appendChild(draggedCard);
                } else {
                    itineraryCards.insertBefore(draggedCard, afterElement);
                }
            });

            function getDragAfterElement(container, y) {
                const draggableElements = [...container.querySelectorAll('.draggable-card:not(.dragging)')];
                return draggableElements.reduce((closest, child) => {
                    const box = child.getBoundingClientRect();
                    const offset = y - box.top - box.height / 2;
                    if (offset < 0 && offset > closest.offset) {
                        return { offset: offset, element: child };
                    } else {
                        return closest;
                    }
                }, { offset: Number.NEGATIVE_INFINITY }).element;
            }
        });
    </script>
</body>
