    <script>
        function toggleDetail(detailId) {
            const detailView = document.getElementById(detailId);
            detailView.classList.toggle('open');
        }

        const tempChartCtx = document.getElementById('temperatureChart').getContext('2d');
        const tempChart = new Chart(tempChartCtx, {
            type: 'line',
            data: {
                labels: ['Now', '1 AM', '2 AM', '3 AM', '4 AM', '5 AM'],
                datasets: [{
                    label: 'Temperature (°C)',
                    data: [25, 24, 23, 23, 22, 22],
                    borderColor: '#38BDF8',
                    borderWidth: 2,
                    fill: false
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: false
                    }
                },
                plugins: {
                    legend: {
                        display: false
                    }
                }
            }
        });

        const dailyForecastChartCtx = document.getElementById('dailyForecastChart').getContext('2d');
        const dailyForecastChart = new Chart(dailyForecastChartCtx, {
            type: 'bar',
            data: {
                labels: ['Today', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
                datasets: [{
                    label: 'Daily High (°C)',
                    data: [28, 26, 25, 27, 29, 30, 28],
                    backgroundColor: '#FACC15',
                },
                {
                    label: 'Daily Low (°C)',
                    data: [20, 19, 18, 19, 21, 22, 20],
                    backgroundColor: '#0EA5E9',
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: false
                    }
                },
                plugins: {
                    legend: {
                        display: false
                    }
                }
            }
        });

        gsap.utils.toArray('.weather-card').forEach(card => {
            gsap.from(card, {
                y: 50,
                opacity: 0,
                duration: 1,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: card,
                    start: "top 80%",
                    end: "top 20%",
                    toggleActions: "play none none reverse"
                }
            });
        });
    </script>
</body>
</html>
