    <style>
        body {
            font-family: 'Roboto Condensed', sans-serif;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }
        .bebas-neue {
            font-family: 'Bebas Neue', sans-serif;
        }
        .brush-stroke {
            position: absolute;
            background-color: #39FF14;
            opacity: 0.6;
            border-radius: 50%;
            filter: blur(10px);
            animation: pulse 3s infinite alternate;
        }
        .brush-stroke-1 {
            width: 150px;
            height: 30px;
            top: 10%;
            left: 15%;
        }
        .brush-stroke-2 {
            width: 80px;
            height: 80px;
            top: 40%;
            right: 10%;
        }
        .brush-stroke-3 {
            width: 120px;
            height: 40px;
            bottom: 20%;
            left: 30%;
        }
        @keyframes pulse {
            0% {
                transform: scale(1);
                opacity: 0.6;
            }
            100% {
                transform: scale(1.1);
                opacity: 0.8;
            }
        }
        .grid-art {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 2rem;
        }
        .grid-art-item {
            position: relative;
            overflow: hidden;
            border-radius: 0.5rem;
            transition: transform 0.3s ease-in-out;
        }
        .grid-art-item:hover {
            transform: scale(1.05);
        }
        .grid-art-item img {
            display: block;
            width: 100%;
            height: auto;
            aspect-ratio: 1 / 1;
            object-fit: cover;
            transition: opacity 0.3s ease-in-out;
        }
        .grid-art-item:hover img {
            opacity: 0.8;
        }
        .grid-art-item-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.7);
            color: #fff;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            opacity: 0;
            transition: opacity 0.3s ease-in-out;
        }
        .grid-art-item:hover .grid-art-item-overlay {
            opacity: 1;
        }
    </style>
</head>
