<script>
    lucide.createIcons();

    function createBarChart(canvasId, labels, data, label, color) {
        const ctx = document.getElementById(canvasId).getContext('2d');
        new Chart(ctx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [{
                    label: label,
                    data: data,
                    backgroundColor: color,
                    borderColor: color.replace('100', '500'),
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                },
                plugins: {
                    legend: {
                        display: false
                    }
                }
            }
        });
    }

    function createLineChart(canvasId, labels, dataSets) {
        const ctx = document.getElementById(canvasId).getContext('2d');
        const datasetsConfig = dataSets.map(set => ({
            label: set.label,
            data: set.data,
            borderColor: set.color,
            backgroundColor: set.color.replace('500', '100'),
            borderWidth: 2,
            tension: 0.4,
            fill: true
        }));

        new Chart(ctx, {
            type: 'line',
            data: {
                labels: labels,
                datasets: datasetsConfig
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                },
                plugins: {
                    legend: {
                        display: true,
                        position: 'top'
                    }
                }
            }
        });
    }

    createBarChart('basketballChart', ['Game 1', 'Game 2', 'Game 3', 'Game 4', 'Game 5'], [89, 92, 78, 95, 88], 'Points', 'rgba(59, 130, 246, 0.7)');
    createBarChart('footballChart', ['Game 1', 'Game 2', 'Game 3', 'Game 4', 'Game 5'], [1, 3, 0, 2, 1], 'Scores', 'rgba(34, 197, 94, 0.7)');
    createBarChart('baseballChart', ['Game 1', 'Game 2', 'Game 3', 'Game 4', 'Game 5'], [5, 2, 8, 6, 7], 'Runs', 'rgba(168, 85, 247, 0.7)');

    const teamPerformanceLabels = ['Week 1', 'Week 2', 'Week 3', 'Week 4', 'Week 5'];
    const teamPerformanceData = [
        { label: 'Team A', data: [75, 82, 90, 85, 92], color: 'rgba(59, 130, 246, 0.7)', team: 'teamA' },
        { label: 'Team B', data: [68, 75, 80, 78, 85], color: 'rgba(251, 146, 60, 0.7)', team: 'teamB' }
    ];
    createLineChart('teamPerformanceChart', teamPerformanceLabels, teamPerformanceData);

    document.querySelectorAll('.filter-button').forEach(button => {
        button.addEventListener('click', function() {
            document.querySelectorAll('.filter-button').forEach(btn => btn.classList.remove('active', 'border-blue-500'));
            this.classList.add('active', 'border-blue-500');
            const filter = this.dataset.filter;
            const chart = Chart.getChart('teamPerformanceChart');
            if (chart) {
                chart.data.datasets = teamPerformanceData.filter(dataset => filter === 'all' || dataset.team === filter).map(dataset => ({
                    label: dataset.label,
                    data: dataset.data,
                    borderColor: dataset.color,
                    backgroundColor: dataset.color.replace('500', '100'),
                    borderWidth: 2,
                    tension: 0.4,
                    fill: true
                }));
                chart.update();
            }
        });
    });

    document.addEventListener('DOMContentLoaded', () => {
        document.querySelector('.filter-button[data-filter="all"]').classList.add('active', 'border-blue-500');
    });

</script>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
</body>
</html>
