            mobileMenu.classList.toggle('hidden');
        });

        // --- Dummy Data ---
        const transactionsData = [
            { id: 1, type: 'expense', category: 'Food', date: '2024-03-15', description: 'Lunch at Cafe', amount: 25.50 },
            { id: 2, type: 'income', category: 'Salary', date: '2024-03-14', description: 'Monthly Salary', amount: 3200.00 },
