        };

        const categoriesBreakdownData = [
            { category: 'Food', total: 450.00, subcategories: [
                { name: 'Groceries', amount: 280.00 },
                { name: 'Restaurants', amount: 170.00 },
            ]},
            { category: 'Utilities', total: 280.00, subcategories: [
                { name: 'Electricity', amount: 120.00 },
                { name: 'Water', amount: 60.00 },
                { name: 'Internet', amount: 100.00 },
            ]},
            { category: 'Transportation', total: 180.00, subcategories: [
                { name: 'Fuel', amount: 80.00 },
                { name: 'Public Transport', amount: 50.00 },
                { name: 'Maintenance', amount: 50.00 },
            ]},
            { category: 'Entertainment', total: 320.00, subcategories: [
                { name: 'Movies', amount: 80.00 },
                { name: 'Dining Out', amount: 150.00 },
                { name: 'Events', amount: 90.00 },
            ]},
            { category: 'Savings', total: 600.00, subcategories: [
                { name: 'Emergency Fund', amount: 300.00 },
                { name: 'Investments', amount: 300.00 },
            ]},
        ];


        // --- Transaction Feed ---
        const transactionFeed = document.getElementById('transactionFeed');
        const loadingTransactions = document.getElementById('loadingTransactions');
        const noTransactions = document.getElementById('noTransactions');

        function displayTransactions(transactions) {
            loadingTransactions.classList.add('hidden');
            if (transactions.length === 0) {
                noTransactions.classList.remove('hidden');
                return;
            }
            noTransactions.classList.add('hidden');

            transactions.sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 5).forEach(transaction => {
                const transactionItem = document.createElement('li');
                transactionItem.classList.add('transaction-item', 'bg-neutral', 'p-4', 'rounded-lg', 'shadow-custom', 'flex', 'justify-between', 'items-center');

                const amountColorClass = transaction.type === 'income' ? 'text-positive' : 'text-negative';
                const amountPrefix = transaction.type === 'income' ? '+' : '-';

                transactionItem.innerHTML = `
                    <div>
                        <h4 class="font-medium">${transaction.description}</h4>
                        <p class="text-sm text-lightText">${transaction.category} - ${new Date(transaction.date).toLocaleDateString()}</p>
                    </div>
                    <div class="${amountColorClass} font-bold">${amountPrefix}$${transaction.amount.toFixed(2)}</div>
                `;
                transactionFeed.appendChild(transactionItem);
            });
        }

        loadingTransactions.classList.remove('hidden');
        setTimeout(() => {
            displayTransactions(transactionsData);
