            const header = document.createElement('div');
            header.classList.add('p-4', 'flex', 'justify-between', 'items-center', 'cursor-pointer');
            header.addEventListener('click', () => {
                body.classList.toggle('collapsed');
                icon.classList.toggle('fa-chevron-down');
                icon.classList.toggle('fa-chevron-up');
            });

            const title = document.createElement('h5');
            title.classList.add('font-medium');
            title.textContent = categoryData.category;

            const total = document.createElement('span');
            total.classList.add('font-bold', 'text-lightText');
            total.textContent = `$${categoryData.total.toFixed(2)}`;

            const icon = document.createElement('i');
            icon.classList.add('fa', 'fa-chevron-down', 'text-lightText');

            header.appendChild(title);
            header.appendChild(total);
            header.appendChild(icon);
            categoryItem.appendChild(header);

            const body = document.createElement('ul');
            body.classList.add('space-y-2', 'p-4');

            categoryData.subcategories.forEach(subcategory => {
                const subItem = document.createElement('li');
                subItem.classList.add('flex', 'justify-between', 'items-center', 'text-sm', 'text-lightText');
                subItem.innerHTML = `<span>${subcategory.name}</span> <span>$${subcategory.amount.toFixed(2)}</span>`;
                body.appendChild(subItem);
            });
            categoryItem.appendChild(body);

            categoriesBreakdownContainer.appendChild(categoryItem);

            // Initially collapse subcategories (optional - remove for always expanded)
            body.classList.add('collapsed');
            categoryItem.classList.add('collapsed');
        });


        // --- Charts (Placeholder - Replace with actual chart library or custom charting) ---
        function createBarChart(canvasId, labels, data, colors, labelText) {
            const canvas = document.getElementById(canvasId);
            if (!canvas) return;
            const ctx = canvas.getContext('2d');

            const chart = new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: labels,
                    datasets: [{
                        label: labelText,
                        data: data,
                        backgroundColor: colors,
                        borderRadius: 5,
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: { beginAtZero: true, grid: { display: false } },
                        x: { grid: { display: false } }
                    },
                    plugins: { legend: { display: false } }
                }
            });
        }


        function createLineChart(canvasId, labels, incomeData, expenseData) {
            const canvas = document.getElementById(canvasId);
            if (!canvas) return;
            const ctx = canvas.getContext('2d');

            const chart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: labels,
                    datasets: [{
                        label: 'Income',
                        data: incomeData,
                        borderColor: '#86efac',
                        backgroundColor: '#86efac',
                        borderWidth: 2,
                        fill: false,
                        tension: 0.4
                    }, {
                        label: 'Expenses',
                        data: expenseData,
                        borderColor: '#f97316',
                        backgroundColor: '#f97316',
                        borderWidth: 2,
                        fill: false,
                        tension: 0.4
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: { beginAtZero: true, grid: { display: false } },
                        x: { grid: { display: false } }
                    },
                    plugins: { legend: { position: 'bottom' } }
                }
            });
        }


        // --- Initialize Charts ---
        const categoryLabels = categorySpendingData.map(item => item.category);
        const categoryAmounts = categorySpendingData.map(item => item.amount);
        const categoryColors = categorySpendingData.map(item => item.color);
        createBarChart('categorySpendingChart', categoryLabels, categoryAmounts, categoryColors, 'Spending Amount');

        createLineChart('incomeExpenseChart', incomeExpenseData.labels, incomeExpenseData.income, incomeExpenseData.expenses);


    });
</script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.2/chart.umd.min.js"></script>

</body>
</html>
