<script>
document.addEventListener('DOMContentLoaded', () => {
    const canvas = document.getElementById('card-canvas');
    const elementPanelElements = document.querySelectorAll('.draggable-element, .draggable-text, .draggable-image');
    const textContentInput = document.getElementById('text-content');
    const fontSizeInput = document.getElementById('font-size');
    const fontColorInput = document.getElementById('font-color');
    const applyTextChangesButton = document.getElementById('apply-text-changes');
    const layersPanel = document.getElementById('layers-panel');
    let activeElement = null;
    let layerCounter = 0;
    let layers = [];

    function updateLayersPanel() {
        layersPanel.innerHTML = '';
        layers.forEach((layer, index) => {
            const layerDiv = document.createElement('div');
            layerDiv.classList.add('layer-item', 'dynamic-shadow');
            if (layer.element === activeElement) {
                layerDiv.classList.add('active-layer');
            }
            layerDiv.innerHTML = `
                <span>${layer.type} ${layer.id}</span>
                <div class="layer-actions">
                    <button onclick="bringLayerForward(${layer.id})"><i class="fas fa-arrow-up"></i></button>
                    <button onclick="sendLayerBackward(${layer.id})"><i class="fas fa-arrow-down"></i></button>
                    <button onclick="deleteLayer(${layer.id})"><i class="fas fa-trash"></i></button>
                </div>
            `;
            layersPanel.appendChild(layerDiv);
        });
    }

    window.bringLayerForward = (layerId) => {
        const layerIndex = layers.findIndex(layer => layer.id === layerId);
        if (layerIndex < layers.length - 1) {
            [layers[layerIndex], layers[layerIndex + 1]] = [layers[layerIndex + 1], layers[layerIndex]];
            updateZIndices();
            updateLayersPanel();
        }
    };

    window.sendLayerBackward = (layerId) => {
        const layerIndex = layers.findIndex(layer => layer.id === layerId);
        if (layerIndex > 0) {
            [layers[layerIndex], layers[layerIndex - 1]] = [layers[layerIndex - 1], layers[layerIndex]];
            updateZIndices();
            updateLayersPanel();
        }
    };

    window.deleteLayer = (layerId) => {
        const layerIndex = layers.findIndex(layer => layer.id === layerId);
        if (layerIndex > -1) {
            const elementToRemove = layers[layerIndex].element;
            canvas.removeChild(elementToRemove);
            layers.splice(layerIndex, 1);
            activeElement = null;
            updateLayersPanel();
        }
    };

    function updateZIndices() {
        layers.forEach((layer, index) => {
            layer.element.style.zIndex = index + 1;
        });
    }

    elementPanelElements.forEach(element => {
        element.addEventListener('dragstart', (event) => {
            event.dataTransfer.setData('text/plain', element.dataset.type);
            if (element.dataset.type === 'shape') {
                event.dataTransfer.setData('shape', element.dataset.shape);
            }
            if (element.dataset.type === 'image') {
                event.dataTransfer.setData('image-src', element.src);
            }
        });
    });

    canvas.addEventListener('dragover', (event) => {
        event.preventDefault();
    });

    canvas.addEventListener('drop', (event) => {
        event.preventDefault();
        const elementType = event.dataTransfer.getData('text/plain');
        let newElement;

        if (elementType === 'text') {
            newElement = createTextElement('Your Text', event.clientX - canvas.offsetLeft, event.clientY - canvas.offsetTop);
        } else if (elementType === 'shape') {
            const shapeType = event.dataTransfer.getData('shape');
            newElement = createShapeElement(shapeType, event.clientX - canvas.offsetLeft, event.clientY - canvas.offsetTop);
        } else if (elementType === 'image') {
            const imgSrc = event.dataTransfer.getData('image-src');
            newElement = createImageElement(imgSrc, event.clientX - canvas.offsetLeft, event.clientY - canvas.offsetTop);
        }

        if (newElement) {
            canvas.appendChild(newElement);
            layers.push({id: ++layerCounter, type: elementType, element: newElement});
            updateLayersPanel();
            updateZIndices();
        }
    });

    function createTextElement(initialText, x, y) {
        const element = document.createElement('div');
        element.textContent = initialText;
        element.className = 'text-element resizable';
        element.style.left = `${x}px`;
        element.style.top = `${y}px`;
        element.style.color = fontColorInput.value;
        element.style.fontSize = `${fontSizeInput.value}px`;
        makeElementDraggable(element);
        makeElementResizable(element);
        element.addEventListener('click', () => {
            activeElement = element;
            textContentInput.value = element.textContent;
            fontSizeInput.value = element.style.fontSize.replace('px', '');
            fontColorInput.value = element.style.color;
            updateLayersPanel();
        });
        return element;
    }

    function createShapeElement(shapeType, x, y) {
        const element = document.createElement('i');
        let iconClass = '';
        let defaultSize = '50px';
        let colorClass = 'text-pastel-purple';

        switch (shapeType) {
            case 'heart': iconClass = 'fas fa-heart'; colorClass = 'text-pastel-purple'; break;
            case 'star': iconClass = 'fas fa-star'; colorClass = 'text-pastel-orange'; break;
            case 'circle': iconClass = 'fas fa-circle'; colorClass = 'text-pastel-light-blue'; break;
            case 'square': iconClass = 'fas fa-square'; colorClass = 'text-pastel-light-pink'; break;
        }

        element.className = `image-element resizable ${iconClass} ${colorClass}`;
        element.style.fontSize = defaultSize;
        element.style.left = `${x}px`;
        element.style.top = `${y}px`;
        makeElementDraggable(element);
        makeElementResizable(element);
        element.addEventListener('click', () => {
            activeElement = element;
            textContentInput.value = '';
            fontSizeInput.value = defaultSize.replace('px', '');
            fontColorInput.value = getComputedStyle(element).color;
            updateLayersPanel();
        });
        return element;
    }

    function createImageElement(imgSrc, x, y) {
        const element = document.createElement('img');
        element.src = imgSrc;
        element.alt = 'Card Image';
        element.className = 'image-element resizable';
        element.style.width = '100px';
        element.style.height = 'auto';
        element.style.left = `${x}px`;
        element.style.top = `${y}px`;
        makeElementDraggable(element);
        makeElementResizable(element);
        element.addEventListener('click', () => {
            activeElement = element;
            textContentInput.value = '';
            fontSizeInput.value = element.style.width.replace('px', '');
            fontColorInput.value = '#000000'; // No color for images
            updateLayersPanel();
        });
        return element;
    }


    function makeElementDraggable(element) {
        let offsetX, offsetY, isDragging = false;

        element.addEventListener('mousedown', (e) => {
            isDragging = true;
            activeElement = element;
            updateLayersPanel();
            offsetX = e.clientX - element.offsetLeft;
            offsetY = e.clientY - element.offsetTop;
            element.style.cursor = 'grabbing';
        });

        document.addEventListener('mousemove', (e) => {
            if (!isDragging) return;
            element.style.left = `${e.clientX - offsetX}px`;
            element.style.top = `${e.clientY - offsetY}px`;
        });

        document.addEventListener('mouseup', () => {
            isDragging = false;
            element.style.cursor = 'grab';
        });
    }

    function makeElementResizable(element) {
        element.style.overflow = 'auto';
        element.style.boxSizing = 'border-box';

        const handle = document.createElement('div');
        handle.className = 'resize-handle';
        handle.style.position = 'absolute';
        handle.style.right = '0px';
        handle.style.bottom = '0px';
        handle.style.width = '10px';
        handle.style.height = '10px';
        handle.style.backgroundColor = 'rgba(0,0,0,0.2)';
        handle.style.cursor = 'se-resize';
        element.appendChild(handle);

        let isResizing = false;
        let initialWidth, initialHeight, startX, startY;

        handle.addEventListener('mousedown', (e) => {
            isResizing = true;
            startX = e.clientX;
            startY = e.clientY;
            initialWidth = element.offsetWidth;
            initialHeight = element.offsetHeight;
            e.stopPropagation();
        });

        document.addEventListener('mousemove', (e) => {
            if (!isResizing) return;
            const width = initialWidth + (e.clientX - startX);
            const height = initialHeight + (e.clientY - startY);
            element.style.width = `${width > 20 ? width : 20}px`;
            element.style.height = `${height > 20 ? height : 20}px`;
            e.preventDefault();
            e.stopPropagation();
        });

        document.addEventListener('mouseup', () => {
            isResizing = false;
        });
    }

    applyTextChangesButton.addEventListener('click', () => {
        if (activeElement && activeElement.classList.contains('text-element')) {
            activeElement.textContent = textContentInput.value;
            activeElement.style.fontSize = `${fontSizeInput.value}px`;
            activeElement.style.color = fontColorInput.value;
        }
    });

    updateLayersPanel();
});
</script>

</body>
</html>
