    <style>
        body {
            font-family: 'Nunito Sans', sans-serif;
            color: #333;
        }
        h1, h2, h3, h4, h5, h6 {
            font-family: 'Poppins', sans-serif;
            color: #111;
        }
        .hero-slider {
            position: relative;
            height: 100vh;
            width: 100%;
            overflow: hidden;
        }
        .hero-slide {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-size: cover;
            background-position: center;
            opacity: 0;
            transition: opacity 1s ease-in-out;
        }
        .hero-slide.active {
            opacity: 1;
        }
        .slider-content {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            text-align: center;
            color: white;
        }
        .slider-content h2 {
            font-size: 3rem;
            font-weight: 700;
            margin-bottom: 1rem;
            text-shadow: 2px 2px 4px #000000;
        }
        .slider-content p {
            font-size: 1.5rem;
            text-shadow: 1px 1px 2px #000000;
        }
        .portfolio-item {
            position: relative;
            overflow: hidden;
            border-radius: 0.5rem;
        }
        .portfolio-item img {
            transition: transform 0.5s ease-out;
        }
        .portfolio-item:hover img {
            transform: scale(1.1);
        }
        .portfolio-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.6);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            opacity: 0;
            transition: opacity 0.3s ease-in-out;
        }
        .portfolio-item:hover .portfolio-overlay {
            opacity: 1;
        }
        .overlay-text {
            color: white;
            text-align: center;
            padding: 1rem;
        }
        .overlay-text h3 {
            font-size: 1.5rem;
            margin-bottom: 0.5rem;
        }
        .overlay-text p {
            font-size: 1rem;
        }
        .hover-underline {
            position: relative;
            display: inline-block;
        }

        .hover-underline::after {
            content: '';
            position: absolute;
            width: 100%;
            transform: scaleX(0);
            height: 2px;
            bottom: 0;
            left: 0;
            background-color: #2dd4cf;
            transform-origin: bottom right;
            transition: transform 0.3s ease-out;
        }

        .hover-underline:hover::after {
            transform: scaleX(1);
            transform-origin: bottom left;
        }

        .button-primary {
            background-color: #2dd4cf;
            color: white;
            padding: 0.75rem 1.5rem;
            border-radius: 0.375rem;
            transition: background-color 0.3s ease-in-out, transform 0.3s ease-out;
            display: inline-flex;
            align-items: center;
            justify-content: center;
        }

        .button-primary:hover {
            background-color: #25b8b3;
            transform: scale(1.05);
        }
        .button-secondary {
            border: 2px solid #2dd4cf;
            color: #2dd4cf;
            padding: 0.75rem 1.5rem;
            border-radius: 0.375rem;
            transition: background-color 0.3s ease-in-out, color 0.3s ease-in-out, transform 0.3s ease-out;
            display: inline-flex;
            align-items: center;
            justify-content: center;
        }

        .button-secondary:hover {
            background-color: #2dd4cf;
            color: white;
            transform: scale(1.05);
        }
    </style>
</head>
