    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const heroSlides = document.querySelectorAll('.hero-slide');
            let currentSlide = 0;

            function showSlide(index) {
                heroSlides.forEach(slide => slide.classList.remove('active'));
                heroSlides[index].classList.add('active');
            }

            function nextSlide() {
                currentSlide = (currentSlide + 1) % heroSlides.length;
                showSlide(currentSlide);
            }

            setInterval(nextSlide, 5000);
            showSlide(currentSlide);

             gsap.utils.toArray('.animate-fade-in').forEach(element => {
                gsap.from(element, {
                    opacity: 0,
                    yPercent: 20,
                    duration: 1,
                    ease: "power2.out",
                    scrollTrigger: {
                        trigger: element,
                        start: "top 90%",
                        end: "top 20%",
                        toggleActions: "play none none reverse"
                    }
                });
            });

            gsap.utils.toArray('.portfolio-item').forEach(item => {
                gsap.from(item, {
                    opacity: 0,
                    yPercent: 10,
                    duration: 0.8,
                    ease: "power2.out",
                    scrollTrigger: {
                        trigger: item,
                        start: "top 90%",
                        end: "top 20%",
                        toggleActions: "play none none reverse"
                    }
                });
            });

            gsap.utils.toArray('#about > div > div').forEach(item => {
                gsap.from(item, {
                    opacity: 0,
                    xPercent: index => index === 0 ? -20 : 20,
                    duration: 1,
                    ease: "power2.out",
                    scrollTrigger: {
                        trigger: '#about',
                        start: "top 70%",
                        end: "top 20%",
                        toggleActions: "play none none reverse"
                    }
                });
            });
        });
    </script>

</body>
</html>
