                <div class="gallery-item aspect-w-1 aspect-h-1 rounded-lg overflow-hidden depth-1" style="background-image: url('https://picsum.photos/600/600?random=7');" onclick="openLightbox('https://picsum.photos/1200/1200?random=7')"></div>
