                        <label for="message" class="block mb-2 text-sm font-bold">Message</label>
                        <textarea id="message" rows="5" class="w-full bg-gray-700 text-white border border-gray-600 rounded-md py-2 px-4 focus:outline-none focus:border-accent-text" placeholder="Your Message"></textarea>
