                <a href="#" class="hover:accent-text transition-colors"><i class="fa-brands fa-twitter text-lg"></i></a>
                <a href="#" class="hover:accent-text transition-colors"><i class="fa-brands fa-linkedin text-lg"></i></a>
            </div>
        </div>
    </footer>

    <div id="lightbox" class="fixed hidden top-0 left-0 w-full h-full bg-black bg-opacity-90 z-50 flex items-center justify-center" onclick="closeLightbox()">
        <img id="lightbox-image" src="" alt="Lightbox Image" class="max-w-screen-lg max-h-screen depth-3">
        <button onclick="closeLightbox()" class="absolute top-4 right-4 text-white text-3xl focus:outline-none"><i class="fa-solid fa-xmark"></i></button>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });

        function openLightbox(imageSrc) {
            const lightbox = document.getElementById('lightbox');
            const lightboxImage = document.getElementById('lightbox-image');
            lightboxImage.src = imageSrc;
            lightbox.classList.remove('hidden');
            document.body.classList.add('overflow-hidden');
        }

        function closeLightbox() {
            const lightbox = document.getElementById('lightbox');
            lightbox.classList.add('hidden');
            document.body.classList.remove('overflow-hidden');
        }
    </script>

</body>
</html>
