    <style>
        body {
            font-family: 'Poppins', sans-serif;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .motion-trail {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
        }
        .trail-particle {
            position: absolute;
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background-color: magenta;
            opacity: 0;
            transform: translate(-50%, -50%);
            animation: trail 0.8s ease-out forwards;
        }
        @keyframes trail {
            0% { opacity: 1; transform: translate(-50%, -50%) scale(0); }
            100% { opacity: 0; transform: translate(-50%, -50%) scale(1.5); }
        }
        .scheduler-container {
            background-color: rgba(255, 255, 255, 0.9);
            backdrop-filter: blur(10px);
            border-radius: 1rem;
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
        }
        .class-slot {
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .class-slot:hover {
            transform: scale(1.05);
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
        }
        .layered-bg {
            background-image:
                radial-gradient(circle at top left, rgba(207, 31, 167, 0.4), transparent 30%),
                radial-gradient(circle at bottom right, rgba(207, 31, 167, 0.4), transparent 30%),
                linear-gradient(to bottom, black 0%, #1a1a1a 100%);
        }
        .vibrant-magenta {
            color: magenta;
        }
        .interactive-element {
            transition: all 0.3s ease;
        }
        .interactive-element:hover {
            transform: scale(1.05);
            opacity: 0.9;
        }
        .kinetic-motion {
            will-change: transform;
        }
    </style>
</head>
