    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            let currentDate = new Date();
            const monthYearElement = document.getElementById('current-month');
            const daysGridElement = document.getElementById('days-grid');
            const prevMonthButton = document.getElementById('prev-month');
            const nextMonthButton = document.getElementById('next-month');
            let selectedDate = null;
            let selectedTimeSlot = null;
            const appointmentDateInput = document.getElementById('appointment-date');
            const appointmentTimeInput = document.getElementById('appointment-time');
            const timeSlots = document.querySelectorAll('.time-slot');
            const formMessage = document.getElementById('form-message');
            const appointmentForm = document.getElementById('appointment-form');

            function updateCalendar() {
                const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
                const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
                const dayOfWeekOfFirstDay = firstDayOfMonth.getDay();
                monthYearElement.textContent = `${currentDate.toLocaleString('default', { month: 'long' })} ${currentDate.getFullYear()}`;
                daysGridElement.innerHTML = '';

                for (let i = 0; i < dayOfWeekOfFirstDay; i++) {
                    const emptyDay = document.createElement('div');
                    daysGridElement.appendChild(emptyDay);
                }

                for (let day = 1; day <= daysInMonth; day++) {
                    const dayElement = document.createElement('div');
                    dayElement.textContent = day;
                    dayElement.classList.add('calendar-day', 'text-center', 'py-2', 'rounded-md', 'transition-colors');

                    const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
                    const isBooked = isDateBooked(date);
                    if (isBooked) {
                        dayElement.classList.add('booked');
                    } else {
                        dayElement.addEventListener('click', () => {
                            if (selectedDate) {
                                selectedDate.classList.remove('selected');
                            }
                            if (!isBooked) {
                                dayElement.classList.add('selected');
                                selectedDate = dayElement;
                                const formattedDate = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                                appointmentDateInput.value = formattedDate;
                                console.log('Selected date:', formattedDate);
                            }
                        });
                    }
                    daysGridElement.appendChild(dayElement);
                }
            }

            function isDateBooked(date) {
                const bookedDates = [];
                const formattedDate = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
                return bookedDates.includes(formattedDate);
            }

            prevMonthButton.addEventListener('click', () => {
                currentDate.setMonth(currentDate.getMonth() - 1);
                updateCalendar();
            });

            nextMonthButton.addEventListener('click', () => {
                currentDate.setMonth(currentDate.getMonth() + 1);
                updateCalendar();
            });

            timeSlots.forEach(slot => {
                slot.addEventListener('click', function() {
                    if (selectedTimeSlot) {
                        selectedTimeSlot.classList.remove('bg-blue-300', 'text-white');
                        selectedTimeSlot.classList.add('bg-blue-100', 'text-blue-800');
                    }
                    this.classList.remove('bg-blue-100', 'text-blue-800');
                    this.classList.add('bg-blue-300', 'text-white');
                    selectedTimeSlot = this;
                    appointmentTimeInput.value = this.dataset.time;
                    console.log('Selected time:', this.dataset.time);
                });
            });

            appointmentForm.addEventListener('submit', function(event) {
                event.preventDefault();
                if (!appointmentDateInput.value || !appointmentTimeInput.value) {
                    formMessage.textContent = 'Please select a date and time.';
                    formMessage.classList.add('text-red-500');
                    return;
                }
                formMessage.textContent = 'Appointment booked successfully!';
                formMessage.classList.remove('text-red-500');
                formMessage.classList.add('text-green-500');
                console.log('Form submitted', {
                    date: appointmentDateInput.value,
                    time: appointmentTimeInput.value,
                    name: document.getElementById('name').value,
                    email: document.getElementById('email').value,
                    phone: document.getElementById('phone').value,
                    notes: document.getElementById('notes').value
                });
                appointmentForm.reset();
                if (selectedDate) selectedDate.classList.remove('selected');
                if (selectedTimeSlot) {
                    selectedTimeSlot.classList.remove('bg-blue-300', 'text-white');
                    selectedTimeSlot.classList.add('bg-blue-100', 'text-blue-800');
                    selectedTimeSlot = null;
                }
                appointmentDateInput.value = '';
                appointmentTimeInput.value = '';
            });

            updateCalendar();
        });
    </script>
</body>
</html>
