            @apply font-bold text-blue-500;
        }
        .week-row:first-child .date-cell {
            @apply border-t-0;
        }
        .week-row:last-child .date-cell {
            @apply border-b-0;
        }
        .date-cell:first-child {
            @apply border-l-0;
        }
        .date-cell:last-child {
            @apply border-r-0;
        }
        .time-slot-col {
            display: grid;
            grid-template-rows: repeat(24, minmax(40px, auto));
        }
        .hour-label {
            @apply p-2 text-xs text-gray-500 text-right border-b border-gray-100;
        }
        .hour-slot {
            @apply border-b border-gray-100;
        }
    </style>
</head>
<body class="bg-gray-50">
