                    <div><div class="day-header">Mon</div></div>
                    <div><div class="day-header">Tue</div></div>
                    <div><div class="day-header">Wed</div></div>
                    <div><div class="day-header">Thu</div></div>
                    <div><div class="day-header">Fri</div></div>
                    <div><div class="day-header">Sat</div></div>
                </div>
                <div id="calendarDates" class="calendar-grid bg-white">
