                        <div class="time-slot" data-time="09:00" style="background-color: #e0f7fa;"></div>
                        <div class="time-slot" data-time="10:00" style="background-color: #f8bbd0;"></div>
                        <div class="time-slot" data-time="11:00" style="background-color: #f8bbd0;"></div>
                        <div class="time-slot" data-time="12:00" style="background-color: #f8bbd0;"></div>
                        <div class="time-slot" data-time="13:00" style="background-color: #ffe0b2;"></div>
                        <div class="time-slot" data-time="14:00" style="background-color: #ffe0b2;"></div>
                        <div class="time-slot" data-time="15:00" style="background-color: #ffe0b2;"></div>
                        <div class="time-slot" data-time="16:00"></div>
                        <div class="time-slot" data-time="17:00"></div>
                        <div class="time-slot" data-time="18:00"></div>
                        <div class="time-slot" data-time="19:00"></div>
                        <div class="time-slot" data-time="20:00"></div>
                        <div class="time-slot" data-time="21:00"></div>
                        <div class="time-slot" data-time="22:00"></div>
                        <div class="time-slot" data-time="23:00"></div>
                    </div>
                </div>
            </div>
        </main>
    </div>

    <script>
        const currentMonthElement = document.getElementById('currentMonth');
        const currentYearElement = document.getElementById('currentYear');
        const calendarDatesElement = document.getElementById('calendarDates');
        const prevMonthBtn = document.getElementById('prevMonthBtn');
        const nextMonthBtn = document.getElementById('nextMonthBtn');
        const timeSlotsElement = document.getElementById('timeSlots');

        let currentDate = new Date();
        let draggingEvent = null;

        function generateCalendar() {
            const year = currentDate.getFullYear();
            const month = currentDate.getMonth();
            const firstDayOfMonth = new Date(year, month, 1);
            const daysInMonth = new Date(year, month + 1, 0).getDate();
            const dayOfWeekOfFirstDay = firstDayOfMonth.getDay();

            currentMonthElement.textContent = new Intl.DateTimeFormat('en-US', { month: 'long' }).format(currentDate);
            currentYearElement.textContent = year;
            calendarDatesElement.innerHTML = '';

            let dayCounter = 1;
            for (let i = 0; i < 6; i++) {
                const weekRow = document.createElement('div');
                weekRow.classList.add('calendar-row', 'week-row');
                for (let j = 0; j < 7; j++) {
                    const dateCell = document.createElement('div');
                    dateCell.classList.add('date-cell');
                    if (i === 0 && j < dayOfWeekOfFirstDay) {
                        dateCell.textContent = '';
                    } else if (dayCounter > daysInMonth) {
                        dateCell.textContent = '';
                    } else {
                        dateCell.textContent = dayCounter;
                        if (year === new Date().getFullYear() && month === new Date().getMonth() && dayCounter === new Date().getDate()) {
                            dateCell.classList.add('today');
                        }
                        dayCounter++;
                    }
                    weekRow.appendChild(dateCell);
                }
                calendarDatesElement.appendChild(weekRow);
            }
        }

        prevMonthBtn.addEventListener('click', () => {
            currentDate.setMonth(currentDate.getMonth() - 1);
            generateCalendar();
        });

        nextMonthBtn.addEventListener('click', () => {
            currentDate.setMonth(currentDate.getMonth() + 1);
            generateCalendar();
        });

        generateCalendar();

        function createEventElement(eventText, color) {
            const eventDiv = document.createElement('div');
            eventDiv.textContent = eventText;
            eventDiv.classList.add('event');
            eventDiv.style.backgroundColor = color;
            eventDiv.draggable = true;

            eventDiv.addEventListener('dragstart', (event) => {
                draggingEvent = event.target;
                event.target.classList.add('dragging');
            });

            eventDiv.addEventListener('dragend', (event) => {
                draggingEvent = null;
                event.target.classList.remove('dragging');
            });
            return eventDiv;
        }

        timeSlotsElement.addEventListener('dragover', (event) => {
            event.preventDefault();
        });

        timeSlotsElement.addEventListener('drop', (event) => {
            event.preventDefault();
            if (draggingEvent) {
                const targetSlot = event.target.closest('.time-slot');
                if (targetSlot) {
                    targetSlot.appendChild(draggingEvent);
                }
            }
        });

        const event1 = createEventElement('Meeting with Team', '#a7ffeb');
        const event2 = createEventElement('Client Call', '#ffcdd2');
        const event3 = createEventElement('Workout', '#d7ffd9');

        timeSlotsElement.querySelector('[data-time="09:00"]').appendChild(event1.cloneNode(true));
        timeSlotsElement.querySelector('[data-time="11:00"]').appendChild(event2.cloneNode(true));
        timeSlotsElement.querySelector('[data-time="07:00"]').appendChild(event3.cloneNode(true));
        timeSlotsElement.querySelectorAll('.event').forEach(event => {
            event.addEventListener('dragstart', (e) => {
                draggingEvent = e.target;
                e.target.classList.add('dragging');
            });

            event.addEventListener('dragend', (e) => {
                draggingEvent = null;
                e.target.classList.remove('dragging');
            });
        });

    </script>
</body>
</html>
