    <script>
        const darkModeToggle = document.getElementById('darkModeToggle');
        const darkModeIcon = document.getElementById('darkModeIcon');
        const html = document.documentElement;

        darkModeToggle.addEventListener('click', () => {
            if (html.classList.contains('dark')) {
                html.classList.remove('dark');
                darkModeIcon.classList.remove('fa-sun');
                darkModeIcon.classList.add('fa-moon');
            } else {
                html.classList.add('dark');
                darkModeIcon.classList.remove('fa-moon');
                darkModeIcon.classList.add('fa-sun');
            }
        });

        const loadMoreButton = document.getElementById('load-more').querySelector('button');
        const blogPostsSection = document.getElementById('blog-posts');
        let postCount = 5;

        loadMoreButton.addEventListener('click', () => {
            const newPosts = generateBlogPosts(3, postCount);
            blogPostsSection.innerHTML += newPosts;
            postCount += 3;
            if (postCount > 12) {
                loadMoreButton.parentElement.remove();
            }
        });

        function generateBlogPosts(count, offset) {
            let postsHTML = '';
            for (let i = 0; i < count; i++) {
                const postIndex = offset + i + 1;
                postsHTML += `
                    <article class="blog-post bg-white dark:bg-gray-700 p-6 rounded-lg shadow-md animate-fade-in">
                        <img src="https://picsum.photos/200/300?random=${postIndex}" alt="Blog Post Image" class="rounded-md mb-4 w-full object-cover h-48">
                        <h2 class="text-2xl font-bold mb-2"><a href="#" class="hover:text-blue-600 dark:hover:text-blue-400 transition-colors">Another Minimalist Thought ${postIndex}</a></h2>
                        <p class="text-gray-700 dark:text-gray-200 mb-4">More content about minimalism and simple living. Post number ${postIndex}.</p>
                        <a href="#" class="inline-block text-blue-500 hover:text-blue-700 dark:text-blue-400 dark:hover:text-blue-300 transition-colors font-semibold">Read more</a>
                    </article>
                `;
            }
            return postsHTML;
        }

        let loadingMore = false;
        const loadMoreDiv = document.getElementById('load-more');

        const infiniteScrollObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting && !loadingMore && loadMoreButton.parentElement) {
                    loadingMore = true;
                    loadMoreButton.textContent = 'Loading...';
                    setTimeout(() => {
                        const newPosts = generateBlogPosts(3, postCount);
                        blogPostsSection.innerHTML += newPosts;
                        postCount += 3;
                        loadMoreButton.textContent = 'Load More Posts';
                        loadingMore = false;
                        if (postCount > 15) {
                            loadMoreButton.parentElement.remove();
                        }
                    }, 1000);
                }
            });
        }, { threshold: 0.1 });

        infiniteScrollObserver.observe(loadMoreDiv);

    </script>

</body>
</html>
