                        <div class="mb-6">
                            <label for="water" class="block text-gray-700 text-sm font-bold mb-2">Water Intake (Liters):</label>
                            <input type="number" id="water" name="water" class="form-input" placeholder="Enter water intake" step="0.1" required>
                        </div>
                        <div class="mb-6">
                            <label for="sleep" class="block text-gray-700 text-sm font-bold mb-2">Sleep Hours:</label>
                            <input type="number" id="sleep" name="sleep" class="form-input" placeholder="Enter sleep hours" step="0.5" required>
                        </div>
                        <button type="submit" class="bg-custom-green text-white font-bold py-3 px-6 rounded-full hover:bg-green-600 transition-colors pulse-animation">
                            Track Data
                        </button>
                    </form>
                </div>
            </section>

            <section id="reports" class="mb-16 slide-up-animation">
                <h2 class="text-3xl font-bold mb-6 text-gray-900">Reports & Analytics</h2>
                <div class="bg-white p-8 rounded-lg shadow-card">
                    <h3 class="text-xl font-semibold mb-4 text-gray-800">Weight Progress</h3>
                    <canvas id="weightChart" class="chart-container"></canvas>
                    <h3 class="text-xl font-semibold mt-8 mb-4 text-gray-800">Monthly Overview</h3>
                    <canvas id="monthlyOverviewChart" class="chart-container"></canvas>
                </div>
            </section>

            <section id="settings" class="slide-up-animation">
                <h2 class="text-3xl font-bold mb-6 text-gray-900">Settings</h2>
                <div class="bg-white p-8 rounded-lg shadow-card">
                    <h3 class="text-xl font-semibold mb-4 text-gray-800">User Profile</h3>
                    <p class="text-gray-700 mb-4">Manage your personal information and preferences.</p>
                    <button class="bg-gray-200 hover:bg-gray-300 text-gray-800 font-bold py-2 px-4 rounded-full transition-colors">Edit Profile</button>
                </div>
            </section>

        </main>

    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {

            function createChart(canvasId, chartType, labels, data, label, color) {
                const ctx = document.getElementById(canvasId).getContext('2d');
                new Chart(ctx, {
                    type: chartType,
                    data: {
                        labels: labels,
                        datasets: [{
                            label: label,
                            data: data,
                            backgroundColor: color,
                            borderColor: color,
                            borderWidth: 2,
                            tension: 0.4,
                            fill: false,
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        scales: {
                            y: {
                                beginAtZero: true
                            }
                        },
                        plugins: {
                            legend: {
                                display: false
                            }
                        }
                    }
                });
            }

            const stepsLabels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
            const stepsData = [7000, 9000, 8200, 9500, 7800, 8800, 8500];
            createChart('stepsChart', 'line', stepsLabels, stepsData, 'Steps', '#34D399');

            const hydrationLabels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
            const hydrationData = [2.5, 2.8, 2.3, 3.0, 2.6, 2.9, 2.1];
            createChart('hydrationChart', 'bar', hydrationLabels, hydrationData, 'Liters', '#6EE7B7');

            const sleepLabels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
            const sleepData = [7, 8, 6.5, 7.8, 7.2, 8.5, 7.5];
            createChart('sleepChart', 'line', sleepLabels, sleepData, 'Hours', '#A7F3D0');

            const weightLabels = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'];
            const weightData = [75, 74.5, 74, 73.2, 73, 72.5];
            createChart('weightChart', 'line', weightLabels, weightData, 'Weight (kg)', '#10B981');

            const monthlyOverviewLabels = ['Week 1', 'Week 2', 'Week 3', 'Week 4'];
            const monthlyOverviewSteps = [60000, 65000, 70000, 75000];
            const monthlyOverviewHydration = [20, 22, 25, 23];
            const monthlyOverviewSleep = [50, 52, 55, 53];

            const ctxMonthly = document.getElementById('monthlyOverviewChart').getContext('2d');
            new Chart(ctxMonthly, {
                type: 'bar',
                data: {
                    labels: monthlyOverviewLabels,
                    datasets: [{
                        label: 'Total Steps (Thousands)',
                        data: monthlyOverviewSteps,
                        backgroundColor: '#34D399',
                        barThickness: 10,
                    }, {
                        label: 'Total Hydration (Liters)',
                        data: monthlyOverviewHydration,
                        backgroundColor: '#6EE7B7',
                        barThickness: 10,
                    }, {
                        label: 'Total Sleep (Hours)',
                        data: monthlyOverviewSleep,
                        backgroundColor: '#A7F3D0',
                        barThickness: 10,
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    },
                    plugins: {
                        legend: {
                            display: true
                        }
                    }
                }
            });


            document.querySelectorAll('aside nav a').forEach(link => {
                link.addEventListener('click', function(e) {
                    e.preventDefault();
                    document.querySelectorAll('aside nav a').forEach(l => l.classList.remove('active-link'));
                    this.classList.add('active-link');
                    const targetId = this.getAttribute('href').substring(1);
                    document.getElementById(targetId).scrollIntoView({ behavior: 'smooth' });
                });
            });

            const observer = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        document.querySelectorAll('aside nav a').forEach(link => link.classList.remove('active-link'));
                        const activeLink = document.querySelector(`aside nav a[href="#${entry.target.id}"]`);
                        if (activeLink) {
                            activeLink.classList.add('active-link');
                        }
                    }
                });
            }, { threshold: 0.5 });

            document.querySelectorAll('main > section').forEach(section => {
                observer.observe(section);
            });


        });
    </script>

</body>
</html>
