    <style>
        body { font-family: 'Poppins', sans-serif; }
        .progress-bar-container { position: relative; background-color: #e2e8f0; border-radius: 0.5rem; height: 0.75rem; overflow: hidden; }
        .progress-bar { position: absolute; top: 0; left: 0; height: 100%; background-color: #3b82f6; border-radius: 0.5rem; transition: width 0.3s ease-in-out; }
        .form-step { transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out; }
        .form-step.active { opacity: 1; transform: translateY(0); }
        .form-step.inactive { opacity: 0; transform: translateY(20px); pointer-events: none; }
        .input-field { border: 1px solid #e2e8f0; border-radius: 0.375rem; padding: 0.75rem; margin-bottom: 1rem; width: 100%; transition: border-color 0.3s ease; }
        .input-field:focus { outline: none; border-color: #3b82f6; box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2); }
        .btn-primary { background-color: #3b82f6; color: white; padding: 0.75rem 1.5rem; border-radius: 0.375rem; transition: background-color 0.3s ease; }
        .btn-primary:hover { background-color: #2563eb; }
        .btn-secondary { background-color: white; color: #3b82f6; border: 1px solid #3b82f6; padding: 0.6875rem 1.4375rem; border-radius: 0.375rem; transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease; }
        .btn-secondary:hover { background-color: #e2e8f0; border-color: #2563eb; color: #2563eb; }
        .shadow-crisp { box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06); }
        .hover- поднятие { transform: translateY(-3px); box-shadow: 0 7px 14px -3px rgba(0, 0, 0, 0.2), 0 4px 6px -2px rgba(0, 0, 0, 0.05); }
        .transition-поднятие { transition: transform 0.3s ease, box-shadow 0.3s ease; }
        .form-card { background-color: white; border-radius: 1rem; padding: 2rem; }
        .form-header { margin-bottom: 2rem; }
        .form-footer { margin-top: 2rem; display: flex; justify-content: space-between; align-items: center; }
        .form-title { font-size: 2.5rem; font-weight: 700; color: #1e3a8a; margin-bottom: 0.5rem; }
        .form-subtitle { font-size: 1.125rem; color: #475569; }
        .step-icon { display: inline-flex; align-items: center; justify-content: center; width: 2rem; height: 2rem; border-radius: 50%; background-color: #e2e8f0; color: #475569; margin-right: 0.5rem; font-weight: 600; }
        .step-icon.active-step { background-color: #3b82f6; color: white; }
        .step-label { font-weight: 500; color: #475569; }
        .steps-indicator { display: flex; justify-content: space-between; margin-bottom: 2rem; }
        .step { text-align: center; }
        .hidden { display: none; }
    </style>
</head>
<body class="bg-gray-50">
    <div class="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-100 to-white">
        <div class="container mx-auto px-6 py-12">
            <div class="form-card shadow-crisp">
                <div class="form-header text-center">
                    <h2 class="form-title">Tell Us About Yourself</h2>
                    <p class="form-subtitle">Help us personalize your experience.</p>
                </div>

                <div class="steps-indicator">
                    <div class="step">
                        <span class="step-icon active-step">1</span>
                        <p class="step-label">Personal Info</p>
                    </div>
                    <div class="step">
                        <span class="step-icon">2</span>
                        <p class="step-label">Preferences</p>
                    </div>
                    <div class="step">
                        <span class="step-icon">3</span>
                        <p class="step-label">Confirmation</p>
                    </div>
                </div>

                <div class="progress-bar-container mb-6">
                    <div class="progress-bar" id="progress-bar" style="width: 0%;"></div>
                </div>

                <form id="survey-form">
                    <div class="form-step active" id="step-1">
                        <h3 class="text-xl font-semibold text-gray-800 mb-4"><i class="fa-regular fa-user step-icon active-step"></i> Personal Information</h3>
                        <input type="text" class="input-field" placeholder="Your Name" required>
                        <input type="email" class="input-field" placeholder="Your Email" required>
                        <input type="tel" class="input-field" placeholder="Your Phone Number">
                    </div>

                    <div class="form-step inactive" id="step-2">
                        <h3 class="text-xl font-semibold text-gray-800 mb-4"><i class="fa-regular fa-heart step-icon"></i> Preferences</h3>
                        <label class="block text-gray-700 text-sm font-bold mb-2" for="preference-1">
                            <i class="fa-regular fa-check-square mr-2"></i> Favorite Color
                        </label>
                        <select class="input-field">
                            <option>Blue</option>
                            <option>Green</option>
                            <option>Other</option>
                        </select>
                        <label class="block text-gray-700 text-sm font-bold mb-2" for="preference-2">
                            <i class="fa-regular fa-check-square mr-2"></i> How do you spend your free time?
                        </label>
                        <textarea class="input-field" placeholder="Tell us more"></textarea>
                    </div>

                    <div class="form-step inactive" id="step-3">
                        <h3 class="text-xl font-semibold text-gray-800 mb-4"><i class="fa-regular fa-thumbs-up step-icon"></i> Confirmation</h3>
                        <div class="mb-4 text-center">
                            <img src="https://picsum.photos/200/300" alt="Confirmation Image" class="rounded-full shadow-md mx-auto mb-4">
                            <p class="text-gray-700">Please confirm your information is correct.</p>
                        </div>
                        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div><strong>Name:</strong> <span id="confirmation-name"></span></div>
                            <div><strong>Email:</strong> <span id="confirmation-email"></span></div>
                            <div><strong>Phone:</strong> <span id="confirmation-phone"></span></div>
                            <div><strong>Favorite Color:</strong> <span id="confirmation-color"></span></div>
                            <div><strong>Free Time Activities:</strong> <span id="confirmation-freetime"></span></div>
                        </div>
                    </div>

                    <div class="form-footer">
                        <button type="button" id="prev-btn" class="btn-secondary hidden" onclick="prevStep()">Previous</button>
                        <button type="button" id="next-btn" class="btn-primary" onclick="nextStep()">Next</button>
                        <button type="submit" id="submit-btn" class="btn-primary hidden">Submit</button>
                    </div>
                </form>
            </div>
        </div>
    </div>

    <script>
        let currentStep = 1;
        const totalSteps = 3;
        const formSteps = document.querySelectorAll('.form-step');
        const progressBar = document.getElementById('progress-bar');
        const prevBtn = document.getElementById('prev-btn');
        const nextBtn = document.getElementById('next-btn');
        const submitBtn = document.getElementById('submit-btn');
        const stepIcons = document.querySelectorAll('.step-icon');

        function updateProgress() {
            const progressPercentage = ((currentStep - 1) / (totalSteps - 1)) * 100;
            progressBar.style.width = `${progressPercentage}%`;

            stepIcons.forEach((icon, index) => {
                if (index < currentStep) {
                    icon.classList.add('active-step');
                } else {
                    icon.classList.remove('active-step');
                }
            });
        }

        function showStep(stepNumber) {
            formSteps.forEach((step) => {
                step.classList.add('inactive');
                step.classList.remove('active');
            });
            const currentFormStep = document.getElementById(`step-${stepNumber}`);
            currentFormStep.classList.remove('inactive');
            currentFormStep.classList.add('active');
        }

        function updateButtons() {
            if (currentStep === 1) {
                prevBtn.classList.add('hidden');
                nextBtn.classList.remove('hidden');
                submitBtn.classList.add('hidden');
            } else if (currentStep === totalSteps) {
                prevBtn.classList.remove('hidden');
                nextBtn.classList.add('hidden');
                submitBtn.classList.remove('hidden');
            } else {
                prevBtn.classList.remove('hidden');
                nextBtn.classList.remove('hidden');
                submitBtn.classList.add('hidden');
            }
        }

        function nextStep() {
            if (currentStep < totalSteps) {
                currentStep++;
                updateProgress();
                showStep(currentStep);
                updateButtons();

                if (currentStep === 3) {
                    document.getElementById('confirmation-name').innerText = document.querySelector('#step-1 input[type="text"]').value;
                    document.getElementById('confirmation-email').innerText = document.querySelector('#step-1 input[type="email"]').value;
                    document.getElementById('confirmation-phone').innerText = document.querySelector('#step-1 input[type="tel"]').value;
                    document.getElementById('confirmation-color').innerText = document.querySelector('#step-2 select').value;
                    document.getElementById('confirmation-freetime').innerText = document.querySelector('#step-2 textarea').value;
                }
            }
        }

        function prevStep() {
            if (currentStep > 1) {
                currentStep--;
                updateProgress();
                showStep(currentStep);
                updateButtons();
            }
        }

        document.getElementById('survey-form').addEventListener('submit', function(event) {
            event.preventDefault();
            alert('Survey submitted successfully!');
            console.log('Form Data: ', {
                name: document.querySelector('#step-1 input[type="text"]').value,
                email: document.querySelector('#step-1 input[type="email"]').value,
                phone: document.querySelector('#step-1 input[type="tel"]').value,
                color: document.querySelector('#step-2 select').value,
                freetime: document.querySelector('#step-2 textarea').value
            });
        });

        updateProgress();
        showStep(currentStep);
        updateButtons();
    </script>
</body>
</html>
