    <script>
        let readingMode = 'scroll';
        const panelModeButton = document.getElementById('panel-mode-button');
        const scrollModeButton = document.getElementById('scroll-mode-button');
        const comicPanelsContainer = document.getElementById('comic-panels-container');
        const panelNavigation = document.querySelector('.panel-navigation');
        const comicPanelReaders = document.querySelectorAll('.comic-panel-reader');
        const nextPanelButton = document.getElementById('next-panel-button');
        const prevPanelButton = document.getElementById('prev-panel-button');
        let currentPanelIndex = 0;

        function setReadingMode(mode) {
            readingMode = mode;
            if (mode === 'panel') {
                panelModeButton.classList.add('active');
                scrollModeButton.classList.remove('active');
                comicPanelsContainer.classList.remove('scroll-mode');
                comicPanelsContainer.classList.add('panel-mode');
                panelNavigation.classList.remove('hidden');
                panelNavigation.classList.add('flex');
                comicPanelReaders.forEach((panel, index) => {
                    if (index !== 0) {
                        panel.classList.add('hidden');
                    } else {
                        panel.classList.remove('hidden');
                    }
                });
                updatePanelNavigation();
            } else if (mode === 'scroll') {
                scrollModeButton.classList.add('active');
                panelModeButton.classList.remove('active');
                comicPanelsContainer.classList.remove('panel-mode');
                comicPanelsContainer.classList.add('scroll-mode');
                panelNavigation.classList.add('hidden');
                panelNavigation.classList.remove('flex');
                comicPanelReaders.forEach(panel => {
                    panel.classList.remove('hidden');
                });
            }
        }

        nextPanelButton.addEventListener('click', () => {
            if (currentPanelIndex < comicPanelReaders.length - 1) {
                comicPanelReaders[currentPanelIndex].classList.add('hidden');
                currentPanelIndex++;
                comicPanelReaders[currentPanelIndex].classList.remove('hidden');
                updatePanelNavigation();
                gsap.fromTo(comicPanelReaders[currentPanelIndex], {opacity: 0, x: 50}, {opacity: 1, x: 0, duration: 0.5});
            }
        });

        prevPanelButton.addEventListener('click', () => {
            if (currentPanelIndex > 0) {
                comicPanelReaders[currentPanelIndex].classList.add('hidden');
                currentPanelIndex--;
                comicPanelReaders[currentPanelIndex].classList.remove('hidden');
                updatePanelNavigation();
                gsap.fromTo(comicPanelReaders[currentPanelIndex], {opacity: 0, x: -50}, {opacity: 1, x: 0, duration: 0.5});
            }
        });

        function updatePanelNavigation() {
            prevPanelButton.disabled = currentPanelIndex === 0;
            nextPanelButton.disabled = currentPanelIndex === comicPanelReaders.length - 1;
        }

        comicPanelReaders.forEach(panel => {
            panel.addEventListener('mouseenter', () => {
                panel.classList.add('panel-zoom-in');
            });
            panel.addEventListener('mouseleave', () => {
                panel.classList.remove('panel-zoom-in');
            });
        });

        gsap.from('.hero-text-content h1', {opacity: 0, y: 50, duration: 1});
        gsap.from('.hero-text-content p', {opacity: 0, y: 30, duration: 1, delay: 0.3});
        gsap.from('.hero-cta-pulse', {opacity: 0, y: 30, duration: 1, delay: 0.6, stagger: 0.2});
        gsap.from('.hero-image', {opacity: 0, x: 50, duration: 1, delay: 0.9});
    </script>

</body>
</html>
