        <div class="container mx-auto px-6 text-center">
            <p class="text-gray-600">© 2024 Feedback Central. All rights reserved.</p>
            <p class="mt-4 text-sm text-gray-500">Powered by Awesome UI & Tailwind CSS</p>
        </div>
    </footer>

    <script>
        function setRating(rating) {
            document.getElementById('rating').value = rating;
            console.log('Rating selected:', rating);
        }
    </script>
</body>
</html>
