                    <button id="tab-room-2" class="breakout-tab-inactive px-4 py-2 rounded-lg focus:outline-none transition-colors" onclick="openBreakoutRoom('room-2')">Room 2</button>
                    <button id="tab-room-3" class="breakout-tab-inactive px-4 py-2 rounded-lg focus:outline-none transition-colors" onclick="openBreakoutRoom('room-3')">Room 3</button>
