                    <div id="room-2" class="breakout-room-content fade-in hidden absolute top-0 left-0 w-full">
                        <h3 class="font-semibold mb-2">Room 2: Marketing Strategies</h3>
                        <div class="grid grid-cols-2 gap-4">
                            <div><img src="https://picsum.photos/204/300" alt="Room 2 Image 1" class="rounded-lg dynamic-shadow"></div>
                            <div><img src="https://picsum.photos/205/300" alt="Room 2 Image 2" class="rounded-lg dynamic-shadow"></div>
                        </div>
                    </div>

                     <div id="room-3" class="breakout-room-content fade-in hidden absolute top-0 left-0 w-full">
                        <h3 class="font-semibold mb-2">Room 3: Networking Lounge</h3>
                        <p class="dark-mode-secondary-text">Relax and connect with other attendees.</p>
                        <div class="grid grid-cols-1 gap-4">
                             <div><img src="https://picsum.photos/206/300" alt="Room 3 Image 1" class="rounded-lg dynamic-shadow"></div>
