    <footer class="dark-mode-bg dark-mode-border border-t py-4">
        <div class="container mx-auto px-6 text-center dark-mode-secondary-text">
            <p>&copy; 2024 Virtual Conference Platform. All rights reserved.</p>
        </div>
    </footer>

    <script>
        lucide.createIcons();

        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        function openBreakoutRoom(roomId) {
            const roomContents = document.querySelectorAll('.breakout-room-content');
            const tabs = document.querySelectorAll('.breakout-tab-active, .breakout-tab-inactive');

            roomContents.forEach(room => {
                room.classList.add('hidden');
                room.classList.remove('active');
            });
            tabs.forEach(tab => {
                tab.classList.remove('breakout-tab-active');
                tab.classList.add('breakout-tab-inactive');
            });

            document.getElementById(roomId).classList.remove('hidden');
            document.getElementById(roomId).classList.add('active');
            document.getElementById('tab-' + roomId).classList.remove('breakout-tab-inactive');
            document.getElementById('tab-' + roomId).classList.add('breakout-tab-active');

             setTimeout(() => {
                document.getElementById(roomId).classList.add('fade-in');
             }, 10);
        }
    </script>
</body>
</html>
