                    <h4 class="text-xl font-semibold mb-4">Follow Us</h4>
                    <div class="flex space-x-4">
                        <a href="#" class="hover:text-white"><i class="fab fa-facebook-square fa-lg"></i></a>
                        <a href="#" class="hover:text-white"><i class="fab fa-instagram fa-lg"></i></a>
                        <a href="#" class="hover:text-white"><i class="fab fa-twitter-square fa-lg"></i></a>
                    </div>
                </div>
            </div>
            <div class="mt-8 text-center border-t border-gray-700 pt-8">
                <p>&copy; 2024 Art Gallery. All rights reserved.</p>
            </div>
        </div>
    </footer>

    <script>
        const filterButtons = document.querySelectorAll('.filter-btn');
        const galleryItems = document.querySelectorAll('.gallery-item');
        const artworkGrid = document.getElementById('artwork-grid');
        const lightbox = document.getElementById('lightbox');
        const lightboxImage = document.getElementById('lightbox-image');
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        filterButtons.forEach(button => {
            button.addEventListener('click', () => {
                const filterValue = button.dataset.filter;

                filterButtons.forEach(btn => btn.classList.remove('active'));
                button.classList.add('active');

                gsap.to(galleryItems, {
                    opacity: 0,
                    scale: 0.8,
                    duration: 0.3,
                    stagger: 0.05,
                    onComplete: () => {
                        galleryItems.forEach(item => {
                            if (filterValue === 'all' || item.classList.contains(filterValue)) {
                                item.style.display = 'block';
                            } else {
                                item.style.display = 'none';
                            }
                        });

                        gsap.fromTo(galleryItems, {
                            opacity: 0,
                            scale: 0.8
                        }, {
                            opacity: 1,
                            scale: 1,
                            duration: 0.4,
                            stagger: 0.05,
                            ease: "power2.out"
                        });
                    }
                });
            });
        });

        artworkGrid.addEventListener('click', function(event) {
            if (event.target.classList.contains('open-lightbox')) {
                let imageSrc = event.target.dataset.image;
                lightboxImage.src = imageSrc;
                lightbox.style.display = 'block';
                gsap.fromTo(lightboxContent, { opacity: 0, scale: 0.9 }, { opacity: 1, scale: 1, duration: 0.3, ease: "power2.out" });
            }
        });

        function closeLightbox() {
            gsap.to(lightboxContent, { opacity: 0, scale: 0.9, duration: 0.2, ease: "power1.in", onComplete: () => {
                lightbox.style.display = 'none';
                lightboxImage.src = '';
            }});
        }

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        const lightboxContent = lightbox.querySelector('.lightbox-content');

    </script>

</body>
</html>
