<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ProKanban - Productivity Perfected</title>
    <link href="https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&display=swap" rel="stylesheet">
    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Roboto', sans-serif;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }
        .kanban-board {
            display: flex;
            overflow-x: auto;
            gap: 24px;
        }
        .kanban-column {
            flex: 0 0 300px;
            @apply bg-white rounded-lg shadow-md p-6;
        }
        .kanban-column-header {
            @apply text-xl font-semibold mb-4 text-gray-800;
        }
        .kanban-task {
            @apply bg-white shadow-sm rounded-md p-4 mb-4 cursor-grab hover:shadow-md transition-shadow duration-200;
        }
        .kanban-task:last-child {
            margin-bottom: 0;
        }
        .kanban-task-title {
            @apply font-medium text-gray-700 mb-2;
        }
        .kanban-task-description {
            @apply text-sm text-gray-500;
        }
        .is-dragging {
            @apply shadow-lg border-2 border-teal-500;
            opacity: 0.9;
        }
        .drag-over {
            @apply bg-teal-50;
        }
        .add-task-button {
            @apply bg-teal-500 hover:bg-teal-600 text-white font-semibold py-2 px-4 rounded-full transition-colors duration-200 block w-full text-center mt-4;
        }
        .add-column-button {
            @apply bg-gray-200 hover:bg-gray-300 text-gray-700 font-semibold py-2 px-4 rounded-full transition-colors duration-200 inline-flex items-center justify-center;
        }
        .column-controls {
            @apply absolute right-4 top-4 hidden group-hover:block;
        }
        .column-controls button {
            @apply text-gray-500 hover:text-red-500 transition-colors duration-200;
        }
        .column-header-container {
            @apply relative group;
        }
    </style>
</head>
<body class="bg-teal-50">
    <header class="bg-white shadow-md sticky top-0 z-50">
        <nav class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div class="flex justify-between h-16 items-center">
                <div class="flex items-center">
                    <span class="font-bold text-xl text-teal-600">ProKanban</span>
                </div>
                <div class="hidden md:flex space-x-4">
                    <button class="add-column-button">
                        <i class="fa-solid fa-plus mr-2"></i> Add Column
                    </button>
                </div>
                <div class="md:hidden">
                    <button class="text-gray-500 hover:text-gray-600 focus:outline-none focus:text-gray-600" aria-label="Open menu">
                        <i class="fa-solid fa-bars"></i>
                    </button>
                </div>
            </div>
        </nav>
    </header>

    <main class="container mx-auto px-4 py-8">
        <section class="mb-8">
            <h2 class="text-2xl font-bold text-gray-800 mb-4">Project Dashboard</h2>
            <div class="kanban-board" id="kanban-board">
                <div class="kanban-column" data-column-id="todo">
                    <div class="column-header-container">
                        <h3 class="kanban-column-header">To Do</h3>
                        <div class="column-controls">
                            <button aria-label="Delete Column"><i class="fa-solid fa-trash-alt"></i></button>
                        </div>
                    </div>
                    <div id="todo-tasks" class="kanban-tasks" data-column-target="todo">
                        <div class="kanban-task" draggable="true" data-task-id="1">
                            <h4 class="kanban-task-title">Brainstorming Session</h4>
                            <p class="kanban-task-description">Gather ideas for the new campaign.</p>
                            <img src="https://picsum.photos/200/300?random=1" class="mt-2 rounded-md" alt="Example Image">
                        </div>
                        <div class="kanban-task" draggable="true" data-task-id="2">
                            <h4 class="kanban-task-title">Wireframe Design</h4>
                            <p class="kanban-task-description">Create initial wireframes for the app.</p>
                            <img src="https://picsum.photos/200/300?random=2" class="mt-2 rounded-md" alt="Example Image">
                        </div>
                    </div>
                    <button class="add-task-button" data-column-target="todo"><i class="fa-solid fa-plus mr-2"></i> Add Task</button>
                </div>

                <div class="kanban-column" data-column-id="inprogress">
                    <div class="column-header-container">
                        <h3 class="kanban-column-header">In Progress</h3>
                        <div class="column-controls">
                            <button aria-label="Delete Column"><i class="fa-solid fa-trash-alt"></i></button>
                        </div>
                    </div>
                    <div id="inprogress-tasks" class="kanban-tasks" data-column-target="inprogress">
                        <div class="kanban-task" draggable="true" data-task-id="3">
                            <h4 class="kanban-task-title">Develop UI Components</h4>
                            <p class="kanban-task-description">Start coding reusable UI components.</p>
                            <img src="https://picsum.photos/200/300?random=3" class="mt-2 rounded-md" alt="Example Image">
                        </div>
                    </div>
                    <button class="add-task-button" data-column-target="inprogress"><i class="fa-solid fa-plus mr-2"></i> Add Task</button>
                </div>

                <div class="kanban-column" data-column-id="done">
                    <div class="column-header-container">
                        <h3 class="kanban-column-header">Done</h3>
                        <div class="column-controls">
                            <button aria-label="Delete Column"><i class="fa-solid fa-trash-alt"></i></button>
                        </div>
                    </div>
                    <div id="done-tasks" class="kanban-tasks" data-column-target="done">
                        <div class="kanban-task" draggable="true" data-task-id="4">
                            <h4 class="kanban-task-title">User Research</h4>
                            <p class="kanban-task-description">Complete user interviews and surveys.</p>
                            <img src="https://picsum.photos/200/300?random=4" class="mt-2 rounded-md" alt="Example Image">
                        </div>
                    </div>
                    <button class="add-task-button" data-column-target="done"><i class="fa-solid fa-plus mr-2"></i> Add Task</button>
                </div>
            </div>
        </section>
    </main>

    <footer class="bg-white shadow-md mt-16 py-4">
        <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center text-gray-500">
            <p>&copy; 2024 ProKanban. All rights reserved.</p>
        </div>
    </footer>

    <script>
        const tasks = document.querySelectorAll('.kanban-task');
        const columns = document.querySelectorAll('.kanban-tasks');
        let draggedTask = null;

        tasks.forEach(task => {
            task.addEventListener('dragstart', (e) => {
                draggedTask = task;
                task.classList.add('is-dragging');
            });

            task.addEventListener('dragend', (e) => {
                draggedTask = null;
                task.classList.remove('is-dragging');
            });
        });

        columns.forEach(column => {
            column.addEventListener('dragover', (e) => {
                e.preventDefault();
                if (!column.classList.contains('drag-over')) {
                    column.classList.add('drag-over');
                }
            });

            column.addEventListener('dragleave', (e) => {
                column.classList.remove('drag-over');
            });

            column.addEventListener('drop', (e) => {
                e.preventDefault();
                column.classList.remove('drag-over');
                if (draggedTask) {
                    column.appendChild(draggedTask);
                }
            });
        });
    </script>
</body>
</html>
