    <style>
        body {
            font-family: 'DM Sans', sans-serif;
        }
        .serif-heading {
            font-family: 'DM Serif Display', serif;
        }
        .hero-section {
            background-color: #541E2B;
        }
        .gold-accent {
            color: #D4AF37;
        }
        .hero-gradient {
            background: linear-gradient(160deg, #541E2B 30%, #73303F 70%);
        }
        .wine-animation-container {
            overflow: hidden;
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
        }
        .wine-animation-container img {
            position: absolute;
            opacity: 0.6;
            animation: wineFloat 20s linear infinite;
            width: 150px;
        }
        .wine-animation-container img:nth-child(1) {
            top: 10%;
            left: 20%;
            animation-delay: 0s;
        }
        .wine-animation-container img:nth-child(2) {
            top: 40%;
            left: 70%;
            animation-delay: 5s;
            width: 100px;
        }
        .wine-animation-container img:nth-child(3) {
            top: 70%;
            left: 10%;
            animation-delay: 10s;
            width: 120px;
        }
        .wine-animation-container img:nth-child(4) {
            top: 20%;
            left: 85%;
            animation-delay: 15s;
            width: 80px;
        }


        @keyframes wineFloat {
            0% {
                transform: translateY(0) rotate(0deg);
                opacity: 0.6;
            }
            50% {
                transform: translateY(-30px) rotate(10deg);
                opacity: 0.8;
            }
            100% {
                transform: translateY(0) rotate(0deg);
                opacity: 0.6;
            }
        }

        .btn-gold {
            background-color: #D4AF37;
            color: #541E2B;
        }
        .btn-gold:hover {
            background-color: #C09B23;
        }
        .shadow-wine {
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
        }
        .layered-card {
            position: relative;
            overflow: hidden;
            border-radius: 0.75rem;
        }

        .layered-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(255, 255, 255, 0.05);
            pointer-events: none;
        }

        .layered-card::after {
            content: '';
            position: absolute;
            top: 5px;
            left: 5px;
            right: 5px;
            bottom: 5px;
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 0.6rem;
            pointer-events: none;
        }
        .subscription-step.active {
            border-color: #D4AF37;
            background-color: rgba(212, 175, 55, 0.1);
        }

        .subscription-step.completed::before {
            content: '\f00c';
            font-family: 'Font Awesome 6 Free';
            font-weight: 900;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            color: #D4AF37;
            font-size: 1.2rem;
        }
        .wine-glass-bg {
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            opacity: 0.1;
            background-image: url('https://picsum.photos/id/101/400/400'); /* Example background image */
            background-size: cover;
            background-position: center;
            filter: grayscale(100%) blur(10px);
            transform: rotate(-20deg);
        }
        .elegant-shadow {
            box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
        }
        .hover-scale-up {
            transition: transform 0.3s ease-out;
        }

        .hover-scale-up:hover {
            transform: scale(1.05);
        }
        .wine-bottle-tilt {
            transform: rotate(-5deg);
        }

    </style>
</head>
