            </p>
            <div class="space-y-4">
                <input type="text" placeholder="Your Name" class="shadow-sm focus:ring-brown-200 focus:border-brown-200 block w-full sm:text-sm border-gray-300 rounded-md bg-beige-50 text-brown-100">
                <input type="email" placeholder="Your Email" class="shadow-sm focus:ring-brown-200 focus:border-brown-200 block w-full sm:text-sm border-gray-300 rounded-md bg-beige-50 text-brown-100">
                <textarea rows="4" placeholder="Your Message" class="shadow-sm focus:ring-brown-200 focus:border-brown-200 block w-full sm:text-sm border-gray-300 rounded-md bg-beige-50 text-brown-100"></textarea>
                <button class="bg-brown-200 text-beige-100 px-6 py-3 rounded-full font-medium hover:bg-brown-300 transition-colors w-full">
                    Send Message
                </button>
            </div>
            <div class="mt-8 flex justify-center space-x-6">
                <a href="#" class="text-brown-100 hover:text-brown-200"><i class="fab fa-facebook-square text-2xl"></i></a>
                <a href="#" class="text-brown-100 hover:text-brown-200"><i class="fab fa-twitter-square text-2xl"></i></a>
                <a href="#" class="text-brown-100 hover:text-brown-200"><i class="fab fa-instagram-square text-2xl"></i></a>
            </div>
        </div>
    </section>

    <footer class="bg-brown-300 text-beige-100 py-12 vignette">
        <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
            <p>&copy; 2024 Echoes of Time. All rights reserved.</p>
            <p class="mt-4">Crafted with <i class="fa fa-heart text-red-500"></i> and historical passion.</p>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            gsap.registerPlugin(ScrollTrigger);

            gsap.utils.toArray(".timeline-item").forEach(item => {
                gsap.from(item.querySelector('.timeline-content'), {
                    opacity: 0,
                    y: 50,
                    duration: 1,
                    ease: "power2.out",
                    scrollTrigger: {
                        trigger: item,
                        start: "top 80%",
                        end: "top 20%",
                        toggleActions: "play none none reverse"
                    }
                });
            });

            const fadeInElements = document.querySelectorAll('.animate-fade-in');
            fadeInElements.forEach(element => {
                gsap.fromTo(element, { opacity: 0 }, {
                    opacity: 1,
                    duration: 1.5,
                    delay: parseFloat(element.classList.contains('delay-200') ? 0.2 : (element.classList.contains('delay-400') ? 0.4 : 0)),
                    ease: "power2.out"
                });
            });
        });
    </script>
</body>
</html>
