<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Digital Journal</title>
    <link href="https://fonts.googleapis.com/css2?family=Lora:wght@400;700&family=Nunito:wght@400;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Nunito', sans-serif;
            background-color: #f8f8f8;
            color: #333;
        }
        h1, h2, h3, h4, h5, h6 {
            font-family: 'Lora', serif;
            color: #1e293b;
        }
        .hero-section {
            background-color: #f8fafc;
        }
        .hero-title {
            font-size: 3rem;
            line-height: 1.2;
            font-weight: 700;
            letter-spacing: -0.05em;
            color: #1e293b;
        }
        .hero-subtitle {
            font-size: 1.5rem;
            color: #6b7280;
        }
        .journal-entry-title {
            font-size: 1.75rem;
            font-weight: 700;
            color: #1e293b;
        }
        .journal-entry-date {
            font-size: 1rem;
            color: #9ca3af;
        }
        .journal-entry-content {
            font-size: 1.1rem;
            color: #4b5563;
        }
        .subtle-shadow {
            box-shadow: 0 2px 4px 0 rgba(0,0,0,0.05);
        }
        .gentle-gradient {
            background: linear-gradient(135deg, #e0f7fa, #f1f8e9);
        }
        .fade-in {
            opacity: 0;
            transition: opacity 0.5s ease-out;
        }
        .fade-in.visible {
            opacity: 1;
        }
        .hero-image-overlay {
            background-color: rgba(255, 255, 255, 0.6);
            mix-blend-mode: lighten;
        }
        .hover-lift {
            transition: transform 0.3s ease-in-out;
        }
        .hover-lift:hover {
            transform: translateY(-5px);
        }
        .hero-animation {
            animation: heroFadeIn 1s ease-out forwards;
            opacity: 0;
        }

        @keyframes heroFadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
    </style>
</head>
<body class="bg-gray-50">

    <header class="bg-white shadow-sm sticky top-0 z-50">
        <nav class="container mx-auto px-6 py-4">
            <div class="flex justify-between items-center">
                <div class="text-xl font-bold text-gray-800">
                    My Digital Journal
                </div>
                <div class="hidden md:flex space-x-6">
                    <a href="#entries" class="text-gray-700 hover:text-blue-500 transition-colors">Entries</a>
                    <a href="#categories" class="text-gray-700 hover:text-blue-500 transition-colors">Categories</a>
                    <a href="#about" class="text-gray-700 hover:text-blue-500 transition-colors">About</a>
                </div>
                <div class="md:hidden">
                    <button id="mobile-menu-button" class="text-gray-500 hover:text-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-500">
                        <i class="fa fa-bars"></i>
                    </button>
                </div>
            </div>
            <div class="md:hidden hidden" id="mobile-menu">
                <div class="flex flex-col mt-4 space-y-3">
                    <a href="#entries" class="text-gray-700 hover:text-blue-500 transition-colors py-2 px-4 block">Entries</a>
                    <a href="#categories" class="text-gray-700 hover:text-blue-500 transition-colors py-2 px-4 block">Categories</a>
                    <a href="#about" class="text-gray-700 hover:text-blue-500 transition-colors py-2 px-4 block">About</a>
                </div>
            </div>
        </nav>
    </header>

    <section class="hero-section gentle-gradient py-24 md:py-32">
        <div class="container mx-auto px-6 text-center">
            <h1 class="hero-title hero-animation mb-4">
                Welcome to Your Thoughts Space
            </h1>
            <p class="hero-subtitle hero-animation opacity-80 max-w-xl mx-auto" style="animation-delay: 0.2s;">
                Capture your moments, reflect on your days, and organize your thoughts in a beautiful digital journal.
            </p>
            <div class="mt-10 hero-animation" style="animation-delay: 0.4s;">
                <a href="#entries" class="inline-flex items-center bg-blue-500 hover:bg-blue-600 text-white font-semibold py-3 px-6 rounded-full transition-colors subtle-shadow hover-lift">
                    <i class="fa fa-book mr-2"></i>
                    View Entries
