<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Live Chat Support</title>
    <link href="https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'Roboto', sans-serif; }
        .scrollbar-thin::-webkit-scrollbar { width: 5px; }
        .scrollbar-thin::-webkit-scrollbar-track { background-color: transparent; }
        .scrollbar-thin::-webkit-scrollbar-thumb { background-color: #a0aec0; border-radius: 20px; }
        .scrollbar-thin::-webkit-scrollbar-thumb:hover { background-color: #718096; }
        @keyframes slide-up { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .slide-up { animation: slide-up 0.3s ease-out forwards; }
        @keyframes typing-indicator {
            0% { box-shadow: 0 0 0 0 rgba(160, 174, 192, 0.15); }
            50% { box-shadow: 0 0 0 6px rgba(160, 174, 192, 0.15); }
            100% { box-shadow: 0 0 0 0 rgba(160, 174, 192, 0.15); }
        }
        .typing-dots span {
            display: inline-block;
            width: 6px;
            height: 6px;
            margin-right: 4px;
            border-radius: 50%;
            background-color: #a0aec0;
            opacity: 0.6;
            animation: typing-indicator 1.5s infinite;
        }
        .typing-dots span:nth-child(2) { animation-delay: 0.2s; }
        .typing-dots span:nth-child(3) { animation-delay: 0.4s; }
    </style>
</head>
<body class="bg-blue-50">
    <div id="chat-container" class="fixed bottom-8 right-8 md:right-16 z-50">
        <button id="chat-toggle" class="w-16 h-16 rounded-full bg-blue-500 hover:bg-blue-600 text-white shadow-lg transition-transform transform hover:scale-105 focus:outline-none flex items-center justify-center">
            <i class="fas fa-comment-dots text-2xl"></i>
        </button>

        <div id="chat-window" class="hidden md:block absolute bottom-0 right-0 mb-20 md:mb-0 mr-0 md:mr-8 w-full md:w-96 rounded-lg shadow-xl overflow-hidden bg-white border border-blue-100">
            <div class="bg-blue-100 p-4 border-b border-blue-200 flex items-center justify-between">
                <div class="flex items-center">
                    <div class="w-10 h-10 rounded-full overflow-hidden mr-3">
                        <img src="https://picsum.photos/id/25/100/100" alt="Support Agent" class="w-full h-full object-cover">
                    </div>
                    <div>
                        <h5 class="font-semibold text-blue-800">Support Agent</h5>
                        <p class="text-sm text-blue-500">Online</p>
                    </div>
                </div>
                <button id="chat-close-btn" class="text-blue-500 hover:text-blue-700 focus:outline-none">
                    <i class="fas fa-times"></i>
                </button>
            </div>

            <div id="messages-container" class="p-4 h-96 overflow-y-auto scrollbar-thin flex flex-col space-y-2">
                <div class="flex justify-start">
                    <div class="bg-blue-200 text-blue-800 p-3 rounded-xl rounded-tl-none max-w-xs slide-up">
                        Hello! How can I help you today?
                    </div>
                </div>
                <div class="flex justify-end">
                    <div class="bg-gray-100 text-gray-800 p-3 rounded-xl rounded-tr-none max-w-xs slide-up">
                        Hi there! I have a question about my order.
                    </div>
                </div>
                <div id="typing-indicator" class="flex justify-start hidden">
                    <div class="bg-blue-200 p-3 rounded-xl rounded-tl-none max-w-xs flex items-center">
                        <div class="typing-dots">
                            <span></span>
                            <span></span>
                            <span></span>
                        </div>
                    </div>
                </div>
            </div>

            <div class="p-3 border-t border-blue-200 bg-blue-50">
                <form id="message-form" class="flex items-center">
                    <input type="text" id="message-input" placeholder="Type your message..." class="flex-grow rounded-full bg-white border border-blue-300 focus:border-blue-500 focus:ring-blue-500 p-2 pl-4 pr-2 focus:outline-none">
                    <button type="submit" class="bg-blue-500 hover:bg-blue-600 text-white p-2 rounded-full ml-2 focus:outline-none">
                        <i class="fas fa-paper-plane"></i>
                    </button>
                </form>
            </div>
        </div>
    </div>

    <script>
        const chatToggle = document.getElementById('chat-toggle');
        const chatWindow = document.getElementById('chat-window');
        const chatCloseBtn = document.getElementById('chat-close-btn');
        const messagesContainer = document.getElementById('messages-container');
        const messageForm = document.getElementById('message-form');
        const messageInput = document.getElementById('message-input');
        const typingIndicator = document.getElementById('typing-indicator');

        chatToggle.addEventListener('click', () => {
            chatWindow.classList.toggle('hidden');
        });

        chatCloseBtn.addEventListener('click', () => {
            chatWindow.classList.add('hidden');
        });

        messageForm.addEventListener('submit', (event) => {
            event.preventDefault();
            const messageText = messageInput.value.trim();
            if (messageText) {
                addMessage(messageText, 'user');
                messageInput.value = '';

                typingIndicator.classList.remove('hidden');
                messagesContainer.scrollTop = messagesContainer.scrollHeight;

                setTimeout(() => {
                    typingIndicator.classList.add('hidden');
                    addMessage("Thank you for your message! We are looking into your question and will get back to you shortly.", 'support');
                }, 1500);
            }
        });

        function addMessage(message, sender) {
            const messageDiv = document.createElement('div');
            const messageBubble = document.createElement('div');
            messageBubble.textContent = message;
            messageBubble.classList.add('p-3', 'rounded-xl', 'max-w-xs', 'slide-up');

            if (sender === 'user') {
                messageDiv.classList.add('flex', 'justify-end');
                messageBubble.classList.add('bg-gray-100', 'text-gray-800', 'rounded-tr-none');
            } else if (sender === 'support') {
                messageDiv.classList.add('flex', 'justify-start');
                messageBubble.classList.add('bg-blue-200', 'text-blue-800', 'rounded-tl-none');
            }

            messageDiv.appendChild(messageBubble);
            messagesContainer.appendChild(messageDiv);
            messagesContainer.scrollTop = messagesContainer.scrollHeight;
        }
    </script>
</body>
</html>
