    <style>
        body {
            font-family: 'Poppins', sans-serif;
        }
        .hero-section {
            background: linear-gradient(135deg, #4c3589, #2e1a68, #09042a);
            background-size: 200% 200%;
            animation: gradient 10s ease infinite, lights 5s linear infinite;
            position: relative;
            overflow: hidden;
        }
        @keyframes gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        @keyframes lights {
            0% {
                box-shadow:
                    -50px -50px 100px rgba(79, 57, 145, 0.3),
                    50px 50px 100px rgba(46, 26, 104, 0.3),
                    0 0 150px rgba(9, 4, 42, 0.5);
            }
            50% {
                box-shadow:
                    50px -50px 100px rgba(79, 57, 145, 0.3),
                    -50px 50px 100px rgba(46, 26, 104, 0.3),
                    0 0 200px rgba(9, 4, 42, 0.7);
            }
            100% {
                box-shadow:
                    -50px -50px 100px rgba(79, 57, 145, 0.3),
                    50px 50px 100px rgba(46, 26, 104, 0.3),
                    0 0 150px rgba(9, 4, 42, 0.5);
            }
        }
        .stage-lights div {
            position: absolute;
            background: radial-gradient(circle, rgba(102, 51, 153, 0.2), transparent);
            pointer-events: none;
            animation: moveLights 7s linear infinite alternate;
        }
        .stage-lights div:nth-child(1) { top: 10%; left: 20%; width: 80px; height: 80px; animation-delay: 0s; }
        .stage-lights div:nth-child(2) { top: 15%; right: 25%; width: 60px; height: 60px; animation-delay: 1s; }
        .stage-lights div:nth-child(3) { bottom: 20%; left: 30%; width: 100px; height: 100px; animation-delay: 2s; }
        .stage-lights div:nth-child(4) { bottom: 10%; right: 15%; width: 70px; height: 70px; animation-delay: 3s; }
        .stage-lights div:nth-child(5) { top: 30%; left: 10%; width: 90px; height: 90px; animation-delay: 4s; }
        @keyframes moveLights {
            0% { transform: translate(0, 0); opacity: 0.8; }
            100% { transform: translate(50px, 50px); opacity: 0.3; }
        }
        .event-card:hover {
            transform: scale(1.03);
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
        }
        .event-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(135deg, rgba(76, 53, 137, 0.7), rgba(46, 26, 104, 0.7));
            opacity: 0;
            transition: opacity 0.3s ease;
            border-radius: inherit;
        }
        .event-card:hover::before {
            opacity: 1;
        }
        .hero-content-container {
            position: relative;
            z-index: 10;
        }
    </style>
</head>
