<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Luxury Hotel Website</title>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700&family=Nunito+Sans:wght@400;600&display=swap" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <style>
        body {
            font-family: 'Nunito Sans', sans-serif;
            color: #333;
        }
        h1, h2, h3, h4, h5, h6 {
            font-family: 'Playfair Display', serif;
            color: #1A237E;
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .parallax-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 120%;
            background-size: cover;
            background-position: center;
            transform: translateZ(-1px) scale(2);
            will-change: transform;
        }
        .parallax-content {
            position: relative;
            z-index: 1;
        }
        .availability-calendar {
            width: 100%;
            border-collapse: collapse;
        }
        .availability-calendar th, .availability-calendar td {
            padding: 0.75rem;
            border: 1px solid #e2e8f0;
            text-align: center;
        }
        .availability-calendar th {
            font-weight: 600;
        }
        .available {
            background-color: #f0fdfa;
            color: #047857;
            cursor: pointer;
            transition: background-color 0.3s ease;
        }
        .available:hover {
            background-color: #ccfbf1;
        }
        .unavailable {
            background-color: #fef2f2;
            color: #b91c1c;
            opacity: 0.6;
        }
        .selected-date {
            background-color: #3b82f6;
            color: white;
        }
        .react-360-player {
            width: 100%;
            height: 600px;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .fade-in {
            animation: fadeIn 1s ease-out forwards;
            opacity: 0;
        }
        .luxury-gold {
            color: #FFD700;
        }
        .luxury-bg-gold {
            background-color: #FFD700;
        }
        .luxury-border-gold {
            border-color: #FFD700;
        }
        .luxury-blue {
            color: #1A237E;
        }
        .luxury-bg-blue {
            background-color: #1A237E;
        }
        .luxury-border-blue {
            border-color: #1A237E;
        }
        .btn-luxury {
            background-color: #FFD700;
            color: #1A237E;
            transition: background-color 0.3s ease, color 0.3s ease, transform 0.2s ease-in-out;
        }
        .btn-luxury:hover {
            background-color: #1A237E;
            color: #FFD700;
            transform: scale(1.05);
        }
        .card-shadow {
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);
        }
        .parallax-hero-gradient {
            background: linear-gradient(135deg, #1A237E, #3F51B5, #5C6BC0);
            background-size: 200% 200%;
            animation: gradient 15s ease infinite;
        }

        @keyframes gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .zoom-in-out-effect {
            transition: transform 0.3s ease-in-out;
        }

        .zoom-in-out-effect:hover {
            transform: scale(1.05);
        }
    </style>
</head>
