    <title>NeonCode Bootcamp</title>
    <link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;700&family=Fira+Code:wght@400;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Space Grotesk', sans-serif;
            background-color: #0a0a0a;
            color: #f0f0f0;
        }
        .hero-neon-gradient {
            background: linear-gradient(150deg, #0a0a0a 30%, #00ff80 90%);
        }
        .code-snippet {
            font-family: 'Fira Code', monospace;
            background-color: #1a1a1a;
            color: #00ff80;
            padding: 1rem;
            border-radius: 0.5rem;
            overflow-x: auto;
            font-size: 0.8rem;
            white-space: pre;
            tab-size: 2;
        }
        .neon-text {
            text-shadow: 0 0 5px #00ff80, 0 0 10px #00ff80, 0 0 20px #00ff80;
        }
        .btn-neon {
            background-color: #00ff80;
            color: #0a0a0a;
            transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
            box-shadow: 0 0 5px #00ff80, 0 0 10px #00ff80;
        }
        .btn-neon:hover {
            transform: scale(1.05);
            box-shadow: 0 0 10px #00ff80, 0 0 20px #00ff80, 0 0 30px #00ff80;
        }
        .course-preview {
            background-color: #1a1a1a;
            border-radius: 0.75rem;
            overflow: hidden;
            transition: transform 0.3s ease-in-out;
        }
        .course-preview:hover {
            transform: translateY(-5px);
            box-shadow: 0 5px 15px rgba(0, 255, 128, 0.3);
        }
        .layer-depth {
            position: relative;
        }
        .layer-depth::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.1);
            z-index: -1;
            border-radius: inherit;
        }
        @keyframes codeAnimation {
            0% { opacity: 0.8; }
            50% { opacity: 1; }
            100% { opacity: 0.8; }
        }
        .animate-code {
            animation: codeAnimation 1s linear infinite;
        }
        .hero-bg-image {
            background-image: url('https://picsum.photos/1920/1080?nocache');
            background-size: cover;
            background-position: center;
            opacity: 0.3;
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: -2;
        }
    </style>
</head>
<body class="bg-black text-gray-100">

