    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const heroCarousel = document.getElementById('heroCarousel');
            const heroImages = heroCarousel.querySelectorAll('.hero-image');
            const prevHeroButton = document.getElementById('prevHero');
            const nextHeroButton = document.getElementById('nextHero');
            let currentHeroIndex = 0;

            function showHero(index) {
                heroImages.forEach(img => img.classList.remove('opacity-100', 'active'));
                heroImages.forEach(img => img.classList.add('opacity-0'));
                heroImages[index].classList.add('opacity-100', 'active');
            }

            function nextHero() {
                currentHeroIndex = (currentHeroIndex + 1) % heroImages.length;
                showHero(currentHeroIndex);
            }

            function prevHero() {
                currentHeroIndex = (currentHeroIndex - 1 + heroImages.length) % heroImages.length;
                showHero(currentHeroIndex);
            }

            nextHeroButton.addEventListener('click', nextHero);
            prevHeroButton.addEventListener('click', prevHero);
            setInterval(nextHero, 5000);

            const collectionCarousel = document.getElementById('collectionCarousel');
            const collectionSlide = collectionCarousel.querySelector('.carousel-slide');
            const prevCollectionButton = document.getElementById('prevCollection');
            const nextCollectionButton = document.getElementById('nextCollection');
            let collectionScrollPosition = 0;
            const cardWidth = collectionSlide.querySelector('.w-1/3').offsetWidth;
            const cardMargin = 24; // Space-x-6 = 1.5rem = 24px

            nextCollectionButton.addEventListener('click', () => {
                collectionScrollPosition += cardWidth + cardMargin;
                if (collectionScrollPosition > collectionSlide.scrollWidth - collectionCarousel.offsetWidth) {
                    collectionScrollPosition = 0;
                }
                collectionSlide.style.transform = `translateX(-${collectionScrollPosition}px)`;
            });

            prevCollectionButton.addEventListener('click', () => {
                collectionScrollPosition -= cardWidth + cardMargin;
                if (collectionScrollPosition < 0) {
                    collectionScrollPosition = Math.max(0, collectionSlide.scrollWidth - collectionCarousel.offsetWidth - cardWidth - cardMargin);
                }
                collectionSlide.style.transform = `translateX(-${collectionScrollPosition}px)`;
            });


            const sections = document.querySelectorAll('.fade-in-section');
            const observer = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('active');
                        observer.unobserve(entry.target);
                    }
                });
            }, {
                threshold: 0.15
            });

            sections.forEach(section => {
                observer.observe(section);
            });
        });
    </script>

</body>
</html>
