            <div class="mt-10 fade-in" style="transition-delay: 0.4s;">
                <button class="border border-accent-color text-accent-color font-semibold py-3 px-8 rounded-full hover:accent-bg hover:text-f8f8ff transition-colors zoom-in-out">Learn More</button>
