            <button onclick="closeQuickView()" class="absolute top-4 right-4 text-neutral-gray hover:text-charcoal-gray"><i class="fa fa-times fa-lg"></i></button>
            <h2 class="text-2xl font-bold mb-4">Product Quick View</h2>
            <img src="https://picsum.photos/200/300" alt="Product Preview" class="w-full mb-4 rounded-md">
            <p class="text-neutral-gray mb-4">Details about the product will be displayed here. This is a placeholder for the quick view functionality.</p>
            <button class="accent-bg text-f8f8ff font-semibold py-3 px-8 rounded-full hover:opacity-90 transition-opacity zoom-in-out">Add to Cart</button>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const sections = document.querySelectorAll('section');
            sections.forEach(section => {
                const observer = new IntersectionObserver(entries => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            section.querySelectorAll('.slide-in-left, .slide-in-right, .fade-in').forEach(element => {
                                element.classList.add('active');
                            });
                            observer.unobserve(section);
                        }
                    });
                }, { threshold: 0.1 });
                observer.observe(section);
            });

            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });

        function scrollSlider(direction, sliderId) {
            const slider = document.getElementById(sliderId);
            const cardWidth = document.querySelector(`#${sliderId} .product-card`).offsetWidth;
            const scrollAmount = cardWidth * direction;
            slider.scrollBy({ left: scrollAmount, behavior: 'smooth' });
        }

        function openQuickView() {
            document.getElementById('quickViewModal').style.display = 'block';
        }

        function closeQuickView() {
            document.getElementById('quickViewModal').style.display = 'none';
        }

        document.querySelectorAll('.product-card').forEach(card => {
            card.addEventListener('click', openQuickView);
        });

    </script>

</body>
</html>
