        .slide-in-right { transform: translateX(100%); }
        .slide-in-left { transform: translateX(-100%); }
        .slide-out-right { transform: translateX(-100%); }
        .slide-out-left { transform: translateX(100%); }
        .scale-up { transform: scale(0.95); }
        .scale-down { transform: scale(1.05); }
        .fade-in { opacity: 0; }
        .fade-out { opacity: 1; }
        .animate-fade-in { animation: fade-in-animation 0.5s ease-out forwards; }
        @keyframes fade-in-animation {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-out { animation: fade-out-animation 0.3s ease-in forwards; }
        @keyframes fade-out-animation {
            from { opacity: 1; transform: translateY(0); }
            to { opacity: 0; transform: translateY(20px); }
