    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });

        const homeScreen = document.getElementById('home-screen');
        const orderTrackingScreen = document.getElementById('order-tracking-screen');
        const statusText = document.getElementById('status-text');
        const orderStatusSection = document.getElementById('order-status');
        const preparingIcon = document.getElementById('preparing-icon');
        const deliveryIcon = document.getElementById('delivery-icon');
        const deliveredIcon = document.getElementById('delivered-icon');

        function showOrderTrackingScreen() {
            homeScreen.classList.add('slide-out-left', 'fade-out');
            orderTrackingScreen.classList.remove('hidden', 'slide-in-right', 'fade-in');
            orderTrackingScreen.classList.add('animate-fade-in');
            setTimeout(() => {
                homeScreen.classList.add('hidden');
                homeScreen.classList.remove('slide-out-left', 'fade-out');
                orderTrackingScreen.classList.remove('slide-in-right');
            }, 500);
        }

        function showHomeScreen() {
            orderTrackingScreen.classList.add('slide-out-right', 'fade-out');
            homeScreen.classList.remove('hidden', 'slide-in-left', 'fade-in');
            homeScreen.classList.add('animate-fade-in');
            setTimeout(() => {
                orderTrackingScreen.classList.add('hidden');
                orderTrackingScreen.classList.remove('slide-out-right', 'fade-out');
                homeScreen.classList.remove('slide-in-left');
            }, 500);
        }

        function showOrderStatus() {
            statusText.innerText = "Preparing";
            orderStatusSection.classList.remove('hidden');
            preparingIcon.classList.remove('bg-gray-200');
            preparingIcon.classList.add('bg-orange-200');
            preparingIcon.innerHTML = '<i class="fa fa-check text-orange-700"></i>';

            setTimeout(() => {
                statusText.innerText = "Out for Delivery";
                deliveryIcon.classList.remove('bg-gray-200');
                deliveryIcon.classList.add('bg-orange-200');
                deliveryIcon.innerHTML = '<i class="fa fa-check text-orange-700"></i>';
                preparingIcon.classList.add('bg-gray-200');
                preparingIcon.classList.remove('bg-orange-200');
                preparingIcon.innerHTML = '<i class="fa fa-check text-gray-700"></i>';
            }, 3000);

            setTimeout(() => {
                statusText.innerText = "Delivered";
                deliveredIcon.classList.remove('bg-gray-200');
                deliveredIcon.classList.add('bg-orange-200');
                deliveredIcon.innerHTML = '<i class="fa fa-check text-orange-700"></i>';
                deliveryIcon.classList.add('bg-gray-200');
                deliveryIcon.classList.remove('bg-orange-200');
                deliveryIcon.innerHTML = '<i class="fa fa-check text-gray-700"></i>';
            }, 6000);
        }

        // Example trigger for order tracking screen (replace with actual UI element)
        setTimeout(showOrderTrackingScreen, 2000); // Simulate navigation to order tracking after 2 seconds - REMOVE THIS LINE FOR ACTUAL APP
        setTimeout(showHomeScreen, 8000); // Simulate navigation back to home screen after 8 seconds - REMOVE THIS LINE FOR ACTUAL APP
    </script>

</body>
</html>
