    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const heroTextElements = document.querySelectorAll('.dynamic-text');
            heroTextElements.forEach((element, index) => {
                setTimeout(() => {
                    element.classList.add('animate');
                }, 100 * index);
            });

            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });

        gsap.utils.toArray('.plan-card').forEach(card => {
            card.addEventListener('mouseenter', () => {
                gsap.to(card, { scale: 1.05, duration: 0.2, ease: 'power2.out' });
            });
            card.addEventListener('mouseleave', () => {
                gsap.to(card, { scale: 1, duration: 0.2, ease: 'power2.out' });
            });
        });
    </script>
</body>
</html>
