            border-radius: 0.5rem;
            overflow-x: auto;
            font-family: monospace;
            line-height: 1.6;
        }
        .code-block::-webkit-scrollbar {
            height: 8px;
        }
        .code-block::-webkit-scrollbar-thumb {
            background-color: #666;
            border-radius: 4px;
        }
        .code-block::-webkit-scrollbar-thumb:hover {
            background-color: #888;
        }
        .social-share {
            position: fixed;
            top: 50%;
            right: 1rem;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
        }
        .social-icon {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 2.5rem;
            height: 2.5rem;
            border-radius: 0.375rem;
            background-color: rgba(255, 255, 255, 0.1);
            color: white;
            transition: background-color 0.2s ease;
        }
        .social-icon:hover {
            background-color: rgba(255, 255, 255, 0.2);
        }
        .hero-section {
            position: relative;
            overflow: hidden;
        }
        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            animation: pan 20s linear infinite alternate;
        }
        @keyframes pan {
            0% { transform: scale(1.1) translate(-5%, 0); }
            100% { transform: scale(1.1) translate(5%, 0); }
        }
        .layered-card {
            position: relative;
            border-radius: 1rem;
            overflow: hidden;
        }
        .layered-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(to bottom right, rgba(var(--color-primary-rgb), 0.8), rgba(var(--color-secondary-rgb), 0.6));
            opacity: 0.1;
            z-index: 0;
        }
        .layered-card-content {
            position: relative;
            z-index: 1;
            padding: 2rem;
        }
        .animated-underline {
            position: relative;
            display: inline-block;
        }

        .animated-underline::after {
            content: '';
            position: absolute;
            left: 0;
            bottom: -0.125rem;
            width: 100%;
            height: 0.25rem;
            background-color: rgb(var(--color-primary-rgb));
            border-radius: 0.125rem;
            transform: scaleX(0);
            transform-origin: left;
            transition: transform 0.3s ease-in-out;
        }

        .animated-underline:hover::after {
            transform: scaleX(1);
        }
        .fade-in {
            opacity: 0;
            transition: opacity 0.5s ease-out;
        }

        @keyframes gradient-bg {
            0% {
                background-position: 0% 50%;
            }
            50% {
                background-position: 100% 50%;
            }
            100% {
                background-position: 0% 50%;
            }
        }

        .gradient-bg {
            background: linear-gradient(-45deg, #ee7752, #e73c7e, #23a6d5, #23d5ab);
            background-size: 400% 400%;
            animation: gradient-bg 15s ease infinite;
        }


        .tilt-on-hover {
            transition: transform 0.3s ease;
        }

        .tilt-on-hover:hover {
            transform: rotate(2deg);
        }
    </style>
</head>
