<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Photography Portfolio</title>
    <link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;700&family=DM+Sans:wght@400;500&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body { font-family: 'DM Sans', sans-serif; }
        h1, h2, h3, h4, h5, h6 { font-family: 'Montserrat', sans-serif; }
        .gallery-item {
            overflow: hidden;
            position: relative;
        }
        .gallery-item img {
            transition: transform 0.3s ease;
            display: block;
        }
        .gallery-item:hover img {
            transform: scale(1.1);
        }
        .gallery-item::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.1);
            opacity: 0;
            transition: opacity 0.3s ease;
        }
        .gallery-item:hover::before {
            opacity: 1;
        }
    </style>
</head>
<body class="bg-gray-50">
    <header class="bg-white shadow-md sticky top-0 z-50">
        <div class="container mx-auto px-6 py-4 flex justify-between items-center">
            <h1 class="text-xl font-bold text-gray-900">Photography Portfolio</h1>
            <nav class="hidden md:flex space-x-6">
                <button class="filter-button active" data-filter="all">All</button>
                <button class="filter-button" data-filter="nature">Nature</button>
                <button class="filter-button" data-filter="portraits">Portraits</button>
                <button class="filter-button" data-filter="urban">Urban</button>
            </nav>
            <div class="md:hidden">
                <button id="mobile-filter-button" class="text-gray-600 hover:text-gray-900 focus:outline-none">
                    <i class="fa fa-filter"></i>
                </button>
            </div>
        </div>
        <div id="mobile-filter-menu" class="hidden md:hidden bg-white p-4 shadow-md">
            <button class="block w-full text-left py-2 filter-button active" data-filter="all">All</button>
            <button class="block w-full text-left py-2 filter-button" data-filter="nature">Nature</button>
            <button class="block w-full text-left py-2 filter-button" data-filter="portraits">Portraits</button>
            <button class="block w-full text-left py-2 filter-button" data-filter="urban">Urban</button>
        </div>
    </header>

    <main class="container mx-auto px-6 py-8">
        <section class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div class="gallery-item" data-category="nature">
                <img src="https://picsum.photos/200/300?random=1" alt="Nature 1" class="w-full h-full object-cover">
            </div>
            <div class="gallery-item" data-category="portraits">
                <img src="https://picsum.photos/200/300?random=2" alt="Portrait 1" class="w-full h-full object-cover">
            </div>
            <div class="gallery-item" data-category="urban">
                <img src="https://picsum.photos/200/300?random=3" alt="Urban 1" class="w-full h-full object-cover">
            </div>
            <div class="gallery-item" data-category="nature">
                <img src="https://picsum.photos/200/300?random=4" alt="Nature 2" class="w-full h-full object-cover">
            </div>
            <div class="gallery-item" data-category="portraits">
                <img src="https://picsum.photos/200/300?random=5" alt="Portrait 2" class="w-full h-full object-cover">
            </div>
            <div class="gallery-item" data-category="urban">
                <img src="https://picsum.photos/200/300?random=6" alt="Urban 2" class="w-full h-full object-cover">
            </div>
            <div class="gallery-item" data-category="nature">
                <img src="https://picsum.photos/200/300?random=7" alt="Nature 3" class="w-full h-full object-cover">
            </div>
            <div class="gallery-item" data-category="portraits">
                <img src="https://picsum.photos/200/300?random=8" alt="Portrait 3" class="w-full h-full object-cover">
            </div>
            <div class="gallery-item" data-category="urban">
                <img src="https://picsum.photos/200/300?random=9" alt="Urban 3" class="w-full h-full object-cover">
            </div>
        </section>
    </main>

    <footer class="bg-gray-900 text-gray-500 py-8">
        <div class="container mx-auto px-6 text-center">
            <p>&copy; 2024 Photography Portfolio. All rights reserved.</p>
        </div>
    </footer>

    <script>
        const filterButtons = document.querySelectorAll('.filter-button');
        const galleryItems = document.querySelectorAll('.gallery-item');
        const mobileFilterButton = document.getElementById('mobile-filter-button');
        const mobileFilterMenu = document.getElementById('mobile-filter-menu');

        filterButtons.forEach(button => {
            button.addEventListener('click', () => {
                const filter = button.dataset.filter;

                filterButtons.forEach(btn => btn.classList.remove('active'));
                button.classList.add('active');

                galleryItems.forEach(item => {
                    if (filter === 'all' || item.dataset.category === filter) {
                        item.style.display = 'block';
                    } else {
                        item.style.display = 'none';
                    }
                });
                if (mobileFilterMenu.classList.contains('block')) {
                    mobileFilterMenu.classList.remove('block');
                    mobileFilterMenu.classList.add('hidden');
                }
            });
        });

        mobileFilterButton.addEventListener('click', () => {
            mobileFilterMenu.classList.toggle('hidden');
            mobileFilterMenu.classList.toggle('block');
        });
    </script>
</body>
</html>
