            opacity: 0;
        }

        @keyframes fade-in {
            to { opacity: 1; }
        }
        .animate-slide-up {
            animation: slide-up 1s ease-out forwards;
            transform: translateY(20px);
            opacity: 0;
        }

        @keyframes slide-up {
            to { transform: translateY(0); opacity: 1; }
        }


    </style>
