            box-shadow:  20px 20px 60px #bebebe, -20px -20px 60px #ffffff;
        }
        .metallic-silver-inner {
             background: linear-gradient(145deg, #ffffff, #e0e0e0);
            box-shadow:  20px 20px 60px #bebebe inset, -20px -20px 60px #ffffff inset;
        }
        .vibrant-blue {
            color: #3b82f6;
        }
        .route-map {
