                </div>
            </form>
        </div>
    </div>
</section>

<section id="contact" class="py-20 metallic-silver">
    <div class="container mx-auto px-6 text-center">
        <h2 class="text-3xl font-bold vibrant-blue mb-12">Contact Us</h2>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-8">
