<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neon Genesis: Landing Page</title>
    <link href="https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Roboto:wght@400;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@latest"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
    <style>
        body {
            font-family: 'Roboto', sans-serif;
            background-color: #111827;
            color: white;
        }
        .bebas-neue {
            font-family: 'Bebas Neue', sans-serif;
        }
        .neon-text {
            text-shadow: 0 0 5px #34D399, 0 0 10px #34D399, 0 0 20px #34D399;
        }
        .btn-neon {
            background-color: #34D399;
            box-shadow: 0 0 5px #34D399, 0 0 10px #34D399;
        }
        .btn-neon:hover {
            background-color: #4ADE80;
            box-shadow: 0 0 10px #4ADE80, 0 0 20px #4ADE80, 0 0 30px #4ADE80;
        }
        .bg-neon-gradient {
            background: linear-gradient(135deg, #1E40AF, #A855F7, #F472B6);
            background-size: 200% 200%;
            animation: gradient 15s ease infinite;
        }
        @keyframes gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .particle {
            position: absolute;
            border-radius: 50%;
            opacity: 0.7;
            animation: moveParticles 20s linear infinite;
        }
        @keyframes moveParticles {
            0% {
                transform: translate3d(0, 0, 0);
            }
            100% {
                transform: translate3d(100px, 100px, 0);
            }
        }
    </style>
</head>
<body class="overflow-hidden">

<div id="particles-js" class="absolute inset-0 pointer-events-none"></div>

<nav class="fixed top-0 left-0 w-full py-6 z-50 bg-black bg-opacity-70 backdrop-blur-md">
    <div class="container mx-auto px-6 flex justify-between items-center">
        <div class="text-xl font-bold bebas-neue neon-text">NEON GENESIS</div>
        <div class="hidden md:flex space-x-8">
            <a href="#characters" class="hover:text-gray-300 transition-colors">Characters</a>
            <a href="#story" class="hover:text-gray-300 transition-colors">Story</a>
            <a href="#gameplay" class="hover:text-gray-300 transition-colors">Gameplay</a>
            <button class="btn-neon text-black font-bold py-2 px-4 rounded-full hover:opacity-90 transition-opacity">
                Play Now
            </button>
        </div>
        <div class="md:hidden">
            <button id="mobile-menu-button" class="text-white focus:outline-none">
                <i class="fa fa-bars text-xl"></i>
            </button>
        </div>
    </div>

    <div class="hidden md:hidden absolute top-full left-0 w-full bg-black bg-opacity-90 backdrop-blur-md" id="mobile-menu">
        <div class="px-6 py-8 flex flex-col space-y-4">
            <a href="#characters" class="block py-2 hover:text-gray-300 transition-colors">Characters</a>
            <a href="#story" class="block py-2 hover:text-gray-300 transition-colors">Story</a>
            <a href="#gameplay" class="block py-2 hover:text-gray-300 transition-colors">Gameplay</a>
            <button class="btn-neon text-black font-bold py-2 px-4 rounded-full hover:opacity-90 transition-opacity block text-center">
                Play Now
            </button>
        </div>
    </div>
</nav>

<section class="bg-neon-gradient min-h-screen flex items-center justify-center text-center relative overflow-hidden">
    <div class="container mx-auto px-6 relative z-10">
        <h1 class="text-6xl md:text-8xl font-bold bebas-neue neon-text mb-4"> погружение в <br> НЕОНОВЫЙ МИР</h1>
        <p class="text-lg md:text-xl mb-8 opacity-80">Experience the ultimate futuristic adventure.</p>
        <button class="btn-neon text-black font-bold py-3 px-8 rounded-full text-xl hover:opacity-90 transition-opacity">
            Explore
        </button>
    </div>
    <div class="absolute bottom-0 left-0 w-full h-1/3 bg-gradient-to-t from-black to-transparent"></div>
</section>

<section id="characters" class="py-20 relative overflow-hidden">
    <div class="container mx-auto px-6 text-center">
        <h2 class="text-4xl font-bold bebas-neue neon-text mb-12">MEET THE CHARACTERS</h2>
        <div class="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div class="character-card bg-black bg-opacity-60 p-6 rounded-xl transform transition-transform hover:scale-105 cursor-pointer relative">
                <img src="https://picsum.photos/200/300" alt="Character 1" class="rounded-xl mb-4 mx-auto block">
                <h3 class="text-xl font-bold mb-2 bebas-neue neon-text">CYBERIA</h3>
                <p class="opacity-70">The Stealth Assassin.</p>
                <div class="character-overlay absolute inset-0 bg-black bg-opacity-80 flex items-center justify-center rounded-xl opacity-0 transition-opacity duration-300 hover:opacity-100">
                    <p class="text-white text-xl font-bold">Learn More <i class="fa fa-arrow-right ml-2"></i></p>
                </div>
            </div>
            <div class="character-card bg-black bg-opacity-60 p-6 rounded-xl transform transition-transform hover:scale-105 cursor-pointer relative">
                <img src="https://picsum.photos/201/300" alt="Character 2" class="rounded-xl mb-4 mx-auto block">
                <h3 class="text-xl font-bold mb-2 bebas-neue neon-text">VOLT</h3>
                <p class="opacity-70">The Electric Warrior.</p>
                <div class="character-overlay absolute inset-0 bg-black bg-opacity-80 flex items-center justify-center rounded-xl opacity-0 transition-opacity duration-300 hover:opacity-100">
                    <p class="text-white text-xl font-bold">Learn More <i class="fa fa-arrow-right ml-2"></i></p>
                </div>
            </div>
            <div class="character-card bg-black bg-opacity-60 p-6 rounded-xl transform transition-transform hover:scale-105 cursor-pointer relative">
                <img src="https://picsum.photos/202/300" alt="Character 3" class="rounded-xl mb-4 mx-auto block">
                <h3 class="text-xl font-bold mb-2 bebas-neue neon-text">NOVA</h3>
                <p class="opacity-70">The Psychic Enigma.</p>
                <div class="character-overlay absolute inset-0 bg-black bg-opacity-80 flex items-center justify-center rounded-xl opacity-0 transition-opacity duration-300 hover:opacity-100">
                    <p class="text-white text-xl font-bold">Learn More <i class="fa fa-arrow-right ml-2"></i></p>
                </div>
            </div>
        </div>
    </div>
</section>

<section id="story" class="py-20 bg-black bg-opacity-80 relative overflow-hidden">
    <div class="container mx-auto px-6 text-center">
        <h2 class="text-4xl font-bold bebas-neue neon-text mb-12">OUR STORY</h2>
        <div class="max-w-3xl mx-auto opacity-80">
            <p class="mb-8">In a dystopian future where mega-corporations rule, Neon Genesis emerges as a beacon of hope. Players dive into a cyberpunk world filled with intrigue, betrayal, and technological marvel. Unravel the mysteries of the Neon City and fight for freedom against overwhelming odds.</p>
            <p>Experience a narrative-driven adventure with branching storylines and impactful choices. Your decisions shape the fate of Neon Genesis and its inhabitants. Are you ready to become the legend the city needs?</p>
        </div>
    </div>
</section>

<section id="gameplay" class="py-20 relative overflow-hidden">
    <div class="container mx-auto px-6 text-center">
        <h2 class="text-4xl font-bold bebas-neue neon-text mb-12">GAMEPLAY</h2>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
            <div>
                <img src="https://picsum.photos/600/400" alt="Gameplay Image" class="rounded-xl shadow-xl">
            </div>
            <div class="text-left opacity-80">
                <h3 class="text-2xl font-bold bebas-neue neon-text mb-4">Dynamic Combat System</h3>
                <p class="mb-6">Engage in fast-paced, strategic combat that blends real-time action with tactical decision-making. Master unique abilities and upgrade your arsenal to overcome challenging enemies.</p>
                <h3 class="text-2xl font-bold bebas-neue neon-text mb-4">Explore a Cyberpunk World</h3>
                <p class="mb-6">Traverse the sprawling Neon City, from its glittering skyscrapers to its gritty underbelly. Discover hidden secrets, interact with diverse characters, and immerse yourself in a richly detailed world.</p>
                <h3 class="text-2xl font-bold bebas-neue neon-text mb-4">Character Progression</h3>
                <p>Customize and evolve your characters with skill trees, cybernetic enhancements, and powerful gear. Forge your own path and become the ultimate Neon Genesis warrior.</p>
            </div>
        </div>
    </div>
</section>

<footer class="py-12 bg-black bg-opacity-90 text-center relative overflow-hidden">
    <p class="opacity-70">© 2024 Neon Genesis. All rights reserved.</p>
</footer>

<script>
    document.addEventListener('DOMContentLoaded', () => {
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });
    });

    function createParticle(container) {
        const particle = document.createElement('div');
        particle.className = 'particle';
        particle.style.width = `${Math.random() * 5 + 2}px`;
        particle.style.height = particle.style.width;
        particle.style.background = '#34D399';
        particle.style.left = `${Math.random() * 100}vw`;
        particle.style.top = `${Math.random() * 100}vh`;
        particle.style.animationDuration = `${Math.random() * 15 + 5}s`;
        particle.style.animationDelay = `-${Math.random() * 5}s`;
        container.appendChild(particle);

        particle.addEventListener('animationiteration', () => {
            particle.remove();
            createParticle(container);
        });
    }

    const particlesContainer = document.getElementById('particles-js');
    for (let i = 0; i < 50; i++) {
        createParticle(particlesContainer);
    }

    gsap.from('.neon-text', {
        duration: 1.5,
        opacity: 0,
        y: -50,
        stagger: 0.2,
        ease: "power3.out"
    });
    gsap.from('.opacity-80', {
        duration: 1.5,
        opacity: 0,
        delay: 0.5,
        ease: "power2.out"
    });
    gsap.from('.btn-neon', {
        duration: 1.5,
        opacity: 0,
        scale: 0.8,
        delay: 0.8,
        ease: "back.out(1.7)"
    });
    gsap.from('.character-card', {
        duration: 1,
        opacity: 0,
        y: 50,
        stagger: 0.3,
        scrollTrigger: {
            trigger: '#characters',
            start: 'top 80%',
            end: 'bottom 20%',
            toggleActions: 'play none none reverse'
        }
    });
</script>

</body>
</html>
