<!DOCTYPE html>
<html lang="en" class="dark scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Stock Market Dashboard</title>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Inter', sans-serif;
        }
        .candlestick-chart {
            position: relative;
            width: 100%;
            height: 300px;
            border-bottom: 1px solid #ccc;
            border-left: 1px solid #ccc;
            padding-left: 30px;
            padding-bottom: 30px;
        }
        .candlestick-chart .axis-labels {
            position: absolute;
            left: 0;
            bottom: 0;
            font-size: 0.8rem;
            color: #6b7280;
        }
        .candlestick-chart .axis-labels.x {
            width: 100%;
            text-align: center;
            bottom: -20px;
            left: 30px;
        }
        .candlestick-chart .axis-labels.y {
            left: 5px;
            bottom: auto;
            top: 50%;
            transform: translateY(-50%);
            writing-mode: vertical-rl;
            text-orientation: upright;
        }
        .candlestick-chart .bar {
            position: absolute;
        }
        .candlestick-chart .bar-wick {
            background-color: #6b7280;
        }
        .candlestick-chart .bar-body.up {
            background-color: #4ade80;
            border: 1px solid #4ade80;
        }
        .candlestick-chart .bar-body.down {
            background-color: #f43f5e;
            border: 1px solid #f43f5e;
        }
        .dynamic-shadow {
            transition: box-shadow 0.3s ease-in-out;
        }
        .dynamic-shadow:hover {
            box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
        }
        .pulse-animation {
            animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulse {
            0%, 100% {
              opacity: 1;
            }
            50% {
              opacity: .5;
            }
        }
        .slide-in-animation {
            animation: slideIn 0.5s ease-out forwards;
            transform: translateY(20px);
            opacity: 0;
        }
        @keyframes slideIn {
            to {
                transform: translateY(0);
                opacity: 1;
            }
        }
        .fade-in-animation {
            animation: fadeIn 1s ease-out forwards;
            opacity: 0;
        }
        @keyframes fadeIn {
            to {
                opacity: 1;
            }
        }
        .dark-mode-hero {
            background: linear-gradient(135deg, #0f172a, #1e293b, #334155);
            background-size: 200% 200%;
            animation: dark-gradient 15s ease infinite;
        }
        @keyframes dark-gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .light-mode-hero {
            background: linear-gradient(135deg, #e0f2fe, #bae6fd, #7dd3fc);
            background-size: 200% 200%;
            animation: light-gradient 15s ease infinite;
        }
        @keyframes light-gradient {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
    </style>
</head>
<body class="bg-gray-100 dark:bg-gray-900 text-gray-800 dark:text-gray-200">

    <header class="bg-white dark:bg-gray-800 shadow-md sticky top-0 z-50">
        <nav class="container mx-auto px-6 py-4 flex justify-between items-center">
            <div class="font-bold text-xl flex items-center">
                <i class="fa-solid fa-chart-line text-blue-600 mr-2"></i>
                <span class="text-gray-900 dark:text-white">Stock Dashboard</span>
            </div>
            <div class="flex items-center space-x-4">
                <button id="darkModeToggle" class="bg-gray-200 dark:bg-gray-700 p-2 rounded-full transition-colors duration-300 hover:bg-gray-300 dark:hover:bg-gray-600">
                    <i id="darkModeIcon" class="fa-solid fa-moon dark:fa-sun text-gray-700 dark:text-gray-300"></i>
                </button>
            </div>
        </nav>
    </header>

    <main class="container mx-auto mt-8 px-6">

        <section class="mb-8 dark-mode-hero rounded-3xl overflow-hidden shadow-xl p-12 text-center text-white">
            <h2 class="text-4xl font-bold mb-4 fade-in-animation">Real-Time Stock Market Analysis</h2>
            <p class="text-lg opacity-80 fade-in-animation">Visualize market trends and make informed decisions.</p>
        </section>

        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">

            <div class="bg-white dark:bg-gray-800 rounded-3xl shadow-lg p-6 dynamic-shadow slide-in-animation">
                <h3 class="font-semibold text-xl mb-4 flex items-center"><i class="fa-solid fa-chart-simple text-blue-500 mr-2"></i> Stock A - <span class="ml-1 font-normal text-green-500">+1.5%</span></h3>
                <div class="candlestick-chart">
                    <div class="axis-labels x">Time</div>
                    <div class="axis-labels y">Price</div>
                    <div id="chart-a"></div>
                </div>
            </div>

            <div class="bg-white dark:bg-gray-800 rounded-3xl shadow-lg p-6 dynamic-shadow slide-in-animation">
                <h3 class="font-semibold text-xl mb-4 flex items-center"><i class="fa-solid fa-chart-simple text-blue-500 mr-2"></i> Stock B - <span class="ml-1 font-normal text-red-500">-0.8%</span></h3>
                <div class="candlestick-chart">
                    <div class="axis-labels x">Time</div>
                    <div class="axis-labels y">Price</div>
                    <div id="chart-b"></div>
                </div>
