    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const darkModeToggle = document.getElementById('darkModeToggle');
            const darkModeIcon = document.getElementById('darkModeIcon');
            const html = document.documentElement;

            darkModeToggle.addEventListener('click', () => {
                if (html.classList.contains('dark')) {
                    html.classList.remove('dark');
                    localStorage.setItem('theme', 'light');
                    darkModeIcon.classList.remove('fa-sun');
                    darkModeIcon.classList.add('fa-moon');
                } else {
                    html.classList.add('dark');
                    localStorage.setItem('theme', 'dark');
                    darkModeIcon.classList.remove('fa-moon');
                    darkModeIcon.classList.add('fa-sun');
                }
            });

            if (localStorage.getItem('theme') === 'dark' || (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
                html.classList.add('dark');
                darkModeIcon.classList.remove('fa-moon');
                darkModeIcon.classList.add('fa-sun');
            } else {
                html.classList.remove('dark');
                darkModeIcon.classList.remove('fa-sun');
                darkModeIcon.classList.add('fa-moon');
            }

            function generateCandlestickChart(chartId, data) {
                const chartContainer = document.getElementById(chartId);
                chartContainer.innerHTML = '';

                const width = chartContainer.offsetWidth - 30;
                const height = chartContainer.offsetHeight - 30;
                const padding = 10;

                const minPrice = Math.min(...data.map(d => Math.min(d.open, d.close, d.low)));
                const maxPrice = Math.max(...data.map(d => Math.max(d.open, d.close, d.high)));
                const priceRange = maxPrice - minPrice;

                const barWidth = width / data.length - padding;

                data.forEach((item, index) => {
                    const x = index * (barWidth + padding);
                    const openY = height - (item.open - minPrice) / priceRange * height;
                    const closeY = height - (item.close - minPrice) / priceRange * height;
                    const highY = height - (item.high - minPrice) / priceRange * height;
                    const lowY = height - (item.low - minPrice) / priceRange * height;

                    const barHeight = Math.abs(openY - closeY);
                    const barY = Math.min(openY, closeY);
                    const isUp = item.close >= item.open;

                    const bar = document.createElement('div');
                    bar.classList.add('bar');
                    bar.style.left = `${x}px`;

                    const wick = document.createElement('div');
                    wick.classList.add('bar-wick');
                    wick.style.position = 'absolute';
                    wick.style.left = `${barWidth / 2 - 0.5}px`;
                    wick.style.top = `${highY}px`;
                    wick.style.width = '1px';
                    wick.style.height = `${lowY - highY}px`;
                    bar.appendChild(wick);

                    const body = document.createElement('div');
                    body.classList.add('bar-body', isUp ? 'up' : 'down');
                    body.style.position = 'absolute';
                    body.style.left = '0';
                    body.style.top = `${barY}px`;
                    body.style.width = `${barWidth}px`;
                    body.style.height = `${barHeight}px`;
                    bar.appendChild(body);

                    chartContainer.appendChild(bar);
                });
            }

            const chartDataA = [
                { open: 150, close: 152, high: 153, low: 149 },
                { open: 152, close: 155, high: 156, low: 151 },
                { open: 155, close: 153, high: 155, low: 152 },
                { open: 153, close: 154, high: 155, low: 153 },
                { open: 154, close: 156, high: 157, low: 154 }
            ];
            generateCandlestickChart('chart-a', chartDataA);

            const chartDataB = [
                { open: 200, close: 198, high: 201, low: 197 },
                { open: 198, close: 195, high: 199, low: 194 },
                { open: 195, close: 196, high: 197, low: 195 },
                { open: 196, close: 194, high: 196, low: 193 },
                { open: 194, close: 195, high: 196, low: 194 }
            ];
            generateCandlestickChart('chart-b', chartDataB);

            const chartDataC = [
                { open: 100, close: 102, high: 103, low: 99 },
                { open: 102, close: 104, high: 105, low: 101 },
                { open: 104, close: 103, high: 104, low: 102 },
                { open: 103, close: 105, high: 106, low: 103 },
                { open: 105, close: 107, high: 108, low: 105 }
            ];
            generateCandlestickChart('chart-c', chartDataC);
        });
    </script>

</body>
</html>
