    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const fadeElements = document.querySelectorAll('.fade-in');
            const slideUpElements = document.querySelectorAll('.slide-up');

            const observerConfig = {
                threshold: 0.2
            };

            const fadeObserver = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('active');
                        fadeObserver.unobserve(entry.target);
                    }
                });
            }, observerConfig);

            const slideUpObserver = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('active');
                        slideUpObserver.unobserve(entry.target);
                    }
                });
            }, observerConfig);


            fadeElements.forEach(element => fadeObserver.observe(element));
            slideUpElements.forEach(element => slideUpObserver.observe(element));

            const seats = document.querySelectorAll('.seat.available');
            let selectedSeatsCount = 0;
            let totalPrice = 0;

            seats.forEach(seat => {
                seat.addEventListener('click', function() {
                    if (this.classList.contains('selected')) {
                        this.classList.remove('selected');
                        selectedSeatsCount--;
                        totalPrice -= parseInt(this.dataset.seatPrice);
                    } else {
                        this.classList.add('selected');
                        selectedSeatsCount++;
                        totalPrice += parseInt(this.dataset.seatPrice);
                    }
                    console.log(`Seats Selected: ${selectedSeatsCount}, Total Price: $${totalPrice}`);
                });
            });
        });
    </script>

</body>
</html>
