                    </button>
                </div>
            </header>
            <div id="drag-drop-area" class="relative bg-white border-2 border-dashed border-gray-400 rounded-md p-6 text-center cursor-pointer drag-area">
                <input type="file" id="file-input" class="hidden" multiple>
                <i class="lucide lucide-upload-cloud text-gray-500 w-12 h-12 mx-auto mb-4 animate-bounce"></i>
                <p class="text-gray-600">Drag and drop files here or <span class="text-indigo-600 font-semibold underline">browse</span> to upload</p>
                <div id="file-list-container" class="mt-6 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4"></div>
            </div>
        </main>
    </div>
    <script>
        lucide.createIcons();
        const dragDropArea = document.getElementById('drag-drop-area');
        const fileInput = document.getElementById('file-input');
        const fileListContainer = document.getElementById('file-list-container');

        dragDropArea.addEventListener('click', () => {
            fileInput.click();
        });

        fileInput.addEventListener('change', handleFiles);

        dragDropArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            dragDropArea.classList.add('drag-over');
        });

        dragDropArea.addEventListener('dragleave', () => {
            dragDropArea.classList.remove('drag-over');
        });

        dragDropArea.addEventListener('drop', (e) => {
            e.preventDefault();
            dragDropArea.classList.remove('drag-over');
            const files = e.dataTransfer.files;
            handleFiles(files);
        });

        function handleFiles(files) {
            if (!files.length) return;
            fileListContainer.innerHTML = '';
            files = fileInput.files || files;

            for (let i = 0; i < files.length; i++) {
                const file = files[i];
                const fileCard = createFileCard(file);
                fileListContainer.appendChild(fileCard);
                uploadFile(file, fileCard);
            }
             fileInput.value = ''; // Reset file input after upload
        }

        function createFileCard(file) {
            const card = document.createElement('div');
            card.className = 'file-card bg-white rounded-md shadow-sm p-4 flex items-center space-x-4 animate-fade';

            let iconClass = 'fa-regular fa-file';
            if (file.type.startsWith('image/')) {
                iconClass = 'fa-regular fa-image text-indigo-500';
            } else if (file.type.startsWith('video/')) {
                iconClass = 'fa-regular fa-file-video text-blue-500';
            } else if (file.type.startsWith('audio/')) {
                iconClass = 'fa-regular fa-file-audio text-green-500';
            } else if (file.type === 'application/pdf') {
                iconClass = 'fa-regular fa-file-pdf text-red-500';
            } else if (file.type === 'application/zip' || file.type === 'application/x-zip-compressed') {
                iconClass = 'fa-regular fa-file-zipper text-yellow-500';
            }

            const icon = document.createElement('i');
            icon.className = iconClass + ' text-2xl';

            const details = document.createElement('div');
            details.className = 'flex-1';

            const name = document.createElement('p');
            name.className = 'font-semibold text-gray-800 truncate';
            name.textContent = file.name;

            const size = document.createElement('p');
            size.className = 'text-sm text-gray-500';
            size.textContent = formatFileSize(file.size);

            const progress = document.createElement('progress');
            progress.className = 'upload-progress w-full h-2 bg-gray-200 rounded-full appearance-none';
            progress.value = 0;
            progress.max = 100;
            progress.style.display = 'none';

            details.appendChild(name);
            details.appendChild(size);
            details.appendChild(progress);

            card.appendChild(icon);
            card.appendChild(details);
            return card;
        }

        function uploadFile(file, fileCard) {
            const progressElement = fileCard.querySelector('progress');
            progressElement.style.display = 'block';

            const formData = new FormData();
            formData.append('file', file);

            const xhr = new XMLHttpRequest();
            xhr.upload.onprogress = (event) => {
                if (event.lengthComputable) {
                    const percentage = (event.loaded / event.total) * 100;
                    progressElement.value = percentage;
                }
            };

            xhr.onload = () => {
                if (xhr.status === 200) {
                    progressElement.style.display = 'none';
                    fileCard.classList.remove('animate-fade');
                    fileCard.classList.add('opacity-50');
                } else {
                    console.error('Upload error:', xhr.statusText);
                    progressElement.style.display = 'none';
                    fileCard.classList.add('border-red-500');
                }
            };

            xhr.onerror = () => {
                console.error('Network error during upload.');
                progressElement.style.display = 'none';
                fileCard.classList.add('border-red-500');
            };

            xhr.open('POST', '/upload');
            xhr.send(formData);
        }

        function formatFileSize(bytes) {
            if (bytes < 1024) {
                return bytes + ' bytes';
            } else if (bytes < 1048576) {
                return (bytes / 1024).toFixed(1) + ' KB';
            } else if (bytes < 1073741824) {
                return (bytes / 1048576).toFixed(1) + ' MB';
            } else {
                return (bytes / 1073741824).toFixed(1) + ' GB';
            }
        }
    </script>
</body>
</html>
