    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            const filterButtons = document.querySelectorAll('.filter-button');
            const articleGrid = document.getElementById('article-grid');
            const articles = Array.from(articleGrid.children);

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            filterButtons.forEach(button => {
                button.addEventListener('click', () => {
                    filterButtons.forEach(btn => btn.classList.remove('active'));
                    button.classList.add('active');
                    const filter = button.dataset.filter;

                    articleGrid.classList.add('animate-opacity-out');
                    setTimeout(() => {
                        articleGrid.innerHTML = '';
                        let filteredArticles = articles;
                        if (filter !== 'all') {
                            filteredArticles = articles.filter(article => {
                                const title = article.querySelector('h3').textContent.toLowerCase();
                                return title.includes(filter);
                            });
                        }
                        filteredArticles.forEach(article => articleGrid.appendChild(article));
                        articleGrid.classList.remove('animate-opacity-out');
                    }, 150);
                });
            });
        });
    </script>

