<script>
    const incomeExpenseChartCanvas = document.getElementById('incomeExpenseChart').getContext('2d');
    const budgetChartCanvas = document.getElementById('budgetChart').getContext('2d');

    const incomeExpenseChart = new Chart(incomeExpenseChartCanvas, {
        type: 'line',
        data: {
            labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
            datasets: [{
                label: 'Income',
                data: [4500, 4800, 5200, 5000, 5500, 5300, 5600, 5800, 6000, 6200, 6500, 6300],
                borderColor: '#22C55E',
                backgroundColor: '#22C55E30',
                borderWidth: 2,
                tension: 0.4,
                pointRadius: 0,
                fill: true,
            }, {
                label: 'Expenses',
                data: [2500, 2800, 3000, 3200, 3500, 3300, 3600, 3800, 4000, 4200, 4500, 4300],
                borderColor: '#EF4444',
                backgroundColor: '#EF444430',
                borderWidth: 2,
                tension: 0.4,
                pointRadius: 0,
                fill: true,
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true,
                    grid: {
                        drawBorder: false,
                    },
                    ticks: {
                        color: '#6B7280',
                        callback: function(value, index, values) {
                            return '$' + value;
                        }
                    }
                },
                x: {
                    grid: {
                        display: false,
                    },
                    ticks: {
                        color: '#6B7280'
                    }
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                    align: 'end',
                    labels: {
                        usePointStyle: true,
                        pointStyle: 'circle',
                        color: '#4B5563'
                    }
                },
                tooltip: {
                    mode: 'index',
                    intersect: false,
                    backgroundColor: '#1E293B',
                    titleColor: '#F9FAFB',
                    bodyColor: '#F9FAFB',
                    padding: 10,
                    cornerRadius: 4,
                }
            }
        }
    });

    const budgetChart = new Chart(budgetChartCanvas, {
        type: 'doughnut',
        data: {
            labels: ['Groceries', 'Entertainment', 'Utilities', 'Savings', 'Other'],
            datasets: [{
                data: [30, 20, 15, 25, 10],
                backgroundColor: [
                    '#A855F7',
                    '#FCD34D',
                    '#3AB7BF',
                    '#22C55E',
                    '#EF4444',
                ],
                hoverOffset: 10,
                borderWidth: 0,
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '65%',
            plugins: {
                legend: {
                    position: 'right',
                    align: 'center',
                    labels: {
                        usePointStyle: true,
                        pointStyle: 'circle',
                        color: '#4B5563'
                    }
                },
                tooltip: {
                    backgroundColor: '#1E293B',
                    titleColor: '#F9FAFB',
                    bodyColor: '#F9FAFB',
                    padding: 10,
                    cornerRadius: 4,
                    callbacks: {
                        label: function(context) {
                            let label = context.label || '';
                            if (label) {
                                label += ': ';
                            }
                            if (context.parsed !== null) {
                                label += context.parsed + '%';
                            }
                            return label;
                        }
                    }
                }
            }
        }
    });


    function updateRealTimeData() {
        const incomeElements = document.querySelectorAll('.data-glow');
        const expenseElements = document.querySelectorAll('.expense-glow');

        incomeElements.forEach(el => {
            let currentIncome = parseFloat(el.textContent.replace('$','').replace(',',''));
            let newIncome = currentIncome + Math.floor(Math.random() * 100) - 50;
            el.textContent = '$' + newIncome.toLocaleString();
        });

        expenseElements.forEach(el => {
            let currentExpense = parseFloat(el.textContent.replace('-$','').replace(',',''));
            let newExpense = currentExpense + Math.floor(Math.random() * 50) - 25;
            el.textContent = '-$' + Math.abs(newExpense).toLocaleString();
        });

        incomeExpenseChart.data.datasets[0].data.push(incomeExpenseChart.data.datasets[0].data.shift() + Math.floor(Math.random() * 200) - 100);
        incomeExpenseChart.data.datasets[1].data.push(incomeExpenseChart.data.datasets[1].data.shift() + Math.floor(Math.random() * 150) - 75);
        incomeExpenseChart.update();

        budgetChart.data.datasets[0].data.forEach((value, index) => {
            budgetChart.data.datasets[0].data[index] = Math.max(0, value + (Math.random() * 5) - 2.5);
        });
        budgetChart.update();
    }

    setInterval(updateRealTimeData, 5000);
    updateRealTimeData();
</script>

</body>
</html>
```

