    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const playerPerformanceChartCtx = document.getElementById('playerPerformanceChart').getContext('2d');
            const teamStatsChartCtx = document.getElementById('teamStatsChart').getContext('2d');

            const playerPerformanceChart = new Chart(playerPerformanceChartCtx, {
                type: 'line',
                data: {
                    labels: ['Game 1', 'Game 2', 'Game 3', 'Game 4', 'Game 5', 'Game 6'],
                    datasets: [{
                        label: 'Points per Game',
                        data: [22, 25, 30, 28, 35, 32],
                        borderColor: '#00FFFF',
                        backgroundColor: 'rgba(0, 255, 255, 0.1)',
                        borderWidth: 2,
                        tension: 0.4,
                        pointRadius: 5,
                        pointBackgroundColor: '#00FFFF'
                    }, {
                        label: 'Assists per Game',
                        data: [8, 9, 7, 10, 12, 11],
                        borderColor: '#00FF7F',
                        backgroundColor: 'rgba(0, 255, 127, 0.1)',
                        borderWidth: 2,
                        tension: 0.4,
                        pointRadius: 5,
                        pointBackgroundColor: '#00FF7F'
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true,
                            grid: { color: 'rgba(255, 255, 255, 0.05)' },
                            ticks: { color: '#E5E7EB' }
                        },
                        x: {
                            grid: { color: 'rgba(255, 255, 255, 0.05)' },
                            ticks: { color: '#E5E7EB' }
                        }
                    },
                    plugins: {
                        legend: {
                            labels: {
                                color: '#E5E7EB'
                            }
                        },
                        tooltip: {
                            backgroundColor: '#1F2937',
                            titleColor: '#E5E7EB',
                            bodyColor: '#E5E7EB',
                            borderColor: '#00FFFF',
                            borderWidth: 1
                        }
                    }
                }
            });

            const teamStatsChart = new Chart(teamStatsChartCtx, {
                type: 'bar',
                data: {
                    labels: ['Team A', 'Team B', 'Team C', 'Team D', 'Team E'],
                    datasets: [{
                        label: 'Win Percentage',
                        data: [75, 60, 80, 55, 70],
                        backgroundColor: ['#00FFFF', '#00FF7F', '#FFFF00', '#FF00FF', '#00BFFF'],
                        borderWidth: 0
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true,
                            max: 100,
                            grid: { color: 'rgba(255, 255, 255, 0.05)' },
                            ticks: { color: '#E5E7EB', callback: function(value) { return value + '%'; } }
                        },
                        x: {
                            grid: { color: 'rgba(255, 255, 255, 0.05)' },
                            ticks: { color: '#E5E7EB' }
                        }
                    },
                    plugins: {
                        legend: { display: false },
                        tooltip: {
                            backgroundColor: '#1F2937',
                            titleColor: '#E5E7EB',
                            bodyColor: '#E5E7EB',
                            borderColor: '#00FFFF',
                            borderWidth: 1,
                            callbacks: {
                                label: function(context) {
                                    return 'Win Rate: ' + context.parsed.y + '%';
                                }
                            }
                        }
                    }
                }
            });

            gsap.registerPlugin(ScrollTrigger);

            gsap.from('.neon-text-green', {
                opacity: 0,
                y: 50,
                duration: 1,
                ease: "power3.out"
            });
            gsap.from('.neon-text-cyan', {
                opacity: 0,
                y: 50,
                duration: 1,
                delay: 0.3,
                ease: "power3.out"
            });
            gsap.from('#live-games .grid > div', {
                opacity: 0,
                y: 50,
                duration: 1,
                stagger: 0.2,
                scrollTrigger: {
                    trigger: '#live-games',
                    start: 'top 80%',
                    end: 'bottom 20%',
                    toggleActions: 'play none none reverse'
                }
            });
            gsap.from('#data-analytics .grid > div', {
                opacity: 0,
                y: 50,
                duration: 1,
                stagger: 0.2,
                scrollTrigger: {
                    trigger: '#data-analytics',
                    start: 'top 80%',
                    end: 'bottom 20%',
                    toggleActions: 'play none none reverse'
                }
            });
        });
    </script>

</body>
</html>
