```html
<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Minimalist Weather App</title>
    <link href="https://fonts.googleapis.com/css2?family=Roboto+Condensed:wght@400;700&family=Roboto:wght@400;500&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="REMOVED-SHA-DUE-TO-INSTRUCTION" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Roboto', sans-serif;
            transition: background-color 0.5s ease;
        }
        .weather-header {
            font-family: 'Roboto Condensed', sans-serif;
        }
        .animated-bg {
            transition: background-image 0.5s ease;
        }
        .chart-container {
            overflow-x: auto;
        }
        .bar {
            transition: height 0.3s ease, background-color 0.3s ease;
        }
        .temp-circle {
            transition: background-color 0.3s ease, transform 0.3s ease;
        }
        .temp-circle:hover {
            transform: scale(1.1);
        }
        .day-card {
            transition: background-color 0.3s ease, transform 0.3s ease, box-shadow 0.3s ease;
        }
        .day-card:hover {
            transform: scale(1.05);
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
        }
        .location-input {
            transition: border-color 0.3s ease, box-shadow 0.3s ease;
        }
        .location-input:focus {
            border-color: #60a5fa;
            box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.5);
        }
    </style>
</head>
<body class="bg-blue-100 text-gray-800">

    <div class="min-h-screen flex flex-col">

        <!-- Animated Background -->
        <div id="bg-gradient" class="fixed inset-0 animated-bg -z-10"></div>

        <!-- Header & Location -->
        <header class="weather-header p-6 text-center mb-8">
            <h1 class="text-4xl font-bold text-gray-900 mb-2">Minimal Weather</h1>
            <div class="flex justify-center items-center space-x-2">
                <i class="fa-solid fa-location-dot text-gray-600"></i>
                <input type="text" id="location-input" placeholder="Enter location" class="location-input px-4 py-2 rounded-full border border-gray-300 focus:outline-none">
            </div>
        </header>

        <main class="flex-grow container mx-auto px-6 pb-12">

            <!-- Current Weather -->
            <section id="current-weather" class="mb-10">
                <div class="bg-white rounded-3xl shadow-xl p-8 flex flex-col md:flex-row items-center justify-around">
                    <div class="text-center md:text-left">
                        <h2 id="city-name" class="text-3xl font-bold text-gray-900 mb-2">City Name</h2>
                        <p id="date-time" class="text-gray-600 mb-4">Today, 12:00 PM</p>
                        <div class="flex items-center justify-center md:justify-start space-x-4 mb-4">
                            <i id="weather-icon" class="fa-solid fa-sun text-4xl text-yellow-500"></i>
                            <p id="weather-description" class="text-xl text-gray-700">Sunny</p>
                        </div>
                        <p class="text-5xl font-bold text-gray-900">
                            <span id="temperature" class="temp-circle inline-block p-3 rounded-full bg-blue-200 text-blue-800 hover:bg-blue-300 cursor-pointer">25°C</span>
                        </p>
                    </div>
                    <div class="text-center">
                        <img id="current-image" src="https://picsum.photos/200/300?random=1" alt="Weather condition" class="rounded-xl shadow-md w-64 h-auto">
                    </div>
                </div>
            </section>

            <!-- Hourly Forecast Chart -->
            <section id="hourly-forecast" class="mb-10">
                <h2 class="text-2xl font-bold text-gray-900 mb-6">Hourly Forecast</h2>
                <div class="bg-white rounded-3xl shadow-xl p-6 chart-container">
                    <div id="hourly-chart" class="flex items-end justify-around h-40">
                        <!-- Chart bars will be dynamically added here -->
                    </div>
                </div>
            </section>

            <!-- Daily Forecast Cards -->
            <section id="daily-forecast">
                <h2 class="text-2xl font-bold text-gray-900 mb-6">7-Day Forecast</h2>
                <div id="daily-cards" class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    <!-- Day cards will be dynamically added here -->
                </div>
            </section>

        </main>

        <footer class="weather-header text-center p-6 mt-8 bg-gray-100 text-gray-700">
            <p>&copy; 2024 Minimal Weather App</p>
        </footer>

    </div>

    <script>
        const bgGradient = document.getElementById('bg-gradient');
        const weatherIcon = document.getElementById('weather-icon');
        const weatherDescription = document.getElementById('weather-description');
        const temperatureElement = document.getElementById('temperature');
        const cityNameElement = document.getElementById('city-name');
        const dateTimeElement = document.getElementById('date-time');
        const hourlyChartElement = document.getElementById('hourly-chart');
        const dailyCardsElement = document.getElementById('daily-cards');
        const currentImageElement = document.getElementById('current-image');
        const locationInput = document.getElementById('location-input');

        function updateBackground(condition) {
            let bgColorStart, bgColorEnd, iconClass, textColorClass, iconColorClass;
            let backgroundImage = '';

            if (condition.includes("clear")) {
                bgColorStart = 'blue-200';
                bgColorEnd = 'blue-400';
                iconClass = 'fa-sun';
                iconColorClass = 'text-yellow-500';
                backgroundImage = 'bg-gradient-to-b from-blue-200 to-blue-400';
            } else if (condition.includes("cloud")) {
                bgColorStart = 'gray-200';
                bgColorEnd = 'gray-300';
                iconClass = 'fa-cloud';
                iconColorClass = 'text-gray-500';
                backgroundImage = 'bg-gradient-to-b from-gray-200 to-gray-300';
            } else if (condition.includes("rain")) {
                bgColorStart = 'gray-400';
                bgColorEnd = 'gray-500';
                iconClass = 'fa-cloud-rain';
                iconColorClass = 'text-blue-700';
                backgroundImage = 'bg-gradient-to-b from-gray-400 to-gray-500';
            } else if (condition.includes("snow")) {
                bgColorStart = 'blue-100';
                bgColorEnd = 'blue-200';
                iconClass = 'fa-snowflake';
                iconColorClass = 'text-white';
                backgroundImage = 'bg-gradient-to-b from-blue-100 to-blue-200';
            } else if (condition.includes("thunderstorm")) {
                bgColorStart = 'yellow-700';
                bgColorEnd = 'yellow-900';
                iconClass = 'fa-bolt';
                iconColorClass = 'text-yellow-300';
                backgroundImage = 'bg-gradient-to-b from-yellow-700 to-yellow-900';
            } else if (condition.includes("mist") || condition.includes("haze")) {
                bgColorStart = 'gray-100';
                bgColorEnd = 'gray-200';
                iconClass = 'fa-smog';
                iconColorClass = 'text-gray-400';
                backgroundImage = 'bg-gradient-to-b from-gray-100 to-gray-200';
            } else {
                bgColorStart = 'blue-100';
                bgColorEnd = 'blue-300';
                iconClass = 'fa-question-circle';
                iconColorClass = 'text-gray-600';
                backgroundImage = 'bg-gradient-to-b from-blue-100 to-blue-300';
            }

            bgGradient.className = `fixed inset-0 animated-bg -z-10 ${backgroundImage}`;
            weatherIcon.className = `fa-solid ${iconClass} text-4xl ${iconColorClass}`;
        }

        function updateDateTime() {
            const now = new Date();
            const options = { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: 'numeric', hour12: true };
            dateTimeElement.textContent = now.toLocaleDateString('en-US', options);
        }

        function updateHourlyChart(hourlyData) {
            hourlyChartElement.innerHTML = '';
            const maxTemp = Math.max(...hourlyData.map(hour => hour.temp_c));
            hourlyData.forEach(hour => {
                const barHeight = (hour.temp_c / maxTemp) * 100;
                const bar = document.createElement('div');
                bar.className = 'bar bg-blue-300 hover:bg-blue-500 rounded-b w-8 mx-1 flex flex-col justify-end items-center';
                bar.style.height = `${barHeight}%`;
                bar.innerHTML = `
                    <span class="text-xs text-gray-700 mb-1">${hour.time.split(' ')[1]}</span>
                    <span class="text-sm text-white bg-blue-500 rounded-t-md px-1 py-0.5">${hour.temp_c}°C</span>
                `;
                hourlyChartElement.appendChild(bar);
            });
        }

        function updateDailyCards(dailyData) {
            dailyCardsElement.innerHTML = '';
            dailyData.forEach(day => {
                const dayCard = document.createElement('div');
                dayCard.className = 'day-card bg-white rounded-xl shadow-md p-4 text-center hover:bg-gray-100 cursor-pointer';
                dayCard.innerHTML = `
                    <h3 class="font-semibold text-gray-800">${day.date}</h3>
                    <i class="fa-solid ${getDayIconClass(day.condition)} text-2xl my-2 ${getDayIconColorClass(day.condition)}"></i>
                    <p class="text-gray-700">${day.avgtemp_c}°C</p>
                    <p class="text-sm text-gray-600">${day.condition}</p>
                `;
                dailyCardsElement.appendChild(dayCard);
            });
        }

        function getDayIconClass(condition) {
            if (condition.includes("clear")) return 'fa-sun';
            if (condition.includes("cloud")) return 'fa-cloud';
            if (condition.includes("rain")) return 'fa-cloud-rain';
            if (condition.includes("snow")) return 'fa-snowflake';
            if (condition.includes("thunderstorm")) return 'fa-bolt';
            if (condition.includes("mist") || condition.includes("haze")) return 'fa-smog';
            return 'fa-question-circle';
        }
        function getDayIconColorClass(condition) {
            if (condition.includes("clear")) return 'text-yellow-500';
            if (condition.includes("cloud")) return 'text-gray-500';
            if (condition.includes("rain")) return 'text-blue-700';
            if (condition.includes("snow")) return 'text-white';
            if (condition.includes("thunderstorm")) return 'text-yellow-300';
            if (condition.includes("mist") || condition.includes("haze")) return 'text-gray-400';
            return 'text-gray-600';
        }


        function updateWeatherUI(weatherData) {
            cityNameElement.textContent = weatherData.location.name + ', ' + weatherData.location.country;
            temperatureElement.textContent = `${weatherData.current.temp_c}°C`;
            weatherDescription.textContent = weatherData.current.condition.text;
            updateBackground(weatherData.current.condition.text.toLowerCase());
            updateDateTime();
            updateHourlyChart(weatherData.forecast.forecastday[0].hour.slice(0,8)); // Display next 8 hours
            updateDailyCards(weatherData.forecast.forecastday.map(day => ({
                date: day.date,
                avgtemp_c: day.day.avgtemp_c,
                condition: day.day.condition.text
            })));
            currentImageElement.src = `https://picsum.photos/200/300?random=${Math.random()}`; // Example image update
        }

        async function fetchWeatherData(location) {
            const apiKey = 'YOUR_API_KEY'; // Replace with your actual API key
            const apiUrl = `https://api.weatherapi.com/v1/forecast.json?key=${apiKey}&q=${location}&days=7&aqi=no&alerts=no`;

            try {
                const response = await fetch(apiUrl);
                const data = await response.json();
                if(data.error) {
                    alert("Location not found. Please enter a valid location.");
                    return;
                }
                updateWeatherUI(data);
            } catch (error) {
                console.error('Error fetching weather data:', error);
                alert('Failed to fetch weather data. Please try again.');
            }
        }

        locationInput.addEventListener('keypress', function(event) {
            if (event.key === 'Enter') {
                const location = locationInput.value;
                if (location) {
                    fetchWeatherData(location);
                } else {
                    alert("Please enter a location.");
                }
                locationInput.blur();
            }
        });

        // Initial Weather Load (Default Location - can be improved with geolocation)
        fetchWeatherData('London');

        // Optional: Update time every minute
        setInterval(updateDateTime, 60000);

    </script>

</body>
</html>
