    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const mobileMenuButton = document.querySelector('[aria-controls="mobile-menu"]');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            gsap.registerPlugin(ScrollTrigger);

            gsap.utils.toArray('section').forEach(section => {
                gsap.from(section.querySelectorAll('.bebas-neue, p, .grid > div, table'), {
                    y: 50,
                    opacity: 0,
                    duration: 1,
                    ease: "power3.out",
                    stagger: 0.2,
                    scrollTrigger: {
                        trigger: section,
                        start: "top 80%",
                        end: "top 20%",
                        toggleActions: "play none none reverse"
                    }
                });
            });

            const slider = document.getElementById('artistSlider');
            const prevButton = document.getElementById('sliderPrev');
            const nextButton = document.getElementById('sliderNext');
            let slideIndex = 0;
            const slides = document.querySelectorAll('.lineup-slide');
            const slideWidth = slides[0].offsetWidth;

            function updateSlider() {
                slider.style.transform = `translateX(-${slideIndex * slideWidth}px)`;
            }

            nextButton.addEventListener('click', () => {
                if (slideIndex < slides.length - 1) {
                    slideIndex++;
                } else {
                    slideIndex = 0;
                }
                updateSlider();
            });

            prevButton.addEventListener('click', () => {
                if (slideIndex > 0) {
                    slideIndex--;
                } else {
                    slideIndex = slides.length - 1;
                }
                updateSlider();
            });

            setInterval(() => {
                if (slideIndex < slides.length - 1) {
                    slideIndex++;
                } else {
                    slideIndex = 0;
                }
                updateSlider();
            }, 5000);
        });
    </script>

</body>
</html>
