                    fontFamily: {
                        'poppins': ['Poppins', 'sans-serif'],
                        'nunito': ['Nunito Sans', 'sans-serif'],
                    },
                    keyframes: {
                        'nature-float': {
                            '0%, 100%': { transform: 'translateY(0px)' },
                            '50%': { transform: 'translateY(-10px)' },
                        },
                        'fade-in-down': {
                            '0%': {
                                opacity: '0',
                                transform: 'translateY(-20px)'
                            },
                            '100%': {
                                opacity: '1',
                                transform: 'translateY(0)'
                            },
                        },
                        'fade-out-up': {
                            '0%': {
                                opacity: '1',
                                transform: 'translateY(0)'
                            },
                            '100%': {
                                opacity: '0',
                                transform: 'translateY(-20px)'
                            },
                        },
                    },
                    animation: {
                        'nature-float': 'nature-float 6s ease-in-out infinite',
                        'fade-in-down': 'fade-in-down 0.5s ease-out',
                        'fade-out-up': 'fade-out-up 0.5s ease-out',
                    },
                },
            },
        }
    </script>
    <style>
        .hero-area::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(247, 250, 250, 0.4);
            backdrop-filter: blur(5px);
            z-index: 1;
        }
        .hero-image-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            z-index: 0;
        }
        .content-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 2rem;
        }
        .content-card {
            background-color: white;
            border-radius: 0.75rem;
            overflow: hidden;
            transition: transform 0.3s ease, shadow 0.3s ease;
        }
        .content-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1);
        }
        .animated-nature-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 0;
            overflow: hidden;
        }

