                <a href="#" class="text-teal-500 hover:text-teal-600 transition-colors"><i data-lucide="phone" class="w-7 h-7"></i> Phone</a>
                <a href="#" class="text-teal-500 hover:text-teal-600 transition-colors"><i data-lucide="map-pin" class="w-7 h-7"></i> Location</a>
            </div>
        </div>
