    <script>
        lucide.createIcons();

        document.addEventListener('DOMContentLoaded', function() {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', function() {
                mobileMenu.classList.toggle('hidden');
            });

            const calendarDaysContainer = document.getElementById('calendar-days');
            const currentMonthSpan = document.getElementById('current-month');
            const prevMonthButton = document.getElementById('prev-month');
            const nextMonthButton = document.getElementById('next-month');

            let currentDate = new Date();
            let selectedDate = null;

            function generateCalendar(date) {
                calendarDaysContainer.innerHTML = '';
                currentMonthSpan.textContent = date.toLocaleString('default', { month: 'long', year: 'numeric' });

                const firstDayOfMonth = new Date(date.getFullYear(), date.getMonth(), 1);
                const daysInMonth = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
                const startingDayOfWeek = firstDayOfMonth.getDay();

                for (let i = 0; i < startingDayOfWeek; i++) {
                    const emptyDay = document.createElement('div');
                    calendarDaysContainer.appendChild(emptyDay);
                }

                for (let day = 1; day <= daysInMonth; day++) {
                    const dayElement = document.createElement('div');
                    dayElement.textContent = day;
                    dayElement.classList.add('booking-calendar-day', 'py-2', 'px-3', 'text-center', 'rounded-md');

                    if (currentDate.getDate() === day && currentDate.getMonth() === date.getMonth() && currentDate.getFullYear() === date.getFullYear()) {
                        dayElement.classList.add('bg-teal-200');
                    }

                    dayElement.addEventListener('click', function() {
                        document.querySelectorAll('.booking-calendar-day.selected').forEach(el => el.classList.remove('selected'));
                        dayElement.classList.add('selected');
                        selectedDate = new Date(date.getFullYear(), date.getMonth(), day);
                        console.log('Selected date:', selectedDate);
                    });
                    calendarDaysContainer.appendChild(dayElement);
                }
            }

            generateCalendar(currentDate);

            prevMonthButton.addEventListener('click', function() {
                currentDate.setMonth(currentDate.getMonth() - 1);
                generateCalendar(currentDate);
            });

            nextMonthButton.addEventListener('click', function() {
                currentDate.setMonth(currentDate.getMonth() + 1);
                generateCalendar(currentDate);
            });
        });
    </script>

</body>
</html>
