        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        gsap.registerPlugin(ScrollTrigger);

        gsap.utils.toArray(".parallax-group").forEach((group, index) => {
            let layers = group.querySelectorAll(".parallax-layer");

            layers.forEach((layer) => {
                let speed = layer.classList.contains("parallax-back") ? -0.5 : layer.classList.contains("parallax-front") ? 0.5 : 0;
                gsap.to(layer, {
                    yPercent: speed * 100,
                    ease: "none",
                    scrollTrigger: {
                        trigger: group,
                        start: "top bottom",
                        end: "bottom top",
                        scrub: 0.1,
                        invalidateOnRefresh: true
                    }
                });
            });
        });

        gsap.from('#services .grid > div', {
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.2,
            scrollTrigger: {
                trigger: '#services',
                start: 'top 80%',
                end: 'bottom 20%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.from('#portfolio .grid > div', {
            y: 50,
            opacity: 0,
            duration: 1,
            stagger: 0.2,
            scrollTrigger: {
                trigger: '#portfolio',
                start: 'top 80%',
                end: 'bottom 20%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.from('#about > div > *', {
            x: i => i % 2 === 0 ? -50 : 50,
            opacity: 0,
            duration: 1,
            stagger: 0.2,
            scrollTrigger: {
                trigger: '#about',
                start: 'top 80%',
                end: 'bottom 20%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.from('#contact .max-w-lg > *', {
            y: 30,
            opacity: 0,
            duration: 0.8,
            stagger: 0.15,
            scrollTrigger: {
                trigger: '#contact',
                start: 'top 80%',
                end: 'bottom 20%',
                toggleActions: 'play none none reverse'
            }
        });

        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                if (this.getAttribute('href') !== '#') {
                    document.querySelector(this.getAttribute('href')).scrollIntoView({
                        behavior: 'smooth'
                    });
                } else {
                    window.scrollTo({
                        top: 0,
                        behavior: 'smooth'
                    });
                }
                if (mobileMenu.classList.contains('hidden') === false) {
                    mobileMenu.classList.add('hidden');
                }
            });
        });
    </script>
</body>
</html>
