    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="YOUR-FONT-AWESOME-INTEGRITY-VALUE" crossorigin="anonymous" referrerpolicy="no-referrer" />
