    <style>
        body { font-family: 'Poppins', sans-serif; }
        .config-section {
            transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out;
        }
        .config-section.hidden {
            opacity: 0;
            transform: translateY(20px);
            pointer-events: none;
        }
        .config-step-active {
            border-color: #6366f1;
            background-color: #e0e7ff;
            color: #6366f1;
        }
        .furniture-view-3d {
            perspective: 1000px;
        }
        .furniture-model {
            transition: transform 0.7s ease-in-out;
            transform-style: preserve-3d;
        }
        .furniture-model-rotate-y-45 { transform: rotateY(45deg); }
        .furniture-model-rotate-y-90 { transform: rotateY(90deg); }
        .furniture-model-rotate-y-135 { transform: rotateY(135deg); }
        .furniture-model-rotate-y-180 { transform: rotateY(180deg); }
        .furniture-model-rotate-y-225 { transform: rotateY(225deg); }
        .furniture-model-rotate-y-270 { transform: rotateY(270deg); }
        .furniture-model-rotate-y-315 { transform: rotateY(315deg); }
        .furniture-model-rotate-y-0 { transform: rotateY(0deg); }


        @keyframes pulse-shadow {
            0% { box-shadow: 0 0 0 0 rgba(99, 102, 241, 0.4); }
            70% { box-shadow: 0 0 0 10px rgba(99, 102, 241, 0); }
            100% { box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); }
        }

        .pulse-border {
            border-width: 2px;
            animation: pulse-shadow 2s infinite;
        }


    </style>
</head>
