                Furniture Configurator
            </h2>

            <div class="mb-10 flex justify-center space-x-4">
                <button id="config-step-1-btn" class="config-step-btn px-4 py-2 rounded-full border border-gray-300 hover:border-indigo-500 hover:bg-indigo-50 transition-colors config-step-active" data-step="1">1. Model</button>
                <button id="config-step-2-btn" class="config-step-btn px-4 py-2 rounded-full border border-gray-300 hover:border-indigo-500 hover:bg-indigo-50 transition-colors" data-step="2">2. Color</button>
                <button id="config-step-3-btn" class="config-step-btn px-4 py-2 rounded-full border border-gray-300 hover:border-indigo-500 hover:bg-indigo-50 transition-colors" data-step="3">3. Review</button>
            </div>

            <div id="config-step-1" class="config-section">
                <h3 class="text-2xl font-semibold text-gray-900 mb-6 text-center">Choose Your Model</h3>
                <div class="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <div class="rounded-xl overflow-hidden shadow-lg hover:shadow-2xl transition-shadow duration-300 cursor-pointer model-option" data-model="chair">
