    <script>
        const configSteps = ['config-step-1', 'config-step-2', 'config-step-3'];
        const configStepButtons = ['config-step-1-btn', 'config-step-2-btn', 'config-step-3-btn'];
        let currentStep = 1;
        let selectedModel = 'chair';
        let selectedColor = '#f8fafc';
        let selectedColorName = 'White';

        function showStep(stepNumber) {
            configSteps.forEach((stepId, index) => {
                const stepElement = document.getElementById(stepId);
                const stepButton = document.getElementById(configStepButtons[index]);
                if (index + 1 === stepNumber) {
                    stepElement.classList.remove('hidden');
                    stepButton.classList.add('config-step-active');
                } else {
                    stepElement.classList.add('hidden');
                    stepButton.classList.remove('config-step-active');
                }
            });
            currentStep = stepNumber;
        }

        configStepButtons.forEach(buttonId => {
            document.getElementById(buttonId).addEventListener('click', (event) => {
                const step = parseInt(event.target.dataset.step);
                showStep(step);
            });
        });

        document.querySelectorAll('.model-option').forEach(option => {
            option.addEventListener('click', function() {
                selectedModel = this.dataset.model;
                document.querySelectorAll('.model-option').forEach(opt => opt.classList.remove('pulse-border'));
                this.classList.add('pulse-border');
                updatePreview();
                showStep(2);
            });
        });

        document.querySelectorAll('.color-option').forEach(option => {
            option.addEventListener('click', function() {
                selectedColor = this.dataset.color;
                selectedColorName = this.style.backgroundColor;
                document.querySelectorAll('.color-option').forEach(opt => opt.classList.remove('pulse-border'));
                this.classList.add('pulse-border');
                updatePreview();
                showStep(3);
            });
        });

        document.querySelectorAll('.rotate-btn').forEach(button => {
            button.addEventListener('click', function() {
                const rotation = this.dataset.rotation;
                const modelView = document.getElementById('furniture-preview-image');
                modelView.classList.remove('furniture-model-rotate-y-0', 'furniture-model-rotate-y-45', 'furniture-model-rotate-y-90', 'furniture-model-rotate-y-135', 'furniture-model-rotate-y-180', 'furniture-model-rotate-y-225', 'furniture-model-rotate-y-270', 'furniture-model-rotate-y-315');
                modelView.classList.add(`furniture-model-rotate-y-${rotation}`);
            });
        });


        function updatePreview() {
            const previewImage = document.getElementById('furniture-preview-image');
            previewImage.src = `https://picsum.photos/200/300?furniture=${selectedModel}&color=${selectedColor.substring(1)}`;
            document.getElementById('review-model').textContent = selectedModel.charAt(0).toUpperCase() + selectedModel.slice(1);
            const reviewColorPreview = document.getElementById('review-color-preview');
            reviewColorPreview.style.backgroundColor = selectedColor;
            document.getElementById('review-color-name').textContent = selectedColorName;

        }

        showStep(1);
    </script>

</body>
</html>
