        .lightbox { display: none; position: fixed; z-index: 1000; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0,0,0,0.9); overflow: auto; text-align: center; }
        .lightbox-content { position: relative; margin: auto; display: block; max-width: 90%; max-height: 90%; }
        .lightbox-close { position: absolute; top: 15px; right: 15px; color: white; font-size: 30px; font-weight: bold; cursor: pointer; }
        .fade { animation-name: fade; animation-duration: 1.5s; }
        @keyframes fade { from {opacity: .4} to {opacity: 1} }
        .slide-in-bottom { animation: slide-in-bottom 0.5s cubic-bezier(0.250, 0.460, 0.450, 0.940) both; }
        @keyframes slide-in-bottom {
