        <div class="container mx-auto px-4 md:px-6 lg:px-8 text-center">
            <p>&copy; 2024 Photographer Name. All rights reserved.</p>
            <div class="mt-4 flex justify-center space-x-6">
                <a href="#" class="hover:text-white"><i class="fab fa-facebook-square fa-lg"></i></a>
                <a href="#" class="hover:text-white"><i class="fab fa-instagram fa-lg"></i></a>
                <a href="#" class="hover:text-white"><i class="fab fa-twitter-square fa-lg"></i></a>
            </div>
        </div>
    </footer>

    <div id="lightbox" class="lightbox fade" onclick="closeLightbox()">
        <span class="lightbox-close" onclick="closeLightbox()">&times;</span>
        <img class="lightbox-content" id="lightbox-img">
    </div>

    <script>
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });

        let slideIndex = 0;
        const slides = document.querySelector('.slider-wrapper');
        const slideWidth = document.querySelector('.slide').offsetWidth;
        const prevButton = document.getElementById('prevSlide');
        const nextButton = document.getElementById('nextSlide');

        function showSlide(index) {
            slides.style.transform = `translateX(${-slideWidth * index}px)`;
        }

        function nextSlide() {
            slideIndex = (slideIndex + 1) % 3;
            showSlide(slideIndex);
        }

        function prevSlide() {
            slideIndex = (slideIndex - 1 + 3) % 3;
            showSlide(slideIndex);
        }

        let sliderInterval = setInterval(nextSlide, 5000);

        nextButton.addEventListener('click', () => {
            clearInterval(sliderInterval);
            nextSlide();
            sliderInterval = setInterval(nextSlide, 5000);
        });

        prevButton.addEventListener('click', () => {
            clearInterval(sliderInterval);
            prevSlide();
            sliderInterval = setInterval(nextSlide, 5000);
        });

        const portfolioItems = document.querySelectorAll('.portfolio-item img');
        const lightbox = document.getElementById('lightbox');
        const lightboxImg = document.getElementById('lightbox-img');

        portfolioItems.forEach(item => {
            item.addEventListener('click', () => {
                lightbox.style.display = 'block';
                lightboxImg.src = item.src;
            });
        });

        function closeLightbox() {
            lightbox.style.display = 'none';
        }
    </script>

</body>
</html>
