<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Epic Comics Reader</title>
    <link href="https://fonts.googleapis.com/css2?family=Bebas+Neue:wght@400&family=Roboto:wght@400;700&display=swap" rel="stylesheet">
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <style>
        body {
            font-family: 'Roboto', sans-serif;
        }
        .bebas-neue {
            font-family: 'Bebas Neue', sans-serif;
        }
        .panel-transition {
            transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out;
        }
        .page-flip-right {
            transform-origin: right center;
            animation: pageFlipRight 0.8s forwards ease-in-out;
        }
        .page-flip-left {
            transform-origin: left center;
            animation: pageFlipLeft 0.8s forwards ease-in-out;
        }
        @keyframes pageFlipRight {
            0% { transform: rotateY(0); }
            100% { transform: rotateY(-180deg); }
        }
        @keyframes pageFlipLeft {
            0% { transform: rotateY(-180deg); }
            100% { transform: rotateY(0); }
        }
        .shadow-hero {
            filter: drop-shadow(0 0 10px rgba(0, 0, 0, 0.6));
        }
        .vibrant-blue { --tw-bg-opacity: 1; background-color: rgba(37, 99, 235, var(--tw-bg-opacity)); }
        .vibrant-red { --tw-bg-opacity: 1; background-color: rgba(220, 38, 38, var(--tw-bg-opacity)); }
        .vibrant-yellow { --tw-bg-opacity: 1; background-color: rgba(251, 191, 36, var(--tw-bg-opacity)); }
        .vibrant-text-blue { color: rgba(37, 99, 235, 1); }
        .vibrant-text-red { color: rgba(220, 38, 38, 1); }
        .vibrant-text-yellow { color: rgba(251, 191, 36, 1); }
        .hero-bg-gradient {
            background: linear-gradient(135deg, #2563eb, #dc2626, #fbbd24);
            background-size: 200% 200%;
            animation: gradientAnimation 15s ease infinite;
        }
        @keyframes gradientAnimation {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
    </style>
</head>
<body class="bg-gray-50">

    <header class="hero-bg-gradient py-20 md:py-32 text-center text-white overflow-hidden relative">
        <div class="absolute inset-0 opacity-20" style="background: url('https://picsum.photos/id/10/1920/1080'); background-position: center; background-size: cover;"></div>
        <div class="relative">
            <h1 class="bebas-neue text-6xl md:text-8xl vibrant-text-yellow shadow-hero">DYNAMIC COMICS</h1>
            <p class="mt-4 text-xl md:text-2xl vibrant-text-blue shadow-hero">Experience Stories Like Never Before</p>
            <div class="mt-8 flex justify-center space-x-4">
                <button class="bg-white text-vibrant-red font-bold py-3 px-6 rounded-full hover:bg-gray-100 transition-colors shadow-md">
                    <i class="fa-solid fa-book-open mr-2"></i> Start Reading
                </button>
                <button class="border-2 border-white hover:border-gray-200 text-white font-bold py-3 px-6 rounded-full transition-colors shadow-md">
                    <i class="fa-solid fa-circle-info mr-2"></i> Learn More
                </button>
            </div>
        </div>
    </header>

    <main class="container mx-auto px-4 py-12 md:py-24">
        <section id="comic-reader" class="relative">
            <div id="comic-panel-container" class="relative bg-white shadow-xl rounded-lg overflow-hidden">
                <div id="comic-panel" class="panel-transition flex justify-center items-center">
                    <img id="comic-image" src="https://picsum.photos/id/1/800/1200" alt="Comic Panel" class="block max-w-full max-h-screen">
                </div>
            </div>

            <div class="mt-8 flex justify-between items-center">
                <button id="prev-panel" class="bg-gray-200 hover:bg-gray-300 text-gray-700 font-bold py-2 px-4 rounded-full transition-colors" disabled>
                    <i class="fa-solid fa-arrow-left"></i> Previous
                </button>
                <div id="page-indicator">Page 1</div>
                <button id="next-panel" class="bg-vibrant-blue hover:bg-vibrant-red text-white font-bold py-2 px-4 rounded-full transition-colors">
                    Next <i class="fa-solid fa-arrow-right"></i>
                </button>
            </div>

            <div id="navigation-controls" class="mt-8 flex justify-center space-x-4">
                <button id="first-page" class="bg-gray-200 hover:bg-gray-300 text-gray-700 font-bold py-2 px-4 rounded-md transition-colors">
                    <i class="fa-solid fa-angles-left"></i> First
                </button>
                <button id="last-page" class="bg-gray-200 hover:bg-gray-300 text-gray-700 font-bold py-2 px-4 rounded-md transition-colors">
                    Last <i class="fa-solid fa-angles-right"></i>
                </button>
                <button id="toggle-thumbnails" class="bg-gray-200 hover:bg-gray-300 text-gray-700 font-bold py-2 px-4 rounded-md transition-colors">
                    <i class="fa-solid fa-images"></i> Thumbnails
                </button>
            </div>

            <div id="thumbnail-strip" class="hidden mt-8 p-4 bg-gray-100 rounded-md overflow-x-auto whitespace-nowrap">
                </div>

        </section>
    </main>

    <footer class="bg-gray-900 text-gray-300 py-12">
        <div class="container mx-auto px-4 text-center">
            <p>&copy; 2024 Epic Comics. All rights reserved.</p>
            <p class="mt-2">Powered by Dynamic Storytelling</p>
        </div>
    </footer>

    <script>
        const comicPanel = document.getElementById('comic-panel');
        const comicImage = document.getElementById('comic-image');
        const prevPanelButton = document.getElementById('prev-panel');
        const nextPanelButton = document.getElementById('next-panel');
        const pageIndicator = document.getElementById('page-indicator');
        const firstPageButton = document.getElementById('first-page');
        const lastPageButton = document.getElementById('last-page');
        const thumbnailStrip = document.getElementById('thumbnail-strip');
        const toggleThumbnailsButton = document.getElementById('toggle-thumbnails');

        const totalPages = 10;
        let currentPage = 1;
        let isFlipping = false;

        function updatePanel() {
            if (isFlipping) return;
            isFlipping = true;

            const newImageSrc = `https://picsum.photos/id/${currentPage}/${800}/1200`;
            const flipDirection = currentPage > previousPage ? 'page-flip-right' : 'page-flip-left';
            previousPage = currentPage;

            comicPanel.classList.add(flipDirection);
            comicPanel.style.opacity = 0;

            setTimeout(() => {
                comicImage.src = newImageSrc;
                pageIndicator.textContent = `Page ${currentPage}`;
                prevPanelButton.disabled = currentPage <= 1;
                nextPanelButton.disabled = currentPage >= totalPages;

                comicPanel.classList.remove(flipDirection);
                comicPanel.style.opacity = 1;
                isFlipping = false;
            }, 400);
        }

        let previousPage = 1;
        nextPanelButton.addEventListener('click', () => {
            if (currentPage < totalPages) {
                currentPage++;
                updatePanel();
            }
        });

        prevPanelButton.addEventListener('click', () => {
            if (currentPage > 1) {
                currentPage--;
                updatePanel();
            }
        });

        firstPageButton.addEventListener('click', () => {
            currentPage = 1;
            updatePanel();
        });

        lastPageButton.addEventListener('click', () => {
            currentPage = totalPages;
            updatePanel();
        });

        toggleThumbnailsButton.addEventListener('click', () => {
            thumbnailStrip.classList.toggle('hidden');
        });

        function generateThumbnails() {
            for (let i = 1; i <= totalPages; i++) {
                const thumbnail = document.createElement('img');
                thumbnail.src = `https://picsum.photos/id/${i}/100/150`;
                thumbnail.alt = `Page ${i}`;
                thumbnail.classList.add('inline-block', 'w-20', 'h-30', 'object-cover', 'rounded-md', 'mx-1', 'cursor-pointer', 'hover:opacity-75', 'transition-opacity');
                thumbnail.addEventListener('click', () => {
                    currentPage = i;
                    updatePanel();
                    thumbnailStrip.classList.add('hidden');
                });
                thumbnailStrip.appendChild(thumbnail);
            }
        }
        generateThumbnails();
    </script>

</body>
</html>
