                <button class="btn-primary btn-primary px-6 py-3 rounded-full font-semibold hover:shadow-lg transition-shadow" id="add-to-plan-btn">
                    Add to Meal Plan <i class="fa-solid fa-calendar-plus ml-2"></i>
