    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const heroSection = document.querySelector('.hero-section .fade-in-slide-down');
            heroSection.classList.add('active');
        });

        const viewRecipeButtons = document.querySelectorAll('.view-recipe-btn');
        const recipePopup = document.getElementById('recipe-popup');
        const closePopupButton = document.getElementById('close-popup');

        const recipeTitlePopup = document.querySelector('.recipe-title-popup');
        const recipeImagePopup = document.querySelector('.recipe-image-popup');
        const recipeInstructionsPopup = document.querySelector('.recipe-instructions-popup');
        const nutrientListPopup = document.querySelector('.nutrient-list-popup');

        viewRecipeButtons.forEach(button => {
            button.addEventListener('click', () => {
                const recipeId = button.dataset.recipeId;
                recipePopup.classList.remove('hidden');
                document.body.classList.add('overflow-hidden');

                if (recipeId === '1') {
                    recipeTitlePopup.textContent = 'Mediterranean Quinoa Salad';
                    recipeImagePopup.src = 'https://picsum.photos/400/300?popup1';
                    recipeInstructionsPopup.textContent = 'Combine cooked quinoa, chopped cucumbers, tomatoes, olives, feta cheese, and a lemon-herb dressing. Toss gently and serve chilled.';
                    nutrientListPopup.innerHTML = `
                        <li>Calories: <span class="font-medium">420</span></li>
                        <li>Protein: <span class="font-medium">15g</span></li>
                        <li>Carbohydrates: <span class="font-medium">50g</span></li>
                        <li>Fat: <span class="font-medium">20g</span></li>
                    `;
                } else if (recipeId === '2') {
                    recipeTitlePopup.textContent = 'Lemon Herb Roasted Chicken';
                    recipeImagePopup.src = 'https://picsum.photos/400/300?popup2';
                    recipeInstructionsPopup.textContent = 'Rub chicken pieces with olive oil, lemon zest, herbs, and garlic. Roast in the oven until golden brown and cooked through.';
                    nutrientListPopup.innerHTML = `
                        <li>Calories: <span class="font-medium">550</span></li>
                        <li>Protein: <span class="font-medium">45g</span></li>
                        <li>Carbohydrates: <span class="font-medium">10g</span></li>
                        <li>Fat: <span class="font-medium">35g</span></li>
                    `;
                } else if (recipeId === '3') {
                    recipeTitlePopup.textContent = 'Vegan Lentil Soup';
                    recipeImagePopup.src = 'https://picsum.photos/400/300?popup3';
                    recipeInstructionsPopup.textContent = 'Sauté vegetables, add lentils, vegetable broth, and spices. Simmer until lentils are tender. Blend a portion for creaminess if desired.';
                    nutrientListPopup.innerHTML = `
                        <li>Calories: <span class="font-medium">380</span></li>
                        <li>Protein: <span class="font-medium">20g</span></li>
                        <li>Carbohydrates: <span class="font-medium">60g</span></li>
                        <li>Fat: <span class="font-medium">8g</span></li>
                    `;
                }
            });
        });

        closePopupButton.addEventListener('click', () => {
            recipePopup.classList.add('hidden');
            document.body.classList.remove('overflow-hidden');
        });

        recipePopup.addEventListener('click', (event) => {
            if (event.target === recipePopup) {
                recipePopup.classList.add('hidden');
                document.body.classList.remove('overflow-hidden');
            }
        });
    </script>

</body>
</html>
