            </div>
        </div>
        <div class="absolute top-0 left-0 w-full h-48 bg-gradient-to-b from-purple-50 to-transparent transform rotate-180"></div>
    </section>

    <footer class="bg-blue-900 py-12 text-white">
        <div class="container mx-auto px-4 text-center">
            <p>&copy; 2024 SereneMind. All rights reserved.</p>
            <p class="mt-4 text-blue-200">
                <a href="#" class="hover:text-white transition-colors">Terms of Service</a> | <a href="#" class="hover:text-white transition-colors">Privacy Policy</a>
            </p>
        </div>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const fadeElements = document.querySelectorAll('.fade-in');
            const slideUpElements = document.querySelectorAll('.slide-up');

            const observerConfig = { threshold: 0.2 };

            const fadeObserver = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('active');
                        fadeObserver.unobserve(entry.target);
                    }
                });
            }, observerConfig);

            fadeElements.forEach(el => fadeObserver.observe(el));

            const slideUpObserver = new IntersectionObserver(entries => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('active');
                        slideUpObserver.unobserve(entry.target);
                    }
                });
            }, observerConfig);

            slideUpElements.forEach(el => slideUpObserver.observe(el));
        });
    </script>

</body>
</html>
