        document.addEventListener('DOMContentLoaded', () => {
            const caseStudyButtons = document.querySelectorAll('.open-case-study');
            const closeButtons = document.querySelectorAll('.close-button');
            const caseStudyModals = document.querySelectorAll('.case-study-modal');

            caseStudyButtons.forEach(button => {
                button.addEventListener('click', () => {
                    const caseStudyId = button.dataset.caseStudy;
                    const modal = document.getElementById(caseStudyId);
                    modal.style.display = "block";
                    document.body.style.overflow = 'hidden';
                });
            });

            closeButtons.forEach(button => {
                button.addEventListener('click', () => {
                    const caseStudyId = button.dataset.caseStudy;
                    const modal = document.getElementById(caseStudyId);
                    modal.style.display = "none";
                    document.body.style.overflow = 'auto';
                });
            });

            window.onclick = function(event) {
                caseStudyModals.forEach(modal => {
                    if (event.target == modal) {
                        modal.style.display = "none";
                        document.body.style.overflow = 'auto';
                    }
                });
            }
        });

        gsap.from('.hero-content h1', {
            y: 50,
            opacity: 0,
            duration: 1,
            ease: 'power3.out'
        });

        gsap.from('.hero-content p', {
            y: 30,
            opacity: 0,
            duration: 1,
            delay: 0.3,
            ease: 'power3.out'
        });

        gsap.from('.hero-content button', {
            y: 30,
            opacity: 0,
            duration: 1,
            delay: 0.6,
            ease: 'power3.out'
        });

        gsap.from('.project-grid', {
            opacity: 0,
            duration: 1,
            delay: 0.5,
            scrollTrigger: {
                trigger: '#projects',
                start: 'top 80%',
                toggleActions: 'play none none reverse'
            }
        });

        gsap.utils.toArray('.project-item').forEach((item, index) => {
            gsap.from(item, {
                opacity: 0,
                y: 50,
                duration: 0.7,
                delay: 0.7 + index * 0.1,
                scrollTrigger: {
                    trigger: '#projects',
                    start: 'top 80%',
                    toggleActions: 'play none none reverse'
                }
            });
        });
    </script>
</body>
</html>
