    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <style>
        body {
            font-family: 'Roboto', sans-serif;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }
        .bebas-neue {
            font-family: 'Bebas Neue', sans-serif;
            letter-spacing: 0.05em;
        }
        .hero-section {
            background-color: #000;
        }
        .neon-pink {
            color: #FF69B4;
        }
        .neon-pink-bg {
            background-color: #FF69B4;
        }
        .grid-animation-container {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
            gap: 1rem;
        }
        .grid-item {
            overflow: hidden;
            border-radius: 0.5rem;
            position: relative;
        }
        .grid-item img {
            transition: transform 0.6s ease-out;
            display: block;
            width: 100%;
            height: auto;
            aspect-ratio: 1 / 1;
            object-fit: cover;
        }
        .grid-item:hover img {
            transform: scale(1.1);
        }
        .grid-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.6);
            color: white;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            opacity: 0;
            transition: opacity 0.3s ease-out;
            padding: 1rem;
            text-align: center;
        }
        .grid-item:hover .grid-overlay {
            opacity: 1;
        }
        .dynamic-text {
            position: relative;
            display: inline-block;
            overflow: hidden;
            white-space: nowrap;
        }
        .dynamic-text span {
            animation: dynamicTextAnimation 8s linear infinite;
            display: inline-block;
        }
        @keyframes dynamicTextAnimation {
            0% { transform: translateX(100%); }
            100% { transform: translateX(-100%); }
        }
        .parallax-bg {
            background-attachment: fixed;
            background-position: center;
            background-repeat: no-repeat;
            background-size: cover;
        }
        .parallax-content {
            position: relative;
            z-index: 1;
        }
        .parallax-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.6);
            z-index: 0;
        }
        .layered-section {
            position: relative;
            overflow: hidden;
        }
        .layered-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.1;
        }
        .layered-content {
            position: relative;
            z-index: 1;
        }
        .hover-neon-pink:hover {
            color: #FF69B4;
        }
        .interactive-link {
            position: relative;
            display: inline-block;
            cursor: pointer;
        }

        .interactive-link::after {
            content: '';
            position: absolute;
            left: 0;
            bottom: -2px;
            width: 100%;
            height: 2px;
            background-color: #FF69B4;
            transform: scaleX(0);
            transform-origin: left;
            transition: transform 0.3s ease-out;
        }

        .interactive-link:hover::after {
            transform: scaleX(1);
        }


    </style>
</head>
<body class="bg-gray-50">

