<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Urban Explorer</title>
    <link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" integrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer" />
    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>
    <style>
        body {
            font-family: 'Space Grotesk', sans-serif;
        }
        .hero-cityscape {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            z-index: -1;
        }
        .neon-text {
            text-shadow: 0 0 5px #fff, 0 0 10px #fff, 0 0 20px #0ff, 0 0 30px #0ff, 0 0 40px #0ff, 0 0 55px #0ff, 0 0 75px #0ff;
        }
        .btn-neon {
            position: relative;
            overflow: hidden;
            transition: color 0.3s ease-in-out;
        }
        .btn-neon::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 200%;
            height: 100%;
            background: linear-gradient(120deg, transparent, #0ff, transparent);
            transform: translateX(-100%);
            transition: transform 0.3s ease-in-out;
        }
        .btn-neon:hover {
            color: #fff;
            box-shadow: 0 0 10px #0ff, 0 0 20px #0ff, 0 0 40px #0ff;
        }
        .btn-neon:hover::before {
            transform: translateX(0);
        }
        .map-overlay-button {
            background-color: rgba(0, 255, 255, 0.2);
            border: 2px solid #0ff;
            color: white;
            padding: 0.5rem 1rem;
            border-radius: 0.375rem;
            cursor: pointer;
            transition: background-color 0.3s, border-color 0.3s;
        }
        .map-overlay-button:hover {
            background-color: rgba(0, 255, 255, 0.5);
            border-color: #0ff;
        }
        .pulse {
            animation: pulse-neon 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
        @keyframes pulse-neon {
            0%, 100% {
                opacity: 1;
            }
            50% {
                opacity: 0.5;
            }
        }
        .animated-border {
            position: relative;
            padding: 2px;
            background: linear-gradient(to right, #0ff, #f0f, #0f0, #0ff);
            background-clip: padding-box;
            border: solid 5px transparent;
            border-radius: 0.5rem;
            animation: border-pulse 4s linear infinite;
        }
        .animated-border::before {
            content: '';
            position: absolute;
            top: 0; right: 0; bottom: 0; left: 0;
            z-index: -1;
            margin: -5px;
            border-radius: inherit;
            background: linear-gradient(to right, #0ff, #f0f, #0f0, #0ff);
            animation: bg-rotate 4s linear infinite;
        }
        @keyframes bg-rotate {
            to {
                --angle: 360deg;
            }
        }
        @property --angle {
            syntax: '<angle>';
            initial-value: 0deg;
            inherits: false;
        }
        @keyframes border-pulse {
            50% {
                box-shadow: 0 0 15px 10px rgba(0, 255, 255, 0.3);
            }
        }
        .layer-shadow {
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06), 0 0 20px rgba(0, 0, 0, 0.3);
        }
    </style>
</head>
<body class="bg-gray-900 text-white">

    <header class="relative h-screen overflow-hidden">
        <img src="https://picsum.photos/1920/1080" alt="Cityscape" class="hero-cityscape">
        <div class="absolute inset-0 bg-black opacity-70"></div>
        <nav class="fixed top-0 left-0 w-full z-50 p-6">
            <div class="container mx-auto flex justify-between items-center">
                <a href="#" class="text-xl font-bold neon-text">UrbanX</a>
                <div class="hidden md:flex space-x-8">
                    <a href="#explore" class="hover:text-cyan-400 transition-colors">Explore</a>
                    <a href="#discover" class="hover:text-cyan-400 transition-colors">Discover</a>
                    <a href="#plan" class="hover:text-cyan-400 transition-colors">Plan Your Trip</a>
                    <button class="btn-neon px-4 py-2 border border-cyan-400 rounded-full hover:bg-cyan-400 hover:text-gray-900 transition-colors">
                        Get Started
                    </button>
                </div>
                <div class="md:hidden">
                    <button id="mobile-menu-button" class="text-white hover:text-cyan-400 focus:outline-none">
                        <i class="fa fa-bars fa-lg"></i>
                    </button>
                </div>
            </div>
        </nav>

        <div id="mobile-menu" class="hidden fixed inset-0 bg-gray-900 z-50 md:hidden">
            <div class="flex flex-col items-center justify-center h-full">
                <button id="mobile-menu-close" class="absolute top-6 right-6 text-white hover:text-cyan-400 focus:outline-none">
                    <i class="fa fa-times fa-lg"></i>
                </button>
                <a href="#explore" class="block py-2 text-xl hover:text-cyan-400 transition-colors">Explore</a>
                <a href="#discover" class="block py-2 text-xl hover:text-cyan-400 transition-colors">Discover</a>
                <a href="#plan" class="block py-2 text-xl hover:text-cyan-400 transition-colors">Plan Your Trip</a>
                <button class="btn-neon px-6 py-3 border border-cyan-400 rounded-full hover:bg-cyan-400 hover:text-gray-900 transition-colors mt-4">
                    Get Started
                </button>
            </div>
        </div>

        <div class="container mx-auto flex flex-col items-center justify-center h-full text-center relative z-10">
            <h1 class="text-5xl md:text-7xl font-bold neon-text mb-6 pulse">
                Uncover the City's Secrets
            </h1>
            <p class="text-lg md:text-xl text-gray-300 mb-12">
                Interactive Urban Exploration Platform
            </p>
            <div class="flex space-x-4">
                <button class="btn-neon px-8 py-4 text-lg rounded-full font-semibold border border-cyan-400 hover:bg-cyan-400 hover:text-gray-900 transition-colors">
                    Explore Now
                </button>
                <button class="btn-neon px-8 py-4 text-lg rounded-full font-semibold border border-pink-400 hover:bg-pink-400 hover:text-gray-900 transition-colors">
                    Learn More
                </button>
            </div>
        </div>
    </header>

    <section id="explore" class="py-20">
        <div class="container mx-auto px-4">
            <h2 class="text-4xl font-bold text-center neon-text mb-16">
                Explore Urban Landscapes
            </h2>
            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                <div class="p-6 rounded-xl bg-gray-800 layer-shadow hover:scale-105 transition-transform duration-300">
                    <img src="https://picsum.photos/400/300" alt="Urban Location 1" class="rounded-md mb-4 w-full h-60 object-cover">
                    <h3 class="text-xl font-semibold mb-2 text-cyan-300">Location Name 1</h3>
                    <p class="text-gray-400">Brief description of location 1. Highlight its unique urban features.</p>
                    <a href="#" class="inline-block mt-4 text-cyan-400 hover:text-cyan-200 transition-colors">Discover More <i class="fa fa-arrow-right ml-1"></i></a>
                </div>
                <div class="p-6 rounded-xl bg-gray-800 layer-shadow hover:scale-105 transition-transform duration-300">
                    <img src="https://picsum.photos/401/300" alt="Urban Location 2" class="rounded-md mb-4 w-full h-60 object-cover">
                    <h3 class="text-xl font-semibold mb-2 text-pink-300">Location Name 2</h3>
                    <p class="text-gray-400">Brief description of location 2. Highlight its unique urban features.</p>
                    <a href="#" class="inline-block mt-4 text-pink-400 hover:text-pink-200 transition-colors">Discover More <i class="fa fa-arrow-right ml-1"></i></a>
                </div>
                <div class="p-6 rounded-xl bg-gray-800 layer-shadow hover:scale-105 transition-transform duration-300">
                    <img src="https://picsum.photos/402/300" alt="Urban Location 3" class="rounded-md mb-4 w-full h-60 object-cover">
                    <h3 class="text-xl font-semibold mb-2 text-green-300">Location Name 3</h3>
                    <p class="text-gray-400">Brief description of location 3. Highlight its unique urban features.</p>
                    <a href="#" class="inline-block mt-4 text-green-400 hover:text-green-200 transition-colors">Discover More <i class="fa fa-arrow-right ml-1"></i></a>
                </div>
            </div>
        </div>
    </section>

    <section id="discover" class="py-20 bg-gray-800">
        <div class="container mx-auto px-4">
            <h2 class="text-4xl font-bold text-center neon-text mb-16">
                Interactive City Map
            </h2>
            <div class="relative rounded-xl overflow-hidden animated-border">
                <img src="https://picsum.photos/1200/600" alt="City Map" class="w-full block rounded-xl">
                <div class="absolute inset-0 flex items-center justify-center pointer-events-none">
                    <div class="grid grid-cols-3 gap-4">
                        <button class="map-overlay-button pulse pointer-events-auto">Landmark 1</button>
                        <button class="map-overlay-button pointer-events-auto">Hidden Gem</button>
                        <button class="map-overlay-button pointer-events-auto">Viewpoint</button>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <section id="plan" class="py-20">
        <div class="container mx-auto px-4">
            <h2 class="text-4xl font-bold text-center neon-text mb-16">
                Plan Your Urban Adventure
            </h2>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div>
                    <h3 class="text-2xl font-semibold mb-4 text-cyan-300">Create Custom Itineraries</h3>
                    <p class="text-gray-400 mb-6">Easily plan your urban exploration routes. Save your favorite locations and create personalized itineraries.</p>
                    <ul class="list-disc list-inside text-gray-400 space-y-2">
                        <li>Drag and drop location planning</li>
                        <li>Save and share itineraries</li>
                        <li>Offline map access</li>
                    </ul>
