    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');
            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });

            const viewArtifactButtons = document.querySelectorAll('.view-artifact-button');
            const artifactModal = document.getElementById('artifact-modal');
            const artifactModalClose = document.getElementById('artifact-modal-close');
            const artifactModalBody = document.getElementById('artifact-modal-body');

            viewArtifactButtons.forEach(button => {
                button.addEventListener('click', () => {
                    const artifactId = button.dataset.artifactId;
                    artifactModal.style.display = 'flex';
                    artifactModalBody.innerHTML = `
                        <img src="https://picsum.photos/id/24${artifactId}/800/600" alt="Artifact Large View" class="w-full rounded-lg mb-4">
                        <h2 class="text-2xl font-bold text-white mb-2">Artifact Title ${artifactId}</h2>
                        <p class="text-gray-300">Detailed description of artifact ${artifactId}.</p>
                    `;
                });
            });

            artifactModalClose.addEventListener('click', () => {
                artifactModal.style.display = 'none';
            });

            artifactModal.addEventListener('click', (event) => {
                if (event.target === artifactModal) {
                    artifactModal.style.display = 'none';
                }
            });

            gsap.from('.hero-section h1', {opacity: 0, y: 50, duration: 1, ease: 'power3.out'});
            gsap.from('.hero-section p', {opacity: 0, y: 30, duration: 1, delay: 0.3, ease: 'power3.out'});
            gsap.from('.hero-section .guide-animation', {opacity: 0, y: 40, duration: 1, delay: 0.6, stagger: 0.2, ease: 'power3.out'});
            gsap.from('.hero-section .group', {opacity: 0, y: 40, duration: 1, delay: 0.9, stagger: 0.2, ease: 'power3.out'});

            gsap.utils.toArray('#exhibits .grid > div, #artifacts .grid > div, #guides .grid > div, #about .container > *').forEach(element => {
                gsap.from(element, {
                    opacity: 0,
                    y: 30,
                    duration: 1,
                    scrollTrigger: {
                        trigger: element,
                        start: 'top 80%',
                        end: 'bottom 20%',
                        toggleActions: 'play none none reverse'
                    }
                });
            });
        });
    </script>

</body>
</html>
