    <script>
        lucide.createIcons();

        document.addEventListener('DOMContentLoaded', () => {
            const articleCards = document.querySelectorAll('.article-card');
            articleCards.forEach(card => {
                gsap.fromTo(card, { opacity: 0, y: 50 }, { opacity: 1, y: 0, duration: 1, ease: "power2.out", scrollTrigger: { trigger: card, start: "top 80%", } });
            });
        });

        function calculateMargin() {
            const revenue = parseFloat(document.getElementById('revenue').value);
            const costs = parseFloat(document.getElementById('costs').value);
            const marginResultDiv = document.getElementById('marginResult');

            if (isNaN(revenue) || isNaN(costs)) {
                marginResultDiv.textContent = "Please enter valid numbers.";
                return;
            }

            const profitMargin = ((revenue - costs) / revenue) * 100;
            marginResultDiv.textContent = `Profit Margin: ${profitMargin.toFixed(2)}%`;
        }

        function calculateBreakEven() {
            const fixedCosts = parseFloat(document.getElementById('fixedCosts').value);
            const variableCosts = parseFloat(document.getElementById('variableCosts').value);
            const unitPrice = parseFloat(document.getElementById('unitPrice').value);
            const breakEvenResultDiv = document.getElementById('breakEvenResult');

            if (isNaN(fixedCosts) || isNaN(variableCosts) || isNaN(unitPrice)) {
                breakEvenResultDiv.textContent = "Please enter valid numbers.";
                return;
            }

            if (unitPrice <= variableCosts) {
                breakEvenResultDiv.textContent = "Unit price must be higher than variable costs.";
                return;
            }

            const breakEvenPoint = fixedCosts / (unitPrice - variableCosts);
            breakEvenResultDiv.textContent = `Break-Even Point: ${Math.ceil(breakEvenPoint)} units`;
        }
        function calculateLoan() {
            const loanAmount = parseFloat(document.getElementById('loanAmount').value);
            const interestRate = parseFloat(document.getElementById('interestRate').value) / 100 / 12;
            const loanTerm = parseFloat(document.getElementById('loanTerm').value) * 12;
            const loanResultDiv = document.getElementById('loanResult');

            if (isNaN(loanAmount) || isNaN(interestRate) || isNaN(loanTerm)) {
                loanResultDiv.textContent = "Please enter valid numbers.";
                return;
            }

            const monthlyPayment = (loanAmount * interestRate) / (1 - Math.pow(1 + interestRate, -loanTerm));
            const totalPayment = monthlyPayment * loanTerm;
            const totalInterest = totalPayment - loanAmount;

            loanResultDiv.textContent = `Monthly Payment: $${monthlyPayment.toFixed(2)}, Total Interest: $${totalInterest.toFixed(2)}, Total Payment: $${totalPayment.toFixed(2)}`;
        }


        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');

        mobileMenuButton.addEventListener('click', () => {
            mobileMenu.classList.toggle('hidden');
        });
    </script>

</body>
</html>
