    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const mobileMenu = document.getElementById('mobile-menu');

            mobileMenuButton.addEventListener('click', () => {
                mobileMenu.classList.toggle('hidden');
            });
        });

        let carouselIndex = 0;
        const carousel = document.getElementById('recipeCarousel');
        const cardWidth = document.querySelector('.recipe-card').offsetWidth;
        const cardMargin = parseInt(window.getComputedStyle(document.querySelector('.recipe-card')).marginRight);
        const totalCardWidth = cardWidth + cardMargin * 2;
        const cardsToShow = 3;

        function scrollCarousel(direction) {
            carouselIndex += direction;
            const maxIndex = carousel.children.length - cardsToShow;
            if (carouselIndex < 0) {
                carouselIndex = 0;
            } else if (carouselIndex > maxIndex) {
                carouselIndex = maxIndex;
            }
            carousel.style.transform = `translateX(-${carouselIndex * totalCardWidth}px)`;
        }

        function toggleCheck(checkbox) {
            const label = checkbox.nextElementSibling;
            if (checkbox.checked) {
                label.classList.add('checked');
            } else {
                label.classList.remove('checked');
            }
        }
    </script>
